-- ============================================================
-- Ereb3b (2/7) — DB kontentinin AR tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6170 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من هذا الشهر، أصبحت سعة معدة طفلكِ نحو 300 ml. وهذا يعني أن طفلكِ سيتمكن الآن من تناول كمية أكبر من الطعام، لذا يمكنكِ زيادة حجم حصصه تدريجيًا بطريقة لا ترهق جهازه الهضمي. من المهم أن يتناول طفلكِ الفواكه والخضراوات الموسمية ذات القيمة الغذائية العالية، وأن يكتسب في الوقت نفسه عادات غذائية سليمة. وخلال هذه المرحلة المعروفة بمرحلة ما قبل المدرسة، قد يؤدي الإفراط في تناول السكر إلى السمنة مستقبلًا وإلى العديد من الأمراض المرتبطة بها. لذلك، بدلًا من السكر الذي يمنح سعرات حرارية فارغة، يمكنكِ البدء بتقديم دبس الفاكهة المُحضّر بطرق طبيعية، ومستخلص التمر، ومستخلص الخروب لطفلكِ. كذلك، لم يعد هناك سبب يمنع طفلكِ من تناول الأطعمة التي كانت مدرجة ضمن قائمة الممنوعات عند بدء إدخال الأطعمة التكميلية. لذا يمكنكِ، ابتداءً من عمر 1 سنة، إدخال بياض البيض والأطعمة المعروفة بأنها مسببة للحساسية، مثل الفراولة والكيوي والطماطم وحليب الماعز وحليب البقر، إلى قائمة طعام طفلكِ.') WHERE id = '58dc36ac-5b7c-4362-80e3-ab066859eeea';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في ثمانينيات القرن العشرين، طُرحت نظرية تفيد بأن الإنسان لا يستخدم سوى 10% من دماغه، وذلك استنادًا إلى أبحاث أُجريت في المختبر. وحتى يومنا هذا، الذي يُعرف بعصر التكنولوجيا، لا يزال كثيرون يتعاملون مع هذه المعلومة على أنها حقيقة. لكن الأبحاث الحديثة أثبتت أن الإنسان يستخدم كامل قدرات دماغه. وتُظهر هذه الأبحاث أن الدماغ البشري يعمل بوصفه وحدة متكاملة، وأن جميع روابطه تتفاعل مع بعضها، كما أن العديد من الأنشطة تستمر في العمل في الخلفية حتى عند عدم تنفيذ أي مهمة. ويكتمل 70% من هذا التطور الدماغي خلال أول 1 سنة بعد الولادة. أي إن دماغ طفلكِ يكون في هذه المرحلة قد وصل تقريبًا إلى مستوى تطور دماغ الشخص البالغ. لذلك، من المهم جدًا أن تمارسي مع طفلكِ ألعابًا وأنشطة متنوعة لدعم تطوره الذهني.') WHERE id = '6d097ab5-abec-41d4-95bf-d2757270dc79';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد المرحلة التالية لعمر 1 سنة فترة انتقالية لطفلكِ، وتشهد أيضًا تغيرًا في نمط تغذيته. ففي هذا الوقت تزداد حركة طفلكِ كثيرًا، وقد يرفض تناول الطعام رغبةً منه في تخصيص وقت أطول للعب. ومن المتوقع والطبيعي أيضًا أن تتباطأ سرعة نموه خلال هذه المرحلة التي يشيع فيها انخفاض الشهية. لذلك، عليكِ إدراج المجموعات الغذائية الأساسية في نظام طفلكِ الغذائي بكميات كافية وبانتظام، وتشمل اللحوم والحليب ومنتجات الألبان والخضراوات والحبوب والدهون والفواكه. ولتلبية احتياجات طفلكِ اليومية من الكالسيوم، يكفيه نحو كوبين من الحليب أو اللبن الرائب. ويُعد البروتين من أهم العناصر الغذائية الأساسية التي ينبغي أن يتضمنها نظامه الغذائي يوميًا، لما له من دور في نمو العضلات والعظام. لذا حاولي إدراج أطعمة غنية بالبروتين، مثل اللحوم والدجاج، في قائمة طعامه لمدة 4 أيام على الأقل أسبوعيًا.') WHERE id = '1f14934f-6ba0-46b8-bd87-619dc02a6360';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدينا اليوم اقتراح لنشاط يمكنكِ ممارسته مع طفلكِ وستستمتعان به كثيرًا: حافلة، شاحنة، سيارة أجرة، سيارة جيب، بييييب! 😊 هذه اللعبة بسيطة وممتعة جدًا، ويمكن تنفيذها بسهولة من دون أي تكلفة أو تحضير. ستُنشّط أجزاء متعددة من دماغ طفلكِ، وسيستمتع كثيرًا أثناء اللعب. فعندما تلمسين بأصابعكِ بالتتابع خده الأيمن ثم الأيسر وذقنه وجبهته وأنفه، سيُحفَّز حس اللمس في دماغه. وعندما تطلبين من طفلكِ أن يفعل الشيء نفسه معكِ، فسيكون ذلك وسيلة فعالة جدًا لتنمية التناسق بين اليد والعين. كما ستتطور في هذه المرحلة مهارات المتابعة والانتباه لديه. وبعد فترة، ستلاحظين أنه كلما كررتِ اللعبة، بدأ طفلكِ ينتظر جزء «بييب» بحماس! 😊') WHERE id = 'dbf740cc-9b7e-4a4f-823f-1cca951d24d9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشكّل الأطعمة الغنية بالكربوهيدرات الجزء الأكبر من احتياجات طفلكِ اليومية من السعرات الحرارية. وفي هذه المرحلة، عليكِ إدراج الحبوب الصحية الغنية بالكربوهيدرات وذات القيمة الغذائية العالية ضمن نظامه الغذائي. ويمكنكِ استبدال الخبز المصنوع من الدقيق الأبيض الذي يتناوله يوميًا بخبز مصنوع من دقيق القمح الكامل أو الجاودار أو الشوفان. لكن إذا كانت قائمة الطعام تحتوي على أطعمة غنية بالكربوهيدرات، مثل الأرز أو المعكرونة، فينبغي تقليل كمية الخبز. ونظرًا إلى اختلاف الفيتامينات والمعادن الموجودة في كل نوع من الفاكهة، حاولي تقديم الفواكه الطبيعية الموسمية لطفلكِ. ولتقليل فقدان الفيتامينات إلى أدنى حد، يمكنكِ تفضيل طهي الوجبات التي تحضّرينها لطفلكِ على البخار. وإلى جانب الطهي على البخار، يمكن أيضًا استخدام السلق أو الطهي في الفرن. لكن من الأفضل حاليًا تجنّب طرق الطهي مثل القلي.') WHERE id = '7d0f3469-adf8-4ed6-8ee6-cccf8034c80f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم يكن في سيارتكِ مقعد أطفال حتى الآن، فننصحكِ باقتنائه في أقرب وقت ممكن. يوصي المختصون باستخدام مقعد الرضّع منذ ولادة طفلكِ وحتى عمر 1 سنة، ثم استخدام مقعد الأطفال بعد أن يبدأ بالحركة عقب بلوغه عمر 1 سنة. يقلل مقعد الأطفال في السيارة من خطر تعرض طفلكِ للإصابة أثناء السفر بنسبة 90%. وبذلك يكون طفلكِ محميًا، في حال وقوع حادث محتمل، من مخاطر مثل الاندفاع خارج السيارة أو الانحشار أو التعرض للصدمات. وعندما تُثبّت مقاعد الأطفال بإحكام داخل السيارة، يمكن لطفلكِ السفر من دون أي انزعاج. بالإضافة إلى ذلك، وعلى عكس مقاعد الرضّع، يمكنكِ تثبيت مقاعد الأطفال باتجاه سير السيارة بدلًا من وضعها في الاتجاه المعاكس. وهكذا يمكنكِ تقليل شعور طفلكِ بالغثيان إلى أدنى حد، وتمكينه من مشاهدة ما حوله براحة.') WHERE id = 'bc4b0b1c-8079-4973-9564-32f3aa0c7c31';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ في هذه المرحلة باستخدام حواسه ومهاراته الحركية بنشاط لاستكشاف العالم الخارجي. ولأنه يستخدم خياله أثناء هذه الاكتشافات، فإنه لا يستطيع حتى الآن التمييز بين الواقع والمفاهيم المجردة. ونتيجة لذلك، قد يرى كوابيس، لا سيما خلال مرحلة نوم حركة العين السريعة (REM) التي يكون فيها دماغه في أعلى درجات النشاط ليلًا، وقد يستيقظ باكيًا. وعلى الرغم من أن نوم حركة العين السريعة يكون في أعلى مستوياته عند ولادة طفلكِ، فإن بدء تناقصه تدريجيًا في هذه المرحلة يُعد نتيجة طبيعية لنموه. لكنه لا يزال يشكل جزءًا كبيرًا من نومه، لذلك ينبغي لكِ تهدئة طفلكِ عندما يستيقظ باكيًا من خلال التحدث إليه بصوت لطيف، والتربيت على ظهره وطمأنته بكلمات مريحة. ويُعد إنشاء نظام جيد بين النوم واليقظة من أهم جوانب نمو دماغ طفلكِ. ويرجع ذلك إلى ازدياد نقاط الاتصال في دماغه بفضل استمرار نشاط يُسمى «النشاط العصبي الداخلي المنشأ» طوال مدة نومه.') WHERE id = 'badf3432-f515-4611-b2dd-f57dfff399c0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا تنمية مهارات طفلكِ الحركية ودعم التناسق بين يديه وعينيه. لذلك، بدلًا من الاكتفاء بإطعامه، ينبغي لكِ السماح له بالجلوس معكِ إلى مائدة الطعام. ويمكنكِ وضع ملعقة وشوكة وكوب أمامه وتشجيعه على تناول الطعام بنفسه. إن جلوس طفلكِ معكم إلى مائدة الطعام يتيح لكم قضاء وقت ممتع معًا، كما يُعد وسيلة فعالة جدًا لتنمية مهاراته الحركية. كذلك ستساعدكِ آداب المائدة كثيرًا في تعليم طفلكِ تناول الطعام باستقلالية، وتعزيز ثقته بنفسه، وتكوين عادات غذائية صحية لديه. ويُعد اكتسابه عادات غذائية صحية مهمًا أيضًا لتقليل احتمالية مواجهته مشكلات صحية خطيرة، مثل السمنة، في المستقبل. بالإضافة إلى ذلك، يسهم ذلك في نموه الاجتماعي، ويساعده على الشعور بأنه فرد من أفراد الأسرة وعلى اكتساب الثقة بالنفس.') WHERE id = 'a5a8bdd4-c15d-4e3c-b31c-fa8ddc4838d7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتصرف طفلكِ في هذه الفترة بخجل شديد، خصوصًا عندما يوجد وسط حشد من الأشخاص الذين لا يعرفهم. فمنذ عمر 1 سنة، يبدأ طفلكِ بإدراك أنه كيان مستقل، وبتكوين مفهوم "الأنا". وبينما يستطيع بعض الأطفال التواصل سريعًا مع أقرانهم والبالغين، قد يتعامل آخرون بمزيد من الحذر. ويحتاج هؤلاء الأطفال إلى مزيد من الوقت والألفة حتى يتمكنوا من التواصل مع الآخرين. وتتكون السمات الشخصية التي تشكل مهارات التواصل الاجتماعي هذه تحت تأثير العوامل الوراثية والبيئية. وفي هذا السياق، توجد بعض الأنشطة التي يمكنكِ القيام بها لمساعدة طفلكِ على التواصل الاجتماعي وتعزيز ثقته بنفسه وروح المبادرة لديه. فمثلًا، يمكنكِ أثناء لعبه بألعابه التحدث بأصواتها وكأن لكل منها دورًا مختلفًا، ثم تعريفها إلى طفلكِ. سيساعد هذا النشاط على تكوين المهارات الأساسية اللازمة لتواصله الاجتماعي.') WHERE id = '210da92e-a255-4ad9-bddd-29b5d33ece1b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مرحبًا بكِ في الشهر 13 المليء بالمغامرات التي ستخوضينها مع طفلكِ! يمر طفلكِ الآن بمرحلة يرغب فيها في استكشاف كل شيء. ولأن حركته لم تعد محدودة كما كانت من قبل، فقد تظهر روحه المحبة للمغامرة بشكل أوضح. وبالنسبة إلى طفلكِ كثير الحركة داخل المنزل، قد تشكل طاولة القهوة والطاولات المرتفعة والأشياء القابلة للكسر مصادر خطر حقيقية. لذلك، ينبغي لكِ جعل كل مكان يوجد فيه طفلكِ آمنًا. وسيفيدكِ كثيرًا خلال هذه الفترة تحويل غرفته إلى مساحة للعب، واستخدام حواجز الأطفال أو حظائر اللعب عندما لا تكونين بجانبه. فقد يؤدي تقييد طفلكِ إلى إضعاف رغبته وحماسه لتجربة أشياء جديدة. لذا، ينبغي لكِ السماح له بفعل ما يريد بحرية ضمن الحدود التي تحددينها له.') WHERE id = '740aa0ca-f02e-440c-9265-f4789b505cbc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبلغ متوسط وزن طفلكِ في الشهر 13 نحو 10.500 غرام إذا كان ولدًا، ونحو 9600 غرام إذا كانت بنتًا. ومع ذلك، قد يتراوح وزن طفلكِ بين 8000 غرام و14.000 غرام. وهناك أسباب عديدة لاتساع هذا النطاق. ويُعد الجنس أحد أهم العوامل المؤثرة في خصائص النمو. فمن الطبيعي وراثيًا أن يكون الأولاد أكبر حجمًا وأثقل وزنًا وأطول قامة من البنات. ومن الخطأ مقارنة طفلين من جنسين مختلفين، حتى لو وُلدا في الأسبوع نفسه وبالوزن نفسه. ومن الطبيعي من ناحية النمو أن يتطور الجهاز العصبي والجهاز العضلي الهيكلي لدى الأولاد بوتيرة أسرع مقارنة بالبنات حتى أواخر مرحلة الطفولة.') WHERE id = '89a0dfcb-42b6-4d7f-b880-5a576cebf0c5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، قد تحمل التصرفات التي تبدو لكِ بسيطة معنى كبيرًا لطفلكِ. وبالنسبة إلى طفلكِ الذي بدأ المشي بالفعل، يُعد استكشاف كل ما يحيط به من أكثر الأنشطة المحببة إليه. ومن بين الأنشطة التي يمكنكِ القيام بها معه خلال هذا الشهر قراءة كتب مليئة بالصور والرسوم التوضيحية التي ستجذب اهتمامه بشكل خاص. فهذا النشاط سيستحوذ على انتباه طفلكِ، كما سيمنحه فرصة لفهم الكلمات وتذكّرها. ومن المفيد جدًا لتطور النطق لديه أن يسمع كلمة جديدة بصورة متكررة. كما أن تكراركِ معه الكلمات التي يسمعها منكِ وينطق بها سيشجعه أكثر على قراءة الكتب والاستماع إليها. ويؤكد المختصون ضرورة ترسيخ عادة قراءة الكتب منذ سن مبكرة جدًا. لذلك ننصحكِ بأن تجعلي طفلكِ يحب القراءة دعمًا لنموه وتطوره. قراءة ممتعة! 😊') WHERE id = 'faa77562-7254-4896-90da-0246f097b6f8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'شرب كمية كافية من الماء مهم جدًا لطفلكِ. لكن ينبغي ألا تنسي أن الإفراط في الماء قد يكون ضارًا، مثلما يضر الإفراط في أي شيء آخر. فقد يؤدي شرب طفلكِ كمية من الماء تفوق حاجته إلى اختلال توازن الأملاح والكهارل في جسمه. وقد يسبب هذا الاختلال بعض المشكلات الصحية التي قد تصل إلى إصابته بالتشنجات. كذلك، نظرًا إلى أن كليتيه لم يكتمل نموهما بعد في هذه المرحلة، فإن الإفراط في شرب الماء يفرض عليهما عبئًا إضافيًا. وقد يؤثر ذلك سلبًا في نمو طفلكِ وتطوره، كما قد يُلحق الضرر بأعضائه. وإذا كنتِ تستخدمين حليب الأطفال الصناعي في تغذيته، فإن إضافة ماء زائد إليه بهدف جعله يشرب كمية أكبر ستقلل أيضًا من قيمته الغذائية. لذلك، من المهم ألا تجبري طفلكِ على الشرب إذا لم يرغب في ذلك. وتذكّري أن طفلكِ سيشرب من الماء بقدر حاجته.') WHERE id = '410208cc-11e4-4f3d-94f0-5d9ad8d119dd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد أن يُكمل طفلكِ أول 1 عام له في هذا العالم، تبدأ لديه عملية تكوين شخصيته وإدراكه لذاته. لكن استقلاليته هذه لا تعني أن ارتباطه بكِ قد تراجع. فقد بلغ نموه الذهني الآن مستوى يمكّنه من إدراك الخوف من فقدانكِ بوضوح. وهذا يفسر شدة تعلقه بكِ، وسبب بكائه عندما تبتعدين عنه، والقلق الذي يشعر به في الأماكن التي لا تكونين موجودة فيها. وقد يؤدي خوف الفقدان الشديد الذي يشعر به طفلكِ إلى مرحلة أكثر حساسية تستمر في المتوسط نحو 6 أشهر أخرى. وحتى لا تتأثر حالته النفسية سلبًا، اشرحي له في كل مرة تبتعدين فيها عنه خلال هذه الفترة سبب ذهابكِ، وأخبريه بأنكِ ستعودين. وحتى إن لم تكن لديه حصيلة لغوية كافية للرد عليكِ، فلا تشكّي في أنه سيفهم ما تريدين قوله.') WHERE id = 'fe0ff0cd-6498-4ce3-aae2-9c10c75f7fdb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من هذا الشهر، قد يتباطأ اكتساب طفلكِ للوزن بعض الشيء، وقد يحدث حتى فقدان طفيف في الوزن. وربما تظنين أنه يأكل قليلًا جدًا، وينتقي طعامه، ويجد صعوبة في تناول الطعام بنفسه، ويرفض الأكل. ويوضح المختصون أن عمر السنة قد يشهد لدى الأطفال تراجعًا في التغذية، ويرجع ذلك إلى تغيّر الشهية في هذه المرحلة. فبما أن طفلكِ بدأ الآن يتناول الأطعمة التي تأكلينها، فإنه يعيد تشكيل نمط تغذيته. وقد يكون من الأسباب الأخرى ازدياد شعوره بالاستقلالية خلال هذه الفترة ورفضه الطعام لإثبات شخصيته أمامكِ. أولًا، نوصيكِ بأن تتذكري أن هذه حالة مؤقتة، وألا تقلقي كثيرًا بشأن ثبات وزن طفلكِ. ومن المهم جدًا أيضًا أن تتعاملي معه بمرونة وتقبّل أكبر بدلًا من إجباره أو فرض سيطرة شديدة عليه أو الإفراط في مطالبه. هل لاحظتِ أنه يلتفت وينظر إليكِ عندما تنادينه باسمه أو تتحدثين إليه؟') WHERE id = '34ee7ef2-aae6-4a89-859e-a1e8fda8d8a3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ الآن في تكوين تصور ذهني لمعاني الكلمات التي يسمعها كثيرًا. وبفضل ذلك، أصبح قادرًا على التمييز بين اسمه وأسماء أفراد أسرته والتفاعل معها بما يناسب. وخلال الفترة الممتدة من عمر 12-18 شهرًا، التي يتسارع فيها تطور النطق بشكل ملحوظ، قد يبدأ طفلكِ في نطق كلمات ذات معنى أو من دونه بلا توقف. وستتكون هذه الكلمات في الغالب من أصوات متحركة لأنها أسهل في النطق. وللمساهمة في تطور اللغة لديه، يمكنكِ طرح الأسئلة عليه كثيرًا ثم الإجابة عنها بنفسكِ. وخلال وقت قصير، ستلاحظين أن طفلكِ بدأ يكتسب هذه العادة أيضًا. وبعد فترة، سيبدأ هو الآخر في الإجابة عن أسئلتكِ بلغته الخاصة.') WHERE id = 'c2629557-3a23-4c47-8fc6-f9dc2e9fe09e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي تمامًا في هذه المرحلة أن يظل طفلكِ في حركة مستمرة وألا يرغب في التوقف. فقد بدأ الآن يتحرك بوعي، ويشعر بحماس شديد عندما يرى أنه قادر على إنجاز شيء ما. ومن أمثلة ذلك، للأسف، فك لفائف ورق المرحاض، وإلقاء الأشياء الموجودة في أماكن مرتفعة على الأرض، وبعثرة محتويات رفوف الكتب! 😊 لا يهدف طفلكِ هنا إلى إحداث الفوضى أو القيام بسلوك مؤذٍ، بل إلى الاستكشاف. فتحريك كل ما يجده ويثير اهتمامه من مكانه، وإلقائه على الأرض أو إلى الأمام وقلبه، كلها بالنسبة إليه وسائل ممتعة جدًا للتعلم. ولمواكبة حماس طفلكِ، قد يكون من المفيد شراء ألعاب يمكن إدخالها بعضها في بعض أو تفكيكها وتركيبها. وبهذه الطريقة، يمكنكِ الحفاظ على أغراض المنزل سليمة وحماية صغيركِ من المخاطر المحتملة أثناء استكشافه.') WHERE id = 'ce527391-7cf1-440d-bee3-7d79e8fa2c65';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد أن أكمل طفلكِ عامه الأول في هذا العالم، حان الوقت لإضافة أطعمة مثل الطماطم، التي تُعد من مسببات الحساسية القوية خلال الأشهر الأولى، إلى نظامه الغذائي. يمكنكِ أيضًا تحضير حساء صحي ومغذٍّ جدًا لطفلكِ باستخدام مكونات طبيعية يسهل العثور عليها. ستحتاجين إلى: 1-2 حبة من الطماطم والفلفل، وحبة جزر واحدة، وحبة بصل وفص ثوم، وكوب من اللبن الزبادي، والدقيق، وكمية قليلة من الكمون والنعناع. بعد غسل جميع الخضراوات جيدًا، قطّعي الفلفل واطهيه في الماء. ثم اخلطي الطماطم والجزر والثوم والبصل مع الفلفل المطهو باستخدام الخلاط اليدوي. بعد التأكد من عدم وجود أي تكتلات، انتظري حتى يبرد الخليط. أضيفي إليه كوبًا من اللبن الزبادي والتوابل، ثم أضيفي الدقيق تدريجيًا حتى يصبح بقوام العجين، واتركيه يرتاح لمدة 3-4 ساعات. بعد أن يجف العجين، اخلطيه مرة أخرى في الخلاط حتى يتحول إلى مسحوق. حساء الترهانة اللذيذ لطفلكِ أصبح جاهزًا. بالهناء والشفاء! 😊') WHERE id = '5d048a4f-b4b0-4727-ad67-5bbff6c67131';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تعتقدين أن طفلكِ، الذي يُتوقع أن يكون كثير الحركة في هذه المرحلة، يميل إلى النوم بشكل مفرط ولا يتمتع بالطاقة الكافية، فقد يكون من الضروري فحص مستوى فيتامين B12 لديه. فيتامين B12، المعروف أيضًا باسم سيانوكوبالامين، هو فيتامين يؤدي دورًا في إنتاج خلايا الدم الحمراء في الجسم. وقد يسبب نقصه التعب والوهن والنعاس وفقدان الشهية وجفاف البشرة وشحوبها. كما قد يظهر في صورة فقدان الوزن أو توقف زيادته أو تقرحات داخل الفم تُعرف باسم "القلاع الفموي". يكون مخزون فيتامين B12 في جسم طفلكِ عند الولادة كافيًا لنموه خلال الأشهر الستة الأولى بعد الولادة. لكن بدءًا من الشهر السادس، ينخفض هذا المخزون بدرجة كبيرة، وإذا لم يحصل طفلكِ على ما يكفي من فيتامين B12 من الأطعمة التكميلية، فقد يحدث بعض التأخر في نموه. لذلك، من المهم جدًا أن تضيفي إلى نظام طفلكِ الغذائي أطعمة غنية بفيتامين B12، مثل اللحوم والدجاج والأسماك والكبد والبيض والحليب ومنتجات الألبان.') WHERE id = '6f7d0c13-65dd-4b38-aa89-153bf2d87600';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك العديد من الأمور التي ينبغي لكِ الانتباه إليها عند السفر بالسيارة مع طفلكِ. وأهمها استخدام مقعد سيارة ملائم لعمره حفاظًا على سلامته. إضافة إلى ذلك، قد يفتح طفلكِ باب السيارة أثناء الرحلة بسبب كثرة حركته. ولأن هذا الأمر قد يؤدي إلى عواقب خطيرة جدًا، فمن الضروري للغاية إبقاء قفل أمان الأطفال في سيارتكِ مفعّلًا. وقد تتساءلين عن المواصفات التي ينبغي أن تتوافر في مقعد السيارة الخاص بطفلكِ. الأولوية هنا لعمر طفلكِ ووزنه. ومن المهم جدًا اختيار الطراز الملائم لعمره ووزنه حتى يؤدي المقعد الغرض المخصص له. كما ينبغي لكِ التحقق من متانة أحزمة التثبيت واختيار الطرز المزودة بحزام أمان خماسي النقاط ومتوافق مع المعايير المعتمدة.') WHERE id = 'b1729ded-cafa-45bd-8d10-000cf5711478';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكون سعة معدة طفلكِ صغيرة جدًا خلال الأشهر الأولى بعد ولادته، لذلك يُعد استيقاظه المتكرر ليلًا بسبب الجوع أمرًا طبيعيًا. لكن بعد الشهر 4، يبدأ في الاستيقاظ مرات أقل أثناء الليل مع ازدياد حجم معدته. وبدءًا من الشهر 6، يحتاج طفلكِ إلى نوم ليلي متواصل لدعم نموه. وقد يستمر استيقاظه ليلًا مدة إضافية بسبب العادات التي تكونت لديه على مدار الأشهر. أما الآن، في الشهر 13، فقد يستمر في الاستيقاظ حتى إن لم يكن جائعًا، لأن ذلك أصبح عادة لديه. وفي هذه المرحلة، يحتاج إلى مساعدتكِ للتخلص من عادته القديمة. إذا كنتِ ترضعينه طبيعيًا، فقد يفيدكِ إرضاعه قبل وضعه في السرير مباشرة، أو إعطاؤه الحليب الصناعي المخصص لمرحلته العمرية. وبذلك سيشعر بالشبع مدة أطول خلال الليل، فيستيقظ مرات أقل، وستتمكنين على المدى المتوسط من مساعدته على تكوين نمط نوم منتظم.') WHERE id = 'b85a9b65-ee9c-45ae-a0a7-601fc164c0a0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لاحظتِ بقعًا أو بدايات تسوس على أسنان طفلكِ الصغيرة الشبيهة باللؤلؤ، فننصحكِ بأخذ الأمر على محمل الجد. ولأن هذه الحالة تظهر خصوصًا لدى الأطفال الذين يستخدمون زجاجة الرضاعة، يُطلق عليها المختصون اسم "تسوس زجاجة الرضاعة". ومن سماته أنه يظهر بصورة أكبر في الأسنان العلوية ثم ينتقل إلى الأسنان الأخرى خلال فترة قصيرة. تبدأ هذه المشكلة في صورة بقع بيضاء وصفراء، ثم تتحول بعد فترة إلى لون بني مائل إلى السواد. ويحدث ذلك بسبب ملامسة الحليب الذي تقدمينه لطفلكِ لأسنانه مباشرة، ثم تراكم بقايا الغذاء على سطح الأسنان نتيجة عدم تنظيف الفم بعد ذلك. وعلى الرغم من إمكانية علاج هذا التسوس، فإن الوقاية منه قبل حدوثه هي الخيار الأفضل. ولمنع ظهور هذه المشكلة لدى طفلكِ أو تفاقمها، يمكنكِ تنظيف أسنانه بعد الوجبات باستخدام فرشاة الأسنان التي تُثبت على الإصبع.') WHERE id = '5019f758-f1eb-4332-8fb6-b0119b339b94';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا أن يحظى اللعب والنشاط البدني بمساحة كافية في روتين طفلكِ اليومي. فاللعب والحركات التي يؤديها مهمان لتفاعله الاجتماعي وتعرّفه إلى العالم وتنمية مهاراته واكتشاف ذاته. خلال هذه المرحلة، يحاول طفلكِ استكشاف قدراته ومعرفة ما يمكنه فعله وما لا يمكنه فعله. ويؤدي كل ذلك دورًا مهمًا في تعزيز استخدامه لمهارات اللغة والكلام، وزيادة ثقته بنفسه، وتنمية المهارات الأساسية التي ستفيده طوال حياته. كما ستساعد الأنشطة التي يمارسها خلال اليوم على تحفيز شهيته. لكن بقاء طفلكِ مستيقظًا مدة مفرطة وشعوره بالتعب قد يؤثران سلبًا في شهيته. ولتجنب اضطراب نظامه الغذائي، احرصي على أن يستريح مدة 20 دقيقة تقريبًا قبل الوجبات. وبهذه الطريقة، سينصب تركيز طفلكِ أثناء تناول الطعام على الوجبة وحدها، وستحصلين أنتِ أيضًا على أفضل نتيجة ممكنة.') WHERE id = 'd077fdd8-cbeb-4397-8aed-7974e355456b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحدث أسرع مراحل نمو طفلكِ داخل الرحم. ففي هذه الفترة يمر بأسرع مرحلة تطور سيشهدها طوال حياته. ورغم استمرار هذا النمو السريع لبعض الوقت بعد الولادة، فإن زيادة الوزن تبدأ بالتراجع تدريجيًا، خاصة بعد بلوغه عمر 1 سنة. ويُعد اكتساب طفلكِ ما متوسطه 100-150 غرامًا خلال هذه الأشهر أمرًا طبيعيًا؛ فلا يُتوقع أن يزداد وزنه بمقدار 900-1000 غرام كما كان الحال في الأشهر الأولى. بل قد يُعد ثبات الوزن أو فقدان مقدار بسيط منه من حين إلى آخر أمرًا طبيعيًا أيضًا. واعلمي أن وتيرة النمو لن تتسارع مجددًا حتى عمر 6-10 سنوات، فهذه هي المرحلة الوحيدة التي يتسارع فيها النمو خارج فترة الرضاعة. وقد يرجع وضع وزن طفلكِ أيضًا إلى نشاطه الشديد خلال اليوم وعدم رغبته في تخصيص وقت لتناول الطعام. وإذا لم تكشف الفحوصات الدورية وتحاليل الدم التي يجريها الطبيب عن أي مشكلة صحية، فلا داعي للقلق بشأن ذلك.') WHERE id = '1bf4db64-14c4-4c92-9597-a3543f95396e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تقع على عاتقكِ مسؤولية اختيار النكهات المناسبة في غذاء طفلكِ، والاهتمام بالقيمة الغذائية، وتنظيم مواعيد الوجبات. لكن يجب أن يقرر طفلكِ مقدار ما سيتناوله من الطعام الذي أعددتِه. كما أن عدم اقتصار نظامه الغذائي على الوجبات الرئيسية، وتقديم وجبات خفيفة بينها، سيساعدان على الحفاظ على شهيته. وقد يؤدي الضغط عليه ليتناول المزيد إلى بعض المواقف السلبية بينكما. ويمكن أن تظل آثار أي تجربة سلبية تنشأ بينكِ وبين طفلكِ خلال مرحلة اكتساب عادات تناول الطعام ملازمة له طوال حياته. فكلما عاندتِ طفلكِ، قاومكِ بالقدر نفسه. لذلك، قد يكون من الأفضل أن تبدئي بإعداد حصص صغيرة، ثم تزيدي الكمية وفقًا لشهيته ورغبته.') WHERE id = '540d6c51-7eac-42c0-8644-43d0623f6aca';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ الآن في استكشاف ما حوله، وأصبح أكثر اهتمامًا خصوصًا بالأماكن التي تحاولين إبعاده عنها. فقد يشكل الحمام والمرحاض والمطبخ والدرج، إن وُجد في منزلكم، خطرًا جسيمًا عليه. وعلى الرغم من أن طفلكِ قد أصبح قادرًا في هذه المرحلة على صعود الدرج، فإنه لا يزال غير ماهر بما يكفي في النزول. ولذلك عليكِ اتخاذ الاحتياطات اللازمة لحمايته من خطر السقوط والإصابة. ويمكنكِ الاطلاع على بوابات أمان الأطفال المتوفرة في الأسواق لتهيئة بيئة منزلية آمنة لطفلكِ الصغير. وهناك بعض النقاط التي ينبغي الانتباه إليها عند اختيار واحدة من أنواع هذه البوابات المختلفة؛ إذ يجب أن يكون ارتفاعها أعلى من طول طفلكِ. كما ستكون النماذج المتينة التي لا يستطيع طفلكِ نزعها من مكانها، والتي يمكن قفلها، مفيدة جدًا لكِ.') WHERE id = '3e9a697a-9c74-4491-8b57-a79e63e4f840';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن بشرة طفلكِ لم تعد رقيقة كما كانت في الأشهر الأولى بعد ولادته، فإنها لا تزال شديدة الحساسية. لذلك عليكِ مواصلة العناية بها بالاهتمام نفسه. أشعة الشمس مفيدة جدًا لطفلكِ، لكنها قد تكون خطرة على بشرته الحساسة في أوقات معينة من اليوم. ولحمايته من آثار الشمس الضارة، يُفضل تجنب الخروج خلال ساعات الظهيرة حين تكون أشعة الشمس في أشدها. وإذا اضطررتِ إلى الخروج، فعليكِ حمايته بقبعة أو مظلة أطفال، أو استخدام كريم واقٍ من الشمس مناسب لبشرة الأطفال. بالإضافة إلى ذلك، احرصي جيدًا على أن تكون ملابس طفلكِ مصنوعة من أقمشة جيدة التهوية ولا تسبب التعرق. فقد تؤدي الملابس الملامسة لبشرته مباشرة إلى التهيج إذا لم تُختَر بعناية. وبما أن ذلك قد يؤدي إلى انسداد المسام وظهور مشكلات جلدية مثل الطفح الحراري، فننصحكِ باتخاذ الاحتياطات اللازمة من الآن.') WHERE id = 'baabf765-39b9-4839-adad-77a6c863f562';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، أصبح لدى طفلكِ نحو 3-4 أسنان. وهذا يعني أن وقت زيارة طبيب الأسنان قد حان! واستنادًا إلى أبحاث أُجريت على مدى سنوات، توصي الأكاديمية الأمريكية لطب الأطفال بإجراء أول فحص للأسنان في عمر 1 سنة تقريبًا. ويمكن إجراء هذه الفحوصات بوتيرة أكبر مع ظهور الأسنان، ثم مرتين سنويًا بعد اكتمال ظهورها. ومن المهم جدًا ألا يخاف طفلكِ من فحص الأسنان وألا يتطور لديه رهاب منه. لذلك، قد يكون من الجيد أن تشرحي لطفلكِ ما ينتظره قبل الذهاب إلى الطبيب. فتجاهل هذه الخطوة ظنًا منكِ أنه لن يفهم قد يؤدي إلى خوفه من طبيب الأسنان مستقبلًا. ومن المهم جدًا أيضًا أن يكون طبيب الأسنان الذي تختارينه بشوشًا وصبورًا. لذا يمكنكِ الاستفسار عنه وجمع المعلومات من أقاربكِ ومعارفكِ.') WHERE id = '0c5d07c7-c8fe-42d1-b69e-2a3e6839e46d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'انتقل طفلكِ الآن بالكامل إلى الأطعمة الصلبة، وبفضل ذلك يمكنه تناول الأطعمة التي تتناولينها بسهولة. إلا أن بعض الأطعمة قد تسبب تراكم الغازات في الأمعاء، ومن الطبيعي أن يؤثر ذلك في طفلكِ أيضًا. فقد يختلف تفاعل كل جسم مع الأطعمة نفسها. ويُعد الملفوف والقرنبيط والبروكلي والبقوليات ومنتجات الألبان عمومًا من الأطعمة التي قد تسبب الغازات. لكن هذا التعميم لا يعني بالضرورة أن هذه الأطعمة ستسبب مشكلة لطفلكِ أيضًا. ويمكنكِ من خلال التجربة معرفة الأطعمة التي تسبب له الغازات والانزعاج. وفي حال حدوث الغازات، قد يساعدكِ تدليك بطن طفلكِ برفق بحركات خفيفة، أو وضع منشفة دافئة سخّنتِها بالمكواة على منطقة البطن.') WHERE id = '9f63d50f-7166-4560-9204-76cd4e4af961';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُشكّل السنوات الأولى التي يقضيها طفلكِ داخل الرحم وفي العالم الخارجي أساسًا بالغ الأهمية لنموه. وعلى الرغم من الاعتقاد بأن تكوّن الشخصية يحدث عادةً بين عمر 0-6 سنوات، فقد تبيّن أن هذه العملية تبدأ في الواقع منذ فترة الحمل. وهذا أمر مهم للغاية في تحديد طبيعة الإنسان الذي سيصبح عليه طفلكِ مستقبلًا ونمط حياته. ومن الضروري أن تتقبّلي شخصية طفلكِ المستقلة، لما لذلك من أهمية في قدرته مستقبلًا على التكيّف مع محيطه الاجتماعي. لذلك عليكِ إرشاده وألّا تحرميه أبدًا من اهتمامكِ وحبكِ. فقد تصبح حالة الذعر والقلق التي تُظهرينها تجاه أي موقف نموذجًا يحتذي به طفلكِ. ومن المهم جدًا أن تبدِي سعيدة أمام طفلكِ، وألّا تعكسي عليه متاعبكِ، وأن تكوني قدوة حسنة له. فسعادتكِ من أهم أسباب سعادة طفلكِ. تذكّري دائمًا: "أمهات سعيدات، أطفال سعداء!"😊') WHERE id = 'bc3f1891-4234-45fd-82e4-8d5e9ccf24f4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نظرًا إلى أن بروتين السمك من أصل حيواني، فإن توافره الحيوي، أي معدل تحوّله إلى بروتينات يستخدمها الجسم، مرتفع للغاية. ويُعد هذا المصدر من البروتين أحد أهم العناصر اللازمة لتكوين أنسجة جديدة لدى طفلكِ الذي يمر بمرحلة نمو وتطور سريعين. كما تُعد أحماض أوميغا-3 الدهنية الموجودة في الأسماك من العوامل التي تدعم نمو الجهاز العصبي لطفلكِ بدرجة كبيرة. وتشير دراسات أُجريت في السنوات الأخيرة إلى أن مؤشرات الذكاء تكون أعلى، خصوصًا لدى الأطفال الذين يتناولون السمك بانتظام. ويُقصد بمؤشر الذكاء المذكور هنا ارتفاع معدل الذكاء IQ بنحو 10-15 نقطة. لذلك، من المهم جدًا لنمو طفلكِ الجسدي والعقلي أن يتناول السمك بانتظام مرتين أسبوعيًا على الأقل. وللحفاظ على القيمة الغذائية للسمك، سيكون السمك المطهو في الفرن الخيار الأنسب لطفلكِ.') WHERE id = '981b41f5-021b-47c3-ab24-fd2239fed961';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ طفلكِ يومه مبكرًا ويظل كثير الحركة طوال اليوم! وهذا يعني أنه يحتاج إلى قدر كبير من الطاقة. لذلك يُعد الإفطار أهم من جميع وجبات طفلكِ الأخرى، لأن تناوله في الساعات الأولى من اليوم ينشّط عملية الأيض لديه ويساعده على أن يكون أكثر نشاطًا. يمكنكِ تقديم أنواع الجبن في إفطار طفلكِ بوصفها مصدرًا جيدًا للطاقة. ويمكنكِ لهذا الغرض تقديم قطعة من الجبن الأبيض غير المملح بحجم علبة كبريت، أو 3-4 ملاعق صغيرة من جبن القريش غير المملح. وإذا لم يكن طفلكِ مصابًا بحساسية البيض، فيمكنكِ أيضًا إعداد فطائر كريب شهية باستخدام بيضة ودقيق القمح الكامل. وفي بعض الصباحات، يمكنكِ تحضير الزبادي بالفواكه الموسمية، إذ يساعد على تلبية جانب كبير من احتياجاته من البروتين والفيتامينات ويمنحه الطاقة التي يحتاج إليها خلال اليوم.') WHERE id = '89756ae1-dd1f-454f-b774-e30f54db7adf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد عدوى الإنفلونزا من أكثر الأمراض شيوعًا لدى الأطفال. وينتج هذا المرض، الذي يصيب الجهاز التنفسي العلوي، عن فيروسات، وهو من المشكلات التي قد يتعرض لها كل طفل في بعض الفترات. عندما يُصاب طفلكِ بالإنفلونزا، يحتوي حليبكِ على أجسام مضادة إضافية تساعد على تقوية مناعته ومقاومة الكائنات الدقيقة المسببة للمرض. ولكن حتى إن لم تكوني ترضعين طفلكِ طبيعيًا، فهناك العديد من الوسائل التي يمكنكِ اللجوء إليها عند الاشتباه بإصابته بالإنفلونزا. فعلى سبيل المثال، يمكن أن يكون حساء مرق الدجاج الذي تُعدّينه لطفلكِ مفيدًا جدًا أثناء إصابته بالإنفلونزا. وخلال هذه الفترة، عليكِ إعطاء طفلكِ كمية وفيرة من السوائل لمساعدة جسمه على التعافي من المرض بسهولة. لذلك احرصي على إعطائه الكثير من الماء، ويمكنكِ تقديم أنواع الحساء المُعدّة من الخضراوات الموسمية ومرق الدجاج والعظام.') WHERE id = '0b73e61f-6698-462a-8b7e-eef178ac3033';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع بدء طفلكِ بالمشي بنشاط، قد يعني بلوغه الشهر 14 أنه بدأ يدخل مرحلة الطفولة المبكرة. ولا توجد لقاحات مقررة لطفلكِ خلال هذا الشهر. ومع ذلك، قد يطلب منكِ الطبيب الحضور إلى المستشفى لإجراء الفحوصات الدورية. وخلال هذه الفحوصات، سيُقاس وزن طفلكِ وطوله لتقييم نموه العام، كما سيُقاس محيط رأسه لمتابعة نمو الدماغ. وقد يطرح عليكِ الطبيب أيضًا بعض الأسئلة حول نظام طفلكِ الغذائي وبعض مهاراته الأساسية. وفقًا لجدول نمو الطفل في الشهر 14، يبلغ متوسط وزن الأولاد في هذا الشهر 10.800 غرام. أما متوسط وزن البنات في عمر 14 شهرًا فيبلغ 10.100 غرام. ويجب ألّا تنسي أن هذه القيم قد تختلف بدرجة كبيرة. ويتراوح نطاق الوزن الآمن للأطفال بعمر 14 شهرًا بين 8300 غرام و13.400 غرام. أما الأطفال المولودون قبل الأوان، فقد يظل نموهم أقل من هذه القيم.') WHERE id = '65e79653-9811-4ac2-a32e-9c82ef7262dc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدو لكِ طفلكِ أنحف مما كان عليه في الأشهر الأولى. وقد يكون هذا الأمر مقلقًا جدًا لبعض الأمهات، لكن انخفاض وزن طفلكِ عن المتوقع قد يرجع إلى أسباب عديدة ومختلفة. والسبب الرئيسي هو انخفاض شهيته قليلًا، وبالتالي تراجع كمية السعرات الحرارية التي يتناولها. يحتاج الجسم إلى قدر معين من السعرات الحرارية لأداء وظائفه اليومية، مثل الهضم والتنفس والإخراج. وإذا كان طفلكِ يحصل على سعرات حرارية أقل من حاجته، فمن الطبيعي أن يفقد مقدارًا طفيفًا من وزنه. وقد لا تتوازن السعرات الحرارية التي يتناولها مع ما يحرقه، خصوصًا بعد أن يبدأ بالمشي ويظل في حركة مستمرة. وعادةً ما تستعيد شهية طفلكِ عافيتها خلال بضعة أشهر، لذلك يُعد فقدان مقدار طفيف من الوزن أمرًا طبيعيًا في هذه الفترة.') WHERE id = '3ecdedd3-7b18-4dac-bf11-4e204ffa1806';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نظرًا إلى حساسية بشرة طفلكِ الشديدة، فإن مكونات الشامبو الذي تستخدمينه عند تحميمه لها أهمية كبيرة. ولأن جهازه المناعي لم يكتمل نموه بعد كما هو الحال لدى البالغين، ينبغي أن تختاري أنواع الشامبو الخالية من الكحول والعطور والمواد الكيميائية المستخدمة لإطالة مدة الصلاحية. فقد يتفاعل جهاز طفلكِ المناعي، الذي لا يزال في طور النمو، مع بعض المواد الكيميائية الموجودة في الشامبو مسببًا رد فعل تحسسيًا. كذلك، تُعد درجة حموضة الشامبو الذي تختارينه مهمة جدًا لحماية الطبقة الخارجية من البشرة والحفاظ على صحتها. وتُعتبر أنواع الشامبو ذات درجة الحموضة المتعادلة، أي 7، الأكثر أمانًا لأنها لا تسبب أي تفاعل في بشرة طفلكِ. ورغم أن تكوّن الرغوة قد يبدو ميزة مهمة للتنظيف، فإن هذا الاعتقاد غير صحيح في الواقع. لذلك ننصحكِ، عند مقارنة أنواع الشامبو، باختيار المنتجات الخالية من المادة الكيميائية الضارة المسماة SLS، والتي تُستخدم لتكوين الرغوة.') WHERE id = 'f8b0ec51-f351-462b-96a6-b82037c58e61';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مهما حرصتِ على رعاية طفلكِ، فقد تكون الإصابة بالأمراض أمرًا لا مفر منه أحيانًا. ولأن جهازه المناعي لم يكتمل نموه بعد، يمكن للإنفلونزا ونزلات البرد أن تؤثرا بسهولة في جسمه. ويُعد احتقان الأنف والانزعاج ورفض الطعام من أولى العلامات التي تشير إلى مرض طفلكِ. وقد يصاحب ذلك أيضًا سعال جاف وإسهال وخمول ونوبات بكاء. عندما يمرض طفلكِ، عليكِ أولًا قياس درجة حرارة جسمه، ثم تكرار ذلك على فترات منتظمة. وسيساعده الحصول على قسط كافٍ من النوم والراحة على التعافي بسرعة. وخلال هذه الفترة، لا تجبريه على تناول الطعام، وامنحي الأولوية للأطعمة الغنية بالسوائل.') WHERE id = '9ef652c0-6810-47ad-9c0e-cf7c58bc940f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتعرض طفلكِ لاحتقان الأنف بصورة متكررة، خاصة عند تغير الفصول، لأن مجاريه التنفسية لا تزال ضيقة جدًا. ويستدعي احتقان الأنف اهتمامكِ، لأنه لا يجعل التنفس صعبًا على طفلكِ فحسب، بل قد يؤثر أيضًا في نمط تغذيته ونومه. وإذا كان أنفه يُصاب بالاحتقان كثيرًا، فقد يرجع ذلك إلى تضخم اللحمية أو جفاف الهواء أو بعض حالات الحساسية. لذلك يمكنكِ استخدام جهاز لترطيب الهواء في الغرفة التي يوجد فيها طفلكِ، أو وضع أوعية ماء مقاومة للحرارة فوق أجهزة التدفئة في المنزل. ومع تبخر الماء، سترتفع رطوبة الغرفة ويقل الجفاف. ولتخفيف انزعاج طفلكِ عند احتقان أنفه، يمكنكِ استخدام محلول ملحي تشترينه من الصيدلية أو تحضرينه بنفسكِ في المنزل. فالمحلول الملحي وسيلة فعالة جدًا لتليين طبقة المخاط التي تسد أنف طفلكِ وفتح مجاريه التنفسية.') WHERE id = '9c0cb79b-68bb-4505-a06f-a92e33fff4b9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد تناول الفواكه والخضراوات الموسمية مهمًا جدًا لتزويد طفلكِ بالفيتامينات. وإلى جانب ذلك، ينبغي أن تُدرجي الأسماك بانتظام في نظامه الغذائي، فهي من أفضل مصادر البروتين وأحماض أوميغا-3 الدهنية التي يحتاج إليها الجسم. تنتشر بين الناس بعض المخاوف بشأن تناول الأطفال للأسماك، لكن الخبراء يؤكدون أن السمك لا يشكل أي خطر ما دام طازجًا. لذلك يمكنكِ اختيار أسماك البحر الطازجة لطفلكِ بدلًا من الأسماك المعلبة. ومن الأفضل في الوقت الحالي تجنب الأسماك الصغيرة والكثيرة الأشواك، تفاديًا لخطر الاختناق أو تعلق شوكة في حلقه. كذلك، قد تتراكم المعادن الثقيلة بدرجة أكبر في الأسماك التي تعيش في قاع البحر، لذا يمكنكِ تفضيل الأسماك التي تعيش بالقرب من السطح.') WHERE id = '50c822ac-6408-41dd-b9a0-333f36a25421';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ تجربين طرقًا عديدة لحماية طفلكِ من طفح الحفاض، خاصة خلال أشهر الصيف. وتُعد بودرة الأطفال من الوسائل المستخدمة لهذا الغرض. يعارض الخبراء استخدام مساحيق البودرة لأنها قد تضر برئتي الأطفال. لكن إذا كنتِ لا تزالين تستخدمين البودرة للعناية بطفلكِ، فهناك بعض النقاط التي ينبغي الانتباه إليها. على سبيل المثال، عليكِ تجنب المنتجات التي تحتوي على الألومنيوم أو العطور أو المواد الحافظة ذات التأثير المسرطن. وإذا كنتِ تقولين: «يمكنني تحضير بودرة الأطفال بنفسي»، فلدينا لكِ وصفة طبيعية تمامًا. كل ما تحتاجين إليه هو نصف كوب شاي من نشا الذرة وبضع قطرات من زيت عطري طبيعي. ضعي النشا في وعاء وأضيفي إليه قطرات الزيت. ويمكنكِ خلطهما في محضرة الطعام لمنع تكون التكتلات. ضعي الخليط الذي حضرتِه في عبوة بودرة قديمة أو في ملّاحة ذات فتحات كبيرة لا تستخدمينها. أصبحت بودرة الأطفال الطبيعية جاهزة! 😊') WHERE id = '3120d7eb-f951-4312-bcfe-96b26a90343b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يدفعكِ فقدان طفلكِ للشهية خلال هذه المرحلة إلى البحث عن وصفات لوجبات خفيفة صحية. وستشجعه هذه الأطعمة اللذيذة والمفيدة على تناول الطعام، وتمنحه الطاقة التي يحتاج إليها طوال اليوم. والآن سنقدم لكِ وصفة بسكويت سيحبها طفلكِ كثيرًا! 😊 يمكنكِ أيضًا الاطلاع على مئات الوصفات في قسم "الوصفات" لدينا! المكونات المطلوبة بسيطة جدًا: 200 غرام من دقيق القمح الكامل، و100 غرام من الزبدة، و100 غرام من السميد، وموزة كبيرة واحدة، وملعقة طعام واحدة من الزبادي. قطّعي الموزة إلى شرائح صغيرة واهرسيها جيدًا بالشوكة. اخلطي جميع المكونات واعجنيها جيدًا. غطّي العجين الذي حضرتِه واتركيه في الثلاجة ليرتاح مدة 20 دقيقة تقريبًا. بعد ذلك، شكّلي العجين بأشكال تجذب انتباه طفلكِ، واخبزيه على درجة حرارة 180 درجة مدة 15-20 دقيقة تقريبًا. بالهناء والشفاء! 😊') WHERE id = '3bed5af2-3e1c-44f1-9796-6af7f86a01fc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ، مثل جميع الأمهات، ترغبين في تربية طفلكِ بأفضل طريقة ممكنة. وأفضل وسيلة لتعليم طفلكِ أن يكون إنسانًا صالحًا هي أن تقدّمي له دائمًا نموذجًا عمليًا لكيفية تصرّف الإنسان الصالح. ولأن طفلكِ بارع في الملاحظة والتقليد، فعليكِ الانتباه أولًا إلى سلوككِ، ثم إلى سلوك الأشخاص المحيطين به. فسلوك الأشخاص الذين يراهم طفلكِ كثيرًا ويتفاعل معهم يشكّل أساس شخصيته. وبما أنه أصبح يهتم باستقلاليته ويمر بمرحلة تكوين شخصيته الفردية، فلا ينبغي لكِ تقييده أكثر من اللازم. فقد يؤدي منعه من القيام بما يرغب فيه إلى بعض ردود الفعل السلبية، مثل نوبات بكاء قصيرة أو نوبات غضب قد يؤذي خلالها نفسه أو من حوله.') WHERE id = '60a3bb7b-e6b8-4840-8b06-634744d70eda';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكون أمعاء طفلكِ معقمة حتى لحظة الولادة، ثم تطرأ عليها بعض التغيّرات تبعًا لطريقة الولادة والخصائص الوراثية ونمط التغذية والتفاعل مع البيئة. وتُسهم هذه العوامل مجتمعة في تكوين أكثر من 500 نوع تقريبًا من البكتيريا التي تساعد على الهضم في أمعاء طفلكِ، وتختلف تركيبتها من شخص إلى آخر. وقد يصل العدد الإجمالي لهذه البكتيريا شديدة التنوع إلى مليارات. ولهذا السبب تُسمى الفلورا المعوية في الطب «العضو المنسي». وتؤدي هذه البكتيريا، الموجودة بكثرة خصوصًا في القولون والأجزاء الأخيرة من الأمعاء الدقيقة، دورًا بالغ الأهمية في الحفاظ على التوازن الداخلي لجسم طفلكِ. وتعتمد الفلورا المعوية على توازن دقيق للغاية، وقد يؤدي اختلاله إلى مشكلات خطيرة في الهضم والغازات. لذلك من المهم جدًا ألا تستخدمي المضادات الحيوية التي قد تُخلّ بتوازن الفلورا المعوية دون استشارة الطبيب.') WHERE id = '2f472f69-49f6-4199-b448-65d485bc6ba1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تعتقدين أن طفلكِ يأكل قليلًا وأن وزنه منخفض بسبب ذلك، فيمكنكِ التحقق من نطاقات الوزن الآمنة المناسبة لعمره. وإذا كان وزن طفلكِ أقل من هذا النطاق الآمن، فلا يعني ذلك بالضرورة وجود مشكلة في نموه، بل قد يحتاج فقط إلى متابعة طبية أكثر انتظامًا. لكل طفل توازنه الهرموني الصحي الخاص به، لذلك لا فائدة من مقارنة طفلكِ بأقرانه المولودين في تواريخ متقاربة. ففي الشهر 14، قد يكون الطفل الذي يزن 8 كغ والطفل الذي يزن 13 كغ سليمين بالقدر نفسه. ويُعدّ كل من بنية جسمكِ وبنية جسم شريككِ، وسرعة الأيض، وطولكما من العوامل الأساسية التي تؤثر في نمو طفلكِ. فعلى سبيل المثال، قد يكون الطفل المولود لأبوين قصيري القامة أقصر من أقرانه، وقد يكون وزنه أقل بما يتناسب مع طوله. كذلك، إذا وُلد طفلكِ قبل أوانه (خديجًا)، فلا يزال أمامه ما يقارب عامين حتى يلحق بنطاقات طول ووزن أقرانه.') WHERE id = 'ee025328-9a30-44d7-887a-d226fa6d94ad';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في النمو البدني للطفل بعمر 14 شهرًا، يُتوقع أن يمشي بصورة أفضل وأن يبقى واقفًا مدة أطول مقارنة بالأشهر السابقة. وهذا يزيد ثقته بنفسه مع مرور الوقت ويشجعه على الحركة أكثر. لكن مساعدته في كل مرة يسقط فيها قد تضر بثقته بنفسه في هذه المرحلة. لذلك، ورغم أن الأمر قد يكون صعبًا عليكِ، ينبغي أن تتعلمي عدم التدخل ما لم تكن هناك حاجة لذلك. وعندما يسقط طفلكِ، اقتربي منه من دون إظهار أي رد فعل سلبي، وقولي له بدلًا من ذلك كلمات تشجعه على النهوض والحركة مجددًا. وعوضًا عن الغضب منه أو النظر إليه بتعبير حزين، يمكنكِ أن تخبريه أن كل شيء بخير وأنه قادر على فعل ذلك. وحين ينجح طفلكِ في النهوض بنفسه، يكون قد بدأ في بناء الأساس الذي سيساعده على التعامل بفاعلية مع الصعوبات طوال حياته مستقبلًا.') WHERE id = '414824fb-64c6-4b3c-bb3a-769c24ddf66c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما اكتسب طفلكِ الآن مهارات جديدة، مثل الإمساك بشيء أو لعبة تُرمى إليه ودحرجتها. وهذه نتيجة تطور التناسق بين اليد والعين، وقد يستغرق اكتماله بعض الوقت. ويمكنكِ لعب ألعاب ممتعة جدًا معه لتنمية هذا التناسق. على سبيل المثال، أحضري كرة متوسطة الحجم بلون يحبه طفلكِ، واجلسي في مواجهته. اجذبي انتباهه إلى الكرة ثم دحرجيها نحوه. وحتى إن أمسك بها، فقد لا يتمكن بعد من دحرجتها إليكِ مجددًا؛ إذ قد يمسكها ويتفحصها لبعض الوقت. ويمكنكِ تشجيعه على إعادتها إليكِ. وقد تصبح هذه اللعبة خلال وقت قصير النشاط المفضل لدى طفلكِ. استمتعا بوقتكما! 😊') WHERE id = '6f46b0f1-1f3e-4425-a5dd-6eff8b819a96';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يقوم طفلكِ بسلوك ترغبين فيه، يجب ألا تكون المكافأة التي تقدمينها له طعامًا مضرًا بالصحة مطلقًا. فما زالت رقائق الويفر والشوكولاتة ورقائق البطاطس والحلوى ضمن قائمة الأطعمة التي ينبغي لطفلكِ الابتعاد عنها. ويعود ذلك إلى المواد الكيميائية الموجودة في هذه المنتجات المعبأة. فعلى سبيل المثال، قد تؤدي جميع المُحلّيات، وفي مقدمتها الأسبارتام، إلى السمنة وغيرها من المشكلات الصحية مستقبلًا. كما قد تسبب النكهات والألوان الاصطناعية تشتت الانتباه وفرط النشاط لدى الأطفال. ولأن هذه المواد قد تُحدث أيضًا تأثيرًا سامًا في جسم طفلكِ، فقد تزيد احتمالية تضرر كبده. لذلك، بدلًا من إعطاء طفلكِ أطعمة جاهزة ضارة تحت مسمى «المكافأة»، يمكنكِ تقديم بدائل تسعده ولا تضر بصحته.') WHERE id = 'aa4f705b-b1bf-4a27-a480-8e278fc3f58d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ منزعجًا جدًا خلال هذه الفترة واضطرب نومه ليلًا، فقد يكون السبب الرئيسي هو بدء ظهور أضراسه. عادةً ما يكتمل ظهور الأضراس بحلول الشهر 20، لكن من الطبيعي أيضًا أن تبدأ علاماتها في الظهور خلال هذه الأشهر. فبينما تُستخدم الأسنان الأمامية والأنياب لتقطيع الطعام، تؤدي الأضراس دورًا بالغ الأهمية في تناول الطعام. وتساعد أسطحها المسطحة والعريضة على طحن الطعام بسهولة أكبر. كما تتحمل الأضراس الجزء الأكبر من عملية المضغ بفضل أسطحها البارزة والمتعرجة وحجمها الكبير. ولتهدئة طفلكِ خلال هذه الفترة، يمكنكِ تقديم أطعمة باردة وصلبة يستطيع الإمساك بها بيده، مثل الخيار أو الجزر البارد.') WHERE id = '64b96eb8-8284-4d84-b6bb-5e9a619fbb8e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، قد يتغير نظام نوم طفلكِ وفقًا لمقدار نشاطه البدني خلال اليوم وانتظام مواعيد وجباته. وفي المتوسط، لا يزال طفلكِ بحاجة إلى النوم مدة 13-14 ساعة، قد تتوزع على 11-12 ساعة ليلًا و1-2 ساعة نهارًا. وخلال هذه الفترة، قد ينتقل طفلكِ من قيلولتين نهاريتين إلى قيلولة واحدة. لذا عليكِ مراقبته ومساعدته على هذا الانتقال عندما يصبح مستعدًا. تساعد القيلولة النهارية على استعادة طاقته لبقية اليوم. ولدعم هذا التطور، يمكنكِ تحديد موعد قيلولته بعد نحو 6-7 ساعات من استيقاظه صباحًا. وهكذا، سيتمكن طفلكِ من التخلص من التعب مع الحفاظ على جودة نومه ليلًا.') WHERE id = '7e899c41-bf02-4b4f-af49-2790f64d5c5f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي جدًا أن تتوقعي أن يتناول طفلكِ البالغ من العمر 14 شهرًا كمية أكبر من الطعام مقارنةً بالفترة الأولى التي بدأتما فيها إدخال الأطعمة التكميلية. لكن تذكّري أن معدته لا تزال صغيرة. لذلك، بدلًا من تقديم حصص كبيرة، يُفضّل أن يتناول كمية كافية من الطعام على 6 وجبات يوميًا، تشمل 3 وجبات رئيسية و3 وجبات خفيفة. يساعد هذا النظام طفلكِ على البقاء نشيطًا طوال اليوم ويقيه من عسر الهضم. ولا يزال طفلكِ في طور تكوين عاداته الغذائية. وقد يؤدي إجباره على تناول الطعام إلى بعض المشكلات؛ فالضغط عليه يُعد من أكثر أسباب رفض الطعام شيوعًا. ففي هذه المرحلة التي تتشكل فيها استقلاليته، يرغب طفلكِ في أن يقرر بنفسه ما سيأكله والكمية التي سيتناولها. لذلك، من المهم جدًا أن تحاولي وضع نظام غذائي خلال هذه الفترة من دون إجباره بشدة أو الدخول في صراع معه.') WHERE id = 'afc54856-70b8-4f36-b450-98aa1aca2b83';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبذل طفلكِ منذ لحظة ولادته الأولى جهدًا كبيرًا للتواصل معكِ. وفي البداية، لم يكن يستطيع فعل ذلك إلا بالبكاء. وعندما بلغ عمره 2-3 أشهر، بدأ أيضًا بالصراخ وإصدار أصوات متحركة. ثم حاول خلال فترة قصيرة التواصل باستخدام بعض التعبيرات غير اللفظية. أما الآن، فقد وصل طفلكِ بفضل تطوره العقلي ومهاراته اللغوية إلى مستوى يمكّنه من التواصل معكِ ومع محيطه بفاعلية أكبر. ومع تطور حصيلته اللغوية، أصبح قادرًا على التعبير لكِ عما يزعجه وإخباركِ بما يريده، ولو بطريقة بسيطة. وعلى الرغم من أن طفلكِ يمر بمرحلة تكوين استقلاليته، فإن هذا التواصل مهم جدًا لتطوره الاجتماعي. لذلك، يمكنكِ أن تغني له أغاني الأطفال باستمرار وتعرضي عليه كتبًا ممتعة لدعم مهاراته اللغوية وتطوره الاجتماعي معًا. وتحويل ذلك إلى روتين قبل النوم سيساعد طفلكِ على فهم الاستعداد للنوم بصورة أفضل، كما سيسهم في إثراء حصيلته اللغوية.') WHERE id = 'c526273a-8e7f-42a9-8d2b-ea1bf33fb5e7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيدخل طفلكِ خلال هذه الأسابيع مرحلة طفرة نمائية جديدة. وخلال هذه الطفرة، سيكتسب مهارات عقلية وفسيولوجية جديدة تمامًا. وبعد اكتمال هذه المرحلة، سيرغب طفلكِ في اكتشاف ما يمكنه فعله باستخدام جسمه. وقد يشمل ذلك التسلق إلى مكان مرتفع، والركض، وصعود الدرج ونزوله، والاختباء وانتظاركِ حتى تجديه... 😊 كما سيكتسب مهارات عقلية جديدة، مثل القيام بتصرفات لطيفة، وحماية ألعابه بغيرة، واتخاذ قرارات واعية، والاختيار، وفهم مفهومي نعم ولا بصورة كاملة. وستُضاف إلى ذلك مهارات جسدية، مثل الإمساك بالقلم والملعقة بطريقة صحيحة، وتقليدكِ أثناء قيامكِ بالأعمال المنزلية، وتكديس الأشياء فوق بعضها ثم هدمها. وقد يُظهر أيضًا خلال هذه الفترة العناد للحصول على ما يريده. ويمكنكِ ملاحظة ذلك بوضوح عندما يهرب أثناء تغيير حفاضه أو يبكي حين لا يرغب في النوم.') WHERE id = '6e4bf078-f30a-41d3-b0f1-e67a9a9faed1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن اكتساب طفلكِ عادات غذائية صحية خلال هذه الأشهر مهم جدًا لصحته في المستقبل. وقد أظهرت الدراسات، لا سيما في البلدان المتقدمة والنامية، أن طفلًا واحدًا من كل 10 أطفال تتراوح أعمارهم بين 5-17 عامًا يعاني من زيادة الوزن أو السمنة. لذلك، عليكِ بذل جهد كبير لمساعدة طفلكِ على اكتساب عادات غذائية صحية في المستقبل وحمايته من السمنة، التي تُعد من أمراض عصرنا. أولًا، تذكّري أن طفلكِ سيقتدي بكِ في التغذية كما يقتدي بكِ في مختلف جوانب الحياة. ولكي تساعداه على اكتساب عادات غذائية صحية، ينبغي لكِ ولشريككِ، بصفتكما والديه، أن تكونا قدوة حسنة ومرشدين مناسبين له. وعليكما ألا تنسيا أن الأسرة هي القدوة الأساسية للطفل، وأنه سيقلد ما يراه منكما. لذلك، من المهم جدًا ألا تتناولي أنتِ أيضًا طعامًا تمنعين طفلكِ من تناوله أو تحظرينه عليه.') WHERE id = 'f7d2bdee-d2ae-49c1-a04e-221370278e9e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لتنمية قدرة طفلكِ على الكلام، يمكنكِ التحدث معه خلال اليوم عما تفعلانه معًا. ومن الخطوات المهمة جدًا لتحقيق تواصل فعّال أن تناديه باسمه باستمرار أثناء الحديث، وأن تشجعيه على النظر إلى وجهكِ عندما يحاول التعبير عن نفسه. قد لا يستوعب طفلكِ التواصل البصري خلال التفاعل لبعض الوقت. وفي هذه المرحلة، عليكِ التحلي بالصبر حتى يبدأ في توجيه انتباهه إليكِ. فمدة تركيزه خلال هذه الفترة قصيرة جدًا، لذا قد يكون من المفيد ألا تستعجليه وأن تمنحيه الوقت الكافي. ومع ذلك، من المهم أن تواصلي المحاولة والتواصل معه وجهًا لوجه بشكل متكرر ومعتدل، من دون الضغط عليه. ويمكنكِ أيضًا الاستعانة بدمى الأصابع أو ألعابه المفضلة لجذب انتباهه.') WHERE id = '3ce788c0-f070-45ad-81cb-f88068c7f73a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تؤثر البروبيوتيك التي يحصل عليها طفلكِ من الأطعمة أو المكملات الغذائية إيجابيًا في صحة جهازه الهضمي. فهي تساعد على تنظيم الغشاء المخاطي للأمعاء والمناعة الجهازية، والحفاظ على التوازن الغذائي والميكروبي. وتشمل الكائنات الحية الدقيقة المعتمدة طبيًا كبروبيوتيك: البكتيريا المشقوقة، والعصيات اللبنية، وبعض أنواع الخمائر. ومن أبرز خصائص هذه الكائنات المساعدة على وقاية الأمعاء من الضرر وحمايتها من أحماض المعدة والعصارة الصفراوية. وأفضل طريقة ليحصل طفلكِ على البروبيوتيك بصورة مناسبة هي من خلال الأطعمة التي يتناولها بانتظام. لذلك يمكنكِ تقديم أطعمة مثل الزبادي والكفير والحليب له خلال اليوم. وإذا كنتِ تحضّرين الزبادي لطفلكِ في المنزل، فيمكنكِ أيضًا إضافة أحد مساحيق البروبيوتيك المتوفرة في الأسواق والمخصصة للأطفال أثناء تحضيره.') WHERE id = '4288b6eb-8c29-4319-9748-ef1056bfa3a6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين في هذه المرحلة أن مدة قيلولة طفلكِ نهارًا قد أصبحت أقصر. فبعد أن كان ينام نهارًا لمدة 1.5-2 ساعة حتى قبل 1-2 شهر، قد يستيقظ الآن بعد ساعة واحدة من النوم. ويرجع ذلك ببساطة إلى تغيّر احتياجاته إلى النوم مع نموه. ويمكنكِ معرفة مقدار النوم الذي يحتاج إليه من خلال ملاحظة حالته خلال الفترة بين القيلولتين. فإذا لم يبدُ متعبًا وكان سعيدًا عمومًا، فهذا يعني أن طفلكِ قد بدأ مرحلة الاكتفاء بقيلولة واحدة يوميًا. وقد يوصي بعض المختصين في هذه المرحلة بقيلولتين مدة كل منهما 45 دقيقة بدلًا من قيلولة واحدة تدوم نحو 1.5 ساعة. والأفضل أن تستشيري الطبيب الذي يتابع نمو طفلكِ بشأن هذا الأمر.') WHERE id = '6ba44648-3933-4291-9703-f585d3124ad2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الإفطار من أهم الوجبات التي تساعد طفلكِ على بدء يومه بصحة ونشاط. وإذا كان طفلكِ ضعيف الشهية تحديدًا، فقد تكون مهمتكِ أصعب قليلًا مقارنة بالأمهات الأخريات. يحب الأطفال الأطباق المرحة كثيرًا، لذا يمكنكِ إعداد أطباق ملونة وجذابة بأشكال ممتعة له. فمثلًا، يمكنكِ تشكيل رأس بالعجة التي أعددتِها، وعينين بحبات الزيتون، وفم مبتسم بالجبن! كما يمكنكِ تقديم حليب الصباح في كوب يحمل صورة شخصيته المفضلة بدلًا من كوب عادي. ستجذب الأطباق المرحة والمناديل الملونة والملاعق والشوك المخصصة للأطفال انتباه طفلكِ وتشجعه على تناول الطعام! 😊 وبهذه الطريقة ستجدين حلًا فعّالًا يساعد طفلكِ على حب وجبة الإفطار. بالهناء والشفاء! 😊') WHERE id = '100e3bf4-7099-4e07-b464-4e8f9fc75448';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم يبدأ طفلكِ المشي بعد، فمن الطبيعي تمامًا أن تشعري ببعض القلق. لكن تذكّري أن الطفل السليم يبدأ المشي عادةً بين عمر 12 و18 شهرًا. وهذا يعني أنه لا يزال أمام طفلكِ نحو 4 أشهر ليخطو خطوته الأولى. ومع ذلك، قد يبدأ بعض الأطفال المشي قبل بلوغ الشهر 12. وخلافًا للاعتقاد الشائع، لا توجد أي علاقة بين توقيت بدء الطفل بالمشي ومستوى ذكائه. فتوقيت المشي لا يعتمد على التطور الذهني، بل يختلف بحسب تطور المهارات الحركية الكبرى. ومن المعروف أن الوزن الزائد خصوصًا قد يؤخر تطور مهارات حركية كبرى لدى الأطفال، مثل التقلب والحبو والمشي. إذا كان عدم مشي طفلكِ حتى الآن يثير قلقكِ، فمن الأفضل متابعة مراحل نموه الأخرى واستشارة طبيبه. وإذا كانت نتائج الفحوصات طبيعية، فيمكنكِ الانتظار 4 أشهر أخرى من دون قلق.') WHERE id = '5d51cb37-4895-49ef-9653-5387c0bc8578';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد الفيتامينات والمعادن التي يحصل عليها طفلكِ من الغذاء ضرورية جدًا لنموه الذهني والجسدي السليم. لكن المعادن الموجودة في الجسم تحتاج إلى عنصر منظّم يساعدها على الحفاظ على التوازن الداخلي المعروف باسم الاستتباب. وهذا المعدن المهم الذي يساعد على الحفاظ على توازن الماء وجميع المعادن في الجسم هو البوتاسيوم. يُعد البوتاسيوم ثامن أكثر العناصر وفرة في جسم الإنسان. فعلى سبيل المثال، يحتوي جسم شخص بالغ يبلغ وزنه نحو 60 كغ على 120 غرامًا فقط من البوتاسيوم. ويدخل هذا المعدن في تركيب العديد من البروتينات والإنزيمات في الجسم. كما تشمل وظائفه الأخرى دعم وظائف العضلات والحفاظ على ضغط دم طبيعي. ولذلك، من المهم جدًا إضافة الأطعمة الغنية بالبوتاسيوم إلى النظام الغذائي لطفلكِ. وتشمل هذه الأطعمة البطاطس وأنواع السمك والجزر والسبانخ والمشمش والتمر والموز، إضافة إلى البقوليات مثل الفاصولياء والعدس.') WHERE id = 'b49d44ad-509b-45da-b50c-13a1e54a66ac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، أصبح طفلكِ بارعًا في استخدام تعابير الوجه. وغالبًا ما تظهر أكثر تعابيره استخدامًا عندما يشعر بالفضول أو يركّز انتباهه. تذكّري أن طفلكِ لا يزال في مرحلة التجربة والخطأ والاستكشاف. فعندما يكتشف شيئًا جديدًا، أو يرى غرضًا يلفت انتباهه، أو لعبة لم يرها منذ مدة، يفتح عينيه على اتساعهما. ويحدّق في ذلك الغرض باهتمام من دون أن يرمش، وغالبًا ما يبقى فمه مفتوحًا أيضًا. ولأنه يرغب في التوجه بكامل جسده نحو الشيء الذي أثار فضوله، فقد يُظهر ردود فعل مثل التصفيق والحماس. وقد يؤدي تقييد طفلكِ في هذه اللحظة إلى ردود فعل شديدة، أو نوبة بكاء، أو حتى سلوك عدواني. لذلك، لا تمنعيه ما دام لن يؤذي نفسه، أما إذا كان الموقف قد يشكّل خطرًا، فأبعدي ذلك الغرض تمامًا عن متناوله.') WHERE id = '0ce5b94c-09e6-4a0f-95d7-434109b1665a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يساعد تقوية جهاز طفلكِ المناعي على زيادة مقاومته للعدوى الناجمة عن العوامل الداخلية والخارجية. لذلك، يُعد حصوله يوميًا على كمية كافية من البروتين أمرًا بالغ الأهمية للحفاظ على قوة جهازه المناعي. وقد يؤدي عدم تلبية احتياجاته اليومية من البروتين إلى نقص الأحماض الأمينية في جسمه وفقدان الشهية. وفي هذه المرحلة تحديدًا، التي يستخدم فيها طفلكِ مهاراته الحركية الكبرى بنشاط، يحتاج يوميًا إلى نحو 1200-1300 سعرة حرارية من الطاقة، وإلى 13 غرامًا من البروتين في المتوسط. يتكوّن البروتين من اتحاد 20 حمضًا أمينيًا مختلفًا. وعلى الرغم من أن جسم الإنسان يستطيع إنتاج 11 منها، فإنه يجب الحصول على الأحماض الـ9 المتبقية من الطعام. ويُعد البيض والحليب ومنتجات الألبان والأسماك والدجاج واللحوم الحمراء الخالية من الدهون من أغنى مصادر البروتين. لذلك، احرصي على أن يتناول طفلكِ البيض ومنتجات الألبان يوميًا في وجبة الإفطار، والأطعمة الحيوانية التي تُعد مصادر للبروتين الكامل في وجبتي الغداء والعشاء.') WHERE id = '32913ce6-24a8-4d25-9cc1-6c3c071090db';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يواصل طفلكِ، الذي يكبر يومًا بعد يوم، إدهاشكِ باكتساب مهارات جديدة كل يوم ضمن مسيرة نموه. ففي هذه المرحلة يبدأ بالوقوف بمفرده والزحف والمشي. وقد تؤدي هذه المهارات المكتسبة حديثًا إلى تراجعات مؤقتة في النوم نتيجة التغير في استهلاك الطاقة. ويتمثل دوركِ هنا في مراقبة احتياجات طفلكِ جيدًا ومنحه الوقت الكافي للتكيّف. خلال هذه الأشهر، يستطيع الأطفال البقاء مستيقظين مدة تتراوح بين 4-5 ساعات تقريبًا. وترجع زيادة مدة اليقظة إلى أن الطفل لم يعد يحتاج إلى هرمون النمو الذي يُفرز أثناء النوم بالقدر نفسه الذي كان يحتاج إليه سابقًا. وعند إعادة تنظيم روتين نوم طفلكِ خلال هذه المرحلة الانتقالية، تذكّري أن الإشارات التي يُظهرها هي العامل الأهم.') WHERE id = '2406fe8c-a932-4659-944e-d34a90335aef';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد السنوات الـ3 الأولى، أي فترة 36 شهرًا، مرحلة شديدة الحساسية في تطور الجهاز العصبي لدى طفلكِ. لذلك، فإن الأطعمة التي يتناولها خلال هذه الفترة بالغة الأهمية لنموه وتطوره بصورة صحية. ويتفق المختصون على أهمية تغذية الأطفال بأطعمة عضوية بالكامل خلال السنوات الـ3 الأولى. والأطعمة العضوية هي مجموعة من الأغذية التي لا تحتوي على أي مواد ضارة منذ زراعتها في الحقل أو البستان وحتى وصولها إلى طفلكِ. وفي السنوات الأخيرة، ارتبطت أمراض خطيرة مثل السرطان والاضطرابات الهرمونية وفرط النشاط والتوحد وأورام الدماغ، التي أصبحت من آفات عصرنا، إلى حد كبير بالتغذية غير الصحية. كما قد تؤدي التغذية غير الصحية إلى مشكلات مثل البلوغ المبكر والسمنة ونقص الانتباه خلال سنوات الدراسة. لذلك، يُنصح عند التسوق لطفلكِ باختيار المنتجات الطبيعية وتلك التي تحمل ملصقًا يفيد بأنها عضوية.') WHERE id = '87ccab00-63bc-4286-b706-8a9dd745c897';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا بد أنكِ لاحظتِ كيف يحاول طفلكِ شرح موقف ما أو التعبير عن شكوى لكِ. تتطور المهارات الحركية والقدرة على فهم اللغة لدى الأطفال أسرع من قدرتهم على الكلام. لذلك، يبدأون باستخدام بعض الإشارات للتعبير عن رغباتهم، أي إن البكاء لم يعد وسيلة طفلكِ الوحيدة لتلبية احتياجاته. فعلى سبيل المثال، قد يشير طفلكِ في هذه المرحلة إلى المطبخ عندما يشعر بالجوع، أو يمد إصبعه نحو زجاجة الماء إذا كانت قريبة منه. ومن المهم جدًا أن تحاولي فهم رغباته هذه، لكن عليكِ ألا تستجيبي لها فورًا ومن دون كلام. ولمساعدته على تطوير قدرته على الكلام، يمكنكِ محاولة التعبير بالكلمات عن الإشارات التي يستخدمها. فعلى سبيل المثال، عندما يشير إلى لعبة بعيدة، بدلًا من إعطائه إياها فورًا وإنهاء الأمر، سيكون من المفيد أن تتواصلي معه بقولكِ: «هل تريد لعبتك؟»، «أي لعبة تريد؟»، «هل تريد الدب الأحمر؟».') WHERE id = 'ab91ed36-9244-4c5f-8311-b066e05594f7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد اليود أحد المعادن المهمة جدًا لجسم طفلكِ كي ينمو ويصبح بصحة جيدة. وهو معدن أساسي يُستخدم في إنتاج الهرمونات التي تفرزها الغدة الدرقية. وتنظّم الغدة الدرقية عمليات الأيض لدى طفلكِ، كما تؤثر مباشرة في نموه العقلي والجسدي بأكمله، بما في ذلك النوم والشهية والحالة النفسية. وإذا لم يحصل الجسم على كمية كافية من اليود عبر الغذاء، فقد يحدث تأخر في النمو والتطور، ومشكلات في القدرات الذهنية، وتضخم في الغدة الدرقية يؤدي إلى الإصابة بالدُّراق وظهور العُقيدات. ويعاني عدد كبير جدًا من الأطفال حول العالم من نقص اليود، كما تُعد منطقتنا من المناطق المعرّضة لخطر هذا النقص. لذلك، من المهم جدًا أن تعرفي احتياجات طفلكِ اليومية من اليود. وفي هذه المرحلة، تبلغ حاجته اليومية منه نحو 80-120 ميكروغرامًا. وتعادل هذه الكمية وعاءين من الزبادي وسمكة بحرية واحدة متوسطة الحجم. وإذا كان طفلكِ لا يتناول كمية كافية من هذه الأطعمة، فيمكنكِ استخدام الملح الطبيعي المعالج باليود عند إعداد وجباته، على ألا تتجاوز الكمية نصف ملعقة صغيرة.') WHERE id = '522a3fe5-04bf-4e2d-9c55-d18ab04d51f1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'منذ لحظة ولادة طفلكِ، تبدأ ذاكرته بتسجيل جميع المحفزات الموجودة في محيطه، مثل الأصوات والروائح والألوان واللمسات. وتبدأ مليارات الخلايا العصبية في جهازه العصبي بالتواصل مع بعضها بعضًا لتسجيل هذه المؤثرات الخارجية. وخلال هذه المرحلة، التي تُسمى عملية التعلم، توضع أسس الوظائف الذهنية وإمكانات الدماغ التي سيستخدمها طفلكِ طوال حياته. ومن هذا المنطلق، فإن تعرضه للعديد من المحفزات المختلفة واكتشافه أشياء جديدة، بل وحتى سماعه كلمة للمرة الأولى، له أهمية كبيرة. ويمكنكِ دعم هذا التطور من خلال قراءة الكتب لطفلكِ باستمرار، وشرح ما تفعلينه له أثناء قيامكِ بمهامكِ اليومية، وإتاحة الفرصة له لاكتشاف أشياء جديدة. فعلى سبيل المثال، يمكنكما قبل موعد النوم بنصف ساعة تصفح كتب ممتعة مخصصة للأطفال، ويمكنكِ أن تقرئيها له مستعينة بتعابير وجهكِ. وبهذه الطريقة ستقضيان وقتًا ممتعًا للغاية، كما ستساهمين في تنمية ذاكرته البصرية ودعم تطور خياله وإبداعه وحصيلته اللغوية مستقبلًا.') WHERE id = '194ef97e-d059-421e-9e85-a3e5c700d2ed';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لم يعد طفلكِ يكتفي بالمشي فحسب، بل قد يحاول أيضًا الرجوع إلى الخلف والركض. ولكن إذا لم يبدأ طفلكِ بالمشي بعد، فمن الطبيعي أن تشعري بالقلق حيال ذلك. وقد تكون مقارنته بأقرانه وضغوط المحيطين بكِ وأسئلتهم مزعجة، حتى لو كنتِ تعتقدين أنه لا يعاني أي مشكلة. فبعض الأطفال لا يحاولون المشي حتى يشعروا بأنهم مستعدون تمامًا، بينما يحاول آخرون المشي في وقت أبكر، حتى لو كانوا يتعثرون ويسقطون. وإذا سبق لطفلكِ أن سقط أو شعر بالألم أثناء محاولته اتخاذ خطواته الأولى، فمن الطبيعي تمامًا أن يخاف من المشي لبعض الوقت. كما أن إتقانه للحبو قد يجعله لا يبذل جهدًا لتعلم المشي. ومع أخذ كل ذلك في الاعتبار، نود تذكيركِ بألا تضغطي على طفلكِ أكثر من اللازم كي يمشي، فما زال أمامكما وقت حتى بلوغه الشهر 18. 😊') WHERE id = 'fc2610d2-34cd-4a60-8b6c-84a8797e54a6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه الفترة أن طفلكِ يميل إلى عضكِ أو عض المقربين منه. والعض لدى الأطفال عادة مؤقتة تبدأ غالبًا خلال فترة التسنين وقد تستمر حتى عمر 3 سنوات تقريبًا. في البداية، قد يظن طفلكِ أن العض نوع من اللعب، لكنه قد يحوله بعد فترة إلى سلوك يعبر به عن رد فعله. وقد يزداد الميل إلى العض لدى الأطفال الذين يتعرضون للمنع المتكرر جدًا أو يفرض عليهم والداهم قواعد صارمة. إذا واجهتِ هذا الموقف، فعليكِ أولًا الحفاظ على هدوئكِ وتجنب ردود الفعل الحادة. وعلى عكس الاعتقاد الشائع، ليس من الصواب إطلاقًا أن تعضي طفلكِ بهدف منعه من العض. حاولي فهم المشكلة التي تدفعه إلى هذا التصرف. وعندما يحاول العض، قد يفيدكِ أن تقولي له «لا» بوضوح ومن دون رفع صوتكِ، ثم تحولي انتباهه إلى شيء آخر يثير اهتمامه.') WHERE id = '32da4abc-32c4-45a0-9bb4-5ecb9adc28f3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح بإمكان طفلكِ الآن تناول جميع أنواع الفواكه والخضراوات والبقوليات تقريبًا. لكن تذكري أن جهازه الهضمي لم يكتمل نموه بعد مقارنة بجهازكِ الهضمي. لذلك، ضعي في اعتباركِ أن جسمه قد يستمر في إبداء رد فعل تجاه حليب البقر وبعض الفواكه المسببة للحساسية. فقد يسبب حليب البقر خصوصًا لبعض الأطفال مشكلات مثل الغازات المفرطة وألم البطن والقيء. وحساسية حليب البقر هي استجابة غير طبيعية من جسم الطفل للبروتينات الموجودة في الحليب. لذلك يرى بعض الخبراء أهمية عدم تقديم حليب البقر قبل عمر سنتين. كذلك قد تظل فواكه مثل الفراولة واليوسفي والبرتقال، التي ينصح الخبراء بعدم تقديمها قبل عمر سنة لأنها قد تسبب الحساسية، مؤدية إلى بعض التفاعلات التحسسية لدى طفلكِ. لذا، حتى إذا قدمتِ له أطعمة يُذكر أنها مناسبة لمرحلة نموه، فعليكِ اتباع قاعدة الأيام الثلاثة عند تقديم أي طعام يتذوقه للمرة الأولى. وبهذه الطريقة سيكون من الأسهل عليكِ معرفة الأطعمة التي تسبب الحساسية لطفلكِ.') WHERE id = 'd1d27c7e-e74b-46d9-99df-1056732e6f26';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'طفلكِ كائن حي ينمو ويتطور باستمرار من الناحية الفسيولوجية. وتُعد العوامل البيئية بالغة الأهمية لطفلكِ الذي لا يزال في مرحلة شديدة الحساسية من النمو والتطور. ففي هذه المرحلة، قد تتأثر منظومتاه الهرمونية والعصبية الحساستان للغاية تأثرًا بالغًا ببعض المواد الكيميائية. فعلى سبيل المثال، يمكن أن تضر المبيدات المستخدمة في الزراعة لزيادة الإنتاجية وحماية المحاصيل من الآفات بالإنسان والطبيعة. ووفقًا لأبحاث منظمة الصحة العالمية، يتعرض ملايين الأشخاص كل عام للتسمم بالمبيدات الزراعية. كما أصبح من المعروف أن مادة BPA (بيسفينول A) الموجودة في العبوات البلاستيكية قد تسبب نقص الانتباه لدى الأطفال. لذلك، من المهم جدًا أن تتأكدي من أن المنتجات البلاستيكية التي تستخدمينها لطفلكِ خالية تمامًا من BPA.') WHERE id = 'd3a7bf68-2545-4f73-9f08-c29856b1742b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تبدأ دورتكِ الشهرية حتى هذه المرحلة، فمن الطبيعي تمامًا أن تشعري بالقلق. لكن تبعًا للتوازن الهرموني في جسمكِ، يُعد غياب الدورة الشهرية خلال أول 24 شهرًا بعد الولادة أمرًا طبيعيًا. وقد تظل دورتكِ غير منتظمة وتتغير كمية النزف لمدة تقارب 12 شهرًا بعد عودتها. وبوجه عام، تعود الدورة الشهرية لدى الأمهات المرضعات في وقت متأخر مقارنة بالنساء غير المرضعات، لكن لا ينبغي اعتبار ذلك المعيار الوحيد. فخلال فترة الرضاعة الطبيعية، يؤخر هرمونا البرولاكتين والأوكسيتوسين، اللذان يرتبط إفرازهما بمنطقة تحت المهاد في الدماغ، عملية الإباضة. وبدءًا من هذا الشهر، قد تعود دورتكِ الشهرية مع انخفاض مستويات الهرمونات نسبيًا، إذ أصبح نصف احتياجات طفلكِ الغذائية يُلبّى من الأطعمة الصلبة. لكن إذا لم تعد دورتكِ الشهرية خلال 3 أشهر بعد انتهاء فترة الرضاعة الطبيعية، فمن المفيد استشارة طبيبتكِ النسائية.') WHERE id = '7d00f7d8-ae72-4092-bee7-fb933ce52595';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما وُلد طفلكِ بوزن أقل من المتوسط. لكنه في هذه المرحلة يكون قد لحق بأقرانه من حيث النمو. والسبب هو أن الأطفال الذين يولدون بوزن منخفض ينمون لفترة بسرعة تفوق سرعة نمو أقرانهم بنحو 10 أضعاف. تُعرف هذه المرحلة في الطب باسم catch up growth، أي النمو التعويضي. إذا وُلد طفلكِ بوزن منخفض ويبدو لكِ نحيفًا حاليًا، فلم يعد السبب هو صغر حجمه عند الولادة. ففي هذه المرحلة، قد تؤدي كثرة حركته ورفضه الطعام بسبب تطور شعوره بالاستقلالية إلى اكتسابه وزنًا أقل. بالإضافة إلى ذلك، تُعد العوامل الوراثية من أهم العوامل المؤثرة في نمو طفلكِ وتطوره. كما يُعد معدل الأيض الأساسي، المرتبط بالجنس والتوازن الهرموني، من العوامل المهمة التي تؤثر في نموه.') WHERE id = '59294465-e7c2-4591-9517-a393a10bf2cb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الأسنان اللبنية الموجودة في فم طفلكِ هي أول أسنان تظهر له في حياته. وقد بدأت براعم هذه الأسنان بالتكوّن داخل اللثة منذ الأسابيع الأولى التي علمتِ فيها بحملكِ. ويرجع سبب رقتها وحساسيتها الشديدة إلى أنها تهيئ المكان لظهور الأسنان الدائمة. وحتى ظهور الأسنان الدائمة، تسهم الأسنان اللبنية بدرجة كبيرة في قدرة طفلكِ على إصدار الأصوات وتناول الطعام. في هذه المرحلة، ربما تكون القاطعتان العلوية والسفلية قد ظهرتا بالكامل لدى طفلكِ. وقد تبدأ القواطع الجانبية بالظهور أيضًا. وخلال فترة قصيرة، ستبدأ أضراسه بالظهور، السفلية أولًا ثم العلوية. ومع ظهور الأنياب العلوية والسفلية، ثم الأضراس الخلفية أخيرًا، يكتمل ظهور الأسنان اللبنية التي يبلغ عددها الإجمالي 20 سنًا.') WHERE id = '1aed127a-2b52-4500-bf43-b5b0cd18c968';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحتل الأطعمة ذات الأصل الحيواني مكانة مهمة في تلبية احتياجات طفلكِ اليومية من البروتين. لكن بعض الأطفال قد لا يرغبون من وقت إلى آخر في تناول اللحوم أو منتجات الألبان. في هذه الحالة، عليكِ التعرّف إلى البدائل التي يمكنها تلبية احتياجات طفلكِ من البروتين. ما دمتِ تضعين له نظامًا غذائيًا مدروسًا ومتوازنًا، فمن الممكن تلبية كامل احتياجاته من البروتين من المصادر النباتية. فمثلًا، تحتوي بيضة واحدة يتناولها طفلكِ في وجبة الإفطار على نحو 6 غرامات من البروتين. ويحتوي نصف كوب من العدس المطبوخ على 9 غرامات، بينما يحتوي نصف كوب من الفاصولياء المجففة المطبوخة على 7-8 غرامات من البروتين. كذلك، إذا كان طفلكِ يعاني حساسية الغلوتين، فإن 100 غرام من الحنطة السوداء الخالية من الغلوتين تحتوي على نحو 3-4 غرامات من البروتين. وعندما تقدمين البقوليات مع الأرز، سيتمكن طفلكِ من الحصول على كامل احتياجاته اليومية من البروتين.') WHERE id = '499bb82a-5ed3-4d97-8a0a-6e47403d4ebc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا بد أنكِ كثيرًا ما سمعتِ من طبيبكِ وصديقاتكِ ذوات الخبرة، وحتى من المحيطين بكِ، حديثًا عن التغذية العضوية. لكن هل تدركين بما يكفي مكانة المنتجات العضوية وأهميتها في النظام الغذائي لطفلكِ؟ المنتجات العضوية هي منتجات تبدأ زراعتها ببذور طبيعية غير معدلة وراثيًا، ثم تمر بعمليات طبيعية تمامًا من دون التعرّض لأي مواد كيميائية حتى تصل إلى طفلكِ في صورتها النهائية. أي إن المنتجات التي تنمو، بعد الزراعة والري، اعتمادًا على قوة الطبيعة وحدها ووفقًا للظروف الموسمية تُسمى منتجات عضوية. وفي السنوات الأخيرة، أدى ازدياد الوعي بأن الأغذية التي خضعت لتدخلات صناعية قد تكون مصدرًا لتزايد الأمراض إلى انتشار العديد من المنتجات العضوية في الأسواق. لكن بسبب بعض ممارسات البيع والإعلان المضللة، فإن بيع منتج تحت اسم "عضوي" لا يعني بالضرورة أن جميع المراحل التي مر بها كانت طبيعية تمامًا. لذلك، من المهم جدًا عند التسوق لطفلكِ أن تختاري المنتجات المعتمدة من الجهات الرسمية والخاضعة لرقابة هيئات الفحص وإصدار الشهادات.') WHERE id = '20bbd1b6-86c2-409c-a96a-adb576836ee8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مرحبًا بكِ في الشهر الـ15، حين يبدأ طفلكِ بالتفكير في الأشياء بعمق أكبر! قد تلاحظين قريبًا أنه بدأ يلعب بألعابه بطريقة تحمل معنى أكبر. فقد يحاول إطعام ألعابه أو وضعها في الفراش، أو تحريك سياراته بطريقة تتناسب أكثر مع الغرض منها. تؤثر السلوكيات وتعابير الوجه التي يراها منكِ بدرجة كبيرة في تعلّمه أشياء جديدة خلال هذه المرحلة. فمثلًا، عندما يراقبكِ أثناء تناول الطعام، قد لا يكتفي بوضع الملعقة في فمه، بل يبدأ أيضًا بإدراك أنها أداة تُستخدم للتحريك. إن فهم طريقة استخدام الأشياء والغرض منها دليل على أن طفلكِ يحقق تطورًا ذهنيًا ملحوظًا. وهذا يعني أنه بدأ يفكر مسبقًا في كيفية سير الأمور والنتائج المحتملة لأفعاله.') WHERE id = '0c49e00c-ebd6-4537-b4a6-d8dc95dd122b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ترين طفلكِ يكبر ويتطور أمام عينيكِ يومًا بعد يوم، ودوركِ في ذلك لا يُقدّر بثمن! 😊 حتى إن لم يطلب منكِ الطبيب الحضور لإجراء الفحص الروتيني هذا الشهر، فمن المرجح أنكِ تتساءلين عن الطول والوزن المناسبين لطفلكِ. وفقًا لمعايير منظمة الصحة العالمية، يجب ألا يقل وزن الفتيات في عمر 15 شهرًا عن 7700 غرام، وألا يقل وزن الأولاد عن 8400 غرام. ويبلغ الحد الأعلى لهذه القيم نحو 13.500 غرام للفتيات و14.300 غرام للأولاد. ويتراوح طول طفلكِ هذا الشهر بين 72.4 سم و82.7 سم للفتيات، وبين 74.4 سم و83.4 سم للأولاد. وبالطبع، سيسعدكِ كثيرًا أن تكون قياسات طفلكِ ضمن هذه النطاقات، مثل أي أم. لكن نود تذكيركِ بأن هذه الأرقام كلها قد تختلف باختلاف جنس طفلكِ ونظامه الغذائي وشهيته ومهاراته الحركية الكبرى، مثل المشي.') WHERE id = '0007e2fa-cabc-4226-900d-8ea2c472b6ea';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تعتقدين أن طفلكِ يؤذي نفسه أو من حوله جسديًا عند مواجهة موقف ما، فعليكِ محاولة معرفة السبب الأساسي للمشكلة. فعلى سبيل المثال، إذا كان طفلكِ يضرب نفسه أو الآخرين أو يعضّهم أو يشدّهم أو يدفعهم من دون سبب واضح بالنسبة إليكِ، فقد يكون ذلك نابعًا من رغبته في جذب الانتباه. وغالبًا ما يُلاحظ هذا السلوك لدى الأطفال الذين لا يرغبون في مشاركة والديهم مع الآخرين. وقد يمهّد لقدوم أخ أو أخت جديدين، أو وجود طفل آخر في محيطه، أو رفضكِ له عندما يرغب في قضاء الوقت معكِ، لظهور هذه السلوكيات. ويرى بعض المتخصصين أن الإفراط في الأنشطة التي يشعر طفلكِ خلالها بالملل، أو بقاؤه باستمرار في البيئة نفسها، أو عدم اختلاطه اجتماعيًا، أو حتى تعرّضه لأصوات وروائح ونكهات غير مألوفة، قد يؤدي أيضًا إلى هذه المشكلة. في مثل هذه الحالات، لا يعرف الطفل ما الذي ينبغي له فعله، فيحوّل المشاعر التي لا يستطيع فهمها إلى نوع من الطاقة، فيميل إلى إلحاق الأذى. بدلًا من لوم طفلكِ بعد هذه التصرفات، يُفضّل أن تتعاملي معه بتفهّم، وأن تطلبي الدعم من مختص إذا شعرتِ أنكِ غير قادرة على التعامل مع المشكلة.') WHERE id = '3c27d24b-b488-40e8-9ae3-4a71940c8781';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يتراكم جزء كبير من المواد الكيميائية المستخدمة في الزراعة التقليدية داخل الأنسجة الدهنية في جسم طفلكِ. ويكون نمو الخلايا الدهنية وتكوّنها سريعًا جدًا، خصوصًا منذ مرحلة تكوّن الطفل، أي قبل ولادته، وحتى أول 36 شهرًا بعد الولادة. وقد يصبح تعرّض طفلكِ للمواد الكيميائية خلال هذه الفترات أحد العوامل التي تؤثر بشدة في صحته مستقبلًا. وتتمثل أكبر مخاطر الفواكه والخضروات غير العضوية في بقايا المبيدات الموجودة فيها. فجسم طفلكِ أكثر حساسية وأقل قدرة على الدفاع عن نفسه مقارنة بجسمكِ، ولذلك لا يستطيع التخلّص من بقايا المبيدات بأمان. وفي ضوء هذه المعلومات، توصي المؤسسات الصحية وأطباء الأطفال باستهلاك الأغذية العضوية خصوصًا خلال هذه المراحل المهمة لصحة الأطفال. لذا ينبغي أن تكون المنتجات العضوية خياركِ الأول عند اختيار الفواكه والخضروات من أجل صحة طفلكِ.') WHERE id = '130cff01-0ee0-4d85-a9f9-730114f30e31';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تتمكني حتى الآن من إكساب طفلكِ عادات نوم جيدة، فقد تنتظركِ الآن مرحلة صعبة بعض الشيء. فالأطفال الذين ينامون عند هزّهم أو حملهم أو إرضاعهم يطالبون بعد فترة باستمرار هذه العادات. فعلى سبيل المثال، إذا كان طفلكِ ينام في شهره 6 بعد هزّه لمدة 15 دقيقة، فقد لا ينام في هذه المرحلة إلا بعد هزّه لمدة 60 دقيقة. كذلك قد تتراجع جودة نوم طفلكِ كثيرًا إذا كان يستيقظ بصورة متكررة ولا يعرف كيف يعود إلى النوم بمفرده. لذلك، يهدف تدريب النوم إلى مساعدة الطفل على الاستغراق في النوم ومواصلته. ولدى المتخصصين آراء وأساليب مختلفة بشأن تدريب النوم، ولكل أسلوب مزاياه وسلبياته، إذ لا توجد طريقة واحدة لتدريب النوم تناسب جميع الأطفال. يمكنكِ طلب الدعم من طبيبكِ أو من مختص في نوم الأطفال، واختيار الطريقة الأنسب لكِ ولطفلكِ والبدء في تطبيقها.') WHERE id = 'ac9afa68-79a2-47e7-9eb6-1a18006b8d77';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن حصول طفلكِ في هذه المرحلة على تغذية موسمية متنوعة ومتوازنة مهم جدًا، ليس لنموه فحسب، بل ليتمتع بحياة صحية في المستقبل وحتى في مرحلة الشيخوخة. يستخدم جسم طفلكِ الكالسيوم الذي يحصل عليه من الطعام خلال هذه الفترة لبناء عظام قوية حتى نهاية مرحلة النمو. كما أن الكالسيوم ضروري لنمو طفلكِ الصحي، ولانقباض العضلات، وسلامة عمل الجهاز العصبي، وأداء بعض الهرمونات لوظائفها. وعندما لا يجد الجسم كمية كافية من الكالسيوم لأداء هذه الوظائف، يبدأ في استخدام الكالسيوم المخزّن في العظام. وقد نواجه مشكلات مثل هشاشة العظام وسهولة تعرّضها للكسور وتسوس الأسنان عند عدم الحصول على كمية كافية من الكالسيوم أو حدوث مشكلة في امتصاصه داخل الجسم لأسباب مختلفة. لذلك، من الضروري أن يتضمن النظام الغذائي لطفلكِ أغذية غنية بالكالسيوم بصورة متوازنة ومنتظمة. وتبلغ حاجة طفلكِ اليومية إلى الكالسيوم في هذه المرحلة نحو 500 mq، وهي كمية تعادل كوبين تقريبًا من الحليب.') WHERE id = '5c393b52-f9a1-4c68-a9cf-d1637f40a2ce';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد بلغ طفلكِ الآن مرحلة يستطيع فيها بسهولة استخدام قبضة الكماشة بأطراف أصابعه، وهي إحدى المهارات الحركية الدقيقة. وهذا يعني أنه بات قادرًا، خصوصًا في أوقات الطعام، على إمساك ملعقته بسهولة وبطريقة صحيحة. ومع اكتسابه هذه المهارة، يمكنكِ الآن شراء أقلام ملوّنة ودفاتر تلوين له! 😊 لا يسهم نشاط التلوين في تنمية عضلات طفلكِ الصغيرة فحسب، بل يعزّز أيضًا التناسق بين اليد والعين. وبفضل هذا النشاط الممتع جدًا، تتطور قدرة طفلكِ على التركيز ويبدأ في تعلّم الألوان. وقد يضع طفلكِ أدوات التلوين التي يستخدمها في فمه ويحاول أكلها لاستكشافها خلال هذه المرحلة. لذلك، يجب ألا تتركيه بمفرده مطلقًا أثناء التلوين، وأن تولي اهتمامًا خاصًا لجودة الأدوات التي تشترينها. استمتعا بوقتكما! 😊') WHERE id = '238df585-4e45-41a7-a863-82dc10a5f6bf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تثير وضعية وقوف طفلكِ في هذه المرحلة قلقكِ أحيانًا. فالأطفال الذين ما زالوا يتعلمون المشي يحاولون الحفاظ على توازنهم من خلال إمالة أجسامهم إلى الأمام. وقد تستمر هذه الوضعية حتى يتقن طفلكِ المشي تمامًا ويكتسب الثقة في قدرته على التوازن. وكما هو الحال لدى الغالبية العظمى من الأطفال، قد تلاحظين أيضًا أن قدمي طفلكِ تتجهان إلى الخارج أثناء الوقوف وبدء الخطوات الأولى. ويرجع ذلك إلى أن الأربطة في منطقة الوركين لا تزال رخوة، ولذلك قد لا يتمكن طفلكِ من إبقاء قدميه في الوضعية الصحيحة. ومع اقترابه من عمر عامين، ستزداد صلابة هذه الأربطة تدريجيًا وسيتمكن من إبقاء قدميه في الوضعية المناسبة. إذا لاحظتِ هذه الحالات أو أي علامات مختلفة لدى طفلكِ خلال مرحلة تعلّم المشي، فيمكنكِ استشارة طبيبكِ.') WHERE id = '8f8df060-6fb0-4f3e-9d13-5fa9a316d2ab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الحديد، الذي يساعد على إيصال الأكسجين الموجود في دم طفلكِ إلى الأنسجة، من أهم المعادن. ويُعد فقدان الشهية من أكثر المشكلات شيوعًا لدى الأطفال الذين يعانون من نقص الحديد. كما يُلاحظ لديهم كثيرًا ازرقاق الجلد وانقطاع النفس عند البكاء. إذا لاحظتِ أن طفلكِ مضطرب أو عصبي ولا يستطيع التركيز، فيمكنكِ أن تطلبي من طبيبه إجراء الفحوصات اللازمة. ووفقًا للرأي العام، ينبغي للأطفال الذين تتراوح أعمارهم بين 1-3 سنوات الحصول على نحو 7 mq من الحديد يوميًا. لذلك عليكِ إدراج أطعمة مثل اللحوم الحمراء والبيضاء والأسماك والبيض والحليب في نظام طفلكِ الغذائي بوتيرة أكبر. وإذا كنتِ تعتقدين أن طفلكِ يجد صعوبة في هضم اللحوم الحمراء والبيضاء، فيمكنكِ إضافتها بانتظام إلى أطباق الخضراوات. وتذكّري أن جميع البقوليات والفاصولياء والسبانخ والجزر والبطاطا والفواكه المجففة يمكنها أيضًا تلبية احتياجات طفلكِ اليومية من البروتين عند تناولها بكميات كافية.') WHERE id = '8d2b01ca-6cc3-467d-9372-bc9b93da9f40';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تدوّنين الكلمات الأولى التي ينطق بها طفلكِ؟ إذا لم تكوني تفعلين ذلك، فقد يكون الاحتفاظ بها ذكرى جميلة فكرة رائعة! 😊 بعد أن يتجاوز طفلكِ عامه الأول، قد يتمكن من نطق الكثير من الكلمات. لكن خلال هذا الشهر، لا يزال جزء صغير منها فقط كلمات ذات معنى. وبدء استخدامه كلمات ذات معنى هو بداية مرحلة لن يعود فيها بحاجة إلى البكاء لجذب الانتباه. 😊 لدعم تطور مهارات طفلكِ اللغوية والكلامية، لا تنسي اللعب معه والتحدث إليه كثيرًا. فمن المؤكد أن تطور الكلام يكون أسرع لدى الأطفال الاجتماعيين الذين يحيط بهم الناس ويتحدثون معهم كثيرًا. لذلك يمكنكِ التدرب مع طفلكِ باستمرار لمساعدته على تعلم كلمة جديدة، وعندما ينجح في نطق الكلمة التي تحاولين تعليمه إياها، يمكنكِ تشجيعه باحتضانه. كما أن قراءة كتاب لطفلكِ قبل النوم ستكون مفيدة جدًا لكليكما.') WHERE id = '68b3d7fb-f868-4d9c-8326-d2aa2fa33869';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم أن يحصل طفلكِ من غذائه على كمية كافية من معدن اليود الذي تحتاج إليه الغدة الدرقية، المسؤولة عن تنظيم جميع العمليات الأيضية. يدخل اليود في تكوين هرمونات الغدة الدرقية، التي تُعد من أهم الركائز الأساسية لنمو دماغ طفلكِ وتطوره الصحي. ويتطلب هذا المعدن توازنًا دقيقًا للغاية، إذ قد يسبب نقصه أو تناوله بكميات تفوق الحاجة مشكلات عديدة. يوجد هذا المعدن في البحار، كما يصل إلى النباتات نتيجة تبخر المياه ثم هطولها على التربة في صورة أمطار. ومع ذلك، تظل الأسماك والمأكولات البحرية أهم مصادر اليود. كما توجد كميات مهمة منه في السبانخ واليقطين والثوم وبعض البقوليات. وإذا رفض طفلكِ تناول هذه الأطعمة، فيمكنكِ تشجيعه على تناول الكثير من الفراولة في موسمها. كذلك فإن وعاءين صغيرين من اللبن الزبادي وكوبًا من الحليب وبيضة واحدة تقدمينها لطفلكِ في وجبة الإفطار ستلبي احتياجاته اليومية من اليود بدرجة كافية.') WHERE id = 'e59fa1f2-cb77-40ca-b9d1-6dbc6abcb2a5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك بعض الأمور التي ينبغي لكِ الانتباه إليها عند قضاء الوقت مع طفلكِ. وأهمها أن تركّزي عليه وحده جسديًا وذهنيًا طوال الوقت الذي تقضينه معه. فعلى سبيل المثال، إذا كنتِ تشاهدين التلفاز أو تستخدمين الهاتف في أثناء قراءة كتاب له أو بناء قلعة من المكعبات معًا، فسيؤدي ذلك إلى تشتيت تركيزه. وقد يمنعه هذا من التركيز الكامل، ويقلل جودة الوقت الذي تقضيانه معًا، ويجعله يشعر بالملل سريعًا. وإذا كنتِ تتساءلين: كيف يمكنني قضاء وقت ممتع وذي جودة مع طفلي؟ فيمكننا توضيح ذلك بمثال قصير. تأكدي أولًا من أن طفلكِ شبعان وحفاضه نظيف. دعيه يختار أحد كتبه بنفسه. واقرئي له الكتاب الذي اختاره بطريقة تتيح له رؤية الصفحات ومتابعتكِ. توقفي مدة أطول عند صورة أو صفحة تلفت انتباهه، وحاولي أن تشرحي له ما أثار اهتمامه باستخدام جمل وصفية. نتمنى لكما وقتًا ممتعًا! 😊') WHERE id = '0c72e589-c1b8-4d06-947f-ca255a690b32';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذه المرحلة، قد يرغب طفلكِ في اتخاذ قراراته بنفسه في إطار تطور شخصيته واستقلاليته. وقد يكون من بين ذلك رغبته في تناول الطعام مستلقيًا كما اعتاد، بدلًا من الجلوس على كرسي الطعام. وعلى الرغم من أن تناول الطعام في وضعية الاستلقاء ينطوي على مخاطر في جميع الأعمار، فإنه يشكل خطرًا كبيرًا بصورة خاصة خلال مرحلة الرضاعة. يؤدي لسان المزمار، وهو غضروف يقع خلف قاعدة اللسان بين الجهازين الهضمي والتنفسي، وظيفة وقائية تمنع دخول الطعام إلى مجرى التنفس. وعند تناول الطعام في وضعية الاستلقاء، قد لا يؤدي هذا الغضروف وظيفته بصورة كاملة، ما قد يتسبب في دخول الطعام إلى القصبة الهوائية بدلًا من المريء. وتشكل جميع أنواع الطعام خطرًا عند تناولها في وضعية الاستلقاء. كما أن استخدام كرسي الطعام وحده مهم جدًا، لا سيما خلال مرحلة الانتقال إلى الأطعمة الصلبة. كذلك قد لا تعمل آلية الحماية المذكورة بصورة صحيحة لدى الأطفال الذين يشاهدون التلفاز أو ينشغلون بأمر آخر، لأنهم لا يركزون بشكل كامل على تناول الطعام. لذلك يُعد التأكد من تركيز طفلكِ على الطعام وحده في أثناء الأكل، وإتمام عملية التغذية على كرسي الطعام فقط، من أهم الأمور التي ينبغي لكِ الانتباه إليها.') WHERE id = 'a96b4d14-328a-4913-8705-3d205531513b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد ترتفع درجة حرارة جسم طفلكِ في بعض الفترات بسبب إصابته بمرض ما، أي قد يُصاب بالحمى. ومن المهم جدًا متابعة درجة حرارته على فترات منتظمة للمساعدة على التشخيص المبكر لأي مرض محتمل. عندما ترتفع درجة حرارة الجسم، يبدأ الجسم باستهلاك طاقة أكبر من المعتاد، ويعمل الجهازان الدوري والتنفسي بوتيرة أسرع. كذلك تتضيق الأوعية الدموية في الذراعين والساقين أثناء الحمى، فيصل إليهما مقدار أقل من الدم، بينما يزداد تدفق الدم إلى الأعضاء الحيوية مثل الدماغ والقلب والكبد. وهذا يعني أن طفلكِ يحتاج إلى مزيد من الأكسجين والسوائل أثناء الحمى. عندما تشعرين بأن حرارة طفلكِ قد ارتفعت، يمكنكِ وضع كمادات من الماء الفاتر والقطن على مفاصله، وإعطاؤه الماء لتلبية حاجته إلى السوائل، والحرص على أن يرتدي ملابس خفيفة. وأهم ما ينبغي لكِ الانتباه إليه هو ألّا تتجاوز درجة حرارته 38.5°C. وإذا بلغت هذا المستوى، فمن الضروري اصطحابه دون تأخير إلى أقرب منشأة طبية بسبب خطر حدوث التشنجات.') WHERE id = 'e1d2295d-b294-489f-9966-9998c1e7d923';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الزنك مهمًا جدًا لأنه يدخل في تركيب الأجسام المضادة التي ينتجها جسم طفلكِ لمكافحة العدوى. وبفضله تزداد قوة جهاز المناعة الذي لا يزال في طور النمو، كما يساعد على التئام الإصابات في الجسم بسرعة. ويرى الخبراء أن الأطفال في الفئة العمرية لطفلكِ يحتاجون إلى 3 mq من الزنك يوميًا في المتوسط. ويمكنكِ دعم مناعة طفلكِ بإضافة الأطعمة الغنية بالزنك إلى نظامه الغذائي. ويُعد الدجاج واللحوم الحمراء والفاصولياء وأنواع الجبن والزبادي والأطعمة المصنوعة من الحبوب الكاملة من أفضل مصادر الزنك. كما تُعد البروبيوتيك، التي تساعد على حماية النبيت المعوي لدى طفلكِ، مهمة أيضًا لاحتوائها على الزنك. لذلك يمكنكِ إضافة منتجات الألبان ذات القيمة العالية من البروبيوتيك، مثل الزبادي والكفير، إلى نظام طفلكِ الغذائي.') WHERE id = '60910a3a-5d54-4db7-a85a-700511cdfbaf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كانت لطفلكِ غرفة مستقلة، فعليكِ الاهتمام بنظافة السجادة فيها عناية خاصة. وإذا كنتِ لا تريدين أن تتسخ بسرعة، فاحرصي أولًا على تنظيفها بالمكنسة الكهربائية بانتظام. ولكن نظرًا إلى أن طفلكِ مفعم بالرغبة في استكشاف محيطه، فلا مفر من ظهور البقع على السجادة مهما حرصتِ على تنظيفها. في هذه الحالات، لا تلجئي فورًا إلى المواد الكيميائية القوية. جرّبي أولًا تنظيفها يدويًا بالماء الساخن فقط. كما يُعد استخدام الثلج أو جهاز التنظيف بالبخار من الطرق الآمنة لإزالة البقع غير المستعصية. وإذا لم تختفِ البقع، فيمكنكِ استخدام خليط تحضّرينه بنفسكِ في المنزل بدلًا من المنظفات الكيميائية القوية. ويمكن إزالة البقع بسهولة بمزج كوب من الخل الأبيض مع كوبين من الماء. وإذا بقيت البقع، فيمكنكِ إضافة كمية لا تتجاوز ملعقة طعام واحدة من سائل غسل الأطباق إلى الخليط.') WHERE id = '2dc63046-9c98-4c12-82b7-0078c136176f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تشعرين بالقلق عندما يمر طفلكِ بنوبات غضب، ولا سيما في بعض الأيام. ويحدث ذلك عادةً عندما لا تتحقق رغباته. وتشيع نوبات الغضب هذه أكثر لدى الأطفال الذين بدؤوا المشي حديثًا، وقد تبدأ بعد عمر سنة واحدة وتستمر على فترات حتى عمر 4 سنوات. ووفقًا لأحدث الدراسات، يمر 85% من الأطفال الذين تتراوح أعمارهم بين 1 و4 سنوات بمثل هذه الحالة مرة واحدة على الأقل. لذلك لا تلومي نفسكِ عندما يغضب طفلكِ، وتذكّري أن هذا جزء طبيعي من نموه. وهناك بعض الأمور التي ينبغي لكِ مراعاتها في هذه الحالة. إذا كانت بالقرب منه أشياء قد تؤذيه، فانقليه فورًا إلى مكان آمن. احتضني طفلكِ، وامنحيه الشعور بالأمان، وحاولي تشتيت انتباهه. وإذا لم تنجح أي من هذه الطرق، فلا تتركيه وحده، لكن تجنّبي التفاعل المباشر معه حتى يهدأ.') WHERE id = 'e1849b6d-7712-4f59-9d5f-7999fc0f6ae5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد السيلينيوم أيضًا من العناصر المهمة التي ينبغي أن يتضمنها النظام الغذائي لطفلكِ كي ينمو بصحة جيدة. ويؤدي السيلينيوم دورًا مهمًا في الحفاظ على بنية شعر طفلكِ وأظافره واستمرار صحتهما. كما يعود بفائدة كبيرة على جهازه المناعي بفضل خصائصه المضادة للأكسدة، إذ يعمل على تحييد الجذور الحرة التي تضر خلايا الجسم وتُسرّع شيخوختها. ويسهم السيلينيوم أيضًا في دعم الوظيفة الطبيعية للغدة الدرقية التي تنظّم التوازن الهرموني لدى طفلكِ. كما يساعد على حماية الغدة الدرقية من هجمات المناعة الذاتية والوقاية من الإصابة بمرض هاشيموتو. لذلك يمكنكِ إضافة الحليب ومنتجات الألبان والأسماك والعنب الأسود والبروكلي والجوز ومنتجات الحبوب الغنية بالسيلينيوم إلى قائمة طعام طفلكِ.') WHERE id = '385a4e35-463b-400b-a449-47047191ef07';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُفترض أن يكون طفلكِ قادرًا في هذه المرحلة على الجلوس بمفرده تمامًا من دون دعم. وقد يفقد توازنه ويسقط في حالات نادرة جدًا، لكن بفضل المهارات الحركية الكبرى والكتلة العضلية اللتين تتطوران خلال هذه الفترة، يُفترض أن يتمكن من حماية نفسه بالاستناد إلى ذراعيه بمجرد أن يفقد توازنه. وتكون عضلات جذع طفلكِ قد أصبحت أقوى بكثير في هذه الأشهر. وقد تلاحظين أنه ينحني كثيرًا ليلتقط لعبته التي سقطت على الأرض، ويجلس القرفصاء بسهولة عندما يتعب، ويتدحرج على بطنه، وينتقل من وضعية الجلوس إلى الاستلقاء والعكس. ونظرًا إلى ازدياد حركته، هناك أمر مهم ينبغي لكِ الانتباه إليه: إذا كنتِ لا تزالين تستخدمين طاولة تغيير الحفاضات، فقد حان الوقت للاستغناء عنها. فقد يتقلب طفلكِ أثناء تغيير حفاضه بسرعة لا تتوقعينها، ما قد يؤدي إلى حوادث خطِرة، مثل السقوط أو إصابة الرأس. لذلك من الأكثر أمانًا تغيير حفاضه على سرير أو أريكة واسعة بعد فرش غطاء مخصص تحته.') WHERE id = '174ec7ea-cdae-4336-8a3e-e5772a684836';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد أن أصبح طفلكِ مستكشفًا صغيرًا بكل معنى الكلمة، سيرغب الآن في تفحّص كل ما يلفت انتباهه بتمعّن، سواء كان مناسبًا لعمره أم لا. وبفضل مهاراته الحركية الدقيقة، يحاول اكتشاف ما يمكنه فعله بالأشياء التي يمسكها بيديه. ويشمل ذلك هزّها، وضرب بعضها ببعض، وطرقها على الحائط، ونقلها من يد إلى أخرى، ورميها وعضّها أيضًا... 😊 ومن المهم لنموه ألا تتدخلي كثيرًا ما دام لا يوجد أي خطر ولا يؤذي طفلكِ نفسه. وخلال هذه الفترة، سيُظهر طفلكِ اهتمامًا كبيرًا بالألعاب ذات العجلات، والمكعبات القابلة للفك والتركيب، والأشياء المتحركة الشبيهة بمشايات الأطفال. كما تُعد الأشياء التي تحتوي على فتحات يمكنه إدخال أصابعه فيها من أكثر ما يستمتع به. لذلك من الضروري إبعاد الأشياء التي قد تشكل خطرًا عليه، مثل مقابس الكهرباء والمبشرة، عن متناول يديه.') WHERE id = '044883c1-c92f-4911-bbe8-6d91510fdfdd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يتبنّى طفلكِ، بالمعنى الحرفي للكلمة، عاداتكِ الغذائية وعادات أسرتكِ. لذلك، كلما تأخرتِ في تعريفه بالسكر والمنتجات السكرية والأطعمة المعلبة، كان ذلك أفضل لصحته. فالسكر الطبيعي الموجود في الفاكهة والحليب كافٍ لتلبية احتياجاته من الطاقة. أما السكر المضاف، فلا يقدم أي فائدة لنموه، وقد يتحول إلى عادة تمهّد للإصابة بالعديد من الأمراض مستقبلًا. ويوصي المختصون بإبعاد الأطفال عن السكر والأطعمة المحتوية على سكر مضاف، لا سيما في الفترة من 0-3 سنوات، بل وحتى سن المدرسة. إذا كان طفلكِ قد اعتاد تناول الأطعمة السكرية حتى هذه المرحلة، فيمكنكِ إعداد كعكات طبيعية في المنزل وتحليتها بالدبس أو العسل. وهكذا، يلبّي طفلكِ احتياجاته اليومية من الطاقة، ويتناول طعامًا طبيعيًا خاليًا من الإضافات بدلًا من الأطعمة الضارة.') WHERE id = '165f1f49-0759-4859-99bf-4fd465d6fe2b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الخطوة الأولى لمساعدة طفلكِ على نوم أكثر صحة هي وضع روتين محدد قبل النوم. تؤدي هذه العادات دورًا مهمًا في نموه؛ فتكرار الأنشطة اليومية بترتيب معين يعزز قدرته على التكيّف بدرجة كبيرة. ورغم أن وضع روتين يكون أسهل بين عمر 4-6 أشهر، فلم يفت الأوان بعد. يمكنكِ مثلًا اختيار أنشطة يستمتع طفلكِ بممارستها قبل النوم وتساعده على الهدوء، مثل الاستحمام أو قراءة كتاب أو غناء تهويدة. وهكذا، عندما يرى طفلكِ هذا التسلسل قبل كل مرة ينام فيها، سيدرك أن موعد النوم قد حان وأن عليه الاستعداد له. المهم هنا أن تتحلي بالصبر، وتحافظي على هذا التسلسل، وتستمري في اتباع الترتيب نفسه كل يوم. كذلك، إذا وضعتِ طفلكِ في سريره عندما يشعر بنعاس شديد، فسيتعلم الخلود إلى النوم بمفرده بسهولة أكبر. لذلك، عليكِ الانتباه جيدًا إلى الأوقات التي تظهر عليه فيها علامات النعاس.') WHERE id = 'e72c175e-57e8-4db2-8440-4cf54e9693fe';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا شك أن الكالسيوم هو أهم عنصر لنمو عظام طفلكِ بصورة صحية. ويُعد الحليب أفضل مصادر الكالسيوم، ولا سيما للأطفال الصغار. إذا لم يكن طفلكِ مصابًا بحساسية تجاه حليب البقر، وسمح طبيبكِ بذلك، فيمكنكِ البدء بإعطائه الحليب. يحتوي الحليب على الماء والدهون والبروتين والكربوهيدرات والمعادن والفيتامينات. وبصورة أدق، يحتوي كوب من الحليب بحجم 200 ml تقريبًا على 300 mq من الكالسيوم، و9 qram من الكربوهيدرات، و6 qram من البروتين، و6 qram من الدهون. ويُعد الحليب غذاءً قيّمًا للغاية خلال مرحلتي النمو والتطور. وبصفته أحد أغنى مصادر الكالسيوم، فإنه يساعد على تكوّن الأسنان والعظام، والوقاية من انخفاض كثافة العظام مستقبلًا. يمكنكِ إعطاء طفلكِ نحو كوبين من الحليب يوميًا. لكن عليكِ الانتباه: فقد يؤدي تجاوز الحد اليومي البالغ 500 ml، على وجه الخصوص، إلى مشكلات مثل الإمساك وفقر الدم (الأنيميا)، لذا من المهم ضبط الكمية بصورة صحيحة.') WHERE id = 'be6e1172-84f7-42b6-b5e2-965f7afc4dd1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد ترتفع درجة حرارة طفلكِ لأسباب مختلفة. ومن الطبيعي تمامًا أن تشعري بالخوف ظنًا منكِ أن الحمى قد تضر بطفلكِ. فقد ترتفع درجة حرارة الجسم عن المعدل الطبيعي بعد التطعيم، أو خلال فترات التسنين، أو بسبب مشكلات صحية مختلفة. في الواقع، درجة حرارة جسم طفلكِ ليست ثابتة، بل تتغير وفق إيقاع معين على مدار اليوم. فقد تكون 36 °C في ساعات الصباح الباكر، ثم تصل إلى نحو 37,5 °C خلال اليوم. وترتبط هذه التغيرات بالحركة، وسماكة الملابس، ودرجة حرارة الجو، والنوم، أو الأطعمة التي يتناولها. إذا تجاوزت قراءة درجة الحرارة تحت الإبط 37,2 °C، أو تجاوزت القراءة عبر المستقيم 38 °C، فهذا يعني أن طفلكِ مصاب بالحمى. وما ينبغي لكِ الانتباه إليه هنا هو أنه في حال عدم وجود مرض، كما يحدث عند التسنين فقط مثلًا، فإن درجة الحرارة لا تتجاوز عادةً 38°C.') WHERE id = 'f4068428-56c5-4d18-9814-d5b4a6624690';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا بد أنكِ لاحظتِ كيف تمر الأيام بسرعة وسط هذا الانشغال المتواصل. لقد أتممتِ الآن 16 شهرًا حافلًا برفقة طفلكِ. 😊 وابتداءً من هذا الشهر، ستواصل وظائفه الذهنية تطورها. إذ تتحسن مهاراته في التعلم والإدراك والفهم والانتباه والتركيز وحفظ المعلومات. وأصبح الآن قادرًا على تذكّر المعلومات التي حفظها بسهولة، والاستفادة منها في تجاربه الجديدة، والربط بين معارفه القديمة والجديدة للتوصل إلى استنتاجات خاصة به. فعلى سبيل المثال، قد يقلب طبقه الفارغ بعد الانتهاء من طعامه ويضعه على رأسه قائلًا إنه قبعة! 😊 وقد يقلّد أصوات الحيوانات التي يسمعها أثناء المشي أو الحبو، ويرغب في التأكد من أنكِ تراقبينه. باختصار، سيطبّق طفلكِ كثيرًا في حياته اليومية ما يتعلمه من خلال مراقبة محيطه واستكشافه! 😊') WHERE id = '1cad17cc-eef5-4325-b0db-c446928d37c9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع بلوغ طفلكِ الشهر 16، يبلغ متوسط وزنه 9800 qram لدى البنات و10.500 qram لدى الأولاد. وبالطبع، هذه الأرقام قيم متوسطة، وقد تختلف الحدود الدنيا والعليا. وبحساب تقريبي، يُتوقع ألا يقل وزن الطفل في عمر 16 شهرًا عن 8250 qram. أما الطول، فينبغي أن يتراوح بين 73.3-83.9 sm لدى البنات، وبين 75.4-85.1 sm لدى الأولاد. خلال هذا الشهر، إن لم يكن ذلك قد حدث بالفعل، فقد يتحول نظام طفلكِ المعتاد المكوّن من قيلولتين إلى قيلولة واحدة أطول وقت الظهيرة. يتعلم ذهن طفلكِ المتفتح معلومات جديدة في كل لحظة. ويحتاج دماغه، الذي يعمل بنشاط كبير ودون توقف، إلى الراحة ليتمكن من حفظ هذه المعلومات. ومن هذا المنطلق، تتيح القيلولة النهارية لطفلكِ فرصة استيعاب ما تعلمه، والتخلص من التعب، واستعادة طاقته لبقية اليوم. إن الاهتمام بقيلولته النهارية ووضع نظام نوم صحي له، إن لم تكوني قد فعلتِ ذلك بعد، من أكثر الخطوات فاعلية لدعم نموه.') WHERE id = 'f1142bfa-de01-40ac-811f-43d85ed0de50';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون طفلكِ في هذه المرحلة قادرًا على الركض، أو ربما بدأ للتو بالوقوف بمفرده واتخاذ بضع خطوات. وعندما يشعر بالأمان أثناء الوقوف والمشي دون مساعدة، سيحاول المشي مستندًا إلى دعامة قريبة. وهنا عليكِ التأكد من أن الأشياء التي يمسك بها أو يستند إليها لا تحتوي على زوايا حادة، وأنها ثابتة وثقيلة بما يكفي لتجنب خطر انقلابها. وبعد أن يطوّر طفلكِ مهاراته الأولى في المشي بهذه الطريقة، سيبدأ بعد مدة بالاستعانة بهذه الأشياء فقط عندما يفقد توازنه ويشعر بأنه على وشك السقوط. ولأن خطواته ليست قوية بما يكفي بعد، ولم يتمكن من الحفاظ على توازنه تمامًا، فمن الأفضل إزالة العوائق التي قد تجعله يتعثر أو يسقط. فمثلًا، قد يؤدي وجود لعبة صغيرة تحت قدمه أو انثناء طرف السجادة إلى فقدانه توازنه بسهولة. لذلك، من المهم جدًا ألا تغفلي عنه وأن تتخذي الاحتياطات اللازمة إلى أن يبدأ بالحفاظ على توازنه جيدًا.') WHERE id = 'c2d6b8c4-c3db-4cb8-ba44-8ba52466f41e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'فيتامينات مجموعة B المركبة اللازمة للنمو الصحي لعضلات طفلكِ وجهازه العصبي هي فيتامينات B1 وB2 وB3 وB5 وB6 وB9 وB12. تذوب هذه المجموعة من الفيتامينات في الماء، وعلى الرغم من تشابه أسمائها، فإن خصائصها الكيميائية مختلفة للغاية. فعلى سبيل المثال، يُعد فيتامين B1، المعروف أيضًا باسم الثيامين، عنصرًا بالغ الأهمية لعملية استقلاب الطاقة لدى طفلكِ. ولأن الثيامين لا يُخزَّن في الجسم، يجب أن يتضمن النظام الغذائي اليومي لطفلكِ بانتظام أطعمة تحتوي عليه. وبحساب تقريبي، تبلغ حاجة طفلكِ اليومية إلى الثيامين نحو 0.6 mq. وعندما يحصل جسم طفلكِ على هذا الفيتامين بانتظام، تتنظم قوة العضلات، ويستمر الجهاز العصبي في أداء وظائفه، كما يساعد ذلك على الوقاية من مرض البري بري الخطير. تشمل العلامات الأولى لنقص الثيامين فقدان الشهية، وفرط التهيج، والحالات الاكتئابية، واضطرابات الجهاز الهضمي، والإرهاق الذهني. أما الأطعمة الغنية بالثيامين فتشمل الخميرة، والكبد وغيره من لحوم الأعضاء، ودقيق القمح الكامل، والحبوب المدعمة، والبقوليات، والمكسرات التي تؤكل نيئة. لذلك، من المهم جدًا إدراج هذه الأطعمة في النظام الغذائي لطفلكِ.') WHERE id = '37d9ddb9-020c-44ca-9003-d396cdd1bf7d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن طفلكِ لا ينمو بالسرعة نفسها التي كان ينمو بها خلال عامه الأول، فإنه لا يزال يواصل التطور بوتيرة سريعة. وبما أنه بدأ الآن بتناول جميع المجموعات الغذائية تقريبًا، فعليكِ إعداد نظام غذائي متوازن يضمن حصوله على ما يكفي من الفيتامينات والمعادن. وتُعد الحبوب، مثل القمح والجاودار والشوفان، من المجموعات الغذائية الضرورية لدعم نمو طفلكِ. ومن أشهر فوائد الحبوب أنها تساعد على تحسين عملية الهضم لديه بفضل محتواها من الألياف. كما أن مجموعة الحبوب غنية جدًا بفيتامينات مجموعة B، ما يدعم النمو المتواصل لجهاز طفلكِ العصبي. كذلك تحتوي الحبوب على معادن مفيدة لنمو عظامه وعضلاته، مثل الحديد والسيلينيوم والمغنيسيوم. ويساعد تناول طفلكِ أطعمة الحبوب الكاملة بانتظام على تنظيم شعوره بالشبع، ما قد يفيده في التحكم بوزنه في مراحل عمرية لاحقة.') WHERE id = '52538747-c4aa-4010-b0db-b59dfb445a2f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يغضب طفلكِ، خصوصًا عندما لا يحصل على ما يريده، وقد يميل إلى إيذاء نفسه أو من حوله. ويُعد الغضب والتصرف بعدوانية لدى الأطفال الصغار وسيلة من وسائل التعبير. وقد يكون سبب غضبه الجوع أو التعب أو المرض، أو مجرد تعبير خارجي عن شعوره بالإحباط. وفي هذه الحالة، ينبغي أن يكون هدفكِ الأساسي محاولة معرفة مصدر غضبه بدلًا من لومه أو إبداء ردود فعل مبالغ فيها. وبعد أن يهدأ، لا تذكّريه بالأمر مرارًا، لأنه على الأرجح لن يتذكره أصلًا. الغضب غريزة بشرية طبيعية، لكن حدوثه بعنف مفرط وبشكل متكرر قد يسبب أضرارًا خطيرة لخلايا الدماغ. لذلك، راقبي الأمور التي تُغضب طفلكِ وحاولي تجنبها. وما إن تشعري بأنه بدأ يغضب، فاصرفي انتباهه فورًا إلى شيء آخر. وأخيرًا، إذا كانت نوبات غضب طفلكِ تتكرر كثيرًا خلال اليوم وتستمر مدة طويلة، فيمكنكِ استشارة طبيب الأطفال المتابع لحالته أو اختصاصي في هذا المجال.') WHERE id = 'de201cb3-bc29-49c0-af6f-e3d645ccc499';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحتل النباتات العلاجية مكانة واسعة في ثقافتنا. وفي السنوات الأخيرة، ازداد كثيرًا عدد الآباء الذين يقدمون شاي الأعشاب لأطفالهم، إذ يُستخدم بكثرة، خصوصًا عند المرض أو الأرق أو الإصابة بمغص الغازات. ورغم أن هذا الشاي قد يبدو غير ضار بسبب مكوناته النباتية، فإنه قد يلحق أضرارًا خطيرة بجسم طفلكِ إذا لم يُستخدم بطريقة صحيحة. تذكّري أن النباتات الموجودة في الطبيعة تحتوي في الواقع على مواد فعالة قوية تُستخدم في صناعة الأدوية. لذلك، يجب ألا تقدمي لطفلكِ أي شاي عشبي دون استشارة طبيبكِ. كما ينبغي تجنب الأعشاب التي تُباع مكشوفة، لأنها قد تتلوث بالبكتيريا بسهولة. وعند اختيار أنواع الشاي المُعدة خصيصًا للأطفال، ينبغي أن تفضّلي العلامات التجارية التي لا تحتوي على السكر أو المُحليات أو النكهات الصناعية. كذلك قد يعتاد طفلكِ بعد فترة على أنواع الشاي المهدئة التي تُعطى لمساعدته على النوم بهدوء، لذا ينبغي تجنب استخدامها باستمرار.') WHERE id = '0d58d564-0c0d-4b3d-bbef-5e6ea873b5cc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كما هو الحال في جميع أنحاء العالم، يؤكد المتخصصون في بلدنا أيضًا أهمية حليب الأم بصورة خاصة. وإذا كنتِ ترضعين طفلكِ طبيعيًا، فربما بدأتِ بالتفكير في الوقت المناسب لفطامه. والتوجه العام هو مواصلة الرضاعة الطبيعية إلى أن يبلغ طفلكِ 24 شهرًا. وسيستمر طفلكِ في الحصول على أفضل الفوائد منكِ في كل مرة ترضعينه فيها. لكن إذا كنتِ ترغبين في فطامه لأي سبب أو بسبب مشكلة صحية، فهناك بعض النقاط التي عليكِ مراعاتها. إن تحديد المدة التي ستواصلين خلالها إرضاع طفلكِ هو قرار شخصي وعاطفي يعود إليكِ بالكامل. وعندما تقررين فطامه، من المهم جدًا اختيار وقت يكون فيه طفلكِ هادئًا ومرتاحًا. وعليكِ تجنب محاولة فطامه، خصوصًا خلال الفترات المجهدة، مثل التسنين أو طفرات النمو أو المرض أو تغيير مقدمة الرعاية. وينصح كثير من المتخصصين بفطام الطفل تدريجيًا على مدى فترة من الزمن بدلًا من فطامه فجأة. وعلى عكس الاعتقاد الشائع، يجب عدم وضع أي مادة مُرّة على الحلمة مطلقًا، لأن ذلك قد يضر بعلاقة الثقة بينكِ وبين طفلكِ.') WHERE id = '2b2331d6-6e4d-4acf-ab51-52a8995652bb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ لا تعملين، فمن المرجح أنكِ الشخص الذي يقضي معظم الوقت مع طفلكِ ويعتني به. لذلك، من الطبيعي تمامًا أن يكون طفلكِ شديد التعلق بكِ. لكن هذه الحالة قد تجعل الحياة اليومية صعبة أحيانًا. ففي هذه المرحلة التي يزداد فيها قلق الانفصال، قد يصبح حتى ذهابكِ لغسل وجهكِ ويديكِ نوعًا من الرفاهية. وهنا تكتسب مسؤولية زوجكِ ودوره كأب أهمية كبيرة. فعندما يكون في المنزل، من المفيد أن يتولى الأب على وجه الخصوص تلبية احتياجات طفلكِ الأساسية، فهذا يخفف العبء عنكِ ويساعد أيضًا على بناء علاقة صحية بين الأب وطفله. ولتحقيق ذلك، ينبغي أن تضعي خطة مسبقة مع زوجكِ. ومن المهم جدًا ألا تتدخلي عندما يعتني الأب بطفلكِ ويلبي احتياجاته. وبعد فترة، ستلاحظين أن طفلكِ أصبح أقل قلقًا في غيابكِ.') WHERE id = 'ca7661e9-8f78-4665-b399-7c5615396281';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج طفلكِ في هذه المرحلة إلى ٣ وجبات رئيسية يوميًا. ومن المهم تنظيم برنامجه الغذائي وفقًا لذلك. لكن لا تنسي أن الوجبات الخفيفة مهمة لطفلكِ بقدر أهمية الوجبات الرئيسية. وكما هو الحال مع الوجبات الرئيسية، يمكنكِ تقسيم الوجبات الخفيفة إلى ثلاث مرات أيضًا. واحرصي على ألا تؤثر الوجبات الخفيفة المقدمة في هذه الأوقات في شهية طفلكِ للوجبات الرئيسية. فما يتناوله بين الوجبات يؤدي دورًا مهمًا في تلبية احتياجاته من الطاقة خلال اليوم والوقاية من الانزعاج الناتج عن التعب. فمثلًا، توفر الفواكه المجففة قدرًا كافيًا من الطاقة، كما تؤثر إيجابيًا في نموه بفضل قيمتها الغذائية العالية. والفواكه المجففة غنية بفيتامين C، لذا فهي فعالة جدًا في تعزيز مناعة طفلكِ ضد الأمراض، وخصوصًا خلال فترات تغير الفصول. يمكنكِ شراء فواكه مجففة مُعدّة خصيصًا للأطفال، أو إعدادها بنفسكِ عبر تقطيع الفواكه الموسمية وتجفيفها. بالهناء والشفاء! 😊') WHERE id = '4b17e497-f9cb-44ce-9613-c013217b2cc2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تختلف مخاوف طفلكِ كثيرًا عن مخاوف البالغين، ويرجع ذلك أساسًا إلى قلة خبرته. فقد يخاف، مثلًا، من شيء أو موقف معين. وفي هذه المرحلة، قد يخاف الطفل من الماء لبعض الوقت إذا انقطع نفسه للحظات بسبب وصول الماء إلى وجهه أثناء الاستحمام. ومن الشائع أيضًا أن يخاف من الغرباء أو من نباح الكلب أو ركضه خلفه. في مثل هذه المواقف، لا ينبغي أن تجبري طفلكِ، بل عليكِ أن تتفهميه وتحترمي مشاعره. ولمساعدته على التغلب على مخاوفه، يمكنكِ مثلًا شراء كلب لعبة له إذا كان يخاف من الكلاب. شجعي طفلكِ على اللعب بهذه اللعبة كثيرًا، وعندما تلاحظين أنه اعتاد عليها، دعيه يشاهد الكلاب في الشارع من مسافة بعيدة. وبعد فترة، ستلاحظين أن هذا الخوف قد تراجع.') WHERE id = '5283373d-f93e-4067-9525-2c93f8c33897';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر الإنسان بأسرع مرحلة نمو في حياته خلال الأشهر التسعة التي يقضيها في رحم أمه. أما الأشهر الـ١٢ الأولى بعد الولادة، فهي أسرع فترات النمو مقارنة بمراحل الحياة اللاحقة. ومن المتوقع أن يتضاعف وزن طفلكِ خلال الأشهر الستة الأولى، وأن يصبح ثلاثة أضعاف عند بلوغه عامًا واحدًا. أما طوله، فمن المفترض أن يزداد بنحو ١٥ سم في الأشهر الستة الأولى و١٠ سم في الأشهر الستة الثانية، أي ما يقارب ٢٥ سم إجمالًا خلال العام. وفي المرحلة الحالية، عندما يُتم طفلكِ شهره الـ٢٤، يُفترض أن يزيد طوله بنحو ١٠ سم مقارنة بطوله في الشهر الـ١٢. لكن يجب ألا تنسي أن هذه الأرقام قد تختلف من طفل إلى آخر. وقد تكون هذه القياسات أعلى بمقدار ٣-٤ سم، وخصوصًا لدى الذكور. إذا كنتِ تعتقدين أن هناك تأخرًا ملحوظًا في نمو طول طفلكِ، فيمكنكِ استشارة طبيبكِ.') WHERE id = 'cfb48ee3-2bc5-48e5-9ea6-f49aa246dc1a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'شهدت أمراض الحساسية، مثل حساسية الطعام والربو التحسسي وحمى القش، ارتفاعًا سريعًا بين الأطفال في السنوات الأخيرة. ووفقًا للإحصاءات، يعاني في المتوسط ٣٠ طفلًا من كل ١٠٠ طفل من هذه المشكلات. وعلى الرغم من أن أسبابها لا تزال قيد الدراسة، يُعتقد أن تغير نمط الحياة والعوامل البيئية والعيش في بيئة مفرطة التعقيم وخالية من البكتيريا تسهم في حدوثها. ومن هذا المنطلق، فإن تعرض طفلكِ للميكروبات، وخصوصًا في مراحله المبكرة، مهم لنمو جهازه المناعي. كما أن قضاء الطفل وقتًا طويلًا جدًا في المنزل أو الأماكن المغلقة يقلل تعرضه للهواء النقي ويزيد خطر حدوث تفاعلات الحساسية. كذلك يؤثر التعرض المستمر لغبار المنزل سلبًا في الرئتين والمناعة. لذلك، احرصي على قضاء الوقت مع طفلكِ في أحضان الطبيعة بصورة متكررة، وستساعدكما النزهات في الطبيعة كثيرًا في هذا الصدد.') WHERE id = '354fce07-8a6f-481b-96ee-5e30484ac5c4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشكل هذه الأشهر بداية مرحلة حساسة جديدة في تغذية طفلكِ. فقد تلاحظين أنه يأكل كل ما في طبقه بشهية في أحد الأيام، ثم يتناول كمية قليلة جدًا في اليوم التالي، كما لو أنه لا يشعر بالجوع إطلاقًا. بل قد يفقد في بعض الأيام اهتمامه بالطعام تمامًا ويرفض تناوله كليًا. وفي مثل هذه الحالات، قد ينتابكِ القلق، مثل كثير من الأمهات، وتبدئين في البحث عن سبب فقدان الشهية. لكن إذا لم يكن فقدان الشهية ناتجًا عن مرض، فلا ينبغي أن تجبريه على تناول الطعام أبدًا. تختلف آلية عمل جسم طفلكِ وعقله في هذه المرحلة عن آلية جسمكِ وعقلكِ؛ فهو يتناول الطعام وفقًا لاحتياجات نموه تحديدًا. لذلك، لا داعي للقلق ما دام فقدان الشهية ورفض الطعام لا يستمران فترة طويلة ولا يؤديان إلى فقدان الوزن.') WHERE id = 'd897e9a5-762e-454d-b280-b3b13c0b4618';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تُحصى فوائد الفيتامينات لصحة طفلكِ. وتؤدي مجموعة فيتامينات B المركبة، على وجه الخصوص، دورًا مهمًا في دعم العديد من الوظائف الحيوية في جسمه. فهي تشارك بفاعلية في إنتاج الهرمونات وخلايا الدم الحمراء والإنزيمات والخلايا العصبية. كما تساعد هذه المجموعة من الفيتامينات، التي تنظّم أيض الكربوهيدرات والبروتينات والدهون، على الحفاظ على التوازن الداخلي لجسم طفلكِ. وتسهم في إنتاج هرمون السيروتونين، لذلك تؤثر مباشرةً في نمط نومه وحالته المزاجية وحساسيته للألم. ولهذه الأسباب، قد يؤدي نقص فيتامين B لدى طفلكِ إلى مشكلات في النوم واضطرابات في وظائف الجهاز العصبي المركزي. ومن المصادر النباتية لفيتامين B: بذور دوار الشمس، والبندق، والجوز، والفول السوداني، واللوز، والفطر، والطماطم، والخضراوات الورقية الخضراء، والبطاطس، والبرتقال، والموز. أما مصادره الحيوانية فتشمل اللحوم الحمراء والبيضاء، والأسماك، والكبد، والحليب، والبيض، والزبادي، والكفير.') WHERE id = '43eb5d6e-1eaa-45a1-946e-ca86a7cd935b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتأثر الجهاز المناعي لطفلكِ سلبًا، خاصةً خلال أشهر الشتاء وعند تغيّر الفصول. لذلك من الضروري حمايته من الأمراض التي تُضعف المناعة سريعًا، مثل الإنفلونزا ونزلات البرد. وأول ما ينبغي لكِ فعله هو التأكد من حصول طفلكِ على كمية كافية من السوائل، وتنظيم نظامه الغذائي بما يتناسب مع فواكه الموسم وخضراواته. وخلال أشهر الشتاء، يمكنكِ تقديم الكثير من الأطعمة الغنية بفيتامين C لطفلكِ، مثل الجزر والخضراوات الورقية الخضراء والبرتقال واليوسفي. وبذلك يستطيع جهازه المناعي زيادة عدد خلايا الدم البيضاء التي تكافح العدوى، ما يساعد على التصدّي للفيروسات بسهولة أكبر. كما يُعد انتظام نمط نوم طفلكِ وحصوله على نوم جيد من العوامل التي تقوّي مناعته. ومن المهم جدًا أيضًا تعويده على غسل يديه بانتظام، خاصةً عند العودة إلى المنزل من الخارج، لحماية جسمه من البكتيريا.') WHERE id = 'ff4f941f-2940-4484-b3f8-3aa7fa73b47c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحتوي الأسماك على نسبة مرتفعة من البروتين عالي الجودة، كما أنها غنية بالأحماض الأمينية المهمة جدًا لجسم طفلكِ. وينبغي لكِ إدراجها في نظامه الغذائي مرتين على الأقل أسبوعيًا، لأنها تدعم نمو الدماغ والعينين على وجه الخصوص. ومع ذلك، يجب مراعاة بعض المعايير عند اختيار السمك الذي ستقدمينه لطفلكِ. فنظرًا إلى حساسية جسمه الشديدة، ينبغي لكِ تجنّب أسماك القاع التي قد تحتوي على معادن ثقيلة. واختاري بدلًا منها أسماك المياه السطحية، مع الحرص على أن تكون طازجة ومناسبة لموسمها. ومن المهم جدًا أيضًا إزالة جميع الأشواك من السمك الذي سيتناوله طفلكِ لتجنّب خطر الاختناق. ولا تشكّل تغذية طفلكِ بالحليب الصناعي أو حليب الأم أي عائق أمام تناوله السمك. والنقطة الأساسية التي ينبغي لكِ الانتباه إليها هي التأكد من طزاجته.') WHERE id = '143d7d0e-c659-4393-ad66-6a71451d969a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عزيزتي الأم، يجب ألا تسمحي لكِ أو لأي شخص آخر بالتدخين بالقرب من طفلكِ إطلاقًا، وأن تكوني حازمة تمامًا في هذا الأمر. يحتوي دخان السجائر على عدد لا يُحصى من المواد السامة التي تُلحق أضرارًا جسيمة بوظائف الجسم. وتذكّري أن هذه المواد الضارة لا تنتقل عبر الهواء فحسب، بل يمكن أيضًا أن تنتقل بسهولة عن طريق الملابس والنَّفَس. ولأن طفلكِ يتنفس بمعدل أسرع من البالغين، فهو أكثر حساسية للدخان. ويشكّل تعرّضه غير المباشر لدخان السجائر خطرًا كبيرًا على صحته، سواء كان التعرض لفترة قصيرة أو طويلة. وتشير الدراسات إلى أن الأطفال الذين يتعرضون لدخان السجائر في سن مبكرة يكونون أكثر عرضة لانخفاض وظائف الرئة، وأمراض الجهاز التنفسي مثل الربو والتهاب الشعب الهوائية، بالإضافة إلى التهابات الأذن.') WHERE id = '5e114626-fa98-4af5-a54c-9bc73d395ef6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن تناول طفلكِ كل ما تقدمينه له بشهية قد يسعدكِ، فإن الهدف الأساسي يجب ألا يقتصر على ملء معدته، بل ينبغي أن يكون تزويده بالأطعمة الأكثر فائدة لنموه. فعلى سبيل المثال، يحتاج جسم طفلكِ يوميًا إلى فيتامين D بمقدار يزيد 6 مرات عما يحتاج إليه جسمكِ. كما يحتاج لتكوين عظام جديدة إلى 4 أضعاف كمية الكالسيوم و4 أضعاف كمية فيتامين C التي يحتاج إليها البالغون. وبالمثل، تكون حاجته إلى الزنك والحديد مرتفعة أيضًا. لذلك، لا ينبغي لكِ ملء معدته الصغيرة بالخبز الذي يصعب هضمه، أو بالحساء منخفض القيمة الغذائية الذي يتكوّن أساسًا من الماء. فالخبز، على وجه الخصوص، طعام ثقيل الهضم على طفلكِ الذي لم يكتمل نضج عملية الأيض لديه بعد، كما أنه لا يلبّي احتياجات جسمه الفعلية من الفيتامينات.') WHERE id = 'f03f7ef6-1201-4627-b01c-144e9eca5d2c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة التي يتدرّب فيها طفلكِ على المشي، يكون الابتعاد عن "مشاية الأطفال" هو الخيار الأفضل. ولا توصي الأكاديمية الأمريكية لطب الأطفال إطلاقًا باستخدام مشاية الأطفال خلال مرحلة تعلّم المشي. ويرجع ذلك إلى أن طفلكِ، الذي لم يكتمل استعداده البدني بعد، لا يستطيع التحكم في عضلاته بصورة كاملة أثناء التحرك بالمشاية. وقد يؤدي ذلك إلى تأخر نمو العضلات، فضلًا عن التسبب في مشكلات بالعمود الفقري وإصابات في مفاصل الورك. تعمل المشاية أساسًا على عضلات ربلة الساق لدى طفلكِ، في حين أن عضلات الفخذ والجزء العلوي من الساق ضرورية للمشي بصورة مستقلة. ولأن طفلكِ يستطيع الوصول بسهولة إلى المكان الذي يريده داخل المشاية، فقد لا يشعر بالحاجة إلى محاولة المشي بنفسه. ولهذا السبب، لا ينصح المختصون باستخدام مشاية الأطفال.') WHERE id = '3fc30308-235c-40fd-b135-b2614f8aa914';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'منذ لحظة ولادة طفلكِ، تتطور العينان والمسارات العصبية المرتبطة بالإبصار بسرعة. ورغم أن هذه السرعة تنخفض قليلًا بعد الشهر السادس، فإن نمو أجزاء الدماغ المسؤولة عن الإبصار يستمر حتى سن 4 سنوات. لذلك، من المهم جدًا إجراء فحوصات منتظمة لعيني طفلكِ، ولا سيما خلال السنوات الأربع الأولى. فمشكلات العين التي تُكتشف خلال هذه السنوات يمكن علاجها بسهولة، بينما قد تصبح بعض الاضطرابات دائمة في السنوات اللاحقة. على سبيل المثال، يمكن علاج الغمش، المعروف شائعًا باسم كسل العين، بدرجة كبيرة عند تشخيصه خلال مرحلة الرضاعة، لكن قد يكون الأوان قد فات عند بلوغ سن المدرسة. وللوقاية من مثل هذه المشكلات الخطيرة التي قد تؤثر في جودة حياة طفلكِ، لا تهملي إجراء فحص روتيني لعينيه كل عام حتى سن 4 سنوات.') WHERE id = 'a8cc1051-99c9-48a6-9019-f1a7720fc939';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تختلف عملية الأيض لدى طفلكِ عنها لدى البالغين، ما يعني أنه قد يواجه صعوبة في هضم الحبوب التي تتناولينها. لذلك، يجب تقديم الحبوب لطفلكِ في صورة سهلة الهضم. وتُعد الحبوب المدعّمة بالحديد مفيدة جدًا لجهازه الهضمي. فقد يحصل الأطفال الذين يتناولون الحبوب المدعّمة بالحديد على كمية من الحديد تزيد 3 أضعاف عمّا يحصل عليه الأطفال الذين يتناولون اللحوم. وبالنظر إلى أن احتياج طفلكِ إلى الحديد أكبر من احتياج البالغين، فإنها تُعد خيارًا ممتازًا. كذلك، قد يُجهد الخبز المصنوع من دقيق القمح جهازه الهضمي، فضلًا عن أنه لا يلبي احتياجاته الغذائية كاملة. تذكّري أن الهدف ليس مجرد ملء معدة طفلكِ، بل ضمان تناوله أطعمة ذات قيمة غذائية عالية ويمكنه هضمها بسهولة.') WHERE id = 'e0612546-b42a-483e-b9b3-dfffcbdbd7fb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد انتقال طفلكِ من سرير الرضيع إلى السرير العادي خطوة كبيرة في طريقه نحو الاستقلال. ومن المهم أن يتم هذا الانتقال تدريجيًا وبصبر. يشير الخبراء إلى إمكانية الانتقال إلى السرير العادي في نحو عمر 1 سنة، عندما يبدأ الأطفال بالمشي، على أن يتوقف استخدام سرير الرضيع تمامًا في موعد أقصاه سن 3 سنوات. وحتى لا يشعر طفلكِ بالحزن أو عدم الأمان خلال هذه المرحلة، احرصي على ألا تكون الغرفة شديدة الظلام؛ ويمكنكِ استخدام مصباح ليلي صغير. لكن حاولي أن يكون ضوؤه خافتًا جدًا حتى لا يؤثر في جودة نومه. واحرصي على أن تكون درجة حرارة الغرفة معتدلة، وساعدي طفلكِ على النوم في سريره نفسه بدلًا من تنويمه في مكان آخر ثم نقله إليه. فبقاؤكِ بجانبه حتى يغط في النوم سيمنحه الشعور بالأمان.') WHERE id = '9f57bbc6-774d-46d9-aed8-04569feb3638';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن أكثر نشاطًا من أي وقت مضى. لذلك نتمنى لكِ شهرًا 17 مفعمًا بالطاقة! 😊 قد تستمر خلال هذا الشهر عادة طفلكِ في إلقاء كل ما تصل إليه يداه من مكان مرتفع، ورمي الأشياء وإحداث الفوضى من حوله لفترة أخرى. وإذا كان يتعامل بالطريقة نفسها مع الطعام وقت الوجبات، فراقبيه قليلًا قبل التدخل فورًا. لكن إذا أصبح هذا السلوك عادة لديه، فقد حان الوقت لاتخاذ بعض الإجراءات. فعلى سبيل المثال، عندما يلقي طعامه على الأرض، ابقي صامتة ولا تُظهري أي رد فعل لبعض الوقت بدلًا من المبالغة في رد فعلكِ أو الضحك. وإذا استمر في ذلك، فحاولي أن توضحي له بهدوء، ومن دون رفع صوتكِ، أن هذا التصرف خاطئ. وإذا واصل التصرف نفسه، فقولي له: «هذا يعني أن وقت الطعام قد انتهى»، ثم أبعديه عن المائدة. وبعد فترة ستلاحظين أن هذه السلوكيات قد بدأت تقل.') WHERE id = '5b43ef47-8f43-413f-82a2-1ee9e30206d0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا توجد أي لقاحات مقررة لطفلكِ هذا الشهر وفقًا لجدول التطعيمات. كذلك، فإن تطور طوله ووزنه يشبه إلى حد كبير ما كان عليه في الشهر السابق. وفي هذه المرحلة، قد يكون اكتساب طفلكِ قدرًا ضئيلًا جدًا من الوزن، أو عدم اكتسابه أي وزن، أو حتى فقدانه مقدارًا بسيطًا منه أمرًا طبيعيًا. وإذا أردتِ معرفة ما إذا كان نمو طفلكِ الجسدي، مثل الطول والوزن، يقع ضمن الحدود الطبيعية، فيمكنكِ الاستعانة بمنحنى النسب المئوية للنمو. يُستخدم منحنى النمو لتقييم ما إذا كانت مؤشرات طول طفلكِ ووزنه تتقدم على النحو المتوقع. وباختصار، تُراجع هذه القيم للتأكد من أن نمو طفلكِ متناسب ومتواصل. وتختلف هذه الجداول بين الإناث والذكور، لكن النقطة الأساسية هي أن يواصل طفلكِ التقدم على مسار النمو نفسه. وإذا لاحظتِ تغيرًا كبيرًا في مسار هذا المنحنى، فعليكِ التواصل مع طبيبكِ بالتأكيد للحصول على إجابات واضحة عن أسئلتكِ.') WHERE id = '1b2b53fb-9227-4684-9e66-3cf833cc1fab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ تقديم الفواكه لطفلكِ كحصة مستقلة، أو مزجها بالزبادي أو بأطعمة أخرى. ومن بين الفواكه، يُعد العنب الداكن اللون غنيًا جدًا بمضادات الأكسدة، كما أن توازُن الفيتامينات والمعادن فيه مفيد جدًا لجسم طفلكِ. لكن تجدر الإشارة إلى أن حبات العنب أو بذورها قد تشكل خطر الاختناق. وإذا لم يسبق لكِ تقديم العنب لطفلكِ، أو كنتِ تقدمينه له على فترات نادرة جدًا، فيمكنكِ في البداية إعطاؤه عنبًا منزوع البذور بعد هرسه قليلًا. إضافة إلى ذلك، يُعد العنب من الأطعمة المعرضة بدرجة كبيرة لاستخدام المواد الكيميائية والمبيدات الزراعية أثناء إنتاجها. لذلك، يُفضل الانتباه إلى الجهة المنتجة عند شراء العنب لطفلكِ واختيار المنتجات العضوية. ولا تنسي غسله جيدًا وبكمية وفيرة من الماء! 😊') WHERE id = '3521705b-778f-4770-b599-04d464340b78';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لأن طفلكِ يمر بمرحلة تكوين شخصيته واستقلاليته، فقد ينزعج بشدة ويدخل في نوبات غضب صغيرة عندما لا يُسمح له بفعل شيء ما. وقد تزداد هذه السلوكيات خصوصًا عندما لا تُلبّى احتياجاته الفسيولوجية، مثل النوم أو الطعام أو الراحة. وإذا تعلّم طفلكِ أنه يستطيع الحصول على ما يريد من خلال البكاء أو التصرف بعدوانية، فقد يتحول ذلك بسهولة إلى عادة. لذلك ننصحكِ بألّا تشعري بالذعر وتفعلي فورًا كل ما يريده أو تعطيه الشيء الذي يطلبه. حاولي أن توضحي لطفلكِ أن هذه التصرفات لن تساعده في الحصول على ما يريد. وإذا لم يستمع إليكِ، فقد يكون من المفيد ألّا تتفاعلي معه لبعض الوقت. وبوجه عام، تمر هذه النزوات بسرعة أكبر عند عدم التفاعل معها، بينما قد تزداد حدةً وتتحول إلى سلوك مستمر عند الاستجابة لها. ما دام طفلكِ لا يؤذي نفسه أو من حوله في أثناء هذه التصرفات، فمن الأفضل أن تلتزمي الهدوء لبعض الوقت. وإذا شعرتِ بأنكِ لا تستطيعين التعامل مع الأمر، فقد يكون من الجيد طلب الدعم من مختص.') WHERE id = '9b70bd77-6922-45b9-a6fd-e814d496d5b5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل لاحظتِ أن طفلكِ يشعر بالقلق ويبدأ فورًا بالبحث عنكِ عندما تبتعدين عنه وتختفين عن ناظريه لبضع ثوانٍ فقط؟ نحن ندرك مدى صعوبة هذا الوضع عليكِ في بعض الأيام. تذكّري أنكِ لستِ وحدكِ، وأن الكثير من الأمهات يمررن بالتجربة نفسها. أهم ما ينبغي أن تعرفيه عن هذه السلوكيات هو أن الخوف أو القلق من الانفصال يبلغ ذروته لدى الأطفال بين الشهرين 14 و18. وبالطبع، قد يظهر هذا الخوف بدرجة أقوى أو أضعف وفقًا لشخصية طفلكِ وتجاربه السابقة. وإذا كنتِ تتساءلين عما يمكنكِ فعله في هذه الحالة، فعليكِ أولًا ألّا تحوّلي هذا الخوف إلى مشكلة كبيرة. إنها مرحلة من مراحل نمو طفلكِ، والتحدث معه وشرح الأمر له من أكثر الخطوات التي يمكن أن تمنحه الشعور بالأمان. وفي الأيام التي يكون فيها طفلكِ أكثر قلقًا، يمكنكِ السماح له باتباعكِ إذا احتاج إلى ذلك. تحلّي بالصبر... وتذكّري أن هذه المرحلة ستمر أيضًا! 😊') WHERE id = '422f0fc6-52c4-4074-943d-ed6c4fc8a6e8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُبدي طفلكِ خلال هذه المرحلة اهتمامًا بنوع واحد فقط من الطعام، وقد يرغب في تناوله باستمرار ويرفض جميع الأطعمة الأخرى. نود أولًا أن نطمئنكِ: عادةً ما تكون هذه الحالات مؤقتة ولا تُعد اضطرابًا غذائيًا خطيرًا. وغالبًا ما يختار الأطفال أطعمة سهلة الهضم، مثل الخيار أو المعكرونة أو البطاطس. وأكثر الطرق فاعلية لإبعاد طفلكِ عن النظام الغذائي غير المتنوع هي تقديم الطعام بطريقة ممتعة! فمظهر الطعام مهم جدًا للأطفال، تمامًا كما هو مهم للبالغين. على سبيل المثال، بدلًا من تقديم الخضراوات مهروسة فحسب، يمكنكِ صنع عينين من البروكلي وأنف من الجزر وفم مبتسم من البازلاء الخضراء. سيثير هذا التقديم اهتمام طفلكِ، وقد يبدأ بتناول الطعام بعد تأمله لبعض الوقت. وإذا لم يأكله فورًا، فلا تشعري بالإحباط، وواصلي تقديمه بالطريقة نفسها على فترات منتظمة.') WHERE id = 'e0ad8dc6-0f06-4fb0-843a-17178927d524';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن شديد الاهتمام بالحركات التي تقومين بها، ولا يزال يحب تقليدكِ كثيرًا. وبفضل هذه المهارة، يمكنه تعلّم أشياء كثيرة واكتساب عادات جديدة. يمكنكِ الاستفادة من قدرته على التقليد لتعليمه العادات التي تريدين أن يكتسبها. على سبيل المثال، لمساعدته على اكتساب عادة تنظيف أسنانه، أعطي فرشاة أسنان لكل منكما. ويمكنكما الجلوس معًا أمام المرآة لتُريه كيفية القيام بذلك. سيحاول طفلكِ تقليدكِ في البداية، لكن كثيرًا من الأطفال سرعان ما يشعرون بالملل أو يترددون لأنهم لا يستطيعون فهم بعض الأنشطة، مثل تنظيف الأسنان، على الفور. في هذه الحالات، لا تجبري طفلكِ، لكن لا تستسلمي أبدًا. وحتى إذا لم يقلّدكِ، فقد يكون تنظيف أسنانكِ بانتظام أمامه وسيلة جيدة لتعليمه. كما يمكنكِ تشجيعه على اكتساب هذه المهارة بعبارات مثل: إذا أردت، يمكنك أن تجرّب أيضًا، فهذا ممتع جدًا!') WHERE id = '1c8045dd-8c86-4b61-8d1a-62a2ece69966';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تراودكِ أسئلة حول أنواع العناصر الغذائية والكميات التي يحتاج إليها طفلكِ ضمن نظامه الغذائي اليومي. وفي الواقع، هناك مخطط يسهّل فهم هذا الأمر المعقد: الهرم الغذائي! يمكن أن يكون الهرم الغذائي دليلكِ في تغذية طفلكِ. إذ يمثّل كل قسم منه مجموعة مختلفة من الأطعمة التي ينبغي لطفلكِ تناولها يوميًا. تشكل الكربوهيدرات الصحية قاعدة الهرم، وهي المجموعة التي تمد جسم طفلكِ بالطاقة اللازمة لكل من عملية الأيض الأساسية وأنشطته اليومية. أما البروتينات، فتسهم في بناء العضلات المحيطة بهيكله العظمي. ويحتاج الجسم إلى كمية كبيرة من البروتين للنمو والتطور. إضافةً إلى ذلك، لا يستطيع الجسم تخزين البروتين كاحتياطي، لذلك ينبغي تلبية هذه الحاجة يوميًا من خلال اللحوم والأسماك والبيض والحليب ومنتجات الألبان. أما الدهون فهي بالغة الأهمية لامتصاص الفيتامينات والمعادن. وسبب وجودها في قمة الهرم هو أن كمية صغيرة منها تمنح الجسم قدرًا كبيرًا جدًا من الطاقة.') WHERE id = 'cc7c7f69-13ff-481e-a7f5-f617a73232e2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين ابتداءً من هذا الشهر زيادة في عدد الكلمات التي يستخدمها طفلكِ. يستطيع الأطفال في عمر 17 شهرًا استخدام 6 كلمات ذات معنى في المتوسط، مما يساعد طفلكِ على تحسين قدرته على التعبير عن نفسه. وبفضل تطور مهاراته اللغوية، قد يطرح عليكِ الأسئلة كثيرًا. وإذا لم يبدأ بعد، فلن يطول الأمر! 😊 في البداية، ستشعرين بحماس كبير تجاه الأسئلة التي يطرحها طفلكِ، لكن كثيرًا من الآباء والأمهات سرعان ما يشعرون بالملل من ذلك ويبدؤون بترك أسئلته دون إجابة. فالعالم الذي بدأ طفلكِ باستكشافه وكل ما يراه يثير فضوله. وقد تكون الأشياء التي تبدو لكِ عادية وروتينية أكثر ما يثير اهتمامه في العالم. لذلك من المهم جدًا ألّا تمنعي طفلكِ من طرح الأسئلة، وأن تقدمي له إجابات ذات معنى بدلًا من تجاهلها. وإلا فقد تلحقين، من دون قصد، ضررًا كبيرًا بتطوره اللغوي ومشاعره وحبه للاستطلاع.') WHERE id = '3e415dd0-b7f2-4960-9725-01d09c2b93c2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يجب أن تتضمن قائمة طفلكِ اليومية أطعمة تحتوي على فيتامين B6، المعروف أيضًا باسم البيريدوكسين. ولأن فيتامين B6، وهو أحد فيتامينات مجموعة B، متوفر بكثرة في الأطعمة الحيوانية والنباتية، فمن السهل الحصول عليه عن طريق الغذاء. هذا الفيتامين القابل للذوبان في الماء شديد الحساسية للضوء. يساهم فيتامين B6 مباشرةً في استقلاب البروتينات والدهون والكربوهيدرات في جسم طفلكِ، كما أنه مهم جدًا لعمل جهاز المناعة بصورة سليمة. وقد يؤدي عدم الحصول على كمية كافية منه إلى ظهور تقرحات في الشفتين واللسان، وفقر الدم (الأنيميا)، وتأخر النمو، وتكوّن حصوات الكلى. إذا كان طفلكِ قد تغذّى على الحليب الصناعي بدلًا من حليب الأم، فقد تكون حاجته إلى فيتامين B6 أكبر. ويمكن الحصول على هذا الفيتامين من اللحوم الحمراء والكبد والحبوب الكاملة والبقوليات المجففة، لذا احرصي على إدراج هذه الأطعمة بانتظام في نظام طفلكِ الغذائي.') WHERE id = '77912752-b7a9-497a-99ba-585af752ea41';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا للأكاديمية الأمريكية لطب الأطفال، يمكن تقديم المكسرات للأطفال منذ الشهر 6 عند بدء تناول الأطعمة التكميلية، شرط أن تكون بقوام مناسب لعمرهم. لكن نظرًا إلى احتمال تسبب المكسرات بالحساسية، يسود في بلدنا رأي عام بعدم تقديمها خلال السنة الأولى. في هذه المرحلة، إذا لم يخبركِ طبيبكِ بخلاف ذلك ولم يكن طفلكِ يعاني حساسية تجاه المكسرات، فقد يكون تناولها مفيدًا جدًا، خصوصًا كوجبة خفيفة. وكما هو معروف، تُعد المكسرات من البذور الغنية بالفيتامينات ومضادات الأكسدة والألياف. كما أنها غنية بالبروتينات والدهون ومعادن مثل المغنيسيوم والمنغنيز والكروم. لذلك فهي تساهم في نمو طفلكِ وتطوره وقدرته على التعلم. إذا لم تكوني قد قدمتِ المكسرات لطفلكِ من قبل، فقد يكون الجوز بداية جيدة. فالجوز غني بأوميغا-3، كما أنه أقل تسببًا بالحساسية مقارنةً ببعض المكسرات الأخرى. وبحسب مرحلة نمو طفلكِ، إذا كنتِ تعتقدين أن المكسرات ستكون قاسية، فيمكنكِ نقعها في الماء مدة قصيرة وتقديمها بقوام آمن ومناسب لعمره. ويفضل تقديم المكسرات نيئة غير محمصة.') WHERE id = '6d0c5ce7-8563-49c1-be57-a0288743f236';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يرغب طفلكِ الآن، مثل والديه، في أن يقرر بنفسه ما يريد فعله ومتى يفعله. وهذا السلوك هو إحدى نتائج نمو شعوره بالاستقلالية، وقد يحاول طفلكِ تحديد مواعيد الطعام واللعب بنفسه. وعندما يدرك أن موعد النوم قد حان، قد يعترض بشدة إذا لم يكن يريد النوم، ويواصل اللعب. في هذه المرحلة، كوني متفهمة تجاه طفلكِ وحاولي أن توضحي له أن الغضب ليس حلًا. وإذا تحول هذا الغضب إلى اعتداء جسدي عليكِ أو على نفسه، فيمكنكِ إخباره بأن هذا السلوك خاطئ ومؤلم. وعندما يكون منفعلاً إلى درجة تمنعه من الاستماع إليكِ، قد يكون الاكتفاء بعبارة واضحة وحازمة مع الحفاظ على هدوئكِ وعدم إبداء رد فعل إضافي فعالًا. أما معاقبته أو الرد عليه بالمثل فلن يفيد في هذه اللحظة، بل قد يزيد الوضع سوءًا. لذلك، إذا لم تعرفي كيفية التعامل مع طفلكِ في مثل هذه المواقف، فيمكنكِ طلب المساعدة من مختص.') WHERE id = '0e7d27d6-207f-40c2-bf3a-a953c053ee08';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تدفعكِ أهمية حصول طفلكِ يوميًا على كمية كافية من كل عنصر غذائي إلى التفكير طويلًا فيما ستُعدّينه له. وفي هذه الحالة، يمكنكِ إعداد قطع مافن صغيرة ومرحة بالخضراوات؛ فهي تلبي حاجة طفلكِ إلى الخضراوات، كما تجذب انتباهه وتشجعه على تناولها. فعلى سبيل المثال، تساعد قطع المافن التي تُعدّينها بأطعمة مثل الكوسا والجزر والبطاطس والموز على تنظيم الجهاز الهضمي لطفلكِ بفضل محتواها من الألياف. كما يمكنكِ إضافة حبوب مدعّمة بالحديد وفواكه موسمية إلى وعاء صغير من الزبادي تُعدّينه لطفلكِ، لتحصلي على فكرة رائعة لوجبة مناسبة له! 😊 تُعد الفواكه الموسمية من أفضل المجموعات الغذائية التي يمكنكِ اختيارها لإعداد وجبات خفيفة صحية لطفلكِ. ويمكنكِ أيضًا إضافة قطع من الجبن اللذيذ إلى الفواكه المقطعة للمساعدة في تلبية احتياجات طفلكِ من الكالسيوم. وهكذا ستقدمين لطفلكِ وجبة شهية ومفيدة جدًا لنموه في الوقت نفسه. بالهناء والشفاء! 😊') WHERE id = 'c5f5b4e2-b06a-4f2f-a220-d6fd136cfc41';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يصل عدد الخلايا العصبية في دماغ طفلكِ منذ لحظة الإخصاب وحتى الولادة، خلال مدة قصيرة تبلغ 9 أشهر، إلى نحو 100 مليار خلية. وتتسارع بعد الولادة عملية التعلم التي بدأت في الرحم مع تطور أعضاء الحواس. وكلما تعلم طفلكِ أشياء جديدة، تبدأ الروابط التشابكية بالتكوّن بين الخلايا العصبية، وتشكّل هذه الروابط هو جوهر عملية التعلم. وتتطور الروابط التشابكية بسرعة كبيرة في هذه المرحلة، ليصل عددها إلى تريليونات عندما يبلغ طفلكِ عمر عامين. نمو الدماغ هو عملية اكتمال بنيته الجسدية بتأثير العوامل الوراثية والعادات الغذائية والمحفزات القادمة من البيئة المحيطة. وقد ثبت علميًا أن دعم نمو الدماغ بالأطعمة المناسبة خصوصًا يساهم في تعزيزه. لكن ما لا يعرفه كثيرون هو أن اللعب لا يقل أهمية لطفلكِ عن الغذاء. فاللعب هو أهم وسيلة يعبّر بها طفلكِ عن عالمه الداخلي وينمّي خياله وقدراته الذهنية. ومن هذا المنطلق، فإن أهمية الألعاب والأنشطة لطفلكِ أكبر بكثير مما قد تتوقعين.') WHERE id = 'bb09cf18-b58b-4a99-8863-125d766de6ce';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتعرض طفلكِ للإسهال كثيرًا، خصوصًا خلال فترات التسنين أو عند الإصابة ببعض الاضطرابات. وإذا صاحبه ألم في البطن، فمن الطبيعي أن يشعر طفلكِ بالانزعاج. أول ما ينبغي عليكِ فعله عند الإصابة بالإسهال هو تعويض السوائل التي فقدها طفلكِ. لذلك احرصي على تقديم السوائل له بكميات أكبر من المعتاد، ويمكنكِ استشارة طبيبه بشأن استخدام محلول الإماهة الفموي المناسب. ولمساعدة الأمعاء على استعادة انتظامها، يمكنكِ خلال هذه الفترة إدراج الزبادي والكفير المحتويين على البروبيوتيك في نظام طفلكِ الغذائي. وتُعد فواكه مثل الموز والتفاح والخوخ من أكثر الأطعمة شيوعًا للمساعدة على تخفيف الإسهال. ويمكن لهذه الأطعمة أن تساعد على الحد من الإسهال بما يتناسب مع طبيعة عمل جسم طفلكِ. كما يُعد جنين القمح من الأطعمة التي يمكنكِ اختيارها لطفلكِ خلال فترة الإسهال، فهو يحتوي على كمية وفيرة من الزنك. وعندما يُصاب الطفل بالإسهال، يفقد جسمه كمية ملحوظة من الزنك. وبفضل هذا الغذاء، يمكنكِ المساعدة على تعويض الزنك الذي فقده جسم طفلكِ. وإذا لم يرغب طفلكِ في تناول هذه الأطعمة، فيمكنكِ تجربة خلطها بالخلاط وتقديمها له بقوام مناسب لعمره.') WHERE id = '0dac3412-69e2-497e-844d-048d053a7edc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان رضيعكِ يرفض تناول بعض الأطعمة الصحية أو كان فاقدًا للشهية عمومًا، فيمكنكِ الاستفادة من فوائد الفواكه! 😊 حاولي أولًا مزج الأطعمة التي عادةً ما يكون مذاقها غير مستساغ أو مُرًّا مع فاكهة يحبها رضيعكِ. كما أن تقديم الفواكه كوجبات خفيفة سيساعد بسهولة على تلبية احتياجاته من الطاقة طوال اليوم. وعادةً ما يتقبل جميع الأطفال الفواكه بسهولة، كما يسهل هضمها بفضل ما تحتويه من ألياف. ومن المهم عند اختيار الفواكه أن تفضّلي الأنواع الموسمية، وأن تتأكدي أيضًا من كونها طبيعية وخالية من المواد الكيميائية. وإذا ساورتكِ شكوك بشأن ذلك، فمن الأفضل اختيار المنتجات المعتمدة التي تحمل شهادة موثوقة. نتمنى إذًا لرضيعكِ أيامًا مليئة بالطاقة والفيتامينات. هنيئًا مريئًا! 😊') WHERE id = '84737837-51a1-43dd-9f5e-13375e4bea0e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يصبح لطفلكِ يومًا ما أخت أو أخ، حتى وإن لم يكن ذلك الآن! 😊 فهل فكرتِ يومًا في كيفية إعداده لهذا الأمر؟ أولًا، لا جدوى من التفكير بأن طفلكِ لا يشعر بالغيرة، فالغيرة شعور متأصل في الطبيعة البشرية. لكن الغيرة بين الإخوة موضوع مختلف تمامًا، والعامل الأساسي الذي يثير هذا الشعور هو تصرفات الوالدين والمحيطين بالطفل. في كثير من الأحيان، لا تبدأ العائلات في تهيئة طفلها لهذا الوضع إلا خلال المراحل الأخيرة من الحمل، وقد تنتظر حتى الولادة. لكن الخبراء يرون أنه ينبغي لكِ البدء منذ البداية بشرح الوضع لطفلكِ وتهيئته له. كما يجب أن تواصلي منحه القدر نفسه من الاهتمام والرعاية حتى قدوم الطفل الجديد. وبعد ولادة أخته أو أخيه، يمكنكِ طلب مساعدته في العناية بالمولود لتنمية شعوره بالمسؤولية وبناء رابطة ودية ومحبّة بينهما.') WHERE id = '44b74612-92c2-4e6e-9dfe-a41e22e6391c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يتميز اللحم الأحمر، الذي ينبغي إدراجه بانتظام في النظام الغذائي لرضيعكِ، باحتوائه على بروتينات غنية بالأحماض الأمينية عالية الجودة. كما أنه غني بالحديد والزنك والمنغنيز، ويساعد على امتصاص الحديد من الأمعاء. وإضافةً إلى ذلك، يدعم النمو الجسدي والعقلي لرضيعكِ بفضل احتوائه على مجموعة فيتامينات B المركّبة، مثل الثيامين والريبوفلافين والنياسين والبيوتين وB6 وB12 وحمض البانتوثينيك والفولاسين. ويؤدي فيتامين B12 دورًا مهمًا في نمو مليارات الخلايا العصبية في دماغ رضيعكِ وترميمها. كما يساهم فيتامين B12 الموجود في اللحم الأحمر في تحويل الكربوهيدرات والدهون والبروتينات في الجسم إلى طاقة. أما حمض الفوليك الموجود فيه، فهو ضروري لحماية أغلفة الأعصاب المسماة بالميالين ولتصنيع الحمض النووي. ولهذه الأسباب كلها، من المهم جدًا لنمو رضيعكِ الصحي أن يتناول اللحم الأحمر مرتين على الأقل أسبوعيًا، سواءً في حصة مستقلة أو ضمن أطباق الخضراوات.') WHERE id = '98672898-99c2-430b-8640-95780d644fb4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُتوقع في هذه المرحلة أن ينام رضيعكِ ليلًا مدة 11-12 ساعة متواصلة، كما يُعد استيقاظه 1 مرة خلال الليل أمرًا طبيعيًا. لكن إذا كان يستيقظ بوتيرة مفرطة، دون أن يكون ذلك بسبب المرض أو التسنين أو طفرات النمو، فعليكِ محاولة معرفة السبب الجذري للمشكلة. أولًا، من الطبيعي أن يستيقظ رضيعكِ كثيرًا إذا لم تُلبَّ احتياجاته الجسدية بالكامل قبل النوم. لذلك، عليكِ تغيير حفاضه وإطعامه جيدًا قبل بدء نومه الليلي. وإذا كانت قيلولاته النهارية أقصر من اللازم، فقد يستيقظ كثيرًا في الليل بسبب الإرهاق. وعلى العكس، قد يؤدي نومه طويلًا خلال النهار إلى تقصير نومه الليلي أو تقطّعه. لذا عليكِ ضبط التوازن بين نوم النهار والليل على نحو صحيح. وإضافةً إلى ذلك، فإن نوم رضيعكِ في مكان مضاء ومليء بالمحفزات يقلل جودة نومه ويؤدي إلى استيقاظه المتكرر.') WHERE id = '3434c215-3fe7-499a-8390-d30adea0614b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لعلّكِ تسمعين كثيرًا عن البروبيوتيك وتأثيره في صحة رضيعكِ، لكن ماذا تعرفين عن البريبيوتيك؟ البروبيوتيك هو بكتيريا نافعة ضرورية لتكوين فلورا معوية صحية لدى رضيعكِ والحفاظ عليها، أما البريبيوتيك فهو غذاء هذه البكتيريا. وباختصار، لا يستطيع البروبيوتيك أداء وظائفه بالكامل في بيئة تفتقر إلى البريبيوتيك. ويعمل البريبيوتيك والبروبيوتيك معًا بانسجام لتقليل الكائنات الضارة في الأمعاء والحفاظ على البكتيريا النافعة. لذلك، ينبغي أن تهتمي في قائمة طعام رضيعكِ بالأطعمة الغنية بالبريبيوتيك بقدر اهتمامكِ بالأطعمة التي تحتوي على البروبيوتيك. ويُعد البصل والثوم من أهم مصادر البريبيوتيك، كما يحتوي الكراث على نسبة مرتفعة منه. ومن الأطعمة الغنية بالبريبيوتيك أيضًا الموز والتفاح والهليون وحساء الترخانة والكاكاو وبذور الكتان والخرشوف المقدسي والشوفان والشعير.') WHERE id = '92e9a917-62e2-4a4a-9b49-359767b9f956';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مثل جميع الأمهات، لعلّ أحد أكبر مخاوفكِ هو احتمال سقوط رضيعكِ من مكان مرتفع. ومهما حرصتِ على حمايته، فقد يتعذر أحيانًا تجنب مثل هذه الحوادث. إذا واجهتِ موقفًا كهذا، فعليكِ أولًا الحفاظ على هدوئكِ، لأن رضيعكِ سيكون خائفًا بالفعل، ولن يفيده ذعر أحد والديه أو مبالغته في رد الفعل. أول ما ينبغي الانتباه إليه هو المسافة بين المكان الذي كان فيه رضيعكِ والسطح الذي سقط عليه. إذا كانت هذه المسافة تتجاوز 50 sm، يزداد احتمال تعرضه لإصابة. وبعد تهدئته مباشرةً، عليكِ مراقبة الأعراض. انزعي ملابسه وحاولي تحديد مواضع الإصابة في جسمه. وإذا كان رضيعكِ غير قادر على تحريك بعض أجزاء جسمه، أو يميل إلى النعاس، أو يتقيأ، أو يبدو عليه الضعف العام، فعليكِ التوجه فورًا إلى مؤسسة صحية.') WHERE id = '9b055594-14fb-4c53-929a-9afb16c23258';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحتوي المكسرات على كثير من الفيتامينات والمعادن المهمة لتغذية طفلكِ، إلى جانب كميات وفيرة من مضادات الأكسدة والدهون والبروتين والألياف. تساعد الألياف على تنظيم جهاز طفلكِ الهضمي، بينما تسهم العناصر الغذائية في نموه الصحي. فمثلًا، يُعد البندق مصدرًا جيدًا للطاقة؛ ويمكنكِ طحنه في الخلاط وتقديمه لطفلكِ مع دبس الفاكهة. ويحتوي اللوز على فيتامينات A وB وC وE، إضافة إلى الألياف والحديد والبوتاسيوم والمغنيسيوم والزنك. ويمكنكِ طحن اللوز وإضافته إلى حساء طفلكِ أو الزبادي لزيادة قيمته الغذائية. أما الكاجو، فيدعم النمو الصحي لشعر طفلكِ وأظافره بفضل احتوائه على السيلينيوم، كما يقوي جهازه المناعي. لكن تذكّري أن المكسرات قد تسبب الحساسية، ونوصيكِ بمراقبة طفلكِ بعناية عند تقديمها له للمرة الأولى.') WHERE id = '5c6eb260-bbaa-4a4e-ace2-b15d6e44bab2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن تلاحظي بدء طفلكِ في التواصل بصورة أكثر وضوحًا منذ هذا الشهر. فقد بدأ الآن باستخدام كلمتي «نعم» و«لا» بفاعلية. وبالطبع، لا يعني ذلك بالضرورة أنه سيتمكن من نطقهما كاملتين بوضوح. فعندما تطرحِين عليه سؤالًا، قد يجيب بصوت يشبه «ممم» إذا كانت إجابته إيجابية، أو «آ آ» إذا كانت سلبية، وقد يهز رأسه من جانب إلى آخر. ومن المهم جدًا في هذه المرحلة أن تواصلي جهودكِ لإكساب طفلكِ مزيدًا من الكلمات وتعليمه معانيها. وعند تعليمه كلمة جديدة، يجب أن يكون هدفكِ الأول أن يتعلمها بطريقة ذات معنى. ولترسيخ هذا التعلم، حاولي إشراك حواس طفلكِ الخمس. فمثلًا، إذا أردتِ تعليمه كلمة «خوخ» ومعناها، اعرضي عليه ثمرة خوخ أولًا وكرري أمامه كلمة «خوخ». ثم قرّبي الثمرة من أنفه ليشم رائحتها. وضعيها في يده ليلمسها ويشعر بقشرتها الزغبية. وفي النهاية، قشّريها ودعيه يتذوقها. ولا تنسي تكرار كلمة «خوخ» باستمرار في أثناء هذه الخطوات! :)') WHERE id = 'b10e37ea-a17e-42e7-b4cf-51362f68d5ef';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكتسب التغذية الصحية لطفلكِ أهمية كبيرة لنموه الجسدي والذهني على حد سواء، وأنتِ تعرفين ذلك بالتأكيد. كما يؤدي اتباع نظام غذائي متوازن ومنتظم منذ الآن دورًا أساسيًا في تعزيز نجاح طفلكِ مستقبلًا خلال سنوات الدراسة! 😊 ومن هذا المنطلق، يحتاج طفلكِ إلى جميع أنواع الخضراوات وإلى ما تحتويه من عناصر غذائية عالية الجودة. فعلى الرغم من اختلاف كمياتها، تزخر جميع الخضراوات بالفيتامينات وعناصر مثل الكالسيوم والصوديوم والبوتاسيوم والحديد والفوسفور والمغنيسيوم والسيلينيوم والنحاس والمنغنيز. وإذا كان طفلكِ لا يتناول أطعمة أخرى غنية بالبروتين، فيمكنكِ الاستفادة من الخضراوات المحتوية عليه، مثل البازلاء الخضراء. فعلى الرغم من صغر حجم حبات البازلاء، فإنها تحتوي على الكالسيوم وفيتاميني A وC والحديد. وهي من الخضراوات الغنية بالطاقة، وتسهم بدرجة كبيرة في نمو طفلكِ الصحي بفضل احتواء كل 100 غرام منها على 5% من البروتين. ولتفادي خطر الاختناق، احرصي على هرس البازلاء قليلًا بالشوكة بعد طهيها. بالهناء والشفاء! 😊') WHERE id = 'd8afee3a-b92b-4e65-9d4b-116cb3237d17';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذا الشهر، يكون جميع الأطفال تقريبًا قد طوروا قدرتهم على المشي، أو بدؤوا باتخاذ خطواتهم الأولى إن لم يكونوا قد مشوا بعد. وقد يحرز طفلكِ تقدمًا ملحوظًا خلال هذا الشهر بحسب وتيرة نموه، بل قد يبدأ بالركض أيضًا. ومع ذلك، قد يظل بعض الأطفال يفضلون الحبو على المشي، أو قد يحتاج طفلكِ إلى مزيد من الوقت بسبب خوفه من السقوط. وفي هذه المرحلة، من الجيد تشجيع طفلكِ وتحفيزه على المشي. فمثلًا، ضعي لعبته المفضلة في مكان يراه وعلى ارتفاع يمكنه الوصول إليه واقفًا. فإذا وضعتِها على الأرض، فسيدفعه ذلك إلى الحبو، أما وضعها في مكان مرتفع جدًا فسيمنعه من الوصول إليها حتى بالحبو. ويمكنكِ أيضًا مساعدته على التغلب على خوفه بإمساك يده في أثناء المشي وتشجيعه بالتصفيق له كثيرًا.') WHERE id = 'b84e52ad-6011-428b-a300-841c183eead5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'جهاز طفلكِ المناعي هو نظام خاص يمتلكه جسمه لمكافحة مختلف أنواع العدوى والمواد السامة. ويزداد جهازه المناعي قوةً تدريجيًا طوال حياته، ويتعلم بفضل الخبرات التي يكتسبها كيفية محاربة الكائنات الحية الدقيقة. خلال السنة الأولى، تساعد الأجسام المضادة التي تصل إلى جسم الطفل عبر حليب الأم على اكتسابه مناعة أقوى. ومع أن حليب الأم يظل غذاءً قيّمًا جدًا في هذه المرحلة، فإن انتقال الأجسام المضادة لن يكون بالقوة نفسها التي كان عليها خلال الأشهر الأولى. لذلك، من المهم جدًا لمستقبل طفلكِ الصحي أن يقوي جهازه المناعي. وتؤدي جميع الأطعمة التي يتناولها دورًا مهمًا في مكافحة الجذور الحرة التي تهدد جسمه. وإلى جانب البروتين والدهون والكربوهيدرات والفيتامينات والمعادن، من الضروري أن يشرب كمية وفيرة من الماء حتى تتمكن الخلايا المكوّنة لجهاز المناعة من مواصلة حركتها داخل الجسم.') WHERE id = '8fa97afc-adc6-4722-ad9f-3d28cf704a12';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يرغب طفلكِ في استخدام أشياء يراكِ تستعملينها كثيرًا في حياتكِ اليومية، مثل المشط والمفاتيح والمحفظة والهاتف. لكن عليكِ توخي الحذر، لأن بعض هذه الأشياء قد يكون خطرًا عليه. وتأتي الأجهزة مثل الهاتف في مقدمة الأشياء التي ينبغي إبعادها عن طفلكِ. وعندما تمنعينه من لمس هذه الأشياء، قد تزيد ردود فعلكِ الحادة فضوله تجاهها، لذا حافظي على هدوئكِ. وفي المقابل، يمكنكِ السماح له باللعب بأشياء يقل احتمال أن تؤذيه، مثل المشط والمفاتيح. فهذا يساعده على تطوير مهاراته اليدوية وتعزيز التناسق بين اليد والعين. لكن لا تعطي أهمية خاصة لاستخدام طفلكِ يده اليمنى أو اليسرى عند التعامل مع هذه الأشياء؛ ففي هذه المرحلة يستطيع الأطفال استخدام كلتا اليدين بالقدر نفسه. وعليكِ الانتظار مدة أطول قليلًا لمعرفة أي اليدين ستكون هي المهيمنة لديه! 😊') WHERE id = 'd77df84a-12b0-42c0-b5d6-9e7aaff5de66';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدى طفلكِ هذا الشهر أيضًا جدول تطعيمات مكثف إلى حد ما. ومن المهم جدًا الالتزام بجدول التطعيمات لتعزيز جهازه المناعي. التطعيمات التي ينبغي أن يتلقاها طفلكِ عند بلوغه 18 شهرًا (1.5 سنة) هي: لقاح DaBT-İPA-Hib (اللقاح الخماسي المركب)، ولقاح شلل الأطفال، ولقاح التهاب الكبد A. يجمع اللقاح الخماسي المركب الحماية من الدفتيريا والسعال الديكي والكزاز وشلل الأطفال والمستدمية النزلية من النوع B. ويحمي لقاح شلل الأطفال المعطّل طفلكِ من شلل الأطفال. كما يمنح لقاح المستدمية النزلية من النوع B مناعة ضد التهاب السحايا والالتهاب الرئوي والتهاب الأذن الوسطى. ونظرًا إلى أن هذه الأمراض قد تسبب مضاعفات خطيرة ودائمة، فمن المهم جدًا إعطاء التطعيمات في مواعيدها.') WHERE id = '1e4a79c4-2aff-4769-bbbf-b7ed53e1716f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يوجد السكر طبيعيًا في كثير من الأطعمة، كما قد يُضاف إليها أثناء التصنيع. وعلى الرغم من أن السكر يمنح الطاقة، فإنه لا يقدم أي قيمة غذائية. لذلك لا ينبغي إدراجه ضمن النظام الغذائي لطفلكِ، لأنه لا يدعم نموه. احرصي على ألا تحتوي المنتجات التي تشترينها على أنواع من السكر مثل الغلوكوز والفركتوز والدكستروز والسكروز. فالسكر مادة يسهل الاعتياد عليها، وهي ليست آمنة لطفلكِ. وسيكون السكر الطبيعي الموجود في الفواكه والخضراوات كافيًا له. ولأن تناول السكريات البسيطة يسبب تغيرات مفاجئة في سكر الدم، فإنه يزيد خطر الإصابة بالسكري والسمنة ويؤثر سلبًا في صحة القلب. ويوصي الخبراء بألا يتناول الأطفال السكريات البسيطة قبل بلوغ سن المدرسة.') WHERE id = '8dac80f3-aaa2-47a7-bba0-611d73c7f97e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'شلل الأطفال، المدرج ضمن جدول تطعيمات طفلكِ لهذا الشهر، مرض انخفض انتشاره عالميًا بنسبة 99% بفضل نجاح حملات التطعيم. ويصيب هذا المرض بصورة رئيسية الأطفال الذين تتراوح أعمارهم بين 3-5 سنوات، وينتقل عبر الجهاز الهضمي؛ وقد يسبب الحمى وآلام العضلات والغثيان وتيبس الرقبة. ويمكن لهذا الفيروس المُعدي أن يؤثر في الدماغ والحبل الشوكي، مسببًا الشلل. ويواجه الأطفال المصابون صعوبة في المشي وقد يعجزون عن تحريك بعض أجزاء أجسامهم. ونظرًا إلى أن الفيروس قد يبقى في البراز لأسابيع، فإن احتمال انتقال العدوى يكون مرتفعًا. لذلك، من المهم جدًا لصحة المجتمع أن يتلقى طفلكِ وجميع الأطفال هذا اللقاح.') WHERE id = '1a8e6e94-b6f4-462b-8ffe-8f3b0bd314c0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد تناول البصل والثوم، خصوصًا لدى الأطفال، موضوعًا يختلف الناس حول مدى ضرورته. لكن تجدر الإشارة إلى أن هذه الأطعمة، خلافًا للاعتقاد الشائع، غنية بمواد عضوية وغير عضوية مفيدة جدًا لجسم طفلكِ. يحتوي البصل على كميات كبيرة من المواد المضادة للالتهاب (anti-inflammatory)، ما يساعد على حماية جهاز طفلكِ المناعي. كما يعزز امتصاص الحديد في الجسم، ويُعد غذاءً مهمًا جدًا لصحة قلب طفلكِ وأوعيته الدموية. أما الثوم، فيُستخدم خصوصًا عند الإصابة بنزلات البرد، لأن مادة الأليسين الموجودة فيه تتمتع بخصائص قوية مضادة للفيروسات والبكتيريا. وتمنح مادة الأليسين الثوم رائحته النفاذة، كما تقلل بدرجة كبيرة احتمال إصابة طفلكِ بالربو. لذلك، إذا لم يكن طفلكِ يعاني حساسية تجاه البصل أو الثوم، فيمكنكِ إضافتهما إلى وجباته لإكسابها نكهة والاستفادة من موادهما المفيدة.') WHERE id = 'f5208cf0-5ee3-4de4-b5a0-87ec5de504e3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يمر طفلكِ بنوبات غضب متكررة خلال الفترة العمرية بين 16-30 شهرًا. وقد تظهر هذه النوبات في صورة بكاء أو عناد أو إلقاء نفسه على الأرض أو رمي الأشياء أو إيذاء المحيطين به. بل إن حبس النفس لفترة وجيزة وشد الشعر والرموش يُعدّان أيضًا من علامات الغضب في هذه المرحلة لدى بعض الأطفال. وفي الواقع، تُعد هذه السلوكيات جزءًا طبيعيًا من نمو طفلكِ. وباختصار، إنها تعبير عن صراع داخلي بين التعلق من جهة، والاستقلال وتكوين الهوية الفردية من جهة أخرى. فقد أصبح طفلكِ يرغب في أن يكون له، مثلكِ، رأي في قراراته ومحيطه. وعندما لا تتحقق توقعاته أو يعجز عن التعبير عن نفسه، تظهر نوبات الغضب. والأهم أن يتجاوز طفلكِ هذه المرحلة وقد اكتسب سلوكيات صحية. لذلك، وحتى لا تتحول هذه التصرفات إلى عادة، لا تستجيبي لمطالبه في أثناء نوبة الغضب وحافظي على هدوئكِ. ويمكنكِ احتضانه وإخباره بمدى حبكِ الكبير له، فالحب قادر على التغلب على كل الصعوبات! 😊') WHERE id = '9f0c0e63-5e12-470a-97c1-46850067a0b3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد قاعدة الانتظار لمدة 3 أيام التي تتبعينها في تغذية طفلكِ مهمة جدًا لمراقبة ردود فعله المحتملة تجاه الأطعمة خلال مرحلة إدخال الأغذية التكميلية. وينبغي أن تواصلي اتباع هذه الطريقة حتى تترسخ عادات طفلكِ الغذائية بالكامل. ولأن جهازه المناعي لم يكتمل نموه بعد، فقد يصاب برد فعل تحسسي تجاه طعام لم يتذوقه من قبل. وكلما تناول كمية أكبر من الأطعمة المسببة للحساسية، زادت شدة رد فعل جسمه. لذلك ينبغي مواصلة توخي الحذر عند تقديم الأطعمة الجديدة. وقد لا تكون علامات الحساسية لدى طفلكِ جسدية فقط، لذا يُفضّل ألا تجبريه على تناول الأطعمة التي يرفضها بإصرار. وإذا شعر طفلكِ بعد تناول طعام جديد بالانزعاج أو الغثيان، أو أصيب بالقيء أو الإسهال أو البكاء أو مشكلات النوم، فقد تكون لديه حساسية تجاه ذلك الطعام. وفي هذه الحالة، جرّبي تقديمه مجددًا بعد مرور بعض الوقت، وإذا تكررت الأعراض نفسها، فأزيلي ذلك الطعام تمامًا من نظامه الغذائي.') WHERE id = '8608ab19-70eb-4523-8e11-483348dadd13';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن تناول طفلكِ الطعام بنفسه في هذه المرحلة لا يقتصر على إشباع جوعه فحسب، بل يساهم أيضًا في تنمية مهاراته الحركية الدقيقة وحواسه. لذلك، احرصي على تحويل أوقات طعام طفلكِ إلى نشاط استكشافي أيضًا. وينبغي أن تتضمن الوجبات التي تحضّرينها أطعمة يستطيع طفلكِ إمساكها بيده. فهذا يتيح له استخدام العديد من حواسه، مثل لمس الطعام الذي يتناوله ورؤيته وشمّه. يتفحّص طفلكِ الطعام الذي يمسكه بيده ويتعلم الكثير عن قوامه، كما يكوّن تصورًا أفضل عن صلابته ومذاقه ورائحته. ولتهيئة الظروف المناسبة لهذه العملية التعليمية الهادفة والراسخة، حاولي قدر الإمكان ألّا تستعجلي طفلكِ أثناء تناول الطعام وأن تمنحيه الوقت الكافي. فقد يكون الطعام الذي يبدو لكِ عاديًا للغاية تجربة جديدة تمامًا تحفّز فضول طفلكِ وجميع حواسه. ولهذه الأسباب كلها، قد تستغرق عملية تناول طفلكِ الطعام بنفسه وقتًا أطول، وقد تتسخ المساحة المحيطة أكثر، وربما يتناول كمية أقل من الطعام. لكن المهارات التي سيكتسبها تستحق كل هذه الصعوبات. 😊') WHERE id = '21efd94a-bfd9-406a-952f-b46e38e5bf10';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد دخلتِ مرحلة مثمرة جدًا لتعليم طفلكِ القواعد العامة للآداب والسلوك. فقد بلغ طفلكِ الآن مستوى من النمو الذهني يمكّنه من التمييز بين كلمتي «نعم» و«لا» وفهم معناهما. والخطوة الأولى التي ينبغي لكِ اتخاذها هي أن تتصرّفي أنتِ أيضًا بالطريقة التي ترغبين في أن يتصرّف بها طفلكِ. فهو يراقب تصرفاتكِ بعناية ويقلّدها ويجعلها جزءًا راسخًا من حياته. لذلك، عليكِ أن تبدئي بنفسكِ. فعلى سبيل المثال، يمكنكِ أن تقولي «من فضلك» عندما تطلبين شيئًا من شريك حياتكِ ضمن روتينكما اليومي. وعندما يعطيكِ ما طلبتِ، فإن قولكِ «شكرًا» وتبادلكما الابتسامة سيقدّمان لطفلكِ نموذجًا مؤثرًا للغاية. لكن المهم هو استخدام هذه العبارات في مواضعها الصحيحة؛ فاستخدامها بلا داعٍ أو في غير موضعها لن يجعلها بلا معنى فحسب، بل قد يسبّب أيضًا التباسًا لدى طفلكِ.') WHERE id = '9b06aba9-9cdc-4627-9c02-97bc750c0a43';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا شك في أهمية الخضراوات والفواكه لطفلكِ. لكن عليكِ ألّا تنسي أن بعض الأطعمة قد ترهق جهازه الهضمي وتسبّب له غازات شديدة. فبعض الخضراوات، على وجه الخصوص، تحتوي على كميات كبيرة من الألياف ونسب أعلى من الكربوهيدرات، وقد يؤدي ذلك إلى زيادة تكوّن الغازات. ولأن جهاز طفلكِ الهضمي لم يكتمل نموه بعد، فقد تسبّب له هذه الغازات انتفاخ البطن والألم. فعلى سبيل المثال، رغم أن البروكلي غني بالألياف المفيدة، فإنه قد يسبّب الإسهال والغازات لدى طفلكِ. ومن الأمثلة الأخرى الذرة، وهي من الأطعمة الغنية بالسعرات الحرارية؛ إذ قد تؤثر سلبًا في أمعاء طفلكِ بسبب محتواها المرتفع من النشا. تذكّري أن لكل طفل خصائص نمو فريدة. فقد لا تسبّب الأطعمة التي تُعد عمومًا مسببة للحساسية أو صعبة الهضم أي مشكلة لطفلكِ. وفي الوقت نفسه، قد لا يناسب طفلكِ طعام يتناوله كثير من الأطفال بسهولة. لذلك، عندما تقدّمين له طعامًا للمرة الأولى، ابدئي بكمية قليلة ثم زيديها بعد التأكد من عدم ظهور أي رد فعل لديه.') WHERE id = '7e49be16-0698-4a6e-9dce-ad753c99571b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أنتِ الآن في مرحلة تجاوز فيها طفلكِ صعوبات الاستقلال الفردي وبدأ يصبح أكثر ميلًا إلى التواصل الاجتماعي. وهذا يعني أن القلق والخجل اللذين كان يشعر بهما عند رؤية شخص غريب قد أصبحا من الماضي! 😊 وقد يتصرّف الآن براحة أكبر مع الغرباء والأقارب الذين لا يراهم كثيرًا، كما قد تصبح رغبته في التواصل ملحوظة بوضوح. فعلى سبيل المثال، قد يشارك طفلكِ ألعابه مع طفل في عمره يلتقيه للمرة الأولى، أو قد يطرح عليكِ أسئلة ليتعرّف إليه. وبالطبع، قد يختلف ذلك بحسب شخصية طفلكِ والعوامل المحيطة به. فقد يعترض مثلًا على شخص يريد اللعب بألعابه ويُظهر انزعاجه من ذلك. وعندما تواجهين موقفًا كهذا، من المهم جدًا أن تدعمي طفلكِ ليأخذ الخطوة الأولى، لما لذلك من دور في نموه الاجتماعي واكتسابه مهارة المشاركة.') WHERE id = 'c5cfc776-e1c8-43f0-953d-42780e4b7f8c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكي يتمتع طفلكِ بجهاز مناعي قوي، يحتاج إلى مضادات أكسدة مثل فيتامينات A وC وE، والبيتا كاروتين، والإنزيم المساعد Q10، والليكوبين، والزنك، والسيلينيوم. كما أن لهذه المواد دورًا فعالًا في حماية جسم طفلكِ من الاضطرابات التي قد تصيبه. فعلى سبيل المثال، تُعد مضادات الأكسدة بالغة الأهمية في مواجهة أنواع السرطان التي ازداد انتشارها خلال السنوات الأخيرة بفعل العوامل البيئية. وتشير المؤلفات العلمية إلى أن بذور العنب من أقوى المواد المضادة للأكسدة المكتشفة حتى الآن. وقد استخدم الأطباء بذور العنب لأغراض علاجية منذ قرون، كما تُباع في بعض البلدان على هيئة مستحضر دوائي. لكن تقديم حبات العنب مع بذورها لطفلكِ قد يعرّضه لبعض المخاطر، مثل الاختناق. لذلك، يمكنكِ شراء مسحوق بذور العنب الجاهز، أو تجفيف بذور العنب الذي تشترينه في موسمه وطحنها ثم إضافتها إلى لبن طفلكِ الرائب.') WHERE id = '9c338815-035b-4a44-b747-28796d4ff2d6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا للبيانات العلمية، تضاعف معدل انتشار الربو تقريبًا خلال السنوات 40 الماضية. وقد تمثل هذه المشكلة، التي تهدد الجميع، خطرًا على طفلكِ أيضًا. فالربو في الأساس رد فعل تُبديه الممرات الهوائية تجاه مختلف المهيّجات، وهو مرض يظهر من خلال أعراض مثل السعال المتكرر والأزيز وضيق التنفس. ويكون الربو لدى الرضّع والأطفال ذا منشأ تحسّسي في 90% من الحالات. وعادةً ما تظهر خلال أول عامين من العمر مؤشرات الربو الذي قد يتطور مستقبلًا. ويزداد خطر الإصابة بهذا المرض بمقدار خمسة أضعاف لدى الأطفال الذين يعاني أحد والديهم من الربو أو التهاب الأنف التحسّسي. لذلك، إذا كنتِ أنتِ أو شريك حياتكِ مصابًا بالربو، فقد تحتاجين إلى مراقبة طفلكِ بعناية أكبر. ويُعد عث غبار المنزل وحبوب لقاح الأعشاب والحشائش والأشجار وفطريات العفن والحيوانات الأليفة من أكثر مسببات الحساسية شيوعًا لدى الأطفال. بالإضافة إلى ذلك، إذا كان طفلكِ يعاني من حساسية تجاه أحد الأطعمة، فعليكِ إبعاد ذلك الطعام عنه قدر الإمكان.') WHERE id = 'cda62213-9742-4d04-a666-8ec8123d5bcc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اليقطين من أغنى الثمار بفيتامين A والبيتا كاروتين، لذا ينبغي أن يكون جزءًا أساسيًا من النظام الغذائي لطفلكِ. ويحتوي اليقطين على العديد من المعادن، كما يُعد مصدرًا للبوتاسيوم والحديد والبروتين. تتحول البيتا كاروتين عند هضمها في الجسم إلى فيتامين A، أي إنها مادة أولية لتكوين هذا الفيتامين. وتتراكم هذه المادة، التي تُسمى طليعة الفيتامين، في كبد طفلكِ وتتحول مجددًا إلى فيتامين A عند الحاجة. والبيتا كاروتين من مضادات الأكسدة القوية التي تساعد على تخليص الجسم من الجذور الحرة. وبذلك تدعم الجهاز المناعي لطفلكِ وتساعد جسمه على مقاومة العدوى. يمكنكِ تحضير اليقطين لطفلكِ على شكل حساء. ابدئي بتقطيع كمية من اليقطين تكفي لملء وعاءين متوسطَي الحجم. ضعي 400 مل من الحليب و400 مل من الماء وحبتين متوسطتي الحجم من الجزر المقطع مع اليقطين واتركي المكونات تُطهى. ويمكنكِ إضافة البصل أو مرق الدجاج حسب الرغبة. بعد نضج المكونات، اخلطيها بالخلاط حتى يصبح قوامها ناعمًا. أصبح حساء اليقطين جاهزًا! 😊') WHERE id = '3e60272a-da0e-434b-a209-3dcddf9e3abc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيبدأ طفلكِ قريبًا في التمييز بين الألوان واختيار الألوان التي يفضلها. لذلك، فإن تعلّمه أسماء الألوان سيساعده على اكتساب كلمات جديدة والتمييز بينها بوضوح أكبر. استخدمي أسماء الألوان في أحاديثكِ اليومية معه أثناء تعليمه إياها. فعلى سبيل المثال، عندما تريان كلبًا في الخارج، يمكنكِ وصفه بقولكِ: انظر، هذا كلب أسود! بدلًا من قول: انظر، هذا كلب! ويمكنكِ شراء أقلام تلوين بألوان قوس قزح لطفلكِ كي يستكشف الألوان بطريقة ممتعة. دعيه يختار الألوان بنفسه أثناء الرسم، وردّدا معًا اسم اللون الذي اختاره. ومن المهم خلال هذا النشاط الممتع ألا تضغطي على طفلكِ كي يتعلم الألوان. وتذكّري أيضًا أنه قد لا يتمكن من تعلّم جميع الألوان بدقة تامة خلال وقت قصير.') WHERE id = '32be02db-2c4a-4a1c-a266-929a18f6c892';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُتوقع في هذه المرحلة أن يكون يافوخ طفلكِ قد انغلق تمامًا. ويحدث انغلاق اليافوخ في المتوسط بين الشهرين 12 و18. فإذا كان يافوخ طفلكِ قد انغلق خلال هذه المدة، فلا داعي للقلق. أما إذا لم ينغلق بعد، فلا يعني ذلك بالضرورة وجود مشكلة، لكنه قد يستلزم المتابعة الدقيقة وإجراء بعض الفحوصات. سيتحقق طبيبكِ في فحص الشهر 18 من انغلاق اليافوخ. وإذا لم يكن قد انغلق، فيمكنكِ طلب معلومات مفصلة من طبيبكِ. ويذكر المختصون أن نقص فيتامين D وقصور الغدة الدرقية، أي انخفاض وظائفها، من أسباب تأخر انغلاق اليافوخ. وفي هذه الحالة، قد يطلب طبيبكِ بعض التحاليل الكيميائية الحيوية لفحص هرمونات الغدة الدرقية وتحديد ما إذا كان طفلكِ يعاني من نقص فيتامين D.') WHERE id = '34c66686-e288-4c81-acc0-070c8d4b0acc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أصبحتِ أمًا منذ 1.5 عام. نهنئكِ! لقد دخلتِ مرحلة أصبح فيها طفلكِ أكثر حركة من ذي قبل. وتمثل هذه المرحلة بداية تصبح فيها أنشطته اليومية أكثر وضوحًا وارتباطًا بأهداف محددة. أصبح صغيركِ الآن يفهم السلوكيات المسموح بها والممنوعة، ويستطيع أن يُظهر لكِ رضاه أو غضبه تبعًا لذلك. وعلى الرغم من محاولتكِ منعه، فقد يصرّ على التعبير عما يريده، ويزداد شعوره بنفسه بوصفه فردًا مستقلًا. وعلى الأرجح، لن يرغب بعد الآن في انتظار ما يريده، لأن مفهوم الوقت لم يكتمل بعد لدى الأطفال في هذا العمر. فعلى سبيل المثال، إذا أراد طفلكِ لعبته أثناء تناول الطعام، فقد يشعر بالارتباك عندما تقولين له: الآن وقت الطعام، وستلعب بلعبتك لاحقًا. لذلك، تمرين بمرحلة تحتاجين فيها إلى التحلي بمزيد من الصبر مع طفلكِ، فهو لا يزال بحاجة إلى الوقت كي يستوعب مفاهيم مثل بعد قليل ولاحقًا.') WHERE id = '466241d8-ca2b-43a2-bf81-53a5de3a0ea0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيُجري الطبيب فحصًا شاملًا لطفلكِ خلال الفحص الروتيني لهذا الشهر، لذا كوني مستعدة لذلك. سيتحقق الطبيب أثناء الفحص من نمو طفلكِ الجسدي والعقلي، وما إذا كان طوله ووزنه ضمن الحدود الطبيعية المناسبة لعمره. وقد يطرح عليكِ أيضًا بعض الأسئلة لمعرفة مدى قدرته على استخدام مهاراته الحركية الدقيقة والكبيرة. اعتبارًا من هذا الشهر، قد يبلغ الحد الأدنى لوزن طفلكِ 8000 غرام والحد الأعلى 14.000 غرام. ويُتوقع أن يتراوح طوله بين 75 سم و87 سم. وبالطبع، تذكّري أن هذه المؤشرات قد تختلف، وأن طفلكِ قد يكون بصحة جيدة حتى لو كانت قياساته خارج هذه الأرقام. وسيقدم لكِ الطبيب الذي يتابع طفلكِ منذ ولادته المعلومات الأدق. وقد يكون من الجيد أن تدوّني على ورقة الأسئلة التي تشغل بالكِ قبل الذهاب إلى الفحص.') WHERE id = '533e198b-5f73-4c58-b031-2b0fc6d70ee4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُسمى الأطعمة التي تمنح طفلكِ الطاقة من دون أن تحتوي على العناصر الغذائية التي تدعم نموه الجسدي والعقلي بالأطعمة ذات السعرات الحرارية الفارغة. وتُعد هذه الأطعمة أحد العوامل التي تزيد خطر إصابة طفلكِ بالسمنة، أي زيادة الوزن، في المستقبل. لذلك، بدلًا من تقديم الخبز الأبيض منخفض القيمة الغذائية لطفلكِ، اختاري منتجات الحبوب الكاملة. تتميز الحبوب الكاملة بانخفاض مؤشرها السكري، ما يعني أنها لا تسبب ارتفاعًا أو انخفاضًا مفاجئًا في مستوى سكر الدم. وبذلك قد تساعد على الوقاية من مشكلات مثل داء السكري ومقاومة الإنسولين. كما تؤثر الحبوب الكاملة الغنية بالألياف إيجابيًا في الجهاز الهضمي لطفلكِ ولا تسبب الإمساك. ويمكنكِ إدراج دقيق القمح الكامل والبرغل والجريش والأرز البني والجاودار بانتظام في النظام الغذائي لطفلكِ.') WHERE id = '2fec9266-9a6a-4223-a4c3-f290f9054c35';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'التهاب الكبد A، المدرج لقاحه ضمن جدول تطعيمات طفلكِ لهذا الشهر، هو عدوى شديدة الانتقال تصيب الكبد ويسببها فيروس التهاب الكبد A. وهذا الفيروس واحد من عدة فيروسات لالتهاب الكبد تؤثر في وظائفه وتسبب التهابه. لا يزال التهاب الكبد A منتشرًا على نطاق واسع حول العالم، ويشيع عادةً خلال فصل الخريف والأشهر الأولى من الشتاء. وتُعد الجرعتان اللتان تُعطيان في عمر 12 و24 شهرًا أكثر وسائل الوقاية فعالية. تحمي هاتان الجرعتان، اللتان تفصل بينهما 6 أشهر، طفلكِ من هذا المرض لنحو 20 عامًا. قد تشمل الآثار الجانبية الموضعية للقاح الألم أو التحسس أو الاحمرار في موضع الحقن، ويظهر ذلك لدى 15-20% من الأطفال. أما الحمى والإسهال والإرهاق فتُلاحظ لدى أقل من 10% منهم. وعند الحاجة، يمكنكِ استخدام أدوية تحتوي على الباراسيتامول بعد استشارة الطبيب.') WHERE id = '6b1536bb-dc88-4b75-bf0c-4f8004f171e6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يزال يستخدم زجاجة الرضاعة، فقد حان الوقت للبدء بتقليل اعتماده عليها. ينبغي أن تحل محلها تدريجيًا أكواب التدريب أو الأكواب العادية أو الملعقة. تذكّري أنه كلما طالت مدة اعتماده على زجاجة الرضاعة، أصبحت عملية فطامه عنها أصعب وأكثر إزعاجًا. وإذا كان طفلكِ ينام وهو يرضع من الزجاجة، فسيطلب تكرار الروتين نفسه كلما استيقظ، وقد يؤدي ذلك إلى مقاومة النوم والعناد. ورغم أن الحد الأقصى الموصى به للتوقف عن استخدام زجاجة الرضاعة هو عمر سنتين، فإن معظم المختصين ينصحون بإنهاء استخدامها قبل إتمام الطفل عامه الثاني. فقد يؤثر استخدامها لفترة طويلة سلبًا في صحة أسنان طفلكِ وبنية فكه. لذلك شجّعي طفلكِ على استخدام الكوب. ويمكنكِ جعل الأمر أكثر تشويقًا من دون إجباره، كأن تختاري له أكوابًا ملوّنة تحمل صور شخصياته المفضلة.') WHERE id = '3558e6e1-3996-42d0-9094-3715d454af37';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا لنظرية التعلّق التي طرحها المختصون، ينمّي الأطفال الذين تُلبّى احتياجاتهم في الوقت المناسب وباستمرار تصورًا أكثر إيجابية عن ذواتهم والعالم من حولهم. ومن هذا المنطلق، يحتاج طفلكِ خلال مرحلة معينة من حياته إلى النوم في الغرفة نفسها معكِ كي يشعر بوجودكِ وحبكِ. كما أن معرفته بأن احتياجاته ستُلبّى سريعًا تقلل فترات بكائه وقلقه، ما يسهم بفاعلية في تنمية شعوره الأساسي بالأمان. لكن عليكِ أن تتذكّري أنكما تقتربان من الحد الأقصى لفترة النوم في الغرفة نفسها. يرى معظم المختصين أنه ينبغي للأطفال أن يناموا بصورة مستقلة عن والديهم عند بلوغهم عمر سنتين، أو 3 سنوات على أقصى تقدير. وكلما طالت هذه الفترة، ازدادت مقاومة طفلكِ للنوم في غرفة منفصلة، واستغرق تخليه عن عاداته وقتًا أطول. إذا لم تكوني قد بدأتِ بعد بتعويد طفلكِ على النوم منفصلًا، فقد يكون عليكِ البدء بذلك تدريجيًا. فعلى سبيل المثال، سيساعدكِ البقاء بجانبه حتى ينام ولبعض الوقت بعد نومه على جعل الانتقال في هذه المرحلة لطيفًا وسلسًا.') WHERE id = '20063b79-c6ac-4e2d-80ba-90afeb71cf22';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ انتقائي تجاه بعض الأطعمة. ولعل السؤال الأهم الذي يتبادر إلى ذهنكِ حينها هو: ماذا ينبغي أن تفعلي كي يأكل؟ أولًا، عليكِ التحلي بالصبر عند التعامل مع طفلكِ الانتقائي في الطعام، لأن إجباره قد يزيد الوضع تعقيدًا. ووفقًا للأبحاث، يحتاج الطفل إلى تجربة الطعام الجديد من 7 إلى 15 مرة على الأقل لمعرفة ما إذا كان سيحبه أم لا. لكن لا ينبغي فهم هذه الأرقام على أنها أيام متتالية؛ فقد يؤدي تقديم الطعام نفسه 7 أيام متتالية إلى رد فعل أشد من طفلكِ. والهدف هنا هو إعادة تقديم الطعام الذي يرفضه طفلكِ بطرق مختلفة وعلى فترات متباعدة. فعلى سبيل المثال، قد لا يتناول طفلكِ طبقًا من الملفوف أو الخرشوف، لكن هل يعني ذلك أنه لن يحب حساء الملفوف أو الخرشوف أيضًا؟ بالطبع لا. لذلك يمكنكِ التفكير في طرق مختلفة لتقديم الطعام الذي يرفضه طفلكِ، أو في إعداد طبق ذي شكل ممتع وجذاب.') WHERE id = '7f4447c8-54a4-4590-9ce6-4ab697ab8292';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد عمل الأيض لدى طفلكِ في الظروف المثالية أحد العوامل الأساسية التي تساعده على عيش حياة صحية ومديدة، الآن وفي المستقبل. تؤدي هرمونات الغدة الدرقية دورًا فعالًا في العديد من الوظائف المهمة، بدءًا من قوة انقباض عضلة قلب طفلكِ وحركات التنفس، ومرورًا بامتصاص الأمعاء وإنتاج الحرارة وتكوين خلايا الدم الحمراء، ووصولًا إلى نمو العظام. ويعتمد إنتاج الغدة الدرقية للهرمونات على الإشارات القادمة من الغدة النخامية الموجودة في دماغ طفلكِ. يصل الهرمون المطلق للثيروتروبين القادم من الغدة النخامية إلى الغدة الدرقية، فيحفّزها على إنتاج هرموناتها. وقد لا يعمل هذا النظام الهرموني، بالغ الأهمية لجسم طفلكِ، بكفاءة أحيانًا بسبب نقص اليود أو مشكلات وراثية، ولا سيما تلك المرتبطة بزواج الأقارب. لذلك من المهم أن تحرصي على إجراء الفحوصات الطبية وتحاليل الدم الدورية لطفلكِ. وإذا لاحظتِ أعراضًا مثل الخمول أو فقدان الشهية أو الزيادة أو الخسارة السريعة في الوزن أو الميل إلى النوم أو التعرق، فعليكِ التواصل مع طبيبكِ بالتأكيد.') WHERE id = 'e05fab87-4d28-4824-90c1-9888d35bd222';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كيف يمكنكِ حماية طفلكِ من العادات الغذائية الضارة والأطعمة غير الصحية؟ ببساطة، بعدم تعريفه بهذه الأطعمة من الأساس. وليكن مبدؤكِ الأساسي في هذا الشأن أن طفلكِ لن يطلب طعامًا لا يعرف مذاقه. لذلك ينبغي ألا تدعيه يتذوق، ولو لمرة واحدة، المقليات أو الشوكولاتة أو الأطعمة السكرية أو مختلف أنواع الوجبات السريعة التي قد يتعلق بها بسهولة. واطلبي دعم زوجكِ والمقربين منكِ في هذا الأمر، واشرحي لهم وجهة نظركِ وأسبابها. وإذا كنتِ لا تريدين أن يكتسب طفلكِ عادات ضارة، فعليكِ البدء بإصلاح نظامكِ الغذائي أنتِ. فحرمان طفلكِ من الأطعمة التي تتناولينها أنتِ أمر غير منصف، كما أنه خطوة محكوم عليها بالفشل. يتخذ طفلكِ السلوكيات التي يراها منكِ داخل الأسرة قدوةً له أكثر من أي شيء آخر. لذلك عليكِ أن تكوني قدوة حسنة لطفلكِ.') WHERE id = 'e3f55e9e-f1cb-4704-8833-dfaa00152285';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ قادرًا على التحكم الكامل في حركاته، بفضل تطور مهاراته الحركية الدقيقة والكبيرة على وجه الخصوص. وتفتح المهارات الجديدة التي اكتسبها نتيجة هذا التطور مرحلة استقلاله التدريجي عن والديه وتكوين شخصيته الفردية. كما تتيح له هذه المهارات فرصة اكتشاف عالم مختلف تمامًا. ومع ذلك، وعلى الرغم من ميله إلى الاستقلال، لا يزال طفلكِ يرغب في العودة إليكِ والاحتماء بكِ كما كان يفعل في أيامه الأولى. فهو يدرك أن استكشاف هذا العالم الجديد يبعدكِ عنه في الوقت نفسه، وهذا يثير قلقه. وبسبب هذا التناقض الداخلي تحديدًا، قد يمر طفلكِ خلال هذه المرحلة ببعض اللحظات المقلقة والصعبة نفسيًا. لذا، فإن طريقة استجابتكِ لهذه الحالات بالغة الأهمية. ومن الضروري أن تدركي صعوبة هذه المرحلة، وألا تضعي أمام طفلكِ عوائق غير ضرورية، وأن تتيحي له حرية الاستكشاف ضمن الحدود التي تحددينها.') WHERE id = '74802a2c-bfa6-467b-b33a-aee4b83ccdbc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يتميز البيض الذي أدرجتِه في النظام الغذائي لطفلكِ بقيمة غذائية عالية، سواء في البياض أو الصفار. فهو يحتوي على فيتامينات A وB5 وB12 وB2 وB6 وD وE وK، إلى جانب الكالسيوم والزنك والفوسفور والسيلينيوم وحمض الفوليك. لكن هذا الغذاء المهم جدًا لطفلكِ قد يسبب بعض المشكلات إذا لم يُطهَ جيدًا. تعيش بكتيريا السالمونيلا في أمعاء الطيور بصورة أساسية، وكذلك في أمعاء بعض الحيوانات والبشر. وعادةً ما تنتقل إلى الإنسان عند تناول أطعمة لامست براز الحيوانات. لذلك، عليكِ طهو البيض جيدًا قبل تقديمه لطفلكِ. ومن المهم سلقه لمدة ١٠ دقائق تقريبًا والتأكد من عدم بقاء أي جزء نيئ فيه. فالطهو الجيد للأطعمة عالية الخطورة، مثل البيض ولحوم الدواجن والخضراوات والفواكه النيئة، يقضي على بكتيريا السالمونيلا. لكن انتبهي إلى أن سلق البيض مدة أطول من اللازم قد يقلل من قيمته الغذائية، لذا احرصي على ضبط مدة الطهو بشكل صحيح.') WHERE id = 'e467989b-610e-431a-a5b3-8aea02815e27';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تقع مسؤولية تعليم طفلكِ مفهوم المشاركة عليكِ وعلى شريك حياتكِ. ومن الطبيعي خلال هذه المرحلة أن يتمسك طفلكِ بأغراضه وألا يرغب أحيانًا في مشاركتها مع الآخرين، لكنه يحتاج أيضًا إلى تعلّم المشاركة. وغالبًا ما يكون الشعور بالغيرة أقوى لدى الأطفال الذين ينشؤون من دون إخوة مقارنةً بمن يكبرون مع إخوتهم. ويمكن لطفلكِ، عندما يكتسب مفهوم المشاركة، أن يصبح مستقبلًا أكثر قدرة على تكوين الصداقات وأكثر ارتياحًا وثقة بالنفس في محيطه الاجتماعي. في المقابل، قد يُظهر الأطفال الذين لا يكتسبون هذا الوعي مستقبلًا سلوكيات تتسم بالغيرة وصعوبة التوافق والعزلة الاجتماعية وعدم التكيف، بل والعدوانية في بعض الحالات. لذلك يرى المختصون أن على الأسر تعليم أطفالها مفهوم المشاركة وكيفية اكتسابه قبل بلوغ سن ٣ سنوات. وأكثر طرق التعلم فاعلية لطفلكِ هي أن يمارس المشاركة ويختبرها، والأهم أن يراقب من حوله. لذا عليكِ أن تبدئي بسلوكياتكِ أنتِ.') WHERE id = '97d2971b-be18-4119-ba9c-e15cc4978bea';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تقتصر أهمية الدهون لجسم طفلكِ على تلبية احتياجاته من الطاقة، بل تساعد أيضًا على امتصاص فيتامينات مثل A وD وE وK. وعندما لا تكفي الكربوهيدرات التي يتناولها لتوفير الطاقة التي يحتاج إليها، يستخدم الجسم الدهون المخزنة لديه. كما تزوّد الدهون التي يحصل عليها طفلكِ من الغذاء جسمه بالأحماض الدهنية التي لا يستطيع إنتاجها، وتدعم نموه وتطوره. وإضافةً إلى مساهمتها في سلامة عمل الجهاز الهضمي، تساعد الدهون أيضًا على الحفاظ على مرونة أغشية الخلايا والجلد. لكن عليكِ الحرص على تلبية احتياجات طفلكِ من الدهون عن طريق الأحماض الدهنية غير المشبعة بدلًا من الدهون المشبعة. وتُعد أوميغا-3 وأوميغا-6 وأوميغا-9 من أكثر الدهون فائدة لنمو طفلكِ الصحي. وتوجد هذه الدهون بصورة أساسية في الأسماك، كما توجد في حليب الأم والبيض وحليب البقر وبذور الكتان والبندق والأفوكادو وزيت الزيتون.') WHERE id = '026bfc7a-ffb1-444b-accf-fb194f005a8f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج الجهاز المناعي لطفلكِ إلى إنتاج عدد كافٍ من خلايا الدم البيضاء (الكريات البيضاء) ليتمكن من مكافحة العدوى بفاعلية. فخلايا الدم البيضاء من أهم عناصر الدفاع في الجسم، إذ تقضي على الكائنات الحية الدقيقة الضارة التي تدخل جسم طفلكِ. وكلما ازداد عدد هذه الكائنات التي تدخل الجسم، ينشط نخاع العظم لإنتاج المزيد من خلايا الدم البيضاء. لكن عملية الإنتاج هذه تتباطأ عند نقص البروتين الذي يدخل في تكوين هذه الخلايا. لذلك، من المهم أن يحصل طفلكِ على البروتين يوميًا. وتُعد اللحوم الحمراء واللحوم البيضاء والأسماك مصادر عالية الجودة للبروتين. ومع ذلك، قد يسبب الإفراط في تناولها آثارًا جانبية، لأن هذه البروتينات الحيوانية تحتوي أيضًا على كميات مرتفعة من الدهون المشبعة. لذا عليكِ التنويع بين مصادر البروتين النباتية والحيوانية وإدراجها بالتناوب في قائمة طعام طفلكِ.') WHERE id = '4719da49-3633-43ff-be20-a04c8e0aa86d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُحضَّر أطعمة الأطفال عمومًا من دون توابل، ما يجعل مذاقها محايدًا، وذلك بسبب الاعتقاد بأن التوابل قد تضر بالأطفال. ويرى المختصون أن هذا قد يجعل طفلكِ انتقائيًا في تناول الطعام مستقبلًا، وقد يؤدي إلى بعض اضطرابات التغذية. وتتميز التوابل بغناها بمضادات الأكسدة وخصائصها المضادة للالتهاب، لذا فهي مفيدة في مكافحة الالتهابات وتنظيم ضغط الدم والحد من الأضرار التي تسببها الجذور الحرة. ويمكنكِ بدءًا من الشهر الثامن تقريبًا إضافة التوابل التي ترغبين فيها إلى وجبات طفلكِ. ويُعد الفلفل الأسود والريحان وإكليل الجبل والقرفة والنعناع والزنجبيل والشبت والكمون والكركم والزعتر والفلفل الأحمر الحلو من التوابل التي يمكنكِ استخدامها بأمان في طعام طفلكِ. لكن قد تكون لدى طفلكِ حساسية تجاه بعض المواد، لذلك إذا لم يسبق لكِ استخدام التوابل في طعامه، فمن الأفضل استشارة طبيبكِ.') WHERE id = 'f9a4f3eb-06ba-4c9f-a773-98194dac485a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يختلف معدل التبرّز من طفل إلى آخر. في هذه المرحلة، قد يتبرّز طفلكِ 3 مرات يوميًا أو مرة واحدة كل 3 أيام. تُفتَّت الأطعمة التي يتناولها طفلكِ في الجهاز الهضمي إلى مكوّناتها، ثم تنتقل المواد التي يحتاج إليها الجسم إلى الدم. أما الفضلات التي لا يستفيد منها الجسم أو التي تُعد غير ضرورية أو ضارة، فتُطرح عبر الشرج، وهو الجزء الأخير من الأمعاء الغليظة. لكن هذه الآلية قد تضطرب بسبب مشكلات ناتجة أساسًا عن اضطرابات التغذية. ويُعد الإمساك على وجه الخصوص من الحالات الشائعة جدًا خلال السنوات الأولى من العمر. إذا كان طفلكِ يعاني من الإمساك بصورة متكررة، فعليكِ مراجعة بعض الأمور. فعلى سبيل المثال، إذا كان نظام طفلكِ الغذائي يفتقر إلى الألياف، فمن المرجح جدًا أن يصاب بالإمساك. وقد تؤدي هذه الحالة إلى بعض المشكلات، مثل الشقوق الشرجية. كما أن قلة شرب الماء وعدم تناول ما يكفي من الفاكهة والخضراوات من العوامل الأخرى التي تهيئ للإصابة بالإمساك.') WHERE id = '3f922ccb-ecc8-46e0-b9c5-bd13cc1f11df';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد البروكلي من الخضراوات التي ينبغي أن تكون حاضرة بالتأكيد في قائمة طعام طفلكِ، خصوصًا خلال أشهر الشتاء، إذ إن حبة واحدة منه يمكن أن توفر نصف احتياجه اليومي من فيتامين C. ولأن شكله الذي يشبه شجرة صغيرة قد يجذب انتباه طفلكِ، فإن طهوه مع الحفاظ على شكله يُعد فكرة جيدة. وبفضل الألياف الموجودة فيه، يساعد البروكلي على إراحة الجهاز الهضمي لطفلكِ وحمايته من مشكلات مثل الإمساك. كما يمكنكِ من خلال البروكلي تلبية احتياجات طفلكِ بسهولة من معادن مثل الكالسيوم والمغنيسيوم والحديد والسيلينيوم والمنغنيز والبوتاسيوم والزنك، إلى جانب فيتامينات C وA وB16 وB2 وE. تؤثر مادة السلفورافان الموجودة في البروكلي إيجابيًا في خلايا دماغ طفلكِ. ووفقًا لأبحاث السنوات الأخيرة، يفيد تناول الأطعمة المحتوية على السلفورافان في علاج اضطرابات الدماغ. وتحتوي البراعم الموجودة في الجزء العلوي من البروكلي على كمية من السلفورافان تزيد 20 مرة على بقية أجزائه، لذا احرصي على أن يتناول طفلكِ هذا الجزء.') WHERE id = 'fdc70af8-a3f8-4766-bbcc-b755e0c46b80';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يفرز جسم طفلكِ، مثل أجسام البالغين تمامًا، هرمونات تحافظ على توازن الجسم في أوقات مختلفة من اليوم. وتؤثر الأنشطة اليومية والحركة البدنية والتغذية والحالة النفسية مباشرةً في إفراز هذه الهرمونات. ويؤدي هرمون الميلاتونين، شديد الحساسية، دورًا مهمًا في وظائف جسم طفلكِ. ولا يُفرز هذا الهرمون، الذي ينظم الإيقاع البيولوجي للجسم وساعته الداخلية، إلا ليلًا. لذلك ينبغي أن يكون طفلكِ نائمًا بحلول الساعة 21:00 كحد أقصى. يبدأ إفراز الميلاتونين في الساعة 21:00، ويبلغ ذروته بين الساعتين 02:00-04:00، وينتهي مع شروق الشمس. يخفض هرمون الميلاتونين درجة حرارة جسم طفلكِ في المساء لمنع فقدان الحرارة، ثم يرفعها صباحًا لإعداده للنشاط اليومي. كما يتمتع هذا الهرمون، الذي يُنتَج في الدماغ، بخصائص واقية من الفضلات السامة الناتجة عن التفاعلات الكيميائية الإيقاعية في الجسم. لذلك يحتاج طفلكِ إلى نوم ليلي منتظم ومتواصل. ولضمان إفراز الميلاتونين بفاعلية، عليكِ تهيئة طفلكِ جيدًا للنوم ليلًا.') WHERE id = 'a646f4e5-416b-4526-927d-bbba8c238b7c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن مذاق الأفوكادو قد لا يناسب الجميع، فإنه مفيد جدًا لطفلكِ لاحتوائه على فيتامينات A وK وE وC وB6. ولأن الأفوكادو سهل الهضم، فهو من الفواكه التي يمكن لطفلكِ تناولها بسهولة في مختلف مراحل نموه. وبفضل ما يحتوي عليه من معادن الكالسيوم والحديد والبوتاسيوم والصوديوم والمغنيسيوم، يساعد على تقوية الجهاز المناعي لطفلكِ وزيادة مقاومته للأمراض. كما يساعد الأفوكادو على ضبط إفراز الحمض في المعدة، وتحمي مضادات الأكسدة الموجودة فيه جسم طفلكِ من الآثار الضارة للجذور الحرة. وإضافة إلى ذلك، ثبت أن له تأثيرًا مضادًا للالتهاب، لذا يساهم في تسريع التئام الجروح وتعزيز تكوّن الأنسجة. ويأتي الأفوكادو الغني بالدهون غير المشبعة في مقدمة الأطعمة المفيدة لصحة عيني طفلكِ ودماغه. لذلك احرصي على إدراج الأفوكادو بانتظام في نظام طفلكِ الغذائي.') WHERE id = '1969883b-6fe0-4fba-a431-9f9a2571a7b1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد اكتشاف المضادات الحيوية وإتاحتها للبشرية نقطة تحول في تاريخ العالم، لأنها أنقذت حياة ملايين الأشخاص. لكن تبيّن خلال فترة قصيرة جدًا أن كثيرًا من البكتيريا اكتسبت مقاومة لها نتيجة الاستخدام الخاطئ والمفرط للمضادات الحيوية. وقد يسبب استخدام المضاد الحيوي دون ضرورة ضررًا لطفلكِ يفوق فائدته. إذ تغيّر المضادات الحيوية الفلورا المعوية لدى طفلكِ، فتقضي على الميكروبات النافعة وتضعف المناعة المخاطية التي تُعد من أهم آليات الدفاع في الجسم. لذلك من الضروري جدًا ألا تعطي طفلكِ أي مضاد حيوي ما لم يوصِ الطبيب بذلك. ونحن، أسرة Anacan، ننصحكِ بالحرص والانتباه إلى هذه المسألة حفاظًا على صحة طفلكِ.') WHERE id = '6e624b3e-94c9-432e-8301-03c5530ae9b0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد بكاء الطفل وشعوره بالألم أثناء التبول من الحالات التي تثير قلق الوالدين بشدة. وغالبًا ما تنتج هذه المشكلة عن عدوى المسالك البولية، وتُلاحظ لدى الرضيعات أكثر من الرضع الذكور، لأن الإحليل لدى الإناث أقصر. كما تهيئ بنية المسالك البولية بيئة مناسبة لتكاثر البكتيريا بسهولة والتسبب في الالتهاب. وبوجه عام، تدخل البكتيريا الموجودة في البراز داخل الحفاض إلى جسم الطفل، مما يؤدي إلى الإصابة بعدوى المسالك البولية. لذلك لا تتركي حفاض طفلكِ مدة طويلة، واحرصي على تغييره باستمرار. ونظرًا إلى أن الرضيعات أكثر عرضة لهذه العدوى، يجب تنظيف منطقة الحفاض من الأمام إلى الخلف. فهذا يقلل خطر انتقال البكتيريا الموجودة في البراز إلى المسالك البولية.') WHERE id = 'a63b7d54-8539-443a-910e-c4d4fabbbddd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تبقّى أقل من 6 أشهر حتى يبلغ طفلكِ عامه 2. وهذا يعني أنكِ قد تبدئين تدريجيًا بملاحظة علامات متلازمة عمر السنتين. تنشأ هذه المتلازمة في الواقع من الصراع الداخلي لدى طفلكِ بين رغبته في الاستقلال وخوفه من البقاء وحده. وفي هذه المرحلة، قد يدخل طفلكِ في صراع على السلطة مع المحيطين به، ويشعر بالتردد، ويقول «لا» لكل شيء. وعلى الأرجح، أنتِ مقبلة على المرحلة التي تتطلب أكبر قدر من الصبر خلال نمو طفلكِ. فقد يقاوم صغيركِ، الذي يعترض على كل شيء ويريد تنفيذ ما يقوله، النوم وتناول الطعام خلال هذه الفترة. ويُعد عدم الانصياع، والتصرف بدلال مفرط، أو فعل عكس ما يُطلب منه من السمات الطبيعية لهذه المرحلة. أول خطوة عليكِ اتخاذها هي تجنّب الدخول معه في صراع عناد، لأن هذا العناد لم يصل بعد إلى مستوى يستطيع طفلكِ التحكم فيه بإرادته.') WHERE id = '7b32ecb7-fa8a-4af5-ac5a-5dca59e6ac47';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن الماء يشكّل نحو 75% من جسم طفلكِ عند ولادته، فإن هذه النسبة تنخفض بعد عمر سنة واحدة إلى المستوى الموجود لدى البالغين. يمكنكِ تجربة طرق مختلفة لتلبية احتياجاته من السوائل، لكن تذكّري أن الماء الخالي من أي نكهات أو منكّهات هو الخيار الأفضل لطفلكِ. وقد تتساءلين عن كمية الماء التي ينبغي أن يشربها. أهم ما عليكِ معرفته هو أن احتياجه إلى الماء يتغير مع تقدمه في العمر. فكلما قلت كمية حليب الأم أو الحليب الصناعي وزادت حصة الأطعمة الصلبة، ازدادت حاجة جسم طفلكِ إلى الماء. كما يمكن أن يمنحكِ طول طفلكِ ووزنه ولون بوله ورائحته مؤشرات على كمية الماء التي ينبغي تقديمها له. في هذه المرحلة، يُنصح بأن يستهلك طفلكِ في المتوسط 1000-1300 ml من الماء يوميًا.') WHERE id = '673e0121-ceca-4086-948c-fac61558696d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تنقسم الدهون التي تستخدمينها في تغذية طفلكِ إلى أنواع مختلفة، منها الدهون المشبعة والأحادية غير المشبعة والمتعددة غير المشبعة. أما الدهون الموجودة في اللحوم والبيض والحليب ومنتجات الألبان، فهي من أصل حيواني وتنتمي إلى مجموعة الدهون المشبعة. ويُعد زيت الزيتون وزيت البندق من الدهون الأحادية غير المشبعة، بينما يُعد زيت الذرة وزيت دوار الشمس من الدهون المتعددة غير المشبعة. ويوصي الأطباء بالإكثار من تناول الأحماض الدهنية غير المشبعة. وتؤدي هذه الدهون دورًا مهمًا في نمو طفلكِ وتطوره بصورة صحية. لكن عليكِ الانتباه إلى أن الدهون الزائدة تتراكم في الجسم، فجسم طفلكِ، مثل جسم البالغ، قادر على تخزين الدهون الزائدة دون حد ثابت. لذلك، عليكِ الاهتمام بنمط تغذية طفلكِ والتأكد من أنه نشيط بما يكفي خلال اليوم، لحمايته مستقبلًا من أمراض مختلفة مثل السمنة.') WHERE id = '8f5d01a0-18e8-4008-8da6-4aa6dfa4f0b7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ، الذي دخل الآن شهره 19، أقرب بخطوة أخرى إلى عامه الجديد. ولا تزال هذه المرحلة من أكثر الفترات نشاطًا وحركة لدى طفلكِ. لذلك، من المهم توفير بيئة نشطة تتيح له تفريغ طاقته، وتقديم أطعمة صحية تساعده على تعويض الطاقة التي يفقدها. يحصل طفلكِ من الطعام على الطاقة اللازمة لنموه السريع، لكن ينبغي عدم نسيان أن الطاقة الزائدة عن حاجته تُخزَّن في الجسم. وتُعد السمنة (البدانة) مشكلة صحية خطيرة في بلادنا كما هي الحال في جميع أنحاء العالم. والسبب الرئيسي للسمنة هو أن تكون الطاقة المستهلكة أقل من الطاقة التي يحصل عليها الجسم. وعلى الرغم من كثرة النشاط في هذه المرحلة، فإن الجهاز اللوحي والهاتف والتلفاز من أبرز العوامل التي تحدّ من حركة طفلكِ. والاعتقاد الشائع بأن الطفل الأعلى وزنًا يكون أكثر صحة هو اعتقاد خاطئ تمامًا. فإذا نتج هذا الوزن عن تغذية غير سليمة وقلة الحركة، فقد يؤدي إلى مشكلات خطيرة في المستقبل.') WHERE id = 'ab96b17f-7a5e-402d-adf2-b939f4193cb3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يتراوح وزن الطفل في هذا الشهر بين 9700 غرام و14.500 غرام لدى الأولاد، وبين 9300 غرام و13.800 غرام لدى البنات. أما الطول، فيتراوح بين 77 sm و89 sm لدى الأولاد، وبين 75 sm و87 sm لدى البنات. وقد يتراوح محيط رأس الطفل في عمر 19 شهرًا بين 46.7 sm و48 sm. ويُتوقع أيضًا أن يكون اليافوخ قد انغلق تمامًا بحلول هذا العمر. إذا كانت قياسات طفلكِ خارج هذه النطاقات، فهذا لا يعني دائمًا وجود مشكلة. فقد تختلف القياسات أحيانًا عن المعايير، وقد تتطلب هذه الحالة متابعة طبية أكثر انتظامًا. تذكّري أن قياسات الجسم الصحية لطفلكِ قد تختلف تبعًا لتغذيته، ومدى نشاطه خلال اليوم، والبيئة التي يعيش فيها. كما قد يؤدي التوازن الهرموني الخاص بصغيركِ وبنية جسم والديه إلى بعض الاختلافات في هذه القيم.') WHERE id = 'b2ab74b8-c58e-4be9-a2eb-0663883e5594';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ في مرحلة التسنين، أو يعاني حساسية تجاه بعض الأطعمة، أو يتناول كميات من الفاكهة أو عصير الفاكهة تفوق المعدل الطبيعي، فقد يُعد إصابته بالإسهال أمرًا طبيعيًا. لكن قد يحدث الإسهال أيضًا، إلى جانب هذه الأسباب، نتيجة كائنات دقيقة ضارة ذات منشأ فيروسي أو بكتيري أو طفيلي. والإسهال، بأبسط تعريف، هو زيادة عدد مرات التبرز يوميًا مع تحوّل البراز إلى قوام مائي أو رخو. وقد تلاحظين حينها وجود مخاط أو رغوة في البراز، أو تغيرًا في لونه، أو رائحة كريهة. كما يُعد ألم البطن والحمى من الأعراض الشائعة المصاحبة للإسهال. ويسبب الإسهال فقدانًا سريعًا وكبيرًا للسوائل والمعادن من جسم طفلكِ. وكلما كان طفلكِ أصغر سنًا، ازدادت صعوبة تعويض جسمه لهذا الفقد. لذلك، عندما تلاحظين إصابة طفلكِ بالإسهال، يجب أن تعوّضي له السوائل والمعادن التي فقدها. وإذا كنتِ تعتقدين أن الإسهال استمر مدة أطول من المعتاد، فمن الأفضل التواصل مع الطبيب.') WHERE id = '23450294-8568-46fa-ae46-48adce4121ac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر طفلكِ حاليًا بمرحلة كثيرة الحركة. لذلك، تُعد الوجبات الخفيفة التي تقدمينها له بين الوجبات وفي الساعات الأولى من اليوم مهمة كي لا يتعب بسرعة. فعلى سبيل المثال، يُعد دبس الفاكهة من أكثر الأطعمة المفيدة التي تمنح طفلكِ قدرًا كبيرًا من الطاقة بفضل احتوائه على الغلوكوز والفركتوز الطبيعيين. ويمكنه تلبية جزء كبير من احتياجات طفلكِ اليومية من البوتاسيوم والكالسيوم والمغنيسيوم. وإلى جانب ذلك، يحتوي الدبس على كميات وفيرة من النحاس والمنغنيز والحديد والسيلينيوم وفيتامين B6. وبفضل هذه التركيبة الغنية، يؤثر الدبس إيجابيًا في الجهاز الهضمي لطفلكِ، ويساعد على تنظيم الدورة الدموية والحفاظ على صحة القلب والأوعية الدموية. ويُعد تناوله، ولا سيما عند تغير الفصول وخلال أشهر الشتاء، من الوسائل المجربة لتقوية المناعة. لكن نظرًا إلى محتواه المرتفع من الكربوهيدرات، يُستحسن أن تستشيري طبيبكِ بشأن الكمية المناسبة التي يمكنكِ تقديمها لطفلكِ.') WHERE id = 'e24ba9b0-b589-4244-8a0c-fad5773debb9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، قد يبدأ طفلكِ برفض الذهاب إلى غرفته أو الاستلقاء في سريره للنوم، وقد يضطرب نظام نومه تمامًا. يمكن أن يثير كل ذلك قلقكِ ويجعلكِ تتساءلين عن كيفية استعادة روتين نومه. ومن المتوقع أيضًا أن ينهض من سريره بعد وقت قصير من استغراقه في النوم، ثم يبحث عنكِ في المنزل أو يأتي إليكِ. لذلك، يمكنكِ تجربة وسائل تساعده على الانتقال إلى النوم بسهولة والنوم بشكل متواصل طوال الليل. فعلى سبيل المثال، ينبغي أن تقللي من تعرضه للكثير من المثيرات ومن ممارسته الألعاب الحركية المفرطة قبل النوم. وقد تساعد أيضًا أطعمة ومشروبات مثل العيران والحليب ونخاع العظم في وجبة العشاء على شعوره بالنعاس. بالإضافة إلى ذلك، تُعد الموسيقى الهادئة واللمسات الحنونة وقراءة القصص وسائل رائعة تساعد طفلكِ على الاسترخاء والاستغراق في نوم هانئ.') WHERE id = '99665c28-7011-4149-a303-4268bf5d91e2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'للفواكه دور بالغ الأهمية في تغذية طفلكِ، كما أن الفواكه الاستوائية غنية بالعناصر الضرورية لنموه. وعند ذكر الفواكه الاستوائية، يتبادر إلى الذهن أولًا المانجو والأفوكادو والموز والأناناس والكيوي وفاكهة التنين وجوز الهند. ومن بينها، يتميز المانجو بانخفاض سعراته الحرارية وغناه بالكاروتينات المفيدة في دعم الجسم في مواجهة نزلات البرد. أما الأناناس، فيستحق أن يكون ضمن قائمة طعام طفلكِ بفضل غناه بفيتامينات B والمنغنيز، وهو معدن نادر نسبيًا. والمنغنيز معدن يحتاج إليه جسم طفلكِ لإنتاج الطاقة، كما يؤدي دورًا مهمًا في التفاعلات الإنزيمية الضرورية داخل الجسم. ويساعد المحتوى المرتفع من فيتامين C ومضادات الأكسدة في الكيوي على الوقاية من أمراض الرئة، وقد يكون مفيدًا خصوصًا للمصابين بالربو. وعند شراء هذه الفواكه الاستوائية ناضجة، فإنها تمثل خيارًا غذائيًا لذيذًا ومفيدًا جدًا لطفلكِ من دون الحاجة إلى طهيها.') WHERE id = '40757955-d7c5-4d49-9cae-8eaa0f33656e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال المرحلة العمرية من 1-2 سنة، ينبغي أن يحصل طفلكِ على 40% من احتياجاته الغذائية اليومية من حليب الأم، وعلى 60% منها من الأطعمة الصلبة. وينبغي أن تتكون نسبة 60% هذه بالكامل من أطعمة صحية تدعم نموه. ويستحق مرق العظام الذي تضيفينه إلى وجبات طفلكِ مكانة مهمة في نظامه الغذائي بفضل ما يحتوي عليه من فيتامينات ومعادن وكمية كبيرة من البروتين. وإذا كان طفلكِ أكثر عرضة للعدوى والأمراض، فلا تنسي تأثير مرق العظام الداعم للمناعة. كما يُعد مرق العظام سهل الهضم بفضل قابليته العالية للامتصاص، وهو ما يناسب جهاز طفلكِ الهضمي الذي لا يزال في طور النمو. كذلك تساعد الأحماض الأمينية، ومنها الغلايسين الموجود في مرق العظام، على تهدئة طفلكِ. لذلك، فإن استخدام مرق العظام، خصوصًا في وجبات العشاء، قد يساعد طفلكِ على النوم بشكل أفضل ومن دون انقطاع طوال الليل.') WHERE id = 'a99c4566-939c-4943-915c-cf701b9d784c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، قد لا تكون الكلمات التي ينطق بها طفلكِ مفهومة تمامًا. ومع ذلك، فهو يفهم بصورة عامة ما تقولينه له، ويرجع ذلك إلى تطور مهاراته اللغوية والإدراكية. فعلى سبيل المثال، عندما تقولين لطفلكِ «شوكة»، ستتبادر إلى ذهنه الشوكة تحديدًا لا الملعقة. وفي هذه الفترة، يستطيع الأطفال نطق ما بين 10-30 كلمة ذات معنى في المتوسط، لكن هذه الحصيلة اللغوية لا تكفي غالبًا للتعبير عن أنفسهم بشكل كامل. لذلك، قد يمر طفلكِ بنوبات غضب بسيطة عندما لا يُفهم ما يريد التعبير عنه، وقد تشتد هذه الحالة في أحيان نادرة. في مثل هذه اللحظات، حاولي تخمين ما يريد طفلكِ قوله وساعديه، فهذا سيجعل التعامل مع الموقف أسهل. راقبيه بعناية وحاولي فهم ما يحتاج إليه؛ فهذا خيار أفضل من مجرد النظر إليه والانتظار.') WHERE id = '062d06b6-6166-4367-8a34-fbca48b06a36';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'للفيتامينات دور لا غنى عنه في نمو طفلكِ وعملية الأيض السليمة وتمتعه بجهاز مناعي صحي. ويُعد فيتامين C (حمض الأسكوربيك) من أهم العناصر الأساسية لنمو الأسنان والعظام والجلد بشكل صحي. يذوب هذا الفيتامين في الماء، ويساعد الجسم على امتصاص الحديد وإنتاج الكولاجين وحماية الأوعية الدموية ودعم إفرازات بعض الغدد الهرمونية. ولأن فيتامين C لا يُخزن في الجسم، فمن المهم إدراجه يوميًا في النظام الغذائي لطفلكِ. يدعم هذا الفيتامين المناعة، ويحافظ على صحة العينين، ويساعد على الوقاية من فقر الدم الناتج عن نقص الحديد، ويحمي البشرة. وتشمل الأطعمة الغنية بفيتامين C الليمون والجريب فروت والبرتقال والفراولة والسبانخ والكيوي والفلفل الأخضر والطماطم وثمار الورد البري. ومن خلال إدراج هذه الأطعمة بانتظام في نظام طفلكِ الغذائي، يمكنكِ تلبية احتياجاته اليومية من فيتامين C.') WHERE id = '26b228ac-1aa9-488c-8a24-c0b3f3f3a2a1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يظهر مرض اليد والقدم والفم، الذي انتشر في العديد من البلدان خلال السنوات الأخيرة، عادةً بارتفاع درجة الحرارة وظهور طفح جلدي. يسببه عدد من الفيروسات المعوية، وهو شديد العدوى ويصيب خصوصًا الأطفال دون سن ٣ سنوات. ويشيع هذا المرض أكثر خلال فصلي الربيع والصيف، ولا يوجد علاج نوعي له. تبدأ أعراضه بالوهن والتعب، وقد تعقبها حمى تستمر من ٣ إلى ٧ أيام. وبما أن المرض ينتقل عن طريق العطاس والسعال واستخدام الأغراض المشتركة، فعليكِ اتخاذ بعض التدابير الوقائية. ومن المهم أولًا أن تعوّدي طفلكِ على غسل يديه. كما ينبغي لكِ مراعاة قواعد النظافة في الأماكن المزدحمة مثل الحدائق ودور الحضانة. وإذا لاحظتِ على طفلكِ فقدان الشهية أو الانزعاج أو صعوبة البلع أو الطفح الجلدي أو الحمى، فاستشيري الطبيب دون تأخير.') WHERE id = '19336517-e2f0-4382-a8b8-70339ad9e2b6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي تمامًا أن يرفض طفلكِ كثير الحركة تناول الطعام ويرغب في مواصلة اللعب. وأول ما ينبغي لكِ فعله في هذه المرحلة هو جعل أوقات الوجبات ممتعة. قد يكون ذلك صعبًا قليلًا في البداية، خصوصًا إذا كان طفلكِ لا يرغب في الجلوس إلى مائدة الطعام. تلجأ أمهات كثيرات في هذه الحالة إلى تشغيل التلفاز أو إعطاء الطفل هاتفًا لتشتيت انتباهه، لكن الخبراء يرون أن هذا السلوك قد يكون ضارًا للغاية. فقد يتحول سريعًا إلى عادة، وبعد فترة قد يرفض طفلكِ تناول الطعام ما لم تتوافر الظروف نفسها. ينبغي أن يكون هدفكِ الأساسي عدم وضع كمية من الطعام في طبق طفلكِ تفوق قدرته على تناولها، وتقديم كميات قليلة ومتنوعة تكفي لإشباعه. وعند إعداد طبق من الفواكه والخضراوات، يمكنكِ إطلاق العنان لخيالكِ وتقديمه بطريقة مرحة على هيئة أشكال حيوانات متنوعة. كذلك، فإن السماح لطفلكِ بالشعور بالجوع يُعد أحد أهم المحفزات على تناول الطعام. وإذا كان طفلكِ لا يرغب في الأكل، فقد تحتاجين إلى إعادة النظر في الوجبات الخفيفة التي تقدمينها له بين الوجبات الرئيسية.') WHERE id = '52d0e2f2-b989-4846-9b56-a7da0c0b96ca';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ندرك أن طفلكِ يمر بأوقات صعبة خلال هذه المرحلة. ومن الطبيعي تمامًا أن يصبح أكثر عنادًا وعدوانية مقارنة بالسابق، وأن يقول «لا» لكل شيء. وفي هذه الأوقات، لا تنسي أن طفلكِ يحتاج إلى مساعدتكِ ودعمكِ واحتضانكِ الحنون. فعلى الرغم من تقدمه الكبير في مرحلة تكوين شخصيته واستقلاليته، فإنه لا يزال يعتمد عليكِ. ومن أكثر الطرق فاعلية لإظهار حبكِ لطفلكِ أن تحتضنيه. فالعناق يحفز إفراز هرمون الأوكسيتوسين في جسم طفلكِ، ويساعد ارتفاع مستواه في الأوعية الدموية على تنظيم ضغط دمه خلال فترة قصيرة. كما أن انخفاض التوتر في الدماغ يساعد طفلكِ على الهدوء ويقلل التوتر والعصبية إلى أدنى حد. لذلك، عندما تعجزين عن التعامل مع نوبات عناده وتشعرين بقلة الحيلة، فإن احتضان طفلكِ سيساعد كليكما على الهدوء بدرجة كبيرة.') WHERE id = 'be155a78-d9a9-48f2-8fc6-0060381e54cd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد السنوات الثلاث الأولى منذ الولادة أسرع مراحل نمو طفلكِ. ولذلك، فإن تغذيته خلال مرحلة الرضاعة مهمة جدًا ليحظى بحياة صحية في المستقبل. يحصل طفلكِ في البداية على المعادن التي يحتاج إليها لهذا النمو السريع، مثل الحديد، من المخزون الذي كوّنه في جسمه خلال فترة حملكِ. وبعد ذلك، وابتداءً من المرحلة الانتقالية إلى الأغذية التكميلية، يجب أن يتبع نظامًا غذائيًا يشمل جميع المجموعات الغذائية لتلبية احتياجاته من الفيتامينات والمعادن. ويُعد الحديد من العناصر الأساسية لتكوين الدم، إذ يستخدمه جسم طفلكِ لإنتاج الهيموغلوبين. وعلى الرغم من إمكانية الحصول على هذا المعدن في صورة مكملات، فإن الحديد الذي يحصل عليه الجسم من المصادر الطبيعية هو الخيار الأفضل لطفلكِ. ويُعد فقر الدم الناتج عن نقص الحديد مشكلة شائعة بين الأطفال. لذلك، ينبغي لكِ إجراء تحاليل دم دورية لطفلكِ في المواعيد التي يحددها الطبيب، والبحث جيدًا عن المصادر الطبيعية التي يمكنه الحصول منها على الحديد.') WHERE id = '8ac73f53-1de0-40be-b034-69d10df7b9d6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن الخبراء يرون أن أنسب وقت لبدء التدريب على استخدام المرحاض يكون في حدود عمر السنتين، فإن ذلك يظل عملية قد تختلف حسب نمو طفلكِ واستعداده. ومن أبرز العلامات التي تدل على استعداد طفلكِ للتدريب على استخدام المرحاض رغبته في أن تبقى حفاضته نظيفة دائمًا وإخباركِ عندما يشعر بالحاجة إلى قضاء حاجته. ففي هذه المرحلة يبدأ طفلكِ بإدراك امتلاء مثانته أو أمعائه، ومع تطور جهازه العصبي يصبح قادرًا على حبس البول أو البراز، ولو لفترة قصيرة. كما يرى الخبراء أنه من الطبيعي ألا تظهر هذه العلامات على طفلكِ بعد. وقد تتعجل بعض الأسر حتى يكتسب طفلها عادة استخدام المرحاض مبكرًا، لكن إجبار طفل غير مستعد على ذلك قد يؤدي مستقبلًا إلى مشكلات في الثقة بالنفس والشخصية والتعلق. لذلك، فإن أول ما ينبغي لكِ فعله هو مراقبة طفلكِ جيدًا. وتذكري أن الأولوية عند تحديد موعد بدء التدريب على استخدام المرحاض ليست لرغبتكِ، بل لطفلكِ ولمدى نموه واستعداده.') WHERE id = 'b7c4aaa4-3c12-4a76-a25b-a511c93b949a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ ترضعين طفلكِ طبيعيًا، فيُنصح بمواصلة الرضاعة حتى عمر سنتين لدعمه بالفيتامينات والمعادن. وإذا كنتِ لا ترضعينه طبيعيًا، فيمكنكِ الاستمرار لبعض الوقت في تقديم الحليب الصناعي المخصص لمرحلته العمرية ليحصل جسمه على العناصر اللازمة. وإضافة إلى ذلك، ستكون عصائر الفاكهة التي تحضّرينها من الفواكه الموسمية مفيدة جدًا لطفلكِ. كما يُعد شراب اللبن المصنوع من الزبادي المنزلي خيارًا ممتازًا لقائمة طعامه. وإذا كنتِ تقدمين لطفلكِ شاي الأعشاب مثل شاي الزيزفون، أو ترغبين في ذلك، فيمكنكِ إدراجه ضمن نظامه الغذائي بعد استشارة طبيبه، على ألا تتجاوز الكمية اليومية نصف كوب. ومن المهم ألا تضيفي الملح أو السكر إلى هذه المشروبات لتحسين مذاقها. كذلك، نظرًا إلى أن المشروبات التي يتناولها طفلكِ في هذه المرحلة تسهم في تشكيل تفضيلاته المستقبلية للمذاق، فمن الضروري أن تتجنبي تقديم المشروبات المحتوية على السكر والمواد المضافة.') WHERE id = 'a7ed9701-76a0-4a1a-9b67-c6c0cda6c5f1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أحيانًا أن طفلكِ يميل إلى البقاء بمفرده بدلًا من التفاعل اجتماعيًا في الأماكن المزدحمة أو التي يوجد فيها أطفال من عمره. خلال هذه المرحلة، قد يُظهر بعض الأطفال سلوكيات غير اجتماعية ويفضّلون اللعب بمفردهم. وقد تصبح لعبة اعتاد طفلكِ وجودها منذ فترة وتعلّق بها وسيلةً تلبّي حاجته إلى التفاعل الاجتماعي، لكن ذلك لا يكفي تمامًا. ولكي يتمكن طفلكِ من التواصل مع أقرانه واتخاذ خطوات نحو التفاعل الاجتماعي، عليه أولًا أن يدرك أنهم أفراد مستقلون مثله. وسيكون التواصل مع أقرانه ومشاركة ألعابه واللعب معهم بداية جيدة لحياته المستقبلية. لذلك، من المهم أن يشارك طفلكِ بانتظام في مجموعات اللعب أو يوجد في بيئات أخرى تضم أطفالًا من عمره. فاللعب في هذه المرحلة وسيلة فعالة جدًا لتعلّم طفلكِ. ونحن في عائلة Anacan ننصحكِ باستخدام اللعب باعتباره أكثر الوسائل فعالية لمساعدة طفلكِ على التفاعل الاجتماعي.') WHERE id = '5f456e81-e768-4ef4-bab4-0c102aeccabb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تحتاجين إلى إجراء بعض التغييرات في تغذية طفلكِ، خصوصًا عندما يصبح الطقس باردًا أو عند تغيّر الفصول. فالأطعمة التي يتناولها طفلكِ تؤثر مباشرةً في جهازه المناعي وآليات مقاومته للأمراض. لذلك، ينبغي أن تكون الخضراوات الموسمية من أفضل الخيارات لطفلكِ. وخلال أشهر الشتاء، من المفيد إدراج خضراوات مثل البطاطس والجزر والفلفل بكثرة في نظامه الغذائي. وإذا كان طفلكِ لا يحب تناول هذه الخضراوات، فيمكنكِ تغيير طريقة تقديمها. فعلى سبيل المثال، يمكنكِ إعداد حشوة من الخضراوات الموسمية وعجن عجينة بدقيق الحبوب الكاملة لتحضير قطع بيتزا صغيرة لطفلكِ. كما يمكن أن يساعد استخدام الصلصات والتوابل المختلفة طفلكِ على تقبّل الخضراوات التي لا يتناولها عادةً.') WHERE id = 'f8162fd9-38d6-4525-aaf5-deae7bb7805e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُعدّ انسداد أنف طفلكِ المتكرر أو شخيره أثناء النوم أمرًا طبيعيًا، خصوصًا خلال فترات مرضه. ويرجع ذلك إلى أن الإفرازات المخاطية التي تتكوّن أثناء عدوى الجهاز التنفسي العلوي قد تسدّ الممرات الهوائية وتجعل التنفس أكثر صعوبة. ولكن إذا كان أنف طفلكِ ينسدّ بوتيرة أكبر، فقد يكون السبب مرتبطًا بالحساسية. وحتى إذا لم تظهر على طفلكِ أي علامات لحساسية، ينبغي أن تضعي الاستعداد الوراثي في الحسبان. ووفقًا للمتخصصين، قد يصل احتمال ظهور أعراض الحساسية نفسها لدى أطفال الوالدين المصابين بالحساسية إلى 70%. وإذا كان طفلكِ يعاني صعوبة في التنفس، خصوصًا أثناء النوم، فيمكنكِ بعد استشارة الطبيب رفع الجزء العلوي من جسمه قليلًا. وبذلك يمرّ الهواء بسهولة أكبر عبر جهازه التنفسي العلوي ويتحسن تنفسه. كما أن زيادة رطوبة الغرفة التي يوجد فيها طفلكِ خلال النهار، وخصوصًا الغرفة التي ينام فيها ليلًا، تساعد على إبقاء الممرات الأنفية أكثر انفتاحًا.') WHERE id = 'be09f355-43f8-49f0-b63e-fac24b36b2bd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تكوني تستخدمين مع طفلكِ طريقة BLW (التغذية الذاتية)، فلم يفت الأوان بعد للبدء بها. فطريقة BLW ليست مجرد وسيلة ليشبع طفلكِ، بل هي نهج يؤثر إيجابيًا أيضًا في نموه الجسدي والعقلي. ومن أهم جوانب إطعام طفلكِ نفسه أن تعمل حواسه الخمس كلها بنشاط. فعندما يتعرّف بهذه الطريقة إلى مذاق الأطعمة ورائحتها، والأهم من ذلك قوامها، يتسارع نموه الحسي. كما أن تناول طفلكِ الطعام بمفرده واتخاذه القرار بشأن ما يأكله وكميته يضعان أساسًا لتكوّن شخصيته. وعلى خلاف التغذية التقليدية، لن يشعر طفلكِ بأنه مقيّد، ما يساعده على تناول الكمية التي يحتاج إليها وتجنّب الإفراط في الطعام. وإذا كنتِ تريدين أن يكتسب طفلكِ عادات غذائية جيدة، فإن BLW من أنسب الخيارات له.') WHERE id = '5fba8804-2bcf-4056-a32b-0f60798a6016';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكون طفلكِ في هذه المرحلة قليل الصبر للغاية، وقد يرغب في حدوث كل شيء أو إنجازه فورًا. ويرجع ذلك عمومًا إلى أنه لا يملك بعد تصورًا واضحًا عن كيفية مرور الوقت. فهو لم يفهم تمامًا مفهومي الماضي والمستقبل، لكنه يستوعب جيدًا مفهوم «الآن». ولا يزال طفلكِ بحاجة إلى نحو عام آخر حتى يتمكن من فهم مفاهيم الزمن الأخرى بصورة صحيحة. ومع ذلك، يمكنكِ في هذه المرحلة استخدام بعض الحيل البسيطة لتعليمه الصبر. فإذا أصرّ طفلكِ، مثلًا، على تحقيق شيء يريده فورًا، فحاولي تحويل انتباهه إلى أمر آخر. قدّمي له اقتراحات مثل: «تعالَ لنرسم معًا» أو «هل نغني معًا؟». وفي بعض الحالات، قد يكون من المفيد أيضًا أن تُريه الساعة وتطلبي منه متابعة حركة عقربها. وإذا تعذّر تحقيق ما يريده طفلكِ، فمن الأفضل أن تُبعدي عن نظره أي غرض قد يذكّره بطلبه.') WHERE id = 'ea8f95c5-370c-4fef-9751-e75f7ae08232';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدءًا من هذا الشهر، بدأ الجهاز الهضمي لطفلكِ يعمل بصورة مماثلة للجهاز الهضمي لدى البالغين. ومع ذلك، قد يستمر اكتمال نموه حتى الشهر 36. وعند اكتمال هذا النمو، ستحتوي أمعاء طفلكِ، وهي أهم أجزاء جهازه الهضمي، على نحو 100 مليون خلية عصبية. وهذا يعني أن الأمعاء ستحتوي على خلايا عصبية أكثر بعشر مرات من الحبل الشوكي. وللحفاظ على صحة الأمعاء، التي تُسمّى اليوم «الدماغ الثاني»، من المهم جدًا أن يتناول طفلكِ الأطعمة المخمّرة. فالأطعمة المُحضّرة بالتخمير تساعد على تنظيم جهازه الهضمي. لذلك، ينبغي أن تُدرجي كميات كافية من الأطعمة المخمّرة، مثل الزبادي والكفير والجبن، في نظام طفلكِ الغذائي.') WHERE id = 'f041f5ba-2299-4c38-afa9-5aced862a00f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ الآن يلعب بألعابه بنشاط أكبر. فعلى سبيل المثال، قد يقلّب صفحات الكتب الممتعة المناسبة لمرحلة نموه، ويتأمل مطولًا ما يظهر أمامه في كل صفحة جديدة. كما يمكنه بناء أبراج باستخدام المكعبات أو الألعاب ذات الزوايا، وقد يصبح هدم هذه الأبراج أو إسقاط الألعاب المكدسة فوق بعضها من أكثر أنشطته المفضلة. وقد يتذكر الدرج الذي توجد فيه كل لعبة، وعندما ينتهي من اللعب يمكنه إعادة ألعابه إلى مكانها إذا ذكّرته بذلك. ويعود كل هذا إلى التطور الملحوظ في مهارات التواصل والتعبير اللفظي لدى طفلكِ. ولدعم هذا التطور وتشجيعه على استكشاف مجالات متنوعة، يمكنكِ البدء بالبحث عن ألعاب جديدة. فعلى سبيل المثال، تُعد ألوان الرسم بالأصابع ومكعبات الليغو والأحاجي البسيطة وعجينة اللعب ومستلزمات ألعاب تقمّص الأدوار المنزلية خيارات مناسبة جدًا لنمو طفلكِ. لكن من المهم أن تراقبيه، خاصة عند لعبه للمرة الأولى بمواد مثل عجينة اللعب. وقتًا ممتعًا! 😊') WHERE id = '0094e862-06ed-4386-a5cf-c1f9439c8d66';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في وقتنا الحاضر، تُعد جميع البلدان التي تشهد ارتفاعًا في معدلات السمنة معرضة لخطر زيادة الإصابة بداء السكري. وفي السابق، كان داء السكري من النوع الأول الناتج عن نقص الإنسولين يظهر في سن 5-7 سنوات على أقل تقدير، لكنه أصبح يُشخَّص الآن حتى لدى الرضع. عند الإصابة بداء السكري من النوع الأول، تدخل الخلايا في حالة شبيهة بالجوع، وتُرسل إشارات إلى الكبد لإنتاج المزيد من الطاقة. عندها يبدأ الكبد بحرق الدهون بسرعة لإنتاج الطاقة. وينتج عن حرق الدهون ظهور مواد حمضية في الجسم تُسمى الكيتونات، وهي غالبًا ما تسبب الغثيان والقيء. كما يُعد فقدان الوزن رغم كثرة تناول الطعام وزيادة الشهية من الأعراض الشائعة. إضافة إلى ذلك، قد تشمل علامات السكري بطء التئام الجروح بسبب ارتفاع مستوى السكر في الجسم، وظهور الحكة والاحمرار المتكررَين المرتبطَين بالعدوى الفطرية في المنطقة التناسلية لدى الرضيعات. لذلك يُعد التشخيص المبكر لداء السكري بالغ الأهمية. وسيساعد إجراء فحوصات طفلكِ الطبية الدورية وتحاليله في مواعيدها على اكتشاف أي إصابة محتملة بالسكري مبكرًا.') WHERE id = 'fc4caf55-748d-4981-b396-817290848621';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لم تكتمل بعد قدرة طفلكِ على التفكير المجرد في هذه المرحلة، ولذلك غالبًا لا يكون قادرًا على اكتساب سلوك جديد من خلال الاستدلال المنطقي. وخلال مرحلة تطور مفهوم الذات والاستقلالية، قد لا ينفذ طفلكِ العادات أو السلوكيات الصحيحة التي تطلبينها منه. وحتى إذا فعل ذلك في لحظتها، فقد لا يتحول هذا السلوك دائمًا إلى عادة. كذلك، قد لا يكون الحديث المطول مع طفلكِ وشرح العادة التي تريدين تعليمه إياها كافيَين لإحداث تغيير. عندما تواجهين مثل هذه المواقف، فإن أول ما عليكِ فعله هو أن تكوني قدوة حسنة لطفلكِ! فالرضع والأطفال الصغار يكتسبون العادات الجديدة من خلال الملاحظة التامة، بعيدًا عن التفكير المجرد. فإذا كنتِ لا تقولين «من فضلك» عندما تطلبين شيئًا من أحد المقربين، فلا ينبغي أن تتوقعي من طفلكِ أن يعتاد قولها. فالسلوك الصحيح في نظر طفلكِ هو ما يراه من حوله. لذلك عليكِ أولًا أن تمارسي بنفسكِ السلوك الذي تريدين من طفلكِ اكتسابه.') WHERE id = 'd637a9d3-9bc2-4e75-bc5f-06b90b92798a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'فيروس الروتا من الأمراض التي تصيب الأطفال الصغار عادةً، وتسبب عدوى في المعدة والأمعاء، وتنتشر غالبًا خلال فصلي الخريف والشتاء. إذا كنتِ قد لقّحتِ طفلكِ ضد فيروس الروتا، فمن المرجح أن تكون أعراض المرض أخف إذا أُصيب بالعدوى. لكن عليكِ أن تتذكري أن اللقاح لا يوفر مناعة كاملة، بل يساعد فقط على تخفيف حدة الأعراض عند الإصابة بالفيروس. لذلك من المهم جدًا حماية طفلكِ، الذي لم يكتمل نضج جهازه المناعي بعد، من فيروس الروتا. وينتقل الفيروس عادةً عبر المياه الملوثة، والأطعمة التي لم تُطهّر جيدًا، وأحواض السباحة العامة، وملامسة الأيدي. وإذا أُصبتِ بفيروس الروتا وكنتِ ترضعين طفلكِ، فلا حاجة إلى إيقاف الرضاعة الطبيعية بسبب ذلك؛ إذ لم تجد الدراسات أي دليل على انتقال فيروس الروتا من الأم إلى رضيعها عبر حليب الثدي.') WHERE id = '408371ed-7459-4486-8982-de0e6127b2cc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن الدراسات الحديثة لم تثبت وجود علاقة مباشرة بين المُحلّيات الصناعية والسرطان، فإنه يُعتقد أن استخدامها على المدى الطويل قد يؤدي إلى إفراز كميات زائدة من الإنسولين في الجسم، وقد يخل بالتوازن الهرموني. لذلك لا ينصح الخبراء باستخدام المُحلّيات، خاصة في أغذية الرضع والحوامل والأطفال. وتشير بعض الدراسات إلى أن المُحلّيات قد تسبب تأثيرات منبهة في أجسام الرضع، ما يؤثر سلبًا في نمط نومهم. لذلك من المهم جدًا إبعاد طفلكِ عن المنتجات الجاهزة والمعبأة التي تحتوي على المُحلّيات. فهذه المواد ليست لها أي قيمة غذائية، ومن الأفضل لطفلكِ الاعتماد على مصادر السكر الطبيعية. وستلبي الأطعمة التي تُحلّينها بالفواكه الموسمية والدبس احتياجات طفلكِ من الكربوهيدرات بصورة كاملة.') WHERE id = 'f3e8fd10-f90c-4115-b3d0-88adbf06800b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ الآن يتعرف جيدًا إلى وجوه الأشخاص الذين يراهم كثيرًا في محيطه القريب. وهذا يعني أيضًا أنه قد يخاف من الغرباء أو من معارفكِ الذين يراهم للمرة الأولى. تُسمى هذه السلوكيات «الخوف من الغرباء»، وهي جزء طبيعي من نمو طفلكِ، لذا لا تقلقي. بل إن هذا يدل على أن طفلكِ أصبح قادرًا على تمييزكِ وتمييز الأشخاص الذين اعتاد عليهم عن الآخرين، وأنه كوّن رابطة عاطفية معكِ. لا تجبري طفلكِ على التعرف إلى شخص لم يسبق له أن عرفه، لأن ذلك قد يزيد الأمر صعوبة. وفي الأماكن التي يوجد فيها غرباء، وفّري لطفلكِ بيئة يشعر فيها بالأمان. ومع مرور الوقت ولقائه بأشخاص جدد وشعوره بالأمان، سيقل هذا الخوف تدريجيًا. تحلّي بالصبر وحاولي تفهّمه.') WHERE id = '06b42174-c457-4e70-9b49-6845b506cc6c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تختلف علامات الإمساك لدى البالغين عنها لدى الرضّع. فعلى سبيل المثال، قد يُعدّ التبرز على فترات متباعدة إمساكًا لدى البالغين، لكن الإمساك في الحقيقة هو صعوبة إخراج البراز بغض النظر عن عدد مرات التبرز. فإذا كان رضيعكِ يتبرز مرة كل 3 أيام من دون صعوبة، فلا يُعدّ مصابًا بالإمساك. أما إذا كان يتبرز 2-3 مرات يوميًا، لكنه يعاني من الشدّ أو الغازات أو البراز الصلب أو التقلصات أو التوتر أو الانزعاج، فيمكن عندئذٍ الحديث عن الإمساك. في الوضع الطبيعي، يجب أن يخرج البراز بسهولة عبر الأمعاء وفتحة الشرج. وقد تشير زيادة سيولة البراز أو صلابته المفرطة أو مرور أكثر من 7 أيام من دون تبرز إلى بعض مشكلات الجهاز الهضمي. إذا لم يكن لدى رضيعكِ أي مشكلة فسيولوجية، فمن المرجح أن يكون الإمساك ناجمًا عن عادات غذائية غير صحيحة. وفي هذه الحالة، عليكِ إضافة مزيد من الأطعمة الغنية بالألياف إلى قائمة طعام رضيعكِ وتجنّب المنتجات السكرية والمعلبة الجاهزة.') WHERE id = 'a55a0cb8-4bf1-4b31-acf7-9e3ccdc65901';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يضطرب نظام نوم طفلكِ بسبب نموه الجسدي وتزايد شعوره بالاستقلالية، وقد يُبدي مقاومة للذهاب إلى النوم. ويشيع في هذه المرحلة رفض النوم، والاستيقاظ بعد وقت قصير من النوم، وصعوبة العودة إلى النوم، واضطراب القيلولات النهارية تمامًا. والسبب الرئيسي لذلك هو أن اهتمام طفلكِ أصبح منصبًا بالكامل على العالم الخارجي. كما يتيح كل اكتشاف جديد المجال لتكوّن مفهوم الخوف لديه. وتُعدّ هذه المخاوف جزءًا من نموه ما دامت لا تسبب مشكلة شديدة. لكن استيقاظ طفلكِ المتكرر بسبب الكوابيس، أو رفضه البقاء وحده، أو نهوضه وتحركه أثناء النوم، قد يكون مرهقًا له. في هذه الحالة، سيكون من الجيد أن تشتري له رفيقًا للنوم (لعبة) إن لم تكوني قد فعلتِ ذلك بعد، أو أن تُجري بعض التغييرات البسيطة في غرفته. وبدلًا من أن تقولي له عبارات مثل: «لا داعي للخوف» أو «ما المخيف في ذلك؟»، امنحيه شعورًا بالأمان بعبارات مثل: «سأبقى بجانبك حتى تنام» و«إذا ناديتني عندما تستيقظ، فسآتي إليك».') WHERE id = '81d78316-8e96-4fa7-97ae-ef09552b8f7c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن بعمر 20 شهرًا. تهانينا! مع اقترابه من عمر السنتين، بات أكثر إدراكًا للمشاعر. يمر كل طفل بمرحلة من حياته لا يفهم فيها سوى مشاعر السعادة والحماس والحزن. وبدءًا من عمر 12 شهرًا، ولا سيما عندما يبدأ المشي، يُضاف الخوف إلى هذه المشاعر. أما الآن، فقد أصبحت مشاعر طفلكِ أكثر تنوعًا، ويُعدّ شعوره بالقلق عند رؤية الغرباء مثالًا واضحًا على ذلك. وفي هذه المرحلة التي ينفتح فيها بنشاط على العالم الخارجي ويكتشف فرديته، قد يعيش مشاعر مثل الغضب وخيبة الأمل بحدّة. وستؤثر مشاعركِ ومشاعر شريككِ والمقربين منكما، وكذلك الأجواء العامة في المنزل، تأثيرًا مباشرًا في طفلكِ. وتؤدي تصرفاتكِ بصفتكِ أحد الوالدين دورًا كبيرًا في نموه العاطفي. وخلال هذه المرحلة، سيرغب طفلكِ في أن يشعر بأنكِ تتفهمينه عندما يمر بمشاعر مختلفة.') WHERE id = '556907e3-8565-4588-b437-8a867d4880bd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اعتبارًا من هذا الشهر، يبلغ متوسط وزن طفلتكِ إن كانت أنثى نحو 10.900 غرام، وإن كان ذكرًا فنحو 11.500 غرام. لكن هذه مجرد قيم متوسطة، ووفقًا لمعايير منظمة الصحة العالمية، يُتوقع أن يتراوح وزن طفلكِ بين 8500 غرام كحد أدنى و14.000 غرام كحد أقصى. أما الطول في هذا الشهر، فيبلغ في المتوسط 82.7 سم لدى الإناث و84.2 سم لدى الذكور. ووفقًا للمعايير نفسها، يُعدّ الطول الذي يتراوح بين 77 سم و89.5 سم طبيعيًا. تذكّري أن كل طفل يختلف عن غيره وأن النمو له خصائص فردية. إذا كانت قياسات طفلكِ ضمن هذه النطاقات، فلا داعي للقلق. وإذا كنتِ تعتقدين أن نموه يقع خارج هذه الحدود، فيمكنكِ استشارة طبيبكِ.') WHERE id = 'f02ccd26-c16b-414b-97d4-105108ef9968';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'منذ اللحظة الأولى لولادة طفلكِ، يُعدّ الوقت الذي تقضينه معه والأنشطة التي تمارسانها معًا بالغة الأهمية لنموه. وفي هذه المرحلة التي يحاول فيها طفلكِ التكيف بنشاط مع العالم الخارجي، يعتمد نموه الاجتماعي والعاطفي على جودة تواصله مع الأشخاص المحيطين به. ولتحقيق تواصل جيد، من المهم أن تقضي أنتِ وشريككِ وقتًا طويلًا معه، وأن تملآ هذا الوقت بأنشطة ملائمة لمستوى نموه. وينبغي أن تسهم هذه الأنشطة في تطوير مهاراته الجسدية والعقلية والعاطفية. وباختصار، فإن جلوس الأسرة أمام التلفاز لن يعود على طفلكِ بأي فائدة. فالوقت الجيد هو الوقت الذي تركزين فيه بالكامل على طفلكِ، ولا تنشغلين بأي عمل آخر، وتتفاعلين وفقًا لرغباته. فعلى سبيل المثال، سيكون من المفيد جدًا أن تتحدثي معه عما حدث خلال اليوم، وتمنحيه فرصة للتعبير عن نفسه، وتنظري في عينيه أثناء ذلك لتجعليه يشعر بقيمته لديكِ.') WHERE id = 'b65936ff-1ea6-49a0-9aee-5eb1e936b860';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن طفلكِ لا ينمو في هذه المرحلة بالسرعة نفسها التي كان ينمو بها خلال الأشهر الأولى، فإنه لا يزال في مرحلة نمو نشطة. وتُعدّ التغذية بالغة الأهمية ليستمر في النمو ويلبّي احتياجاته اليومية من الطاقة. عليكِ التأكد من حصوله على كمية كافية من كل مجموعة غذائية. أي يجب أن يتضمن نظامه الغذائي اليومي أغذية حيوانية مثل البيض واللحوم والأسماك، إلى جانب الفواكه والخضراوات والحبوب ومنتجات الألبان. لكن الطفل قد يرفض الطعام، ولا سيما خلال مرحلة التسنين. وفي هذه الحالات، لا تدخلي معه في صراع، بل تفهّميه ووجّهيه نحو بدائل صحية. فعلى سبيل المثال، إذا كان لا يأكل الخضراوات، فيمكنكِ زيادة حصة الفاكهة التي يحبها قليلًا.') WHERE id = '20ce1fe9-8b2d-4594-843f-1ce4823d8bfa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يفقد جسم طفلكِ يوميًا كمية معينة من السوائل عن طريق البول والعرق والدموع. ويؤدي فقدان هذه السوائل أيضًا إلى فقدان العديد من المعادن. وبما أن توازن الماء والمعادن لدى طفلكِ أكثر حساسية مقارنة بالبالغين، فقد يتأثر بالجفاف بسرعة أكبر. لذلك عليكِ تنظيم كمية الماء التي يشربها مع مراعاة كمية طعامه وعدد مرات تناوله ونشاطه خلال اليوم. إذا كانت كمية السوائل التي يفقدها طفلكِ أكبر من كمية الماء التي يتناولها، فقد تطرأ بعض التغيّرات على جسمه. فعلى سبيل المثال، قد يكون البول الداكن وذو الرائحة القوية، والانزعاج، وقلة الحركة، وانخفاض كمية الدموع عند البكاء علامات على الجفاف. لذلك يمكنكِ تقديم الماء لطفلكِ على فترات متكررة خلال اليوم، ولكن من دون إجباره على الشرب. كما يمكنكِ تقليل استهلاكه للملح لتجنب إرهاق كليتيه ومنع احتباس الماء في جسمه وحدوث التورم.') WHERE id = '836c1705-2d21-4dae-a3cb-901aac3487af';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تتكوّن مليارات الخلايا العصبية خلال الأشهر التسعة التي يقضيها طفلكِ داخل الرحم، قبل أن يولد. وعلى الرغم من أن تكوّن خلايا عصبية جديدة في دماغ طفلكِ يتباطأ بعد الولادة، فإن هذه العملية تستمر لبعض الوقت. وبعد نحو ٦ أشهر، يتوقف انقسام الخلايا العصبية تمامًا ويستقر العدد الإجمالي للخلايا في الدماغ. وكلما تعلّم طفلكِ معلومات جديدة من خلال حواسه، تتكوّن بين هذه الخلايا العصبية روابط تُسمى المشابك العصبية، ويستمر نموه الذهني. وبالتزامن مع نمو محيط رأس طفلكِ، تبدأ الخلايا العصبية في دماغه بزيادة حجمها تحت تأثير بعض الهرمونات. وبعبارة أخرى، كلما نما جسم طفلكِ، أعطى هرمون النمو الخلايا العصبية أيضًا إشارة لزيادة حجمها. وسيستمر هذا النمو حتى تكتمل مرحلة نمو طفلكِ. وعند اكتمال نموه، يصل جهازه العصبي أيضًا إلى شكله النهائي.') WHERE id = 'bf83a43a-3e8b-4dd1-9abe-1c19d8ca30a2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُصاب طفلكِ بالإنفلونزا، خصوصًا عند تغيّر الفصول وفي أشهر الشتاء وخلال فترة التسنين وأوقات انتشار الأوبئة. والإنفلونزا مرض تسببه الفيروسات، لذلك لا تفيد المضادات الحيوية في علاجها. ولهذا ينبغي أن يهدف علاج الإنفلونزا إلى تخفيف الأعراض، لا إلى القضاء على الفيروسات. أول ما عليكِ فعله عند إصابة طفلكِ بالإنفلونزا هو ضمان حصوله على قسط وافر من الراحة وتناوله المزيد من السوائل. كما ينبغي أن تولي تغذيته عناية أكبر لدعم جهازه المناعي وإنتاج الأجسام المضادة اللازمة. يحتاج طفلكِ خلال فترة إصابته بالإنفلونزا إلى فيتامين C ومضادات الأكسدة ومصادر الألياف. إذ تساعد هذه العناصر على تقوية مناعته ومقاومة الفيروسات بسهولة أكبر. وتحتوي فواكه مثل البرتقال واليوسفي والجريب فروت على كميات وفيرة من فيتامين C وعناصر غذائية مفيدة. كما تساعد الشوربات المحضّرة بالخضراوات والثوم والزنجبيل والعسل والأغذية الحيوانية مثل مرق اللحم على تعزيز دفاعات جسم طفلكِ.') WHERE id = '8e404bc8-ce50-47a3-9ba5-932f7b372cec';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد السنوات الثلاث الأولى من حياة طفلكِ الفترة الأسرع من حيث النمو الذهني إلى جانب النمو الجسدي. ويمكن القول إن إدراك طفلكِ ومهاراته الحركية الدقيقة والكبيرة وتطوره اللغوي والعاطفي تتقدم بسرعة كبيرة خلال هذه السنوات الثلاث الأولى. وتمثل كل هذه المهارات خبرات تساعد طفلكِ على التكيّف مع بيئته، والوصول إلى المعلومات، والاستفادة مما يتعلمه على أفضل نحو. ولا تتشكل المهارات التي يكتسبها طفلكِ في هذه الفترة وفق الاستعداد الوراثي فحسب، بل تتأثر أيضًا بالعوامل البيئية وبأسلوب تعاملكِ معه. وبيدكِ مساعدته على استثمار كامل إمكاناته بكفاءة، بل وتجاوزها أيضًا. فكلما تعرّض طفلكِ لمزيد من المحفزات الخارجية، ازدادت فرصته في تطوير نفسه. ومن هذا المنطلق، يُعد اصطحاب طفلكِ إلى بيئات مختلفة، وممارسة أنشطة جديدة معه، وإتاحة فرص التواصل الاجتماعي له، وتعليمه القواعد والحدود من أفضل الاستثمارات التي يمكنكِ تقديمها لمستقبله.') WHERE id = 'f53f49e9-b83a-4928-bf28-5f85fef3ea2d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد عصائر الفاكهة من المشروبات التي يحبها طفلكِ كثيرًا لأنها ملونة وحلوة وسهلة الشرب. ويمكن اعتبار تناول طفلكِ عصائر الفاكهة الموسمية والطازجة جزءًا من التغذية الصحية، لكن ينبغي ألا تتجاوز الكمية كوبًا صغيرًا خلال اليوم. فقد يؤثر الإفراط في شرب عصير الفاكهة في آلية الشعور بالجوع والشبع لدى طفلكِ. كما قد يؤدي إلى تسوس الأسنان بسبب احتوائه على كمية كبيرة من الفركتوز (سكر الفاكهة). أما القيمة الغذائية للعصائر الجاهزة فهي أقل من العصائر المعصورة في المنزل أو الفاكهة الكاملة. لذلك عليكِ الحد من استهلاك طفلكِ لعصير الفاكهة وتفضيل تناوله الفاكهة كاملة. وبهذه الطريقة سيحصل طفلكِ أيضًا على الألياف الموجودة فيها، إذ تتمتع ألياف الفاكهة بفوائد كبيرة لمعدته وجهازه الهضمي.') WHERE id = '822c2875-bf97-4464-96c5-25165de770cc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مثل كل طفل، يولد طفلكِ ومعه طاقة إبداعية. لكن بعض الأخطاء التربوية التي قد تُرتكب أثناء تنشئته، ومواقف المحيطين به، والقيود المفرطة التي تفرضينها من دون قصد قد تلحق ضررًا كبيرًا بإبداعه. فعلى سبيل المثال، إذا حاول طفلكِ الصعود إلى طاولة المطبخ ليرى ما تفعلينه، فإن إنزاله فورًا خوفًا من سقوطه قد يطفئ فضوله ورغبته في الاستكشاف. وبدلًا من ذلك، يُفضّل أن تتخذي احتياطات السلامة اللازمة وتتيحي له إشباع فضوله. وقد يحاول طفلكِ في هذه المرحلة تجاوز الحدود التي تحددينها له. فمثلًا، قد يرفض الجلوس على الكرسي أثناء التلوين ويفضّل مواصلته على الأرض، لأن طفلكِ الذي لا تزال خبرته محدودة يتعلم عن طريق التجربة والخطأ. وقد يؤدي انتقاده أو إبداء رد فعل قاسٍ تجاهه في مثل هذه المواقف إلى تكوين شخصية تخشى ارتكاب الأخطاء.') WHERE id = 'c2c48251-d60f-4d39-bbe0-186388b64af6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كون طفلكِ كثير الحركة يعني أنكِ تضطرين إلى ملاحقته باستمرار، وقد يجعلكِ ذلك تشعرين بالتعب كثيرًا. لكن تذكّري أن نمط الحياة الخامل يُعدّ أحد أهم أسباب زيادة الوزن والسمنة. فنمط الحياة الذي تعوّدين طفلكِ عليه خلال هذه المرحلة من أهم العوامل التي تحدد عاداته المستقبلية. لذلك، لا تتدخلي في حركته ما لم يكن ذلك ضروريًا، وشاركيه ألعابًا حركية متنوعة حتى يتمكن من تفريغ طاقته. ومن العوامل الأخرى المسببة للسمنة تناول الطعام بسرعة شديدة. فلا تستعجلي طفلكِ لينهي طعامه؛ فعند تناول الطعام بسرعة، يتأخر وصول إشارة الشبع إلى الدماغ حتى لو امتلأت المعدة، ما قد يدفع طفلكِ إلى تناول كمية تفوق حاجته. وعندما لا تُحرق السعرات الحرارية الزائدة من خلال الحركة، تتراكم في الجسم على هيئة دهون، ما يمهّد للإصابة بالسمنة مستقبلًا.') WHERE id = 'e705ddac-9bb9-4f4e-a8cb-b34adbf75868';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'للهرمونات التي تُفرَز أثناء النوم أهمية كبيرة في نمو طفلكِ وتطوره. وابتداءً من هذا الشهر، ينبغي أن ينام طفلكِ ما لا يقل عن 13 ساعة يوميًا. ويُفترض أن يكون قد انتقل من أخذ قيلولتين نهارًا إلى قيلولة واحدة. وإذا كان لا يزال ينام مرتين خلال النهار، فمن المرجح أن ينخفض هذا العدد تلقائيًا إلى مرة واحدة قريبًا. وقد يتوقف بعض الأطفال تمامًا عن النوم نهارًا. إذا ترافق ذلك مع ضعف الشهية أو الانزعاج أو العصبية، فهذا يعني أن طفلكِ لا يزال بحاجة إلى القيلولة. أما إذا كان مزاجه جيدًا وشهيته طبيعية رغم عدم نومه نهارًا، فيمكنكِ الاستمرار على هذا النظام. لكن عليكِ إيلاء اهتمام خاص لأن يكون نومه الليلي متواصلًا وعالي الجودة. فالطفل الذي لا يحصل على قسط كافٍ من النوم ليلًا لا يستطيع ترسيخ المعلومات الجديدة التي تعلّمها خلال اليوم في ذاكرته. وسيساعد إيقاف الرضعات الليلية، على وجه الخصوص، على جعل نومه أكثر راحة واستمرارية.') WHERE id = '83bdbf1c-c0eb-40ca-9642-c6234b186654';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عند شراء ألعاب لطفلكِ، اختاري ألعابًا أكثر تعقيدًا وتتطلب بعض المهارات بدلًا من الألعاب البسيطة المكوّنة من قطعة واحدة. وابحثي عن ألعاب تنمّي مهاراته الحركية الدقيقة، وتحفّزه على التفكير، وتعزز إبداعه. فمثلًا، تُعدّ مكعبات التركيب المتداخلة، والدمى القابلة لتبديل ملابسها، وأطقم المطبخ متعددة القطع، أو الشاحنات ذات الصندوق القابل للفصل خيارات ممتازة. وعندما يلعب طفلكِ بهذه الألعاب، اتخذي الاحتياطات اللازمة للوقاية من مخاطر مثل الاختناق أو الإصابة، وراقبيه من دون التدخل في مجريات اللعب. فالفضول والتفكير وطرح الأسئلة وتركيب القطع وفصلها مهارات ينبغي لطفلكِ اكتسابها بنفسه. وعندما يواجه صعوبة أو يرتكب خطأ، لا تسارعي إلى تولّي الأمر. بل امنحيه وقتًا وفرصة كافيين لإتمام المهمة. وهكذا سيتعلم طفلكِ العثور بنفسه على الحل الصحيح من خلال التجربة والخطأ.') WHERE id = 'b496bbf8-f02b-4983-949c-f678a34f52e1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن طفلكِ قطع شوطًا كبيرًا في نموه الجسدي والعقلي منذ ولادته، فإنه لا يزال بحاجة إلى العناصر المفيدة الموجودة في حليب الأم. وتُفرز الغدة النخامية الموجودة في الجزء الأمامي من الدماغ هرمون البرولاكتين، الذي يحفّز الغدد الثديية على إنتاج الحليب. وبمجرد أن يبدأ طفلكِ بالرضاعة، يعمل هذا الهرمون عبر الأعصاب على تحفيز الحبل الشوكي. وتؤدي الإشارة الناتجة عن ذلك إلى تنشيط منطقة تحت المهاد في الدماغ، فيبدأ إنتاج هرموني الأوكسيتوسين والفازوبريسين. وتنتقل هذه الهرمونات عبر الدم إلى الثديين والغدد الثديية. ومع انقباض خلايا الغدد الثديية وارتخائها، يُدفَع الحليب إلى القنوات اللبنية. تحدث هذه العملية المعقدة بأكملها خلال 30 ثانية فقط، ثم يبدأ تدفق حليبكِ. وتعمل هذه الهرمونات على أفضل نحو خلال ساعات الليل. لذلك، من المهم جدًا أن تهتمي بنظام نومكِ الليلي للحفاظ على إدرار الحليب واستمراره.') WHERE id = '743884b4-17a1-4059-ab54-1551b9471069';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن تكون توقعاتكِ بشأن نوم طفلكِ أكثر واقعية. فالنوم المتواصل وعالي الجودة لا يعني بالضرورة أن ينام 13 ساعة بلا انقطاع. فمثلًا، من الطبيعي تمامًا في هذه المرحلة أن ينام طفلكِ عند الساعة 20:00، ثم يستيقظ عند 00:00، ويعود إلى النوم بعد مدة قصيرة ليستمر حتى الساعة 06:00 صباحًا. لا تتوقعي منه أن ينام من المساء حتى الصباح من دون أن يستيقظ، فهذا سيجنبكِ الشعور بالإحباط. لكن إذا كان طفلكِ يستيقظ كثيرًا جدًا خلال الليل ويرغب في الرضاعة أو تناول الطعام في كل مرة، فقد تكون هناك بعض الأخطاء في نظام تغذيته. في هذه الحالة، زيدي أولًا حصص طعامه النهارية ووجبته قبل النوم قليلًا. وعندما يستيقظ ليتغذى ليلًا، قلّصي مدة الرضاعة تدريجيًا إذا كنتِ ترضعينه طبيعيًا، أما إذا كنتِ تقدمين له الحليب الصناعي فقلّلي الكمية تدريجيًا. ستساعد زيادة التغذية نهارًا وتقليلها تدريجيًا ليلًا طفلكِ على اجتياز هذه المرحلة الانتقالية بسلاسة أكبر.') WHERE id = 'e37054f4-9e98-4f6d-9bff-391e03a99243';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ تكليف طفلكِ ببعض المهام ضمن أعمالكِ اليومية المعتادة كي يختبر شعور الإنجاز. فعلى سبيل المثال، عند عودتكما من المتجر، لا تمنعيه من حمل كيس خفيف، بل شجعيه على ذلك. ومن المهم أيضًا أن تطلبي مساعدته عند تبديل ملابسه، وأن تجعليه يضع الملابس التي خلعها في سلة الغسيل المتسخ. ويمكنكِ كذلك طلب مساعدته عند إعداد المائدة، وترتيبها بعد الانتهاء من الطعام، ووضع الأطباق المتسخة في غسالة الصحون. تحفّز هذه المهام شعور طفلكِ بالإنجاز وتجعله يشعر بأنه ذو قيمة. وبعد أن ينجز مهمة ما، امدحي ما قام به بدلًا من توجيه المدح إلى شخصه، فهذا يساعد على استمرار هذه السلوكيات. وهكذا، يمكن لطفلكِ أن يدرك مسؤولياته في سن مبكرة ويصبح مستقبلًا شخصًا أكثر تنظيمًا والتزامًا بالتخطيط.') WHERE id = 'bedb8c25-bf2f-4e64-85f1-ca4820365207';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أمعاء طفلكِ مسؤولة أيضًا عن إفراز الهرمونات التي تنظّم حالته العاطفية. ومن المثير للاهتمام أن ٥٪ فقط من هرمون السعادة، السيروتونين، يُفرز في الدماغ، بينما تُفرز نسبة ٩٥٪ منه في الأمعاء. وهذا يعني أن سر صحة طفلكِ وسعادته يكمن في توازن البكتيريا المعوية. فالطفل الذي يعمل جهازه الهضمي بصورة سليمة ينمو أكثر هدوءًا وسعادة. وللحفاظ على صحة الأمعاء، ينبغي إدراج الأطعمة المخمّرة في النظام الغذائي. وبفضل ما تحتويه هذه الأطعمة من بريبايوتيك، فإنها تحافظ على البكتيريا النافعة وتسهّل عملية الهضم. كما تساعد الأطعمة المحضّرة بالتخمير الأمعاء على امتصاص الفيتامينات والمعادن بصورة أفضل، مما يحسّن جودة حياة طفلكِ.') WHERE id = '43699df8-5258-442b-90de-b5aaf7cb47ca';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما تلاحظين مدى حماس طفلكِ لمساعدتكِ في الأعمال المنزلية. فمع تطور قدراته الجسدية، يدرك أنه أصبح قادرًا على إنجاز المزيد من المهام. وقد يبدأ بإخراج الأطباق من غسالة الصحون، أو إحضار الملابس المتسخة، أو المساعدة في رفع المائدة. وعندما يرى أنكِ سعيدة بما يفعله وأنكِ تمدحينه، يشعر بفرح كبير. بل قد يرفض مساعدتكِ أحيانًا ويرغب في إنجاز المهمة كاملةً بنفسه. ويمكنكِ الاستفادة من حماسه لتعليمه ترتيب ألعابه. وهكذا سيستمتع بإنجاز المهام باستقلالية، ويدرك في الوقت نفسه معنى تحمّل المسؤولية.') WHERE id = '721ffc29-7197-44f5-88ee-2f200062abbc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حان الوقت لتعويد طفلكِ على تنظيف أسنانه! ضعي في اعتباركِ أن المحاولات الأولى قد لا تنجح. يميل طفلكِ في هذه المرحلة إلى التعلّم من خلال تقليد السلوكيات التي يراها من المحيطين به، لذا فإن أول ما عليكِ فعله هو أن تكوني قدوة له. اختاري أولًا فرشاة أسنان صغيرة ومرنة ذات شعيرات ناعمة، ومزيّنة بشخصية محببة إليه. ثم اجعلي طفلكِ يقف أمامكِ وابدئي بتنظيف أسنانكِ. سيراقب ما تفعلينه لبعض الوقت. لا تجبريه على تنظيف أسنانه، بل دعيه يكتفي بمشاهدتكِ بهدوء لفترة. قد يتشتت انتباهه أحيانًا، وفي هذه الحالة حاولي جذب انتباهه إليكِ من جديد. قد لا يتمكن طفلكِ من تنظيف أسنانه في البداية، وقد يجعله ذلك يخاف من هذه العملية، لذا شجّعيه. ويمكنكِ تحويل تنظيف الأسنان إلى لعبة ممتعة من خلال عمل تعابير وجه طريفة أمام المرآة! 😊') WHERE id = '4637000e-4134-4115-9ea0-8e59506a6219';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر طفلكِ في هذه الأسابيع بمرحلة بدء ظهور الأضراس. وسيستمر اكتمال أسنانه اللبنية، التي سيبلغ عددها إجمالًا ٢٠ سنًا، حتى الشهر الثلاثين في المتوسط. وقد يكون ظهور الأضراس أصعب من ظهور الأسنان الأخرى بسبب حجمها. قد تلاحظين انخفاض شهية طفلكِ بصورة ملحوظة، وربما يبكي ويرفض الطعام بمجرد رؤيته. وأهم سبب لرفضه تناول الطعام هو أن لثته تصبح شديدة الحساسية، إذ قد تسبب له أي مادة تلامسها الألم. لذلك ننصحكِ خلال مرحلة التسنين بتقديم الأطعمة السائلة أو اللينة لطفلكِ بدلًا من الأطعمة الصلبة. وتُعد أطعمة مثل حساء الدوفغا، وهريس الفاكهة، واللبن من الخيارات التي يستطيع طفلكِ ابتلاعها من دون مضغ. وبهذه الطريقة، سيتمكن من الحصول على ما يكفيه من الفيتامينات والمعادن الضرورية مع تقليل ملامسة الطعام للثته.') WHERE id = '23f535f9-e4d0-471e-96ba-f603b329cdb3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ تريدين أن يصبح طفلكِ في المستقبل شخصًا بالغًا واثقًا بنفسه وقادرًا على بناء علاقات جيدة مع الآخرين. ولكي يتمتع بشخصية واثقة لا تحتاج إلى توجيه مستمر من أحد، عليكِ الانتباه إلى أسلوب تعاملكِ معه في هذه المرحلة. فعلى سبيل المثال، عندما لا يطيعكِ خارج المنزل، يُعد قولكِ: «انظر، سيغضب منك هذا الرجل»، أو قولكِ عندما لا يتناول طعامه في المنزل: «سأخبر أباك»، نوعًا من التهديد. وحتى إن لم يكن القصد من هذه العبارات تهديده، فإن معناها يخلق موقفًا قائمًا على الخوف. وهكذا قد تترسخ بعض المخاوف، من دون قصد، في ذهن الطفل الذي يُدار بالتهديد. وبدلًا من ذلك، من المهم جدًا أن تمنحي طفلكِ حق الاختيار، وأن تتيحي له التعبير بحرية عما يشعر به. فإذا رفض تناول الطعام، يمكنكِ أن تقولي له: «حسنًا، سيتعين عليك إذن الانتظار حتى موعد الوجبة التالية». وبهذه الطريقة سيتعلم تحمّل مسؤولية اختياره من دون أن تتضرر ثقته بنفسه.') WHERE id = 'dbc49c55-d342-48d1-a126-983d66df0425';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يجد صعوبة في التبرز، وكنتِ تعتقدين أن السبب لا يعود إلى خطأ في نظامه الغذائي، فقد حان الوقت لاستشارة الطبيب. وإذا كان يصرخ ويبكي بشدة، أو كان بطنه منتفخًا بصورة مفرطة، أو يخرج البراز اندفاعيًا، فقد يكون مصابًا بتضيّق الشرج من الناحية التشريحية. ولا يمكن تشخيص هذه الحالة بالنظر أو باستخدام الأجهزة، بل من خلال فحص الشرج بالإصبع والشعور بتضيّق الحلقة الشرجية الداخلية. يظهر تضيّق الشرج لدى الإناث بنسبة تزيد ٨٠٪ مقارنةً بالذكور، والعلاج الوحيد له هو التدخل الجراحي. وإضافةً إلى ذلك، قد تؤدي حساسية طفلكِ تجاه بعض الأطعمة إلى الإمساك. ويصعب اكتشاف هذه الحالة بالتحاليل، لكنها تتضح عندما تتحسن المشكلة بعد إيقاف الطعام المشتبه في تسببه بها. وهذه الحالة تختلف عن الحساسية التحسسية، لذا عليكِ أن تراقبي جيدًا الأطعمة التي يعاني طفلكِ من صعوبة بعد تناولها.') WHERE id = '9ea3b778-8061-4fc9-a899-eb839a41dde7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد معدن الكالسيوم أكثر المركبات غير العضوية وفرةً في جسم طفلكِ. في هذه المرحلة، يحتوي كل 10 ملليلترات من دم طفلكِ على نحو 1 ملغ من الكالسيوم. ويُعد الكالسيوم من أهم العناصر اللازمة لعملية الأيض في عظام طفلكِ النامية ولعضلاته. كما يؤدي دورًا كبيرًا في تكوين العظام الجديدة، وبنية الأسنان، وتخثر الدم، وتنظيم الجهاز العصبي، والحفاظ على توازن صحي للهرمونات. يحصل طفلكِ على الكالسيوم الذي يحتاج إليه من خلال الطعام. وإذا لم يتناول كمية كافية منه، يبدأ الجسم باستخدام الكالسيوم المخزن في الأسنان والأنسجة. وقد يؤدي ذلك إلى زيادة هشاشة أسنان طفلكِ وعظامه وسهولة تعرضها للكسر. يحتاج طفلكِ إلى 800 ملغ من الكالسيوم يوميًا. ويُعد الحليب ومنتجات الألبان، والخضراوات الورقية الخضراء، والهليون، والدبس، والزبيب، والبرقوق المجفف، والبقوليات، والبروكلي، والبامية، واليقطين، والملفوف، والجوز، والأسماك مصادر ممتازة للكالسيوم لطفلكِ.') WHERE id = '2b51d001-1cfb-4b5b-bddc-35b70fcc2c0e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن تمكّن طفلكِ من أداء بعض الأمور باستقلالية يستحق منكِ الثناء بالتأكيد، لكن الغرض من هذا الثناء أكثر أهمية. فمدح طفلكِ يعني تشجيعه وتحفيزه على تكرار هذا السلوك أو مواصلة التقدم فيه. ومن الأخطاء التي يرتكبها الوالدان كثيرًا مدح شخصية الطفل بعبارات عامة بدلًا من مدح ما أنجزه. فعلى سبيل المثال، عندما ينظف طفلكِ أسنانه، فإن قولكِ: أنت طفل ذكي جدًا، أحسنت! لا يُعد ثناءً على ما فعله. وبدلًا من ذلك، يمكنكِ قول: لقد نظفت أسنانك جيدًا، أهنئك! فهذا يحفزه على تطوير ما قام به بصورة أفضل. كما سيعزز هذا التحفيز ثقته بنفسه، إذ يمنحه شعورًا بالنجاح عندما يرى أن جهده موضع تقدير. والثناء الذي يركز على ما أنجزه طفلكِ بدلًا من شخصيته سيزيد حماسه أكثر.') WHERE id = 'b90e13fc-da18-4d18-9cf7-084289311535';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تكوني قد فطمتِ طفلكِ عن الرضعات الليلية بعد، فنوصيكِ ببدء هذه العملية في أقرب وقت ممكن. فقد تؤدي الرضاعة الليلية لفترة طويلة إلى كثير من اضطرابات المعدة لدى الأطفال، وعلى رأسها الارتجاع. كما قد تزيد من سرعة تسوس الأسنان. وفي هذه المرحلة، ينبغي أن ينام طفلكِ طوال الليل دون انقطاع. وقد يتأثر توازنه الهرموني سلبًا عندما يستيقظ ليلًا من أجل تناول الطعام. إضافة إلى ذلك، قد تؤدي الرضعات الليلية إلى ضعف شهية طفلكِ خلال النهار وإصابته ببعض اضطرابات الأكل. والطريقة التي ستتبعينها لإيقاف الرضعات الليلية تعود إليكِ تمامًا؛ إذ يمكنكِ إيقافها دفعة واحدة أو تقليلها تدريجيًا. المهم أن تلتزمي بقراركِ أيًا كانت الطريقة التي تختارينها، فالاستمرارية هي مفتاح النجاح. وعندما تبدئين هذه العملية، ستساعدكِ زيادة كمية الوجبات النهارية أو عددها كثيرًا في التعامل مع استيقاظ طفلكِ ليلًا.') WHERE id = '5d817069-0b19-4915-834b-0e07f7c81bb8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ قد تجدين صعوبة في وضع حدود لطفلكِ. لكن معرفة الطفل للمواضع التي ينبغي أن يتوقف عندها وللحدود التي يجب أن يلتزم بها تسهم كثيرًا في نموه. تتجنب عائلات كثيرة وضع الحدود رغبةً في إسعاد طفلها ومساعدته على النمو واثقًا بنفسه في بيئة حرة. غير أن ذلك يضعف قدرته على التعامل مع العقبات التي سيواجهها مستقبلًا. فالطفل الذي ينشأ في بيئة تخلو من القواعد والحدود لن يعرف كيفية التصرف في الحياة الاجتماعية عندما يبدأ المدرسة. والعيش بلا حدود يعني أن يكون الطفل محور كل شيء، وهذا لا يمنحه الثقة بالنفس، بل يسبب له التوتر. في الواقع، يشعر طفلكِ بأمان أكبر في بيئة تتضمن حدودًا وقواعد واضحة. ويحتاج طفلكِ إلى حدود وقواعد محددة لكي يتمكن من بناء علاقات اجتماعية جيدة، وفهم حدود حريته، وعدم التعدي على حقوق الآخرين.') WHERE id = '8292fe03-48c0-4b8d-8f79-32796a621a8a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذه الأيام التي يمر فيها طفلكِ بمرحلة التسنين، قد يختل توازن التغذية والنوم لديه بدرجة كبيرة. وقد يؤدي ذلك إلى إضعاف جهازه المناعي وزيادة قابليته للإصابة بالأمراض. والجهاز المناعي هو النظام الذي يشكل آلية الدفاع ضد الأمراض، ويتعرف على الميكروبات ويدمرها ويحمي الجسم. وتُنتج مكونات الجهاز المناعي بفضل العناصر التي يحصل عليها طفلكِ من الأطعمة التي يتناولها. لذلك، إذا حدثت مشكلة في التغذية، فقد يعجز الجسم عن إنتاج عدد كافٍ من الخلايا الدفاعية. وعندئذ تقل مقاومة طفلكِ للأمراض، وقد تتسبب حتى الميكروبات الشائعة في إصابته بالمرض. ولتقوية مناعة طفلكِ خلال هذه الفترة، احرصي على حصوله على كميات كافية من الفيتامينات المضادة للأكسدة A وC وD وE، بالإضافة إلى الحديد والزنك والسيلينيوم.') WHERE id = 'deafb12c-0312-478f-84da-f12b3548eb14';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يحب أن تنظفي أسنانه أو أن ينظفها بنفسه، فقد حان الوقت لتجربة بعض الحيل. يمر طفلكِ بمرحلة اللعب ويحب التقليد كثيرًا. لذلك يمكنكِ أن تجعليه بجواركِ وتنظفي أسنان إحدى ألعابه المفضلة. وبعد فترة، اقترحي عليه أن ينظف أسنان اللعبة بنفسه. وقد يكون إعداد خطة أسبوعية مفيدًا أيضًا. ستحتاجين إلى أوراق ملونة وأقلام تلوين وملصقات ممتعة! 😊 خصصي لكل يوم في الخطة التي ستُعدينها لونًا مختلفًا. ومن الجيد أن تطلبي مساعدة طفلكِ في اختيار الألوان. وفي كل يوم ينظف فيه طفلكِ أسنانه، يمكنه لصق الملصق الذي يختاره في الخانة المخصصة لذلك اليوم. وهكذا سينتظر طفلكِ اليوم التالي واللحظة التي سيضع فيها ملصقًا جديدًا بحماس! 😊') WHERE id = 'aa88eedf-fb72-41a6-b61c-927d17332a52';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الحليب ومنتجات الألبان مصدرًا مهمًا للكالسيوم والبروتين، ولهما دور كبير في نمو طفلكِ. وتكتسب الأحماض الدهنية قصيرة السلسلة الموجودة في دهون الحليب أهمية بالغة لطفلكِ خلال مرحلة النمو. لكن الحليب السائب الذي يُشترى من مصادر خارجية اعتقادًا بأنه أكثر فائدة قد ينطوي على بعض المخاطر. فعند غلي هذا الحليب مجهول المصدر، تموت الكائنات الحية الدقيقة النافعة، بينما قد تبقى البكتيريا الضارة المكوِّنة للأبواغ، ما يجعله خطرًا. كما يرتفع خطر وجود المضادات الحيوية والبكتيريا المسببة للأمراض في الحليب الذي لا تُعرف ظروف إنتاجه ونقله. لذلك يُعد الحليب المبستر المعبأ الخيار الأكثر أمانًا لتغذية طفلكِ. ويُنتج الحليب المبستر من حليب خام جرى حلبه تحت الرقابة، ثم يُسخن باستخدام أجهزة تكنولوجية حديثة على درجة حرارة مرتفعة لمدة 12–16 ثانية ويُبرّد. وبهذه الطريقة تُحفظ خصائص الحليب المفيدة، بينما يُقضى تمامًا على الكائنات الحية الدقيقة الضارة.') WHERE id = 'cf2c9950-a55b-42b0-9405-349503832e7b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تؤثر الأنشطة البدنية التي يمارسها طفلكِ خلال اليوم، والأطعمة التي يتناولها، وحالته المزاجية، وساعات نومه تأثيرًا مباشرًا في إفراز الهرمونات في جسمه. فعلى سبيل المثال، يُفرز هرمون النمو بكثافة أكبر خلال المراحل الأولى من النوم ليلًا. ويحتاج طفلكِ إلى إفراز هذا الهرمون بانتظام لتكوين خلايا جديدة ونمو الأنسجة وتطوره العام. كما يزداد إفراز هرمون النمو أثناء النوم والجوع وانخفاض سكر الدم. ولكي يعمل جسم طفلكِ بصورة صحية، من المهم أن تُفرز جميع الهرمونات، وفي مقدمتها هرمون النمو، في أوقاتها وبكميات كافية. لذلك من الضروري تنظيم ساعات النوم، واتباع نظام تغذية منتظم، والتخطيط للأنشطة البدنية والذهنية خلال اليوم. ويشكّل الالتزام بالروتين اليومي في أوقات محددة أساسًا مهمًا لنمو طفلكِ بصحة جيدة.') WHERE id = '20d5c4d1-0748-4522-a578-ae19bc9366d7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن في عمر 21 شهرًا. وهذا يعني أنكِ قد تلاحظين علامات مرحلة التحدي المرتبطة ببلوغ عمر السنتين بصورة أكثر تكرارًا. ومع تطور مهارات طفلكِ الحركية الدقيقة، بدأ يستخدم الملعقة والشوكة بطريقة أفضل. وقد تلاحظين أيضًا أنه يضيف تفاصيل أكثر إلى رسوماته وألعابه. وفي المقابل، قد يقوم طفلكِ بتصرفات مثل لمس نعل حذائه، أو رمي الملابس الموجودة في الخزانة على الأرض، أو مسح يديه المتسختين بملابسه. وقد يكرر هذه التصرفات بعناد لاختبار حدودكِ، خصوصًا عندما يعلم أنها ستثير رد فعلكِ. لذلك تجنبي إظهار رد فعل قاسٍ ومبالغ فيه تجاه التصرفات التي لا تريدين من طفلكِ القيام بها. لكن تجاهلها تمامًا ليس صائبًا أيضًا. ومن الأفضل إبعاده عن المكان، وتحويل انتباهه إلى شيء آخر، ومحاولة توضيح أن هذا التصرف لا يعجبكِ.') WHERE id = '60bd837f-fdec-4844-be98-fa359c556025';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا لنمو طفلكِ أن يشارك بفاعلية في تناول الطعام، ولا سيما على المائدة التي يجتمع حولها جميع أفراد الأسرة. فبذلك يتعلم طفلكِ التفاعل الاجتماعي، ويشعر بأنه جزء من الأسرة، وتزداد ثقته بنفسه. لكن عليكِ الانتباه إلى بعض الأمور، لأن طفلكِ يراقبكِ بعناية أثناء الوجبات العائلية. فهو يتأثر مباشرة بعاداتكِ الغذائية، وقد يؤدي اتباعكِ نمطًا غذائيًا غير صحي إلى اكتسابه العادات نفسها. فعلى سبيل المثال، حتى إن لم تسمحي لطفلكِ بشرب المشروبات الغازية والحمضية، فمن غير المناسب وضعها على المائدة. لأنكِ القدوة الأهم لطفلكِ، وتصرفاتكِ تبدو صحيحة في نظره حتى إن كانت خاطئة. لذلك بدلًا من إخبار طفلكِ بما ينبغي له فعله، تصرّفي أنتِ بالطريقة التي تريدين منه أن يتصرف بها.') WHERE id = '26559994-9ac2-46f1-966d-f214b38c785b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن يتراوح وزن طفلكِ هذا الشهر بين 9700 - 13.800 غرام إذا كانت فتاة، وبين 9300 - 14.300 غرام إذا كان صبيًا. أما الطول، فقد يتراوح بين 77.9 - 89.4 سم لدى الفتيات، وبين 79.7 - 90.5 سم لدى الصبيان. لكن اختلاف قياسات طفلكِ عن هذه الأرقام لا يعني دائمًا وجود مشكلة. فإلى جانب العوامل الوراثية، تؤثر العادات الغذائية والنشاط البدني اليومي مباشرة في الوزن. أما الطول فتحدده العوامل الوراثية إلى حد كبير. أي إذا كان طولكِ وطول شريككِ أعلى من المتوسط، فمن الطبيعي أن يكون طفلكِ أطول قليلًا من أقرانه. كذلك، إذا وُلد طفلكِ قبل أوانه، فمن المتوقع أن تظل هذه القياسات أقل في الوقت الحالي. وإذا أخبركِ الطبيب أثناء الفحص بأن كل شيء على ما يرام، فلا داعي للقلق.') WHERE id = '7bc6e8b6-b844-4ad2-aa4e-838b8a4cdf1d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحتل الأسماك مكانة مهمة في تغذية طفلكِ بفضل احتوائها على أحماض أوميغا-3 الدهنية، وفيتامين D، والكالسيوم، والفوسفور، والبروتين عالي الجودة. لكن تشجيع الطفل على حب السمك قد يكون صعبًا أحيانًا على الوالدين. وعدم تناول طفلكِ طعامًا معينًا الآن لا يعني أنه لن يتناوله أبدًا؛ فهو يحتاج إلى وقت ليعتاد مذاقه. لذلك، حتى إن لم يأكل طفلكِ السمك، فلا تتوقفي عن تقديمه له. وحتى إذا ترك طبقه دون أن يلمسه، فحاولي تقديمه مجددًا مرتين على الأقل أسبوعيًا. ومن الأساليب المجربة إضافة كمية صغيرة من السمك إلى أطعمة يحبها، مثل المعكرونة، ثم زيادة الكمية تدريجيًا. لكن انتبهي: إذا كان طفلكِ يرفض السمك تمامًا، فلا تُصرّي عليه. فإذا حاولتِ إجباره على تناوله، فقد ينفر منه نفسيًا طوال حياته.') WHERE id = '65d0ee78-f4e8-408f-81b6-d461622ab8cc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ يشعر بأنه نما جسديًا وأصبح أقوى. وقد يرغب في إثبات هذه القوة لنفسه أولًا، ثم لكِ. ومن أمثلة ذلك محاولة تغيير مكان مائدة الطعام، أو تحريك الأغراض في المنزل، أو حتى محاولة رفع أقرانه. سيجرّب كل الطرق لاختبار حدود قوته. إذا حاول طفلكِ رفع غرض ثقيل لفترة قصيرة، فلا تتدخلي كثيرًا. لكن إذا كان يجهد نفسه أكثر من اللازم، فحاولي فهم السبب. يلجأ الأطفال أحيانًا إلى مثل هذه الأساليب لجذب مزيد من الاهتمام. في هذه الحالة، بدلًا من التعامل معه بقسوة، حاولي فهم الحاجة الكامنة وراء هذا السلوك.') WHERE id = '19034df5-63aa-4566-9b70-59143f344fa9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'احرصي على أن تكون أطعمة طفلكِ طبيعية ومناسبة للموسم. فعلى سبيل المثال، تُعدّ الرجلة التي تنمو في أشهر الصيف من أكثر الأطعمة احتواءً على أوميغا-3 بعد الأسماك. وإذا كان طفلكِ لا يحب السمك، فالرجلة خيار ممتاز. وخلال الفترة الانتقالية إلى الخريف، يمكنكِ إضافة المكسرات النيئة إلى قائمة طعام طفلكِ لتهيئة جهازه المناعي لفصل الشتاء. وفي الخريف يبدأ أيضًا موسم اليقطين الذي يحبه الأطفال كثيرًا. يمكنكِ إضافة اليقطين إلى الحساء أو الأطباق، أو هرسه وتقديمه مع المكسرات كوجبة خفيفة. أما في أشهر الشتاء، فيُعدّ الحساء المُحضّر بمرق اللحم من أفضل الخيارات لتعزيز مقاومة جسم طفلكِ.') WHERE id = '1738d682-243e-48b6-aebf-069b7de44903';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يرغب طفلكِ دائمًا في تنفيذ ما يريده نتيجة ما يُعرف بمرحلة تحديات عمر السنتين. وقد يفعل غالبًا عكس ما تطلبينه تمامًا، ويعاندكِ لإصراره على تنفيذ قراراته. هذا دليل على نمو طفلكِ وازدياد ثقته بنفسه في اتخاذ القرار بشأن ما سيفعله. وقد يؤدي تركه يفعل ما يشاء تمامًا، بعد فترة، إلى شعوره بأنه لا يحظى بالاهتمام. وفي المقابل، فإن مبالغتكِ في العناد معه قد تمهّد لنوبات الغضب. لذلك، عليكِ منح طفلكِ مساحة من الحرية ضمن حدود معينة تضمن سلامته. لكن من الضروري أن تكوني ثابتة وحازمة بشأن هذه الحدود. فعلى سبيل المثال، يمكنكِ أن تتركي له قرار اختيار الملابس التي سيرتديها عند الخروج، وما يرغب في تناوله في إحدى وجبات اليوم.') WHERE id = 'db959888-c226-4ece-83bc-9cdcc0c9a618';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اكتساب طفلكِ عادات غذائية صحية مهم للغاية ليصبح شخصًا يتمتع بصحة جيدة في المستقبل. لكن لا ينبغي ترسيخ هذه العادات من خلال ربطها بمكافأة مشروطة. فعلى سبيل المثال، ليس من الصواب أن تقدمي لطفلكِ طعامًا يحبه كمكافأة بعد تناوله نوعًا من الخضراوات لا يحبه، لكنكِ ترغبين في أن يأكله. فهذا الأسلوب يحقق فائدة مؤقتة، لكنه لا يدوم ولا يتحول إلى عادة. ولكي يكتسب طفلكِ عادات غذائية صحية، عليه أولًا أن يحب الخضراوات. وخلال هذه المرحلة، يمكنكِ طلب مساعدته عند إعداد الطعام. فمثلًا، قد يكون من الجيد أن تطلبي منه مناولتكِ الخضراوات، أو السماح له بتقليبها أثناء الطهي تحت إشرافكِ. وعندما يشارك طفلكِ في العملية ويساهم فيها، سيرغب في تذوق الخضراوات ليرى نتيجة ما أنجزه.') WHERE id = 'a29ffc6c-9f51-4d1f-9099-df4361738d5a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبتعد طفلكِ إلى زاوية عندما يشعر بالحاجة إلى استخدام المرحاض خلال هذه المرحلة. وقد تلاحظين أيضًا بعض السلوكيات مثل الشدّ أو القرفصاء أو الشعور بالخجل. لكن كل ذلك لا يعني أن طفلكِ مستعد تمامًا للتدريب على استخدام المرحاض. لذلك، لا تستعجلي تدريبه، وانتظري الوقت الأنسب. يرى كثير من المتخصصين أن بدء تدريب الأطفال على استخدام المرحاض قبل إتمام عمر 2 سنة ليس فكرة جيدة. ويرجع ذلك إلى أن المثانة لا تكون قد اكتسبت بعد القدرة الكافية على الاحتفاظ بالبول، مما يجعل التحكم فيه صعبًا. عليكِ الانتظار إلى أن يصبح طفلكِ مستعدًا من الناحية الفسيولوجية أيضًا. وقد يؤدي بدء التدريب قبل ظهور جميع علامات الاستعداد إلى زيادة صعوبة العملية. وفي المتوسط، يصبح طفلكِ مستعدًا تمامًا للتدريب على استخدام المرحاض في الفترة الواقعة بين الشهرين 24 و30.') WHERE id = 'a39ea810-7420-4e1c-a518-23a50b1d1c6e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مستخلص الخروب هو شكل سائل ومركّز يُنتج عبر عصر ثمار شجرة دائمة الخضرة يبلغ ارتفاعها نحو 8 أمتار باستخدام تقنيات خاصة. وعلى خلاف دبس الخروب، لا يُغلى هذا المستخلص ولا يخضع لأي معالجة أخرى، لذلك يحتفظ بالعناصر الغذائية الموجودة فيه. ويحتوي مستخلص الخروب على مجموعة فيتامينات B، إلى جانب فيتاميني A وE، والبوتاسيوم والزنك والصوديوم والبروتين والحديد والمغنيسيوم والفوسفور، كما أنه غني جدًا بالكالسيوم. وبفضل مضادات الأكسدة التي يحتوي عليها، يساعد على تقوية الجهاز المناعي لطفلكِ وحمايته من الأمراض. كما يساهم في نموه الذهني والفسيولوجي ويساعد على الوقاية من فقر الدم. ومن المعروف أيضًا أن مستخلص الخروب يخفف أعراض الحساسية، وقد استُخدم عبر التاريخ وسيلة طبيعية للمساعدة في علاج الربو والتهاب الشعب الهوائية. إن تناول طفلكِ 1-2 ملعقة صغيرة من الخروب في وجبة الإفطار سيساعد، بفضل محتواه الغني بالألياف، على دعم عمل جهازه الهضمي بكفاءة وتزويده بالطاقة التي يحتاج إليها طوال اليوم.') WHERE id = 'cee447ef-1683-40f9-aaa6-1503f753e5fb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ في هذه المرحلة إعداد مواد تعليمية لطفلكِ باستخدام أشياء يسهل العثور عليها في المنزل. ستحتاجين إلى: زجاجة زجاجية، وزجاجة بلاستيكية، وقليل من الماء، والأرز، وأنواع مختلفة من البقوليات الجافة مثل الفاصولياء والعدس. ابدئي أولًا بتعريف طفلكِ إلى جميع هذه المواد. افتحي غطاء الزجاجة الزجاجية والبلاستيكية واطلبي منه أن ينفخ فيهما بالتناوب. يمكنكِ أن تسألي طفلكِ عن سبب اختلاف الصوت الصادر من كل زجاجة. بعد ذلك، اسكبي قليلًا من الماء في الزجاجتين وكرّرا التجربة، وتبادلا الأسئلة حول سبب تغيّر الأصوات. ثم ضعي حبوبًا صغيرة مثل الأرز في الزجاجة الزجاجية ودعي طفلكِ يرجّها. كرّري العملية نفسها مع الزجاجة البلاستيكية، واسأليه عن سبب كون الصوت الصادر من الزجاجة الزجاجية أكثر حدّة رغم استخدام الحبوب نفسها. كرّرا هذا النشاط باستخدام حبوب أخرى، وحاولا معًا فهم أسباب اختلاف الأصوات. نتمنى لكما وقتًا ممتعًا! 😊') WHERE id = '8b5577e9-8555-46ea-9858-e2aca89ca5d4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد الأشهر الـ24 الأولى منذ ولادة طفلكِ المرحلة التي يشهد فيها نموه الفسيولوجي والعقلي في العالم الخارجي أسرع وتيرة. وخلال هذه العملية السريعة، تكون حاجته إلى المغذيات الكبرى والصغرى أكبر من حاجة البالغين. لذلك، تُعد تغذية طفلكِ الكافية والمتوازنة أمرًا أساسيًا للحفاظ على صحته واستمرار نموه. ومع اقتراب طفلكِ من إتمام عامه الثاني، توشك الميكروبيوتا المعوية لديه على بلوغ شكلها النهائي المشابه لما لدى البالغين. كما تكون وظائفه العقلية قد تطورت بنسبة 90%. وفي هذه المرحلة، ينبغي أن يحصل طفلكِ بصورة متوازنة على الكميات التي يحتاج إليها جسمه من المواد العضوية وغير العضوية. يُعد البيض غنيًا جدًا بالكالسيوم والحديد والزنك وفيتامينات B. لذلك، يمكنكِ إدراج البيض ضمن غذاء طفلكِ بوصفه غذاءً تكميليًا. وإذا لم يكن طفلكِ مصابًا بحساسية تجاه البيض، فسيحصل بذلك على أحد أجود مصادر البروتين.') WHERE id = '9f49e07d-85c6-4330-803a-53c01fdd33b1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يمر طفلكِ خلال اليوم بتجارب كثيرة لا يمكنكِ الإشراف عليها، إلى جانب الأوقات التي يكون فيها تحت مراقبتكِ. وقد تكون هذه التجارب مخيفة له، لا سيما المواقف التي يواجهها للمرة الأولى. وحتى إن لم يُبدِ أي رد فعل في حينه بسبب انشغالات اليوم، فقد يتجنب البقاء وحده أو النوم ليلًا نتيجة الخوف الذي شعر به. وإذا نام، فقد يرى في منامه هذا الخوف الراسخ في عقله الباطن ويستيقظ صارخًا. في هذه المرحلة، يعتقد طفلكِ أن الأحلام حقيقية. بعبارة أخرى، يظن أن ما رآه في الحلم كان واقعًا ثم اختفى عندما استيقظ. ومن المهم أن تهدّئي طفلكِ في مثل هذه المواقف، إذ قد لا يستطيع التمييز بين الحلم والواقع حتى سن السابعة تقريبًا. وقد يكون من المفيد أن تعانقيه وتطلبي منه أن يحكي لكِ حلمه، وأن تبقي بجانبه لبعض الوقت.') WHERE id = '9b4f4b9b-e87e-40ab-829d-b7915986e8b3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'استُخدمت طريقة التجفيف منذ العصور القديمة جدًا لحفظ الأطعمة من دون فقدان قيمتها الغذائية. وينبغي إدراج الفواكه المجففة خصوصًا ضمن النظام الغذائي لطفلكِ. تُجمع هذه الفواكه في موسمها وتُجفف تحت أشعة الشمس لتتبخر المياه الموجودة فيها. وأثناء التجفيف، تنخفض نسبة الماء في الفاكهة من 85% إلى 15%، بينما ترتفع نسبة السكر. وتُعد هذه الفواكه مصدرًا جيدًا للكالسيوم والألياف، لذا تسهم بدرجة كبيرة في دعم الجهاز الهضمي لطفلكِ ونمو عظامه. كما تساعد مضادات الأكسدة القوية الموجودة فيها على حماية جهازه المناعي. إضافة إلى ذلك، تُعد الفواكه المجففة وسيلة جيدة لحفظ الفاكهة لأنها تدوم مدة أطول من الفواكه الطازجة. وبفضل ما تحتويه من سكر طبيعي، سيحصل طفلكِ على الطاقة التي يحتاج إليها بعد وقت قصير من تناولها.') WHERE id = 'd3489a97-b65f-4aae-ab71-7ebccc7eca0f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون سبب انخفاض شهية طفلكِ ورفضه الطعام في بعض الفترات هو ظهور تقرحات في فمه تُسمى القلاع الفموي. وهي آفات مؤلمة تظهر بأشكال مختلفة في أي جزء من الغشاء المخاطي للفم. وقد يكون السبب الرئيسي لها أدوية تناولها طفلكِ مؤخرًا أو عدوى أُصيب بها. ومن الأسباب الأخرى المحتملة عدم الاهتمام الكافي بنظافة منطقة الثدي لدى الأم المرضعة، أو عدم تنظيف زجاجات الرضاعة والألعاب جيدًا، أو ضعف الجهاز المناعي. وقد تختفي هذه التقرحات المؤلمة عند لمسها تلقائيًا خلال 1-2 أسبوع من دون علاج. ولكن عندما يتعلق الأمر بطفلكِ، فقد تساعد الأدوية التي تستخدمينها بعد استشارة الطبيب على شفائها خلال 1-2 يوم. ويمكنكِ أيضًا، بموافقة الطبيب، وضع كمادة على موضع التقرح باستخدام محلول مخفف من بيكربونات الصوديوم، وهو من الأساليب المستخدمة في الطب الشعبي.') WHERE id = '2ccbc797-3a7f-4d46-86ba-8a535032d851';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا لأبحاث أُجريت في السنوات الأخيرة، يوصي بعض الخبراء بتوخي الحذر عند إعطاء الأطفال حليب البقر أو المثلجات المصنوعة منه خلال أول عامين من العمر. ويعود السبب الرئيسي إلى أن نمو الأمعاء لا يكتمل إلا قرابة عمر السنتين، وإلى احتمال أن يزيد حليب البقر خطر الإصابة بفقر الدم. يقترب طفلكِ الآن من عمر السنتين؛ وإذا لم تكن لديه حساسية معروفة تجاه الحليب ومنتجات الألبان، فيمكنكِ السماح له بتناول المثلجات بعد استشارة طبيبكِ. فالمثلجات غنية بالبروتينات والكربوهيدرات، وتحتوي تقريبًا على جميع الفيتامينات، بالإضافة إلى معادن مثل الكالسيوم والبوتاسيوم والفوسفور والمغنيسيوم والحديد والزنك. وإذا كان طفلكِ لا يحصل من الأطعمة الأخرى على كمية كافية من الكالسيوم، الذي يُعد مهمًا لنمو عظامه خصوصًا، فقد تكون المثلجات بديلًا جيدًا. ومع ذلك، احرصي على ألا يفرط طفلكِ في تناولها. وتذكّري أن تناول كميات كبيرة من المثلجات يمنحه سعرات حرارية زائدة بسبب محتواها من الكربوهيدرات والسكر.') WHERE id = '6fd1f804-625f-4260-ad27-7db11651d8f4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين في هذه الأيام أن طفلكِ، الذي أوشك على إتمام عامه الثاني، يشير إلى ساقيه ولا يرغب في الحركة كثيرًا. ينمو طفلكِ جسديًا منذ ولادته وحتى سن 12-13 عامًا تقريبًا، وذلك من خلال استطالة العظام عند مناطق صفائح النمو المشاشية. وخلال هذا النمو، يُعد الشعور بالألم أمرًا طبيعيًا، خاصةً في منطقتي الكتفين والرسغين، وكذلك في أجزاء الساقين أعلى الركبتين وأسفلهما. وتظهر هذه الآلام بالدرجة نفسها لدى الإناث والذكور، وتنجم عن التغيرات التي تحدث في مناطق نمو العظام. وبصورة أدق، تنتج هذه الآلام عن ازدياد حساسية الأنسجة الرخوة المحيطة بالعظام، مثل العضلات والأوتار والأربطة، بسبب التورم المصاحب للنمو. وقد يشعر طفلكِ بآلام النمو بصورة أشد في المساء نتيجة نشاطه خلال النهار. ولا تتطلب هذه الآلام علاجًا في العادة، ويمكنكِ تخفيفها بإراحة طفلكِ وتدليك المنطقة برفق.') WHERE id = 'c6878c04-fea4-41bf-9978-ffa27c8ba4e7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تتردد بعض العائلات في تقديم أنواع العدس المختلفة الألوان لأطفالها خوفًا من أن تسبب لهم الغازات. ولكن يمكن الاستفادة من فوائد العدس من دون التسبب في مشكلات الهضم والغازات عند طهيه بطريقة صحيحة. فإذا نقعتِ العدس منذ اليوم السابق وغيّرتِ ماءه أثناء الطهي، فسينخفض احتمال تسببه في الغازات بدرجة كبيرة. ويُعد العدس الأحمر أنسب لحساء طفلكِ وطعامه المهروس لأنه ينضج بسرعة ويتميز بقوام أكثر ليونة. يحتوي العدس على الحديد والبروتين والفوسفور وفيتامينات B، إضافةً إلى كمية كبيرة من المعادن، كما أنه غني بالفولات. ويوفر وعاء واحد من العدس وحده ما يقارب نصف احتياجات طفلكِ اليومية من البروتين. ولكل هذه الأسباب، من المهم جدًا لنمو طفلكِ أن تُدرجي العدس ضمن نظامه الغذائي.') WHERE id = '15714a3a-d1f3-4262-b777-caa9b8b65081';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يمر طفلكِ في هذه المرحلة ببعض النوبات أثناء انتقاله إلى النوم العميق. ويحدث ذلك بسبب عدم اكتمال تنظيم الانتقال بين مراحل النوم بكفاءة. إذا استيقظ طفلكِ ليلًا وهو يصرخ ولم تتمكني من تهدئته لبعض الوقت مهما فعلتِ، فقد يكون ذلك رعبًا ليليًا. وقد تستمر هذه الحالة مدة 5 دقائق أو أكثر من نصف ساعة. وخلال هذه الفترة، ينبغي ألا تبتعدي عن طفلكِ، وأن تحرصي على منعه من إيذاء نفسه أو الاصطدام بما حوله. ففي أثناء النوبة لا يكون طفلكِ مستيقظًا تمامًا، ولذلك لا يتحرك بوعي، مما يزيد احتمال تعرضه للإصابة. وعلى الرغم من أن نوبات الرعب الليلي تقل عادةً مع بلوغ سن المراهقة، فإن تكرارها كثيرًا قد يكون علامة على مشكلة أخرى. وإذا كنتِ تلاحظين هذه الحالة لدى طفلكِ بصورة متكررة، فمن المفيد استشارة طبيبكِ.') WHERE id = 'df85d749-c950-4fca-8bdc-a3b2e555941f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'التمر، الذي يحتوي على السكريات الطبيعية والبروتين ونسبة عالية من الألياف ومجموعة متنوعة من الفيتامينات والمعادن، هو ثمرة أحد أقدم أنواع النباتات التي عرفتها البشرية. ويساعد التمر على دعم توازن خلايا الدم الحمراء لدى طفلكِ، وهو أمر مهم لنموه. كما يؤدي الكالسيوم والفوسفات الموجودان فيه دورًا أساسيًا في تقوية الهيكل العظمي والعظام النامية لدى طفلكِ. والتمر غني بالبيتا كاروتين، الذي يتحول في الجسم إلى فيتامين A. ويُعد البيتا كاروتين مهمًا بصفة خاصة لنمو الدماغ، كما يساعد تناوله بانتظام على دعم الوظائف الذهنية وتوفير حماية مضادة للسرطان. يحتوي التمر على نحو 15% من الألياف، مما يريح الجهاز الهضمي لطفلكِ ويجعله خيارًا فعالًا للوقاية من الإمساك. ولأن الأطعمة الغنية بالألياف تساعد على تقليل خطر الإصابة بالسرطان، فمن المهم أن تفضّلي في قائمة طفلكِ أطعمة غنية بالألياف مثل التمر.') WHERE id = '4303bdd7-56ec-4a2e-93fe-7dba4f34f12e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ تريدين أن ينشأ طفلكِ في المستقبل شخصًا مدركًا لمسؤولياته. وتتشكّل شخصية طفلكِ المستقبلية منذ وجوده في رحمكِ وحتى وصوله إلى سن المدرسة. وهناك أنشطة بسيطة جدًا يمكنكِ البدء بها منذ الآن لوضع أسس الشعور بالمسؤولية لديه. على سبيل المثال: زراعة نبتة! كل ما تحتاجين إليه هو بعض البقوليات سهلة الإنبات، مثل الفاصولياء أو الحمص، وقليل من الماء، ووعاء، وبعض القطن. هذه هي المستلزمات التي تحتاجين إليها فحسب! 😊 ضعي مع طفلكِ بعض القطن داخل الوعاء. ثم ضعي البذرة في منتصف القطن وغطّيها بكمية مماثلة منه. ويمكنكِ أن تسمحي لطفلكِ، تحت إشرافكِ، بسكب كمية قليلة من الماء على ما أعددتماه. بعد ذلك، اتركي الوعاء في مكان مظلم مدة 48 ساعة تقريبًا حتى تنبت البذرة. ويمكنكِ التأكد من أن طفلكِ سيتفقد نبتته من حين إلى آخر. 😊 وبعد اكتمال الإنبات، يمكنكما نقل النبتة إلى أصيص مناسب وسؤال طفلكِ عن الاسم الذي يرغب في إطلاقه عليها. نتمنى لكما وقتًا ممتعًا! 😊') WHERE id = '45b4dd3a-d197-4577-bd56-c783da7250c0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ إضافة العسل إلى نظام طفلكِ الغذائي في أي وقت بعد انقضاء السنة الأولى من حياته. وعلى الرغم من أن العسل غني بالعديد من الفيتامينات والمعادن، فإنه لا يُنصح بتقديمه للأطفال خلال السنة الأولى بسبب احتمال احتوائه على أبواغ بكتيريا تُسمى Clostridium botulinum. وقد تسبب هذه البكتيريا مشكلات صحية خطيرة لطفلكِ خلال أول 1 سنة، إذ لا يكون جهازه المناعي قد اكتمل بعد ويكون جسمه شديد الحساسية. ولكن بعد هذه المرحلة، يمكنكِ استخدام العسل الغني بالعناصر الحيوية المهمة في غذاء طفلكِ بأمان. وإذا كان طفلكِ يعاني خصوصًا من ضعف الشهية، فهناك دراسات تشير إلى أن العسل قد يسهّل الهضم ويساعد على تحفيز الشهية. كما تساعد الأحماض الأمينية والإنزيمات الموجودة في العسل على التئام الجروح التي قد تظهر في جسم طفلكِ لأسباب مختلفة خلال مدة أقصر. وإلى جانب ذلك، تشير الدراسات إلى أن الأطفال الذين يتناولون العسل بانتظام بعد عمر 1 سنة ينمون بوتيرة أسرع مقارنةً بغيرهم.') WHERE id = 'ff1e9f61-df65-4064-8df5-c43b49055772';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل تطوره الذهني، بدأ طفلكِ الآن يولي اهتمامًا أكبر للتفاصيل الصغيرة. مثلًا، قد تلفت انتباهه حبات الخرز الموجودة عند طرف الستارة، أو حشرة صغيرة يراها على الأرض، أو فتات طعام سقط من طبقه، وهي أشياء لم تكن تثير اهتمامه من قبل… لقد أصبحت كل هذه التفاصيل الآن ضمن دائرة اهتمام طفلكِ النشط. وهذا يعني أن هناك مزيدًا من الأمور التي ينبغي لكِ الانتباه إليها. سيرغب طفلكِ في استكشاف جميع التفاصيل الصغيرة التي يلاحظها عن قرب. وبما أنه لا يزال يمر بما يُسمى المرحلة الفموية، فسيستخدم فمه غالبًا وسيلةً للتعرف إلى الأشياء! 😊 قد ترينه يضع حبات الخرز الموجودة عند طرف الستارة في فمه ليستكشفها. وإذا لم يكن هناك خطر من انفصالها، فقد يبدو لكِ ذلك آمنًا. لكن ملاحظته للحشرات ورغبته في استكشافها تتطلبان متابعة أكثر دقة وحذرًا. من الجيد أن تسمحي لطفلكِ بالنظر إلى الحشرة عن قرب للتعرف إليها، مع التدخل عندما يحاول لمسها أو وضعها في فمه.') WHERE id = '9069fb16-d889-49ff-94bd-38c462c7266b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتوي الجوز، مقارنةً بالمكسرات الأخرى، على كميات وفيرة من أحماض أوميغا 3 وأوميغا 6 الدهنية. كما يحتوي على مجموعة فيتامينات B المركبة، والفولات، والمغنيسيوم، والنحاس، والفوسفور، وفيتامين E، وبروتين عالي الجودة. ويحتوي متوسط 50 غرامًا من الجوز الذي تقدمينه لطفلكِ على 8 غرامات من البروتين، و4500 ملغ من أوميغا 3، و19.000 ملغ من أوميغا 6، و1.6 ملغ من الحديد، و78 ملغ من المغنيسيوم، و180 ملغ من الفوسفور. لذلك، من المهم جدًا أن يتناول طفلكِ الجوز. لكن ينبغي لكِ الانتباه إلى بعض خصائص الجوز الذي سيتناوله. وبدلًا من الجوز المباع مكشوفًا أو من دون قشر، يُفضّل اختيار الجوز بقشره مع الانتباه إلى وزنه. وإذا كان طفلكِ يستطيع تناول الجوز بسهولة، فيمكنكِ سحقه قليلًا وتقديمه له في الوجبات الخفيفة. كما يمكن أن يكون طحن الجوز في الخلاط حتى يصبح مسحوقًا وخلطه بالزبادي خيارًا مغذيًا جدًا.') WHERE id = '27105655-fd01-456e-bb71-4a01714e9449';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد العلاقة التي تبنينها مع طفلكِ منذ لحظة ولادته أحد أهم العوامل في تكوين شخصيته. فعندما تُلبّى احتياجات طفلكِ في الوقت المناسب ويحظى منكِ بالحب الذي يحتاج إليه، ينشأ بينكما شعور أساسي بالأمان والثقة. ولا يكفي لتطور شخصيته بشكل صحي أن تُلبّي احتياجاته الجسدية في الوقت المناسب وبشكل كامل فحسب. فإذا لم يحصل على قدر كافٍ من الحب، فقد تظهر بعض الآثار السلبية في تكوين شخصيته. ومن المهم جدًا أيضًا أن تكون هذه الرعاية والاهتمام والمحبة مستمرة. وإلى جانب هذه الاستمرارية، ينبغي أن يكون سلوككِ متسقًا أيضًا. فعندما تتعاملين مع طفلكِ بإيجابية وثبات، يبدأ لديه شعور أساسي بالثقة بأنه سيشعر بالرضا في حياته. ويُعد ترسيخ هذا الشعور الأساسي بالأمان والثقة من أهم ركائز التطور الصحي لشخصية طفلكِ.') WHERE id = '34e65f61-d1c2-4a9e-8715-5a4ccba0a4d1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'العكبر مادة يجمعها النحل من سيقان النباتات وأوراقها وبراعمها، وتتمتع بتأثير قوي مضاد للبكتيريا والأكسدة. وتحتوي هذه المادة، التي تُعد من أقوى المواد المكتشفة في العالم من حيث خصائصها المضادة للأكسدة، على مضادات أكسدة أكثر بـ80 مرة من عصير الرمان. ويستخدم النحل هذه المادة اللزجة أساسًا لتعقيم خلاياه والقضاء على الكائنات الحية الدقيقة الضارة. وعند معالجته بشكل صحيح، يتمتع العكبر بفوائد عديدة مثبتة لمناعة الإنسان. ويمكنكِ الاستفادة من تأثيراته الداعمة للمناعة، خصوصًا للمساعدة في حماية طفلكِ الذي لم يكتمل نمو جهازه المناعي بعد. وإذا كان طفلكِ يتناول العسل ولا يعاني أي حساسية تجاهه، فيمكنه تناول العكبر. وعند استخدام العكبر بانتظام، فإنه يقوّي مناعة طفلكِ، ويساعد على القضاء على الفيروسات والبكتيريا في الجسم أثناء المرض، ويقلل بدرجة كبيرة من خطر الإصابة بالأمراض.') WHERE id = '91bdc58d-0298-42d1-becf-b47ed9613a9c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلتكِ تهتم بالسيارات أكثر من الدمى، أو أن طفلكِ يهتم بالدمى أكثر من السيارات. في مثل هذه الحالة، قد يشعر بعض الوالدين بالقلق ويحاولون تغيير هذا الميل والتدخل في اختيارات طفلهم. وقد تلاحظين ذلك أكثر، خصوصًا إذا كان لديكِ أطفال من الجنسين أو إذا كان طفلكِ يقضي وقتًا متكررًا مع أقران من الجنس الآخر. لقد بدأ طفلكِ في هذه المرحلة يلاحظ جنسه، لكن ملاحظة الجنس وفهم مفهومه أمران مختلفان. وباختصار، لا يستطيع طفلكِ في هذه المرحلة استيعاب مفهوم الجنس بشكل كامل، فهو لا يزال يحتاج إلى نحو عام لفهمه. أما السلوكيات المرتبطة عادةً بالأولاد أو البنات، فتبدأ في التمايز في سن 3.5-4 سنوات على أقرب تقدير. لذلك، لا داعي لمحاولة توجيه طفلكِ نحو اتجاه معين.') WHERE id = 'ed2e24a4-c2b1-4d6f-86c8-6f25e802ef0a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل التطور التكنولوجي في السنوات الأخيرة، أصبح من الممكن العثور على جميع أنواع الفواكه والخضروات في كل فصل. لكن كما يعلم الجميع، تكون الخضروات والفواكه المزروعة في موسمها ألذ وأكثر فائدة للصحة. وإضافةً إلى ذلك، تكون المنتجات الموسمية أغنى بالفيتامينات والمعادن لأنها تنمو بصورة طبيعية. وعندما يتعلق الأمر بتغذية طفلكِ على وجه الخصوص، ينبغي لكِ الحرص أكثر على اختيار الأطعمة المناسبة للموسم. فعلى سبيل المثال، يحتوي السبانخ الذي ينمو طبيعيًا في أشهر الشتاء على فيتامين C أكثر بـ3 مرات من السبانخ المزروع في الصيف. وقد تُستخدم أيضًا إضافات هرمونية وبعض المواد الكيميائية الضارة في زراعة الخضروات والفواكه خارج موسمها. ولأن هذه المواد قد تُحدث تأثيرًا سامًا في جسم طفلكِ، فمن المهم جدًا أن تضعي برنامجه الغذائي اعتمادًا على الخضروات والفواكه الموسمية.') WHERE id = 'cb687d0d-1a07-40e8-8dc8-33e46be11729';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه المرحلة أن طفلكِ يظن أن ألعابه جائعة، فيحاول إطعامها، أو أنه يلتقط أحد أغراضه إذا سقط على الأرض ويقبّله. مع نمو طفلكِ، يُظهر بعض أنماط التفكير المناسبة لخصائص مرحلته العمرية. وقد يتفاعل في هذه الفترة مع الأشياء الجامدة كما لو كانت كائنات حية. تُسمى هذه المرحلة في التطور المعرفي «الإحيائية»، وهي الميل إلى إضفاء صفات الكائنات الحية على الأشياء الجامدة. ويرجع ذلك إلى أن طفلكِ لا يدرك تمامًا بعد ما الذي يجعل الكائن حيًا. فعلى سبيل المثال، قد يظن طفلكِ، الذي يشعر بالألم عندما يسقط، أن لعبته تتألم أيضًا عندما تسقط على الأرض. تستمر هذه المرحلة نحو عامين، ثم تنتهي عندما يبدأ طفلكِ في ربط الحياة بالحركة. وقد يظل يعتقد أن كل ما يتحرك كائن حي حتى سن المدرسة تقريبًا، ولا يبدأ في استيعاب مفهوم الحياة بصورة كاملة إلا في عمر 6-7 سنوات.') WHERE id = 'b8c5e8a1-fa66-481e-a257-382cebe56450';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون تقديم بيض السمان إلى جانب بيض الدجاج ضمن وجبة إفطار طفلكِ خيارًا جيدًا. والاعتقاد الشائع بأن القيمة الغذائية لبيض السمان أقل من بيض الدجاج بسبب صغر حجمه اعتقاد خاطئ. فبيض السمان يحتوي على البروتين بالنسبة نفسها الموجودة في بيض الدجاج. كما أن محتواه من الحديد والزنك والبوتاسيوم أعلى مقارنة ببيض الدجاج. لكن الدراسات التي أُجريت في السنوات الأخيرة تشير إلى أن هرمون الإستروجين الموجود في بيض السمان قد يسبب البلوغ المبكر لدى الأطفال. وقد يؤدي البلوغ المبكر إلى نمو الغدد الثديية لدى طفلكِ قبل أوانها وظهور الشعر بكثافة أكبر. لذلك، بدلًا من أن يتناول طفلكِ بيض السمان يوميًا، يكفي تقديمه له يومين في الأسبوع كحد أقصى.') WHERE id = 'b265a8fe-9ad6-4889-9714-f72792f5fc6a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مرحبًا بكِ في الشهر 22، حيث يصبح طفلكِ قليل الصبر للغاية وتبلغ لديه الأنانية الفكرية، أو التمركز حول الذات، ذروتها! 😊 خلال هذه المرحلة، التي تبدأ في عمر السنتين تقريبًا وتستمر حتى سن 6 سنوات، يبدأ طفلكِ في تفسير العالم والأشخاص من حوله من وجهة نظره وحده. فهو يعتقد أن الجميع يرون الأحداث بالطريقة نفسها التي يراها بها، ولا يهتم بآراء الآخرين. ورغم أن التمركز حول الذات قد يُعد نوعًا من الاضطراب النفسي لدى البالغين، فإنه عملية نمو طبيعية لدى الأطفال في هذه الفئة العمرية. قد لا يحب طفلكِ، الذي يفتخر بنفسه باستمرار، مشاركة أغراضه مع الآخرين، وقد تسمعين منه كثيرًا عبارات مثل «أنا» و«إنه لي» و«هذا يخصني». ولشدة تركيزه على ذاته، يظن أن كل شيء يتمحور حوله وحول قراراته. عليكِ التحلي بمزيد من الهدوء والصبر مع طفلكِ خلال هذه المرحلة. وستساعدكِ محاولة فهمه على اجتياز فترة التمركز حول الذات هذه براحة أكبر.') WHERE id = 'cdeb8d0f-e8d6-42f6-b726-3cb574c7ad31';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يؤدي فيتامين B12، المعروف باسم الكوبالامين، دورًا أساسيًا في تكوين خلايا الدم الحمراء لدى طفلكِ، وعمليات الأيض الخلوية، ووظائف الأعصاب، وإنتاج الحمض النووي (DNA). والكوبالامين فيتامين قابل للذوبان في الماء، وأهم ما يميزه عن بقية فيتامينات مجموعة B أنه الفيتامين الوحيد الذي يحتوي على الكوبالت. ينتج جسم طفلكِ، الذي يمر بمرحلة نمو سريع، ملايين خلايا الدم الحمراء كل دقيقة. ولا يمكن لهذه الخلايا أن تتكاثر بصورة سليمة من دون فيتامين B12. وعندما ينخفض مستوى فيتامين B12 بشدة، يقل إنتاج خلايا الدم الحمراء، ما قد يؤدي إلى مشكلات عديدة، أبرزها فقر الدم. خلال أول 6 أشهر بعد الولادة، يلبي طفلكِ هذه الحاجة من المخزون الذي كوّنه جسمه في أثناء الحمل. وبعد ذلك، يجب توفيره له من خلال الأطعمة التكميلية. يكاد فيتامين B12 يكون غير موجود في الفواكه والخضراوات، لذلك ينبغي تلبية احتياجات طفلكِ منه عبر الأطعمة الحيوانية الغنية بالبروتين. وإذا كان طفلكِ يعاني حساسية تجاه الأطعمة الحيوانية أو لا يتناولها لأي سبب آخر، فيمكنكِ الاستعانة بمنتجات الحبوب المدعمة بفيتامين B12.') WHERE id = '64cdc31d-80de-4ea5-bd52-b34349ce73c3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا لمخطط النسب المئوية للنمو، يبلغ متوسط وزن طفلكِ هذا الشهر 11.800 غرامًا للفتيات و12.400 غرامًا للفتيان. بعد هذه المرحلة، قد تلاحظين مزيدًا من التباطؤ في معدل زيادة وزن طفلكِ أو ثباته لفترة. ومن الطبيعي أن تزداد كمية السعرات الحرارية التي يستهلكها يوميًا بسبب نشاطه وحركته المستمرة. ونتيجة لذلك، يكاد يتحقق توازن بين السعرات الحرارية التي يتناولها وتلك التي يحرقها. وباستثناء بعض الحالات، يُعد انخفاض شهية طفلكِ أيضًا سلوكًا معتادًا يظهر في عمر السنتين تقريبًا. ولهذه الأسباب كلها، قد يُعد توقف زيادة وزن طفلكِ، بل وفقدانه قليلًا من الوزن، أمرًا طبيعيًا. لكن إذا لاحظتِ عدم زيادة وزنه لمدة طويلة أو فقدانه وزنًا بدرجة تثير القلق، فعليكِ استشارة طبيبكِ.') WHERE id = '6d7daca4-fa1d-4f35-8fb6-2e31e98f98b2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تقل طريقة تحضير الفواكه والخضراوات وحفظها أهمية عن اختيار أكثرها فائدة لصحة طفلكِ والاهتمام الدقيق بنظامه الغذائي. أُجريت في السنوات الأخيرة دراسات كثيرة حول الألومنيوم. ووفقًا لنتائج الأبحاث، تبيّن أن التعرض المكثف للألومنيوم قد يكون أحد أسباب الإصابة بمرض ألزهايمر. يستطيع جسم الإنسان البالغ طرح ما يصل إلى 50 ملغ من الألومنيوم يوميًا عن طريق البول من دون أن يلحق به ضرر. والألومنيوم هو أكثر المعادن انتشارًا في الطبيعة؛ إذ توجد كميات منه حتى في الماء الذي نشربه والفواكه والخضراوات التي نتناولها. وقد تنتقل كمية تقارب 2-3 ملغ من الألومنيوم إلى الأطعمة المطهية في المقالي والقدور المصنوعة منه. ورغم أن هذه الكمية قد تبدو غير ضارة بمفردها، فإنها تعني على المدى الطويل تعرض الجسم لكمية أكبر من المعدن. وبما أن أجسام الرضع أكثر حساسية بكثير من أجسام البالغين، فقد يكون من الأفضل استبعاد أواني الألومنيوم من طرق الطهي التي تستخدمينها.') WHERE id = 'e9dafa7a-dbe9-4ea9-83e2-ee717a327062';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعدّ السماح للأطفال بمشاهدة التلفاز من الأساليب التي تلجأ إليها الأمهات كثيرًا، ولا سيما عند مواجهة صعوبة في إطعامهم. وفي عصر التكنولوجيا، قد يصعب أحيانًا إبعاد الأطفال تمامًا عن الأجهزة اللوحية والهواتف والتلفاز. لكن الدراسات تشير إلى أن مشاهدة التلفاز، خصوصًا لدى الأطفال بعمر سنتين أو أقل، تزيد من خطر الإصابة باضطرابات نمائية شديدة، وفي مقدمتها اضطراب طيف التوحد. وقد تظهر أيضًا مشكلات مثل تأثر النمو المعرفي لدى الأطفال سلبًا، وتأخر المهارات اللغوية والكلامية، ونقص الانتباه وفرط النشاط. ولهذه الأسباب جميعها، توصي جهات عديدة، من بينها الأكاديمية الأمريكية لطب الأطفال، بإبعاد الأطفال من عمر 0 إلى سنتين عن الأجهزة التكنولوجية ذات الشاشات. وبدلًا من تعويد طفلكِ على التلفاز، ينبغي لكِ تفضيل أنشطة مثل قراءة الكتب المصورة معه، والرسم، وممارسة تمارين النطق، واللعب مع أقرانه وبالألعاب التعليمية. وفي أثناء تناول الطعام، يمكنكِ إعداد أطباق ملوّنة وجذابة للفت انتباه طفلكِ، أو شراء أوانٍ تحمل صور شخصياته المفضلة.') WHERE id = '94c13633-51b3-4740-9eed-f9195f6997ac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'البطاطا الحلوة من الخضراوات التي تجمع أهم العناصر الغذائية الأساسية والضرورية لنمو طفلكِ. وهي سهلة الهضم للغاية، وتحتوي على كميات وفيرة من البوتاسيوم وفيتامين C وفيتامين A والكالسيوم والحديد والفولات، وهو الشكل الطبيعي لحمض الفوليك. وبفضل غناها بالألياف، يسهل تفكيك البطاطا من دون إرهاق الجهاز الهضمي لطفلكِ، كما يحولها الجسم سريعًا إلى طاقة. وتساعد أيضًا على تقوية جهازه المناعي بفضل مضادات الأكسدة التي تحتوي عليها. وإلى جانب هذه الفيتامينات والمعادن جميعها، تساعد البطاطا الغنية بالبيتا كاروتين على حماية طفلكِ من أمراض مختلفة. وبفضل محتواها المرتفع من السعرات الحرارية، يمكنها دعم زيادة وزن طفلكِ بطريقة صحية، خصوصًا إذا كان يواجه صعوبة في اكتساب الوزن. ويُعدّ طهو البطاطا الحلوة على البخار أفضل طريقة لتحضيرها لطفلكِ، إذ يساعد ذلك على الاحتفاظ بأكبر قدر ممكن من الفيتامينات والمعادن الموجودة فيها.') WHERE id = '7906e1c0-3862-429f-8a6c-67791d53795e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدأ عناد طفلكِ بالظهور بوضوح شديد اعتبارًا من هذا الشهر. ويرجع ذلك أساسًا إلى أنه بدأ يتحكم في إرادته. كما أن قدرته على التعبير عن رغباته وأفكاره بفضل تطور مهاراته اللغوية قد تدفعه إلى معاندتكِ في كثير من الأمور. وقد يتحول العناد إلى موقف يصعب التعامل معه بالنسبة إلى كثير من الأمهات. لذلك، ينبغي لكِ أولًا أن تحافظي قدر الإمكان على هدوئكِ وحزمكِ ورباطة جأشكِ. فمقابلة تصرفات طفلكِ العنيدة بالعناد ليست حلًا، بل قد تجعله أكثر حدة وعرضة لنوبات الغضب. ومع ذلك، ليس من الصواب أيضًا منحه السيطرة الكاملة. فعلى سبيل المثال، إذا أصر طفلكِ على رفض الطعام، يمكنكِ بدلًا من سؤاله: هل ستأكل؟ أو هل ستتناول طعامك؟ أن تسأليه: أيٌّ من الأطعمة التي وضعتها أمامك ستنهيه؟ حينها سيدرك طفلكِ أن زمام الأمور بيدكِ، لكن لديه أيضًا خياراته الخاصة ضمن الحدود التي وضعتِها.') WHERE id = '5b073dd7-301e-41fc-a4c7-a27f4387f1d3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي لكِ قدر الإمكان تجنب استخدام سكين معدني عند تقطيع الفاكهة التي تحضرينها لطفلكِ. ويرجع ذلك أساسًا إلى أن الفيتامينات الموجودة في الفاكهة تفقد جزءًا كبيرًا من فعاليتها عند ملامسة المعدن. ورغم أن تقطيع الفاكهة بسكين من الخيزران أو البلاستيك لا يمنع تلفها تمامًا، فإنه يؤخر فقدان الفيتامينات لبعض الوقت. إضافة إلى ذلك، تفقد الفاكهة بعض الفيتامينات والمعادن عند تعرضها للأكسجين، وذلك لأن الفيتامينات لا تتحمل الأكسجين. وتبدأ بعض الفواكه، خصوصًا التفاح والكمثرى والسفرجل، في الاسمرار بعد مدة من تقطيعها بسبب تعرضها للأكسجين. وتُسمى هذه الحالة الأكسدة، وهي تنتج عن تفاعل الإنزيمات الموجودة في الفاكهة مع الأكسجين. وفي أثناء الأكسدة، تبدأ الأجزاء المقطوعة من الفاكهة بالتأكسد ويتحول لونها إلى البني. ويمكنكِ تأخير الأكسدة بوضع الفاكهة التي قطعتِها في الماء في أثناء التحضير، لأن ذلك يحد من تعرضها للأكسجين.') WHERE id = '6947348f-e44b-494e-9348-b828857829f0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن قادرًا على أداء حركات مثل القفز بنشاط، إلى جانب المشي والركض بثقة. وقد يفقد توازنه ويترنح في محاولاته الأولى للقفز، لكنه سيتعلم خلال وقت قصير الحفاظ على توازنه. ويستخدم طفلكِ في أثناء القفز جزءًا من الدماغ يُسمى المخيخ. ويقع هذا الجزء في المنطقة الخلفية السفلية من الدماغ، ولذلك يُسمى أيضًا الدماغ الخلفي. وتنقل أعصاب المخيخ الإشارات التي تتلقاها إلى العضلات التي تساعد طفلكِ على الحفاظ على توازنه في أثناء القفز. وإلى جانب مسؤولية المخيخ عن حفاظ طفلكِ على توازنه وتنفيذ المهارات الحركية الكبرى، فإنه مسؤول أيضًا عن الانتباه والتركيز. ومن هذا المنطلق، يمكن اعتبار قدرة طفلكِ على القفز مؤشرًا على نجاحه في تركيز انتباهه أيضًا. ويعود تطور الوظائف الذهنية ومهارة القفز بصورة متوازية إلى أن كلا النوعين من المهارات يتحكم فيهما المركز نفسه.') WHERE id = 'd993b593-9436-4f3b-85f9-b80333c24034';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يعاني طفلكِ عمومًا من ضعف الشهية خلال هذه المرحلة. ويمكن أن تنخفض شهيته أكثر، خصوصًا في فصل الصيف وعند الإصابة بالأمراض. ويُعدّ انخفاض الشهية أمرًا طبيعيًا، لأن تناول المزيد من الأغذية السائلة وشرب كميات وفيرة من الماء والميل إلى المشروبات الباردة بسبب الطقس الحار يسبب شعورًا دائمًا بالشبع في معدة طفلكِ. وإذا لاحظتِ أن طفلكِ يعاني من ضعف الشهية، فعليكِ قبل محاولة زيادتها التحقق مما إذا كانت المشكلة ناجمة عن مرض ما. إذ قد تسبب حالات صحية عديدة ضعف الشهية. فعلى سبيل المثال، قد يؤدي عدم ظهور الأضراس بعد إلى رفض الطعام. كما يمكن أن تؤدي الأمراض المصحوبة بالحمى وفقر الدم والطفيليات المعوية والإمساك والتهاب المسالك البولية إلى تناول طفلكِ كميات قليلة من الطعام. كذلك، قد يؤدي إصراركِ المفرط على إطعامه خوفًا من عدم حصوله على تغذية كافية إلى تفاقم الوضع. وإذا كنتِ تستخدمين نظام المكافأة أو العقاب مقابل تناول الطعام، فقد يدفع ذلك طفلكِ إلى العناد بشأن الأكل.') WHERE id = '39b05855-5c29-415a-9d4e-b6d9c28b1572';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُصاب طفلكِ بنزلات البرد بسهولة، لا سيما عند تغيّر الفصول وخلال أشهر الشتاء. ونزلة البرد مشكلة قد يسببها نحو ٢٠٠ فيروس مختلف، وتظهر بأعراض تختلف من طفل إلى آخر. ويُعد إصابة الطفل السليم بنزلة برد بمعدل ٥-٦ مرات سنويًا أمرًا طبيعيًا. وعادةً ما تزول نزلة البرد تمامًا خلال أسبوع واحد، لكنها قد تستمر حتى ٣ أسابيع. ولا يوجد علاج محدد لنزلة البرد التي تظهر بأعراض مثل احتقان الأنف والعطاس والسعال والبلغم. ويرجع ذلك إلى اكتساب الفيروسات المسببة لنزلات البرد مقاومةً للعديد من الأدوية المتاحة. ولمساعدة طفلكِ على التغلب على نزلة البرد بفضل مناعة جسمه، عليكِ تهوية الغرفة التي يوجد فيها بانتظام، وتنظيف أنفه دوريًا، والتأكد من حصوله على كمية وفيرة من السوائل.') WHERE id = '30d86d17-88ba-44a4-83aa-4077d27f7fa2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد عصائر الفاكهة مصدرًا مهمًا جدًا لفيتامين C لطفلكِ. كما أنها من الأطعمة التي يحبها الأطفال كثيرًا ولا يرفضونها بسهولة. فعلى سبيل المثال، عصير الخوخ غني بالبيتا كاروتين، ويساعد على تقوية جهاز طفلكِ الدفاعي ضد الأمراض، أي جهازه المناعي. ويمكن أن يلبّي كوب واحد من عصير المشمش ما يقارب نصف احتياج طفلكِ اليومي من فيتامين A. ويُعد عصير التفاح مصدرًا قويًا لمضادات الأكسدة، وقد أثبتت الأبحاث أن التفاح يساعد على الوقاية من تلف الخلايا. أما عصير الرمان، فهو من مضادات الأكسدة القوية جدًا لطفلكِ بفضل احتوائه على الكالسيوم والبوتاسيوم ومكونات أخرى. ويساعد عصير البرتقال الغني بفيتامين C على دعم جهاز طفلكِ المناعي وحمايته من العدوى. لكن عليكِ ألا تنسي أن الإفراط في تناول عصائر الفاكهة قد يسبب تسوس الأسنان بسبب محتواها من السكر.') WHERE id = 'f63fb22f-332c-41cc-bd05-f7461cef0189';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح قِصر النظر، وهو مشكلة عدم القدرة على رؤية الأشياء البعيدة بوضوح، شائعًا جدًا بين الأطفال، لا سيما في السنوات الأخيرة. وقِصر النظر حالة تسبب صعوبة رؤية الأشياء البعيدة أو تشوش الرؤية، وقد تتفاقم بسهولة إذا لم تُشخَّص مبكرًا ولم تُعالج. ويحدث قِصر النظر عندما يكون المحور الأمامي الخلفي لمقلة العين أطول من الطبيعي. ووفقًا لأحدث الأبحاث، تبيّن أن هذا الاختلاف قد يرتبط أيضًا بنقص التعرض لأشعة الشمس. كما أن قضاء الأطفال وقتًا طويلًا أمام الأجهزة التقنية، مثل التلفاز والهاتف والجهاز اللوحي، من العوامل التي تزيد معدل الإصابة بقِصر النظر. ومن المهم أن تصطحبي طفلكِ لفحص عينيه كل ٦ أشهر على الأكثر، من أجل الكشف المبكر عن أي عيب بصري والحد من تفاقمه. وإذا أُهمل قِصر النظر، فقد يؤدي إلى معاناة طفلكِ من مشكلات بصرية أكثر خطورة خلال سنوات الدراسة.') WHERE id = '8b3f6818-28e3-4c63-890f-86f37d302ed7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد تناول الفواكه والخضراوات الحمراء والبنفسجية مهمًا جدًا لحصول طفلكِ على مختلف الفيتامينات والمعادن ومضادات الأكسدة. وتُعد أطعمة مثل التوت الأزرق، والعُلّيق الأسود، وتوت العُلّيق، والكشمش الأسود، والفراولة، والبطيخ، والطماطم، والفلفل ضرورية للحفاظ على صحة جسم طفلكِ واستمرار نموه وتطوره. وبفضل محتواها المرتفع من مضادات الأكسدة، تساعد الأطعمة الحمراء والبنفسجية على حماية طفلكِ من تكاثر الخلايا السرطانية. وتشير الدراسات إلى أن مضادات الأكسدة الموجودة في الفواكه الحمراء فعالة خصوصًا ضد سرطان القولون. كما تساعد الفواكه والخضراوات بهذه الألوان على موازنة مستويات الكوليسترول وتقليل خطر الإصابة بأمراض القلب والأوعية الدموية، مثل ارتفاع ضغط الدم والنوبة القلبية واضطراب نظم القلب. إضافةً إلى ذلك، تحتوي الفواكه الحمراء والبنفسجية على سعرات حرارية أقل من غيرها من الفواكه. ولأن الماء يشكّل أكثر من نصف محتواها، فقد تكون هذه الفواكه خيارًا صحيًا كوجبة خفيفة، لا سيما للأطفال الذين يعانون من مشكلات في الوزن.') WHERE id = 'b211c72f-eb05-4bbd-bed8-55956213cfa9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أول ما عليكِ الانتباه إليه عند اختيار أدوات المطبخ التي ستستخدمينها لإعداد طعام طفلكِ هو اختيار منتجات آمنة وصحية. وينبغي أن تكون المنتجات المصنوعة من الزجاج والفولاذ والبلاستيك الخالي من مادة BPA من خياراتكِ الأساسية لطفلكِ. كما أن المنتجات المصنوعة من مواد غير مناسبة للغسل في غسالة الصحون تكون عمومًا ضارة بالصحة. ويجب أن تكون الأدوات التي تستخدمينها لتحريك طعام طفلكِ أثناء الطهي مقاومة للحرارة. ونظرًا إلى أن البلاستيك والمواد المشابهة قد تطلق مواد ضارة في الطعام بفعل الحرارة، فعليكِ استخدام أدوات الفولاذ المقاوم للصدأ بدرجة أكبر. وإذا كانت المقالي والقدور التي تستخدمينها في الطهي مطلية، فاحرصي على عدم خدشها. فقد يتجمع الماء داخل الشقوق الناتجة عن خدش الطلاء، ما قد يؤدي إلى نمو البكتيريا وانتقال مواد ضارة إلى الطعام. أما طبق طفلكِ، فيجب أن يكون متينًا بما يكفي لئلا ينكسر إذا ألقاه على الأرض أو ضربه بالطاولة.') WHERE id = '21cf7dfe-5ee8-4bdf-adb1-a494b5e0b192';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يقيس طبيبكِ طول طفلكِ ووزنه خلال الفحوصات الدورية، ثم يقارن النتائج بمتوسط المؤشرات لدى الأطفال في عمره لتحليل نموه. وإذا كان نمو طفلكِ أعلى من المعدل الطبيعي، أو كانت زيادة وزنه بين فحصين أكبر من المتوقع، فقد يعني ذلك وجود مشكلة في الوزن. وعادةً ما يميل الأطفال الذين يزيد وزنهم على وزن أقرانهم إلى تراكم الدهون في منطقة البطن والفخذين والوجه. وإذا كان طفلكِ في مرحلة النمو يعاني من زيادة الوزن، فهذا لا يعني أن تقللي كمية الطعام التي تقدمينها له. فقد تؤثر هذه الطريقة سلبًا في نموه وتخلّ بتوازنه الهرموني. ومن المهم مراجعة نظامه الغذائي وتفضيل الخضراوات والفواكه على الأطعمة السكرية والدهنية. كما أن الألعاب التي تساعد طفلكِ على أن يكون أكثر نشاطًا، إلى جانب التنزه في الهواء الطلق خلال اليوم، ستساعد على الحد من مشكلة الوزن خلال فترة قصيرة.') WHERE id = '82494ee8-a29f-47cd-888b-4c024afa1a5c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ يسقط كثيرًا عندما يمشي بسرعة أو يركض. وعادةً ما يثير ذلك قلق الوالدين. في الواقع، يعود سبب سقوط طفلكِ المتكرر إلى أنه ينظر إلى ما حوله أكثر مما ينظر إلى موضع قدميه أثناء المشي. فعندما لا يركّز على خطواته أو على الأرض، قد لا ينتبه دائمًا إلى المكان الذي يتجه إليه. كما تشكّل العوائق التي تعترض طريق طفلكِ خطرًا لسقوطه، لأنه لا يستطيع استخدام مهارات التوازن والتنسيق بفاعلية مماثلة للبالغين. وغالبًا ما يصعب منع هذه الحالة التي تُعد طبيعية ضمن مراحل النمو. ومع ذلك، من المهم أن تتخذي بعض تدابير السلامة. فمثلًا، يمكنكِ الحرص على أن يمشي طفلكِ في أماكن مغطاة بالسجاد غالبًا بدلًا من الأسطح الصلبة والزلقة. كما يمكنكِ تغطية زوايا الأثاث الحادة بوسائل حماية وتثبيت الأشياء التي يستند إليها في الجدار.') WHERE id = '2a1076da-9d2a-4614-8f87-b9105c907fbb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ هو الأول وكنتِ تخططين لإنجاب طفل ثانٍ، فهناك نقاط مهمة ينبغي أن تعرفيها مسبقًا. أولًا، يصعب جدًا على طفلكِ، الذي يمر بمرحلة التمركز حول الذات، أن يأتي شخص آخر ليشاركه الاهتمام. فعندما يأتي مولود جديد إلى المنزل، يحاول الأطفال عادةً تقليده قدر الإمكان. وقد يرفض طفلكِ، الذي كان يركض ويتنقل كل يوم، المشي فجأة ويرغب في أن تحمليه باستمرار. وقد يرغب أيضًا في ارتداء الملابس التي اشتريتها للمولود الجديد واستخدام أغراضه كما لو كانت تخصه. وإذا كنتِ قد بدأتِ تدريبه على استخدام المرحاض، فقد يرفض التدريب ويتبول أو يتبرز في ملابسه ويطلب العودة إلى ارتداء الحفاض. تنبع هذه التصرفات كلها من رغبة طفلكِ في استعادة الاهتمام الموجّه إليه. وفي الواقع، لا يقصد الإساءة، بل إنه لا يفهم بعد بصورة كاملة معنى وجود أخ أو أخت.') WHERE id = 'd3098156-f9a6-445a-8b64-a1ca3ee248d8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أبرز الأمراض التي قد تصيب الأطفال نتيجة ملامسة المياه الملوثة هي الكوليرا والزحار الأميبي والزحار العصوي وحمى التيفوئيد. يشيع الزحار العصوي في المناخات الحارة، ولا سيما خلال أشهر الصيف، ويصيب أساسًا الأطفال الذين تتراوح أعمارهم بين 1-4 سنوات. وينتقل هذا المرض، الذي تسببه كائنات دقيقة تُسمى الشيغيلا، عن طريق المياه الملوثة والمصابين والذباب. أما الزحار الأميبي، فينتشر أكثر في الأماكن التي لا تُراعى فيها قواعد النظافة وتفتقر إلى مياه الشرب النظيفة. وقد تصيب الكوليرا الأطفال نتيجة تناول منتجات زراعية رُويت بمياه غير نظيفة. أما حمى التيفوئيد، فهي مرض خطير ينجم عن المياه الملوثة بالفضلات البشرية واستخدام هذه المياه في الزراعة. ويمكن أن تسبب جميع هذه الأمراض المنقولة عبر المياه الملوثة لطفلكِ الإسهال والحمى وآلام المعدة والفقدان الشديد للماء والشوارد. لذلك، إذا كنتِ تعتقدين أن طفلكِ قد لامس مياهًا يُشتبه في تلوثها، فاستشيري طبيبكِ فورًا.') WHERE id = '2939358c-07a1-4bb3-8bed-d3d00dfe6abc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الأطفال أكثر حساسية من البالغين للآثار الضارة لأشعة الشمس. لذلك، ينبغي أن تحمي طفلكِ من الشمس في جميع فصول السنة. وقد يُصاب طفلكِ بحروق الشمس والطفح الجلدي، خصوصًا خلال أشهر الصيف، إذا لم تُتخذ الاحتياطات اللازمة. ومن المعروف أيضًا أن استخدام الكريمات الواقية من الشمس منذ سن مبكرة يقلل آثار الشمس الضارة مستقبلًا. وينبغي أن يكون الكريم الواقي من الشمس الذي تستخدمينه لطفلكِ منتجًا مخصصًا ومصنّعًا بما يراعي حساسية بشرته. وتُعد واقيات الشمس ذات المرشحات الفيزيائية من أكثر الأنواع فاعلية التي يمكنكِ اختيارها لطفلكِ. ويحتاج الكريم إلى نحو 30 دقيقة كي تمتصه البشرة تمامًا ويوفر الحماية. لذلك، ينبغي أن تضعي الكريم الواقي من الشمس قبل الخروج بنصف ساعة على الأقل.') WHERE id = 'efce01a9-ede6-4b7c-ba9c-059f7e1fa4ae';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يحب طفلكِ الاتساخ وتلطيخ ما حوله، بل قد يستمتع بذلك كثيرًا. لكن مع اقترابه من عمر السنتين، حان الوقت لتعليمه عادات النظافة الصحيحة. وستقلل عادات النظافة السليمة أولًا من خطر إصابة طفلكِ بالأمراض. كما أن اعتياده غسل يديه بعد استخدام المرحاض وقبل تناول الطعام وعند العودة إلى المنزل من الخارج سيحسن جودة حياته طوال عمره. وفي هذه المرحلة، أصبح طفلكِ قادرًا أيضًا على الشعور قبل قليل بأنه على وشك العطس أو السعال. لذلك، ينبغي أن تعلّميه كيفية اتباع قواعد النظافة بعد العطس. وبالطبع، فإن الطريقة الأكثر فاعلية لتعليمه ذلك هي أن تكوني قدوة له. فطفلكِ، الذي يتعلم عن طريق التقليد، سيتبنى بسهولة هذا السلوك الذي يراكِ تقومين به.') WHERE id = 'c6f0d795-8d9b-48f9-a845-2a90ac3ad87e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ تستخدمين غالبًا منتجات مصنوعة من القطن عند تنظيف منطقة حفاض طفلكِ، وفي مفارش سريره وحفاضاته وملابسه، وأنكِ تحرصين على اختيارها. ولكن هناك أمر ينبغي أن تعرفيه: يُستخدم سنويًا نحو 40 طنًا من المواد الكيميائية في إنتاج القطن. وتشير هذه الكمية إلى أن 25% من المبيدات الحشرية المستخدمة سنويًا في الزراعة حول العالم تُستخدم تحديدًا في زراعة القطن. وإضافة إلى ذلك، تتضمن بعض المواد الكيميائية المستخدمة مواد معروفة بتسببها في السرطان، مثل الأمونيا والفثالات والبارافين والفورمالديهايد والمعادن الثقيلة. لذلك، ينبغي أن تختاري لطفلكِ القطن العضوي والمنتجات المصنوعة منه بدلًا من القطن المُنتج بالطرق الصناعية. فالقطن العضوي أنظف وأكثر استدامة من القطن الصناعي. كما لا تُستخدم في إنتاجه بذور تحتوي على كائنات معدلة وراثيًا. وعند زراعة القطن العضوي، تُفضّل الحقول التي لا تُستخدم فيها المبيدات الزراعية الاصطناعية ولا حتى الأسمدة. وهذا هو الخيار الأكثر صحة لطفلكِ.') WHERE id = '86b8a2a1-5cc2-43a1-a0d3-0f8c36702077';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم، لا سيما خلال أشهر الصيف، أن يستفيد طفلكِ من أشعة الشمس بطريقة فعّالة وصحيحة. فالشمس مصدر جيد لفيتامين D، الذي يؤدي دورًا مهمًا في نمو أسنان طفلكِ وعظامه. ويكفي التعرض للشمس لمدة نصف ساعة يوميًا في المتوسط لمساعدة جسم طفلكِ على تصنيع حاجته من فيتامين D. ومع ذلك، قد يؤدي التعرض لأشعة الشمس فترات طويلة إلى عواقب سلبية خطيرة على طفلكِ. فرغم أن وظيفة التعرق لديه تكون نشطة في هذه المرحلة، فإن جسمه لا يزال أقل قدرة على التحمل من جسم الشخص البالغ. لذلك قد لا يتمكن جسم طفلكِ من الحفاظ على توازنه الداخلي بالكامل عن طريق التعرق عند تعرضه لأشعة الشمس القوية مدة طويلة. احرصي على أن يرتدي طفلكِ قبعة ونظارات شمسية أثناء التعرض للشمس، فهذه وسيلة جيدة لحمايته من آثارها الضارة. واحرصي أيضًا على استخدام مستحضرات واقية من الشمس تحتوي على الزنك ومصممة خصيصًا للأطفال.') WHERE id = 'a261dbd0-eed1-46cd-8f75-71d0a2300d15';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عادةً ما يكون سعال طفلكِ عارضًا يزول خلال فترة قصيرة. لكن استمرار السعال مدة طويلة أو ازدياد شدته قد يكون علامة على السعال الديكي. والسعال الديكي مرض حاد ومعدٍ يصيب الجهاز التنفسي، وقد يكون شديدًا، خصوصًا لدى الأطفال دون سن الخامسة. ينتشر هذا المرض في جميع أنحاء العالم، وتسببه بكتيريا تُسمى Bordetella pertussis. ويؤدي السعال الديكي إلى نوبات سعال طويلة، وينتقل عبر الرذاذ المتطاير في الهواء عند سعال الشخص المصاب. والتطعيم هو أفضل وسيلة للوقاية منه. كما يجب إبعاد الرضع وغيرهم من الأشخاص الأكثر عرضة لمضاعفات السعال الديكي عن الشخص المصاب. ووفقًا لجدول التطعيمات المعتمد من وزارة الصحة، يُعطى لقاح السعال الديكي ضمن اللقاح الخماسي المركب في الشهر الثاني والرابع والثاني عشر. وتُعطى الجرعة الأخيرة ضمن اللقاح الرباعي المركب في الصف الأول من المرحلة الابتدائية، ليُعطى اللقاح ٥ مرات إجمالًا.') WHERE id = '401eecb4-6ff0-4a6b-b5b2-6f546861d6f5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشير الدراسات إلى أن نمو الدماغ واللغة لدى الأطفال الذين يستمعون إلى الموسيقى بانتظام يكون أسرع مقارنةً بغيرهم. لذلك، فإن غناء الأغاني والتهويدات لطفلكِ يتيح لكِ قضاء وقت ممتع ومفيد معه، ويساعد أيضًا على تنمية حصيلته اللغوية وقدراته على الكلام بسرعة أكبر. وقد يُظهر طفلكِ، إذا استمع إلى الموسيقى كثيرًا خلال هذه المرحلة، اهتمامًا أكبر بالآلات الموسيقية مستقبلًا. كما سيبدأ في ابتكار الألحان والدندنة بنفسه، ما يسهم في تطوير مهاراته اللفظية وإحساسه بالإيقاع. ويمكن أن تساعد الموسيقى طفلكِ أيضًا على النوم. فإذا كان طفلكِ يجد صعوبة في النوم، فقد تساعد الألحان الهادئة والبطيئة على تهدئته كثيرًا. لكن احرصي خلال هذه المرحلة على تجنب الأغاني السريعة أو تشغيل الموسيقى بصوت مرتفع، لأن ذلك قد يضر بحاسة السمع وأعضاء السمع لدى طفلكِ.') WHERE id = 'f49ca159-fcc5-4fc3-970d-e7b1bcdc0f16';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن يتناول طفلكِ بانتظام كميات كافية من جميع المجموعات الغذائية، مثل الحليب ومنتجات الألبان، واللحوم، والبيض، والبقوليات، والحبوب، والخضروات، والفواكه. واحرصي على إدراج كل مجموعة غذائية في نظامه الغذائي بكميات كافية ومتوازنة؛ فكون الطعام صحيًا لا يعني أنه ينبغي إطعام طفلكِ كميات أكبر منه. والتغذية الصحية عادة تُكتسب منذ الصغر، لذا فإن تنظيم نمط تغذية طفلكِ في هذه المرحلة سيساعده على أن يصبح شخصًا أكثر صحة في المستقبل. وإذا عوّدتِ طفلكِ على تناول الوجبات الرئيسية والخفيفة خلال اليوم، فسيواصل هذه العادة عندما يكبر. وتساعد الوجبات الخفيفة على منع تناول كميات تفوق الحاجة أثناء الوجبات الرئيسية، ما يقلل خطر الإصابة بالعديد من الأمراض، وفي مقدمتها السمنة. إضافةً إلى ذلك، كلما تأخرتِ في تعريف طفلكِ بالسكر كان ذلك أفضل؛ إذ لا توجد فائدة معروفة للسكريات البسيطة على صحة الإنسان.') WHERE id = '2651d066-b743-4662-b034-75fe5243d7e0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد القيء والارتجاع من الحالات الفسيولوجية الشائعة لدى الأطفال حديثي الولادة. وعادةً ما تبدأ هذه المشكلة بالتراجع مع الانتقال إلى الأطعمة الصلبة، لكنها قد تستمر مدة أطول لدى بعض الأطفال. إذا لاحظتِ أن طفلكِ يتقيأ خلال هذه المرحلة أو شخّص الطبيب إصابته بالارتجاع، فقد يفيد اتخاذ بعض الاحتياطات. أولًا، احرصي على إبقاء طفلكِ في وضع شبه قائم قدر الإمكان أثناء إطعامه. وقد يكون تقديم كميات أقل من الطعام على فترات أكثر تقاربًا فعّالًا أيضًا. كما أن تجنب القفز أو التدحرج واللعب النشط مباشرةً بعد تناول الطعام قد يساعد على منع ارتجاع محتويات المعدة. وقد يؤدي إحكام الحفاض أكثر من اللازم إلى زيادة الضغط على بطن طفلكِ، ما قد يسبب الغازات والارتجاع. وللنوم الآمن، ضعي طفلكِ دائمًا على ظهره فوق سطح مستوٍ وثابت، ولا ترفعي رأس السرير أو تستخدمي وسائد الارتجاع إلا إذا أوصى الطبيب بذلك.') WHERE id = 'cfd2fffc-165b-4343-a449-c5ce0daed80c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يقل تنويع الأطعمة التي تقدمينها لطفلكِ أهميةً عن توفير تغذية متوازنة ومنتظمة له. فألوان الفواكه والخضروات هي في الواقع جزء من آلية دفاع طورتها النباتات لحماية نفسها من الأشعة فوق البنفسجية والإشعاع. ولهذا تتميز كل فاكهة وخضار بلون ورائحة ومذاق مختلف. فمثلًا، تحتوي الفواكه والخضروات الخضراء على كميات كبيرة من المركبات الكيميائية النباتية، التي تدعم آليات الجسم الطبيعية في التعامل مع المواد الضارة. كما أن الأطعمة الخضراء غنية بفيتامين K، المهم لتخثر الدم وصحة العظام. وتساعد الفواكه والخضروات الصفراء، بفضل غناها بفيتامين C، في الحفاظ على صحة بشرة طفلكِ. أما الأطعمة البرتقالية فتدعم جهازه المناعي بفضل محتواها الغني بالبيتا كاروتين، وتساعد على حمايته من العدوى والأمراض المختلفة.') WHERE id = '57ff12a3-c056-48ff-9445-c6afc0710bb9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُصاب الأطفال قبل سن المدرسة بالعديد من الأمراض، وأكثرها شيوعًا أمراض الجهاز التنفسي العلوي. وقد يُصاب طفلكِ بعدوى الجهاز التنفسي العلوي حتى 9 مرات خلال العام. وتُعد الفيروسات السبب الرئيسي لهذه العدوى. إذا كانت هذه الأمراض مصحوبة غالبًا بارتفاع شديد في درجة الحرارة، وكانت الحمى تتكرر على فترات محددة، فقد يُشتبه في الإصابة بمتلازمة الحمى الدورية. تظهر هذه المتلازمة عادة لدى الأطفال الذين تتراوح أعمارهم بين 2-5 سنوات. وفي هذه الحالات، قد تتجاوز درجة الحرارة 40 درجة، مع تورم في منطقة الرقبة وظهور تقرحات داخل الفم تُسمى القلاع والتهاب البلعوم. تبدأ الحمى فجأة وتتراوح بين 39-41 درجة. وعادة ما تستمر من 3-6 أيام ولا تتجاوز أسبوعًا واحدًا. وقد تتكرر هذه النوبات مرة واحدة تقريبًا كل شهر. تُستخدم الأدوية المحتوية على الستيرويدات في العلاج. ورغم أن الستيرويدات لا تمنع النوبات التالية، فإن استئصال اللوزتين جراحيًا قد يمنع هذه المتلازمة تمامًا في بعض الحالات.') WHERE id = 'eca0a9e7-b59d-4519-bf64-570cbfe10ed1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن الكينوا تُعرف على أنها من الحبوب، فإنها في الحقيقة بذور، وهي غذاء رائع يمكنكِ إضافته إلى قائمة طعام طفلكِ. تنحدر الكينوا من أمريكا الجنوبية، وهي أغنى بالعناصر الغذائية والبروتين مقارنة بالأرز والبرغل. وبفضل احتوائها على كميات وفيرة من الكالسيوم والحديد والفولات، تُعد في جميع أنحاء العالم أحد أفضل البدائل للأرز والقمح في أغذية الأطفال. كما تحتوي الكينوا على جميع الأحماض الأمينية الأساسية التسعة المهمة لجسم طفلكِ. وبفضل غناها بالألياف، يسهل هضمها، وتُستخدم كثيرًا لتسهيل التبرز عند الإصابة بالإمساك. يمكنكِ استخدام الكينوا لزيادة كثافة وجبات طفلكِ ورفع قيمتها الغذائية. ويساعد نقعها لبعض الوقت في ماء فاتر قبل طهيها على التخلص من مذاقها المر المميز. بالهناء والشفاء! 😊') WHERE id = 'b325d022-da2a-4ff6-9978-1ed8bee88324';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد وصلتما الآن إلى مرحلة يغادر فيها طفلكِ فترة الرضاعة ويدخل مرحلة الطفولة. في الشهر 23، يظل وزن طفلكِ ثابتًا تقريبًا، لكن طوله يستمر في الازدياد. وأكثر ما يميز هذه الفترة هو بدء تشكل شخصيته المستقلة وميوله العاطفية. فهو يعرف الآن بوضوح ما لا يحبه وما يستمتع به، ويحرص على إظهار ذلك لكِ. ومع اكتشاف طفلكِ لقدراته، يبدأ في الميل إلى الاستقلال. وهذا الشعور بالاستقلال مهم جدًا لثقته بنفسه ونموه. لذلك، بدلًا من تقييده باستمرار، ينبغي تشجيعه على خوض تجارب واكتشافات جديدة. إن تقبُّل حقيقة أن طفلكِ أصبح فردًا مستقلًا والتعامل معه على هذا الأساس سيساعدانه على أن ينشأ مستقبلًا بشخصية أكثر ثقة بنفسها.') WHERE id = '9f9032ef-0837-4725-940d-1bfe4dd93438';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كما هو الحال في جميع أنحاء العالم، يوصي المتخصصون في بلدنا أيضًا بأن يقتصر غذاء الأطفال خلال أول 6 أشهر على حليب الأم، وأن تستمر الرضاعة الطبيعية حتى عمر 24 شهرًا في المتوسط. لكن لا توجد إجابة واحدة صحيحة حول موعد إيقاف الرضاعة الطبيعية؛ فقد تكون هذه المدة أقل من عامين أو أطول منهما. ومن المهم أن تكوني أنتِ وطفلكِ مستعدين لفطامه. فهذا أحد أهم القرارات خلال مراحل نمو طفلكِ. وقد تشعر كثير من الأمهات ببعض الحزن أو التوتر، خصوصًا عند اتخاذ قرار الفطام. ولأنها مرحلة شديدة الحساسية، فقد يكون التخطيط لها مسبقًا مفيدًا. وسيسهّل عليكِ الإكثار من التواصل الجسدي مع طفلكِ، وزيادة الوقت الذي تقضيانه معًا، ومحاولة شرح هذه العملية له بلغة يستطيع فهمها.') WHERE id = '3f0a45ad-f763-4336-92e9-52283443a724';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مرحلة تحديات عمر السنتين هي فترة قد تبدأ في سن 1.5 سنة تقريبًا وتستمر حتى سن 3.5 سنوات. وتُعد هذه الفترة، التي يراها كثير من الآباء والأمهات أصعب مراحل تربية الطفل، مرحلة انتقالية من الرضاعة إلى الطفولة. وعلى الرغم من أن العلامات قد تظهر بدءًا من الشهر 18، فإنها تبلغ ذروتها في سن السنتين تقريبًا. إن العناد والاعتراض على كل شيء لدى طفلكِ خلال هذه الفترة ليسا تصرفين متعمدين في الحقيقة. فهو يشعر بأنه كبر ويحاول إثبات أنه شخص مستقل لا يعتمد عليكِ. وإذا لم تمنحيه خلال هذه الفترة فرصة لإثبات ذاته، فقد تواجهين نوبات من البكاء والغضب، وضرب رأسه بالحائط، وشد شعره، ورمي الأشياء، ورفض الطعام والنوم. وتظهر هذه السلوكيات خصوصًا عندما يشعر طفلكِ بأنه غير مفهوم. تذكّري أنه يمر بمرحلة طبيعية من النمو ويحتاج إلى دعمكِ.') WHERE id = '8f1b03fc-aab4-4c14-82c8-07a348b01b4a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد العدد الإجمالي للخلايا الدهنية التي تتكون في جسم طفلكِ من أهم العوامل التي تحدد صحته في المستقبل. وتختلف آلية اكتساب الوزن لدى الأطفال عنها لدى البالغين. فعندما يحصل البالغون على طاقة زائدة، تتمدد الخلايا الدهنية الموجودة لديهم. أما لدى الأطفال، فكلما زادت الطاقة التي لا يستهلكها الجسم، ازداد العدد الإجمالي للخلايا الدهنية. وتبقى هذه الخلايا في الجسم مدى الحياة، باستثناء حالات نادرة، مما يمهّد مستقبلًا لزيادة الوزن والأمراض المرتبطة بها. وتشير الدراسات إلى أن معظم الأشخاص المصابين بالسمنة كانت لديهم عادات غذائية غير سليمة منذ سن مبكرة. لذلك، عليكِ الابتعاد عن فكرة «الطفل الممتلئ هو طفل سليم»، ووضع نظام غذائي متوازن وكافٍ لطفلكِ.') WHERE id = '1a13218f-56a9-4fd9-9d16-4afe6930ed48';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة التي يمر فيها طفلكِ بأعراض مرحلة السنتين بصورة مكثفة، عليكِ أن تكوني متفهمة وصبورة معه. إذا أصرّ على أمر غير منطقي، فبدلًا من قول "لا" وإنهاء النقاش، اتبعي نهجًا أكثر منطقية، مثل: "لهذا السبب لا يمكننا فعل ما تريده الآن، تعالَ لنفكر فيما يمكننا فعله بدلًا من ذلك". باختصار، عليكِ التعبير عن نفسكِ وإتاحة الفرصة له أيضًا للتعبير عن نفسه. إن السلوكيات العدوانية التي يُظهرها طفلكِ هي في الواقع مؤشر على عدم قدرته على التعبير عن نفسه. وقد يؤدي رد فعلكِ الذي يتضمن اللوم في مثل هذه الحالة إلى تفاقم الأمور. بل إن شعور طفلكِ بأنه غير مفهوم قد يترك جروحًا عميقة في تطور شخصيته، وقد يؤثر ذلك في حياته بأكملها. وسيكون اجتياز هذه المرحلة أسهل إذا منحتِ طفلكِ أكبر قدر ممكن من الاهتمام والحب وأكثرتِ من احتضانه. وإذا كانت سلوكيات طفلكِ شديدة للغاية وشعرتِ بأنكِ غير قادرة على التعامل معها، فيُنصح بالاستعانة باختصاصي.') WHERE id = 'ecae68e6-10b6-42ea-9ce8-5db5804efd92';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، يستخدم طفلكِ كلمة "لا" كثيرًا، مثل العديد من أقرانه. خذي نفسًا عميقًا واسترخي قليلًا. أولًا، عليكِ أن تعرفي أن هذا السلوك ناتج عن مرحلة تكوين شخصيته المستقلة ورغبته في إثبات ذاته أمامكِ. فمثلًا، ماذا يمكنكِ أن تفعلي عندما يقول طفلكِ "لا!" لطبق الخضراوات الذي أعددتِه بحب كبير؟ قد تساعدكِ جملة مثل: "كُل خضراواتك وسأعطيك الشوكولاتة بعد ذلك" على إشباعه في تلك اللحظة بسبب قلقكِ من بقائه جائعًا. لكن هذا سيجعله يربط تناول الطعام بالشروط في الوجبات اللاحقة، وربما في جميع الوجبات. أي إنكِ قد تعرضين نظامه الغذائي بالكامل للخطر من أجل إنقاذ وجبة واحدة. ينصح الاختصاصيون في هذه الحالة باحترام قرار الطفل ورفع الطعام من أمامه. فتفويت طفلكِ وجبة واحدة لن يوقف نموه على الفور. وفي موعد الوجبة التالية، يمكنكِ تجربة تقديم الخضراوات التي لا يحبها بأشكال مختلفة، مثل إضافتها إلى العجة أو أقراص اللحم.') WHERE id = 'a47c0ef8-59a6-4a41-82ce-272ba68b1ac4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُلبسين طفلكِ ملابسه بحماس كبير، ثم تفاجئين به يحمل الملابس التي ألبستِه إياها في يده! يُعد ارتداء الملابس وخلعها من الأنشطة التي تثير اهتمام طفلكِ ويستمتع بها في هذه المرحلة. وحين يفهم تحديدًا كيفية عمل السحّابات والأزرار، يتحول الأمر بالنسبة إليه إلى ما يشبه اللعبة. وقد يخلع الملابس ذات الأشرطة اللاصقة ويرتديها مرارًا لمجرد استمتاعه بالصوت الصادر عنها. لكن مهارة طفلكِ في ارتداء الملابس قد لا تكون بمستوى مهارته في خلعها، لأن ارتداء الملابس يبدو له عملية أكثر تعقيدًا. ويمكنه مساعدتكِ أثناء إلباسه من خلال رفع ذراعيه وتحريك رأسه ورفع ساقيه. لكن عليكِ أن تعرفي أنه لا يزال بحاجة إلى بعض الوقت ليتمكن من ارتداء ملابسه بمفرده، كما يخلعها بمفرده.') WHERE id = '1f1eb57e-db71-4c23-9b07-7b41a8115750';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد بدأ طفلكِ بالفعل في إرساء أسس استقلاليته، وستستمر هذه المرحلة لبعض الوقت. ولأنه يرى نفسه فردًا داخل الأسرة ويتوقع احترام قراراته، فقد يرغب أيضًا في تنظيم عاداته الغذائية بطريقته الخاصة. إن الضغط على طفلكِ ليأكل أكثر، أو محاولة إجباره على تناول طعام لا يحبه، أو اللجوء إلى أساليب المكافأة والعقاب، لن يجدي نفعًا، بل قد يزيد الوضع سوءًا. ومثلكِ تمامًا، قد تكون شهية طفلكِ أكبر في أحد الأيام، ثم لا يرغب في تناول أي شيء في اليوم التالي. وفي مثل هذه الحالة، يستحق طفلكِ أن يُحترم وألا تضغطي عليه. وعليكِ ألا تنسي أن طفلكِ لن يزداد وزنه بمقدار 600-700 غرام شهريًا كما كان الحال في الأشهر الأولى بعد ولادته. فمن عمر 2 عام في المتوسط وحتى مرحلة المراهقة، لن تتجاوز زيادة وزن طفلكِ السنوية 2000 غرام.') WHERE id = '403d2c2b-732a-4c92-81e8-0a52e24c7139';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكن اعتبار طرح طفلكِ أسئلة مثل لماذا، ولأي سبب، وكيف بشأن حدث أو موقف ما نقطة تحول في تطوره العقلي، لأن ذلك يدل على دخوله مرحلة التساؤل النشط. وتؤدي الأسئلة دورًا كبيرًا في عدم اكتفائه بما يعرفه، ورغبته في الحصول على إجابات مقنعة، وفهم الأحداث وإشباع فضوله. وبفضل ذلك، يستطيع طفلكِ الربط بين ما تعلمه، ويبدأ في الانتباه إلى أمور لم يكن يلاحظها من قبل. فمثلًا، عندما تعلّمين طفلكِ كيفية تنظيف أسنانه ويسألكِ: لماذا؟ فإن شرحكِ له سيساعده على الربط بين تنظيف الأسنان وصحتها. لذلك، بدلًا من ترك أسئلة طفلكِ بلا إجابة أو إعطائه إجابات سطحية، حاولي التواصل معه بصريًا والشرح له بكلمات يستطيع فهمها. وهكذا، سيواصل طفلكِ تطوره العقلي من خلال التعلم، كما ستتحسن مهاراته اللغوية والكلامية باكتسابه كلمات جديدة.') WHERE id = '4c355533-2fff-44de-b7a5-b39358099c69';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون لديكِ بعض الأفكار حول تدريب طفلكِ على استخدام المرحاض نهارًا. لكن هل فكرتِ في كيفية تدريبه على استخدامه ليلًا؟ دعينا نذكر نقطة ستشعركِ بالارتياح: في الواقع، الأهم هو أن يكتسب طفلكِ عادة استخدام المرحاض نهارًا. فعندما يتقن ذلك خلال النهار، سيتوقف بسهولة عن تبليل فراشه ليلًا من دون حاجة إلى أي جهد إضافي منكِ. باختصار، لا توجد مرحلة منفصلة تُسمى التدريب الليلي على استخدام المرحاض، فالعادة المكتسبة نهارًا ستنتقل تلقائيًا إلى الليل. كذلك، يجب أن تكون توقعاتكِ واقعية خلال تدريب طفلكِ على استخدام المرحاض. وباستثناء حالات نادرة، لا يستطيع أي طفل اكتساب هذه العادة بصورة كاملة خلال بضعة أيام. وإذا اتبعتِ الخطوات الصحيحة، فسيكتسب طفلكِ عادة استخدام المرحاض بسهولة خلال 2-3 أسابيع في المتوسط. لذلك، من المهم أن تتحلي بالصبر.') WHERE id = '55d12594-4a57-49fb-a454-05ab50e660cd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حليب الأم غذاء معجز لا مثيل له. إذا كنتِ قد أرضعتِ طفلكِ حتى الآن، فنهنئكِ! 😊 اقتراب طفلكِ من إتمام شهره 24 لا يعني أن عليكِ فطامه فورًا. ورغم أن قرار توقيت إنهاء الرضاعة الطبيعية يعود إليكِ، فمن الأفضل، إذا كان كل شيء على ما يرام، الاستمرار فيها حتى عمر سنتين. ويؤكد بعض المتخصصين أهمية الفطام بعد عمر سنتين، لأن استمرار الرضاعة بعد هذه المدة قد يؤخر تطور استقلالية الطفل ويؤثر في نمو شخصيته. وأهم ما ينبغي أن تنتبهي إليه هو ألا تحدث عملية الفطام بشكل مفاجئ. فقطع أهم عادات طفلكِ دفعة واحدة قد يترك آثارًا نفسية عميقة لديه.') WHERE id = 'a12dbbd5-adef-4bb7-9633-097569e91a68';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن الانتقال من مرحلة الرضاعة إلى الطفولة ليس متلازمة في حد ذاته، لكن الأساليب الخاطئة قد تجعل هذه المرحلة صعبة. ويُعد توفير الظروف المناسبة لطفلكِ كي يتحرك بحرية ويفرغ طاقته أفضل وسيلة للحد من السلوك العدواني. باختصار، بدلًا من تقييد حركته، عليكِ إتاحة الفرصة له ليكون أكثر نشاطًا. عندما يغضب طفلكِ، ساعديه على التعبير عن مشاعره بدلًا من لومه. ورغم أنه لا يزال غير قادر على تسمية مشاعره بالكامل، فانظري في عينيه وأشعريه بأنكِ تستمعين إليه بصدق. وعندما يعاند في أمور مثل الطعام أو النوم، حاولي تفهمه. انتظري حتى يهدأ قليلًا، ثم اشرحي له أسباب ضرورة القيام بذلك بلغة بسيطة يستطيع فهمها.') WHERE id = 'e3e8fd28-dc5c-46c8-ad5b-1a55f00eab80';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيؤدي نمط حياة طفلكِ والبيئة الاجتماعية التي ينتمي إليها دورًا مهمًا في نظامه الغذائي من الآن فصاعدًا. وهناك بعض الأمور التي ينبغي أن تنتبهي إليها كي يتمكن طفلكِ من مواصلة تناول طعام صحي، خاصة خلال الأوقات التي يقضيها خارج المنزل. إذا بدأ طفلكِ بالذهاب إلى مجموعة للعب أو إلى الحضانة، فيمكنكِ متابعة قوائم الطعام المقدمة هناك. وإذا لاحظتِ أطعمة لا تتناسب مع نظامه الغذائي أو ترين أنها ضارة بالأطفال، فيمكنكِ إبلاغ الإدارة برأيكِ بالتعاون مع أولياء الأمور الآخرين. ورغم أن البعض قد يقول إن تناول شيء ما لمرة واحدة لن يسبب ضررًا، ينبغي ألا تنسي أن طفلكِ قد يكتسب عادة جديدة بسهولة في هذه المرحلة. وخلال الوجبات العائلية خارج المنزل، قد يكون من الأفضل ألا تطلبي إلى مائدتكم أطعمة لا تريدين لطفلكِ تناولها. والأهم من ذلك أن تراجعي أولًا عاداتكِ الغذائية كي تكوني قدوة حسنة لطفلكِ.') WHERE id = 'b5f7b4a9-f30e-4e71-8607-76ba35a2e8c5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ قادرًا الآن على تكوين جملة من خلال جمع 4-5 كلمات يعرف معانيها ويستطيع استخدامها بفاعلية. وقد تتناول هذه الجمل الحديث عن نفسه، والمواقف التي يحبها أو لا يحبها، ورغباته وأسئلته. كما يستمع إليكِ باهتمام عندما تتحدثين، ويستطيع تكرار كلمة لم يسمعها من قبل، وبذلك يضيف كلمات جديدة إلى حصيلته اللغوية. وقد تلاحظين حتى أن طفلكِ يحاول غناء الأغاني ذات الكلمات البسيطة التي تستمعون إليها كثيرًا! 😊 منذ لحظة ولادته، يتعلم طفلكِ باستمرار اللغة التي يسمعها والأصوات الخاصة بها، ومع ذلك لا يزال أمامه الكثير ليتعلمه حتى يكتسب مهارة التحدث. ولتطوير مهاراته اللغوية والكلامية، لا تنسي أن تغني له كثيرًا، وأن تصفي له الأنشطة التي تقومين بها خلال اليوم، وتتحدثي معه عن كيفية مرور يومكما. كما أن اصطحابه إلى بيئات تتيح له التواصل الاجتماعي والوجود مع أقرانه سيسهم بدرجة كبيرة في تطوير مهاراته اللغوية.') WHERE id = '0cd3469d-8d4a-4f4e-bc31-4c507bf9612c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يُنصح بفطام طفلكِ بشكل مفاجئ، لأن ذلك قد يسبب له صعوبة عاطفية، كما قد يؤدي تراكم الحليب في الثدي إلى مشكلات مثل التهاب الثدي. بالإضافة إلى ذلك، فإن محاولة فطامه بوضع الطماطم أو مادة مُرّة على الثدي قد تزعزع ثقته بأمه، فهي أكثر شخص يرتبط به في هذا العالم. وبالمثل، قد تؤدي محاولة إثارة شعوره بالاشمئزاز عبر وضع مواد كريهة المظهر على الثدي إلى بعض الصدمات النفسية. ويُعد تقليل الرضاعة تدريجيًا أفضل طريقة للفطام. فعلى سبيل المثال، تستغرق العملية الأقل تأثيرًا فيكِ وفي طفلكِ ما بين 4-6 أسابيع في المتوسط. وفي المرحلة الأولى، قد تكون البداية الجيدة هي تقليل عدد مرات الرضاعة بمقدار رضعة واحدة كل يومين أو 3 أيام، من دون أن يشعر طفلكِ بتغير مفاجئ. وإلى جانب تقليل عدد الرضعات، يمكنكِ أيضًا محاولة تقصير الوقت الذي يقضيه طفلكِ على الثدي تدريجيًا.') WHERE id = '3d5ea030-23eb-46a7-94ed-7537bc1bbbf9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أفضل العلامات التي تساعدكِ على معرفة الوقت المناسب لبدء التدريب على استخدام المرحاض أن تلاحظي توقف طفلكِ عن الحركة عند التبول. فالطفل الذي لم تكتمل لديه بعد عضلات التحكم في التبول يفرغ مثانته بسهولة من دون أن يتوقف أثناء الحركة. وعندما يصبح قادرًا على التحكم في هذه العضلات ويبدأ بالشعور بالحاجة إلى استخدام المرحاض قبل حدوثها بقليل، يظهر السلوك الذي نسميه التوقف المؤقت. باختصار، إذا رأيتِ طفلكِ يتوقف للحظة وينحني قليلًا في أثناء انشغاله بنشاط ما أو ذهابه إلى مكان ما، فهذا يعني أنه مستعد للتدريب على استخدام المرحاض! 😊 إذا كنتِ لا تعرفين كيف تبدئين هذا التدريب، فيمكنكِ تجربة قاعدة الأيام الثلاثة التي يوصي بها المتخصصون. وفقًا لهذه القاعدة، يُستخدم في اليوم الأول حفاض يسمح للطفل بالشعور بالبلل، كي ينزعج من الرطوبة. وفي اليوم الثاني، لا يرتدي الطفل حفاضًا، ليشعر بالبلل بدرجة أكبر وينزعج منه. أما في اليوم الثالث، فيُدعَم الطفل، الذي سيبحث عن طريقة لتجنب هذا الشعور مجددًا، بعبارات مثل: «هل تريد أن نذهب إلى المرحاض؟ بهذه الطريقة لن تشعر بالبلل».') WHERE id = '2d14dd63-aabc-4645-bf9f-275bd8acabb6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اكتسب طفلكِ في هذه المرحلة مهارات حركية جديدة، مثل القفز. كما بدأت حالته الاجتماعية والعاطفية تتشكل وفقًا لشخصيته. ومع ذلك، فإن عدد الكلمات التي يفهمها يفوق عدد الكلمات التي يستخدمها. وقد تعوقه حصيلته اللغوية المحدودة عن التعبير عن مشاعره والتغيرات التي يمر بها على نحو صحيح. وكأي شخص، قد يغضب طفلكِ عندما يشعر بأن الآخرين لا يفهمونه، ما قد يؤدي إلى نوبات من الإحباط والغضب. وتُعد هذه السلوكيات من العلامات الشائعة لأزمة عمر السنتين. وإذا قمعتِ هذه المشاعر لديه، فقد تتحول الطاقة المتراكمة داخله إلى سلوكيات مؤذية مثل العضّ. فما زالت السيطرة على الغضب تفوق قدرته في هذه المرحلة، لذلك ينبغي لكِ التحدث معه كثيرًا عن مشاعره.') WHERE id = 'adf73ed7-c816-4db3-ac27-af97090fdb24';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد بلوغ طفلكِ عامه الثاني نقطة تحول حقيقية بعد كل هذا التطور الكبير الذي حققه خلال مدة قصيرة. وعلى الرغم من تنامي استقلاليته، فلا تنسي أنه ما زال يحتاج إلى مساعدتكِ كما كان في يومه الأول. تقبّليه دائمًا بوصفه فردًا مستقلًا، وميّزي بين ما يستطيع فعله وما لا يستطيع. إن إتاحة الفرص له للقيام بما يتقنه، وعدم لومه على ما لا يستطيع فعله، من أهم الخطوات الداعمة لنموه. وتذكّري أن المجال الذي ينجح فيه يختلف من طفل إلى آخر. حاولي اكتشاف اهتمامات طفلكِ؛ فإذا كان لا يحب التلوين مثلًا، فهذا لا يعني أنه لا يستطيع بناء برج بمكعبات الليغو. ولعل لديه حسًا موسيقيًا قويًا جدًا! 😊 وأفضل دعم نوصيكِ به، بصفتنا عائلة Anacan، هو أن تتقبلي طفلكِ كما هو وأن تهيئي له الظروف التي تساعده على إظهار إمكاناته.') WHERE id = '30b012e1-5c89-4c18-b6fd-8796dd3ea562';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن لكل طفل خصائص نمو تميّزه، فإن عمر السنتين عمومًا مرحلة يتسارع فيها تطور التواصل. ويستطيع الأطفال في هذا العمر نطق ما متوسطه 20-30 كلمة مختلفة، وتكوين جمل من كلمتين أو ثلاث كلمات. وخلال مدة قصيرة، ستتطور قدرته على تكوين جمل بسيطة أكثر، وسيبدأ باستخدام اللغة بفاعلية أكبر. وقد يخلط طفلكِ الكلمات أو يدمجها في هذه المرحلة، محاولًا تعلّم أشياء جديدة والتعبير عنها. وبالتوازي مع سرعة تعلّمه، فإنه يفهم تقريبًا كل ما تقولينه، وينفذ تعليماتكِ ويدرك الغرض من أسئلتكِ. لكنه قد يتظاهر أحيانًا بأنه لا يسمعكِ عندما لا يناسبه ما تقولينه! 😊 كل هذه السلوكيات جزء من عملية نموه؛ لذا احترمي وتيرة نمو طفلكِ الفردية وكوني أكثر تفهمًا معه.') WHERE id = '9051f36c-fed8-4ab1-82c1-a9cb54f63349';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا لجدول التطعيمات، ينبغي أن يتلقى طفلكِ هذا الشهر الجرعة الثانية من لقاح التهاب الكبد A، بعد أن تلقى الجرعة الأولى منه سابقًا. التهاب الكبد A مرض مُعدٍ يضر بالكبد ويصاحبه اليرقان. ولأن الفيروس ينتقل عن طريق البراز، فإن مصادر المياه الملوثة والأطعمة المغسولة بهذه المياه تشكل خطرًا كبيرًا. وأفضل طريقة للوقاية من هذا المرض هي تلقي اللقاح قبل الإصابة بالعدوى. ونظرًا إلى أن أعراض التهاب الكبد A قد لا تكون واضحة في بعض الأحيان، فلا بد من تلقي تطعيم عمر السنتين. يُعطى اللقاح في منطقة الفخذ اليسرى، وقد تظهر حمّى خفيفة بوصفها أحد آثاره الجانبية. وقد تلاحظين أيضًا أن طفلكِ منزعج أو فاقد للشهية، لكن هذه حالات طبيعية ومؤقتة.') WHERE id = 'd08455f4-14d3-4090-ae21-9de34395199f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي جدًا أن يعاني طفلكِ من مشكلات في الشهية بعد بلوغه عامه الثاني. وقد تلاحظين الآن أن طبقات الدهون الممتلئة والثنيات التي كانت تميز جسمه في الأشهر الأولى قد بدأت تقل. ويرجع ذلك إلى التباطؤ النسبي في مرحلة النمو الجسدي السريع، وعدم حاجة الجسم إلى القدر نفسه من السعرات الحرارية الذي كان يحتاج إليه سابقًا. ينبغي أن يتراوح وزن الفتيات في عمر 24 شهرًا بين 9100 غرام كحد أدنى و15.100 غرام كحد أقصى (بمتوسط يبلغ 12.200 غرام). أما وزن الأولاد في عمر 24 شهرًا، فيتراوح بين 9500 غرام كحد أدنى و15.700 غرام كحد أقصى (بمتوسط يبلغ 12.600 غرام).') WHERE id = '5e4362b2-06e5-4df6-8936-71c5d239e1a4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ قد واصلتِ إرضاع طفلكِ حتى هذه المرحلة، فنهنئكِ! توصي منظمة الصحة العالمية بإرضاع الأطفال طبيعيًا حتى عمر السنتين. لكن قرار توقيت التوقف عن الرضاعة الطبيعية يعود بالكامل إلى الأم وطفلها. والمسألة الأساسية هنا ليست متى تتوقفين عن الرضاعة، بل كيف تفطمين طفلكِ. إذا كنتِ ترين أن وقت الفطام قد حان، فيؤكد المختصون ضرورة ألا يحدث ذلك فجأة، بل تدريجيًا وعلى مدى فترة محددة حتى يعتاد طفلكِ عليه. والتحلي بالصبر خلال هذه العملية هو الخيار الأكثر صحة لكِ ولطفلكِ.') WHERE id = 'ab8fb6ce-5c13-4d03-8479-2cff8ada8d51';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مهما حاولتِ، قد يُظهر طفلكِ أحيانًا سلوكيات غير مرغوب فيها. وفي مثل هذه المواقف، يكون موقفكِ وحزمكِ في التعامل معه بالغَي الأهمية. لكن المبالغة في رد الفعل أو الغضب أو المنع أو العقاب قد تزيد الأمور صعوبة. وأفضل طريقة هي تحويل انتباه طفلكِ إلى شيء آخر. وللقيام بذلك، عليكِ مراقبة اهتماماته جيدًا. فعلى سبيل المثال، إذا كان يرفض تناول الطعام، يمكنكِ إتاحة الفرصة له لتناوله برفقة لعبته المفضلة. وإذا كان طفلكِ يحب الرسم، فيمكنكِ استخدام صلصة الطماطم في طبقه لصنع أشكال ممتعة. باختصار، ستجذب هذه الأساليب المرحة انتباه طفلكِ وتساعد على تقليل المشكلات.') WHERE id = '232af561-cec2-4585-8cda-9355fd410687';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يختلف نهج كل والدين في وضع الحدود لطفلهما. ويمكن تقسيم هذه النهج إلى ثلاث فئات: من لا يستطيعون وضع حدود، ومن يترددون في وضعها، ومن يضعون حدودًا صارمة. عادةً ما تختار الأسر التي لا تستطيع وضع حدود أسلوب تربية يمنح الطفل حرية كاملة، رغبةً منها في أن يكون سعيدًا وألّا يشعر بأي قيود. لكن الأطفال الذين لا يعرفون الحدود يواجهون صعوبة كبيرة في التكيف مع المجتمع خلال سنوات الدراسة وفي مرحلة البلوغ. أما الأسر المترددة، فتتبنى نهجًا مختلفًا وفقًا للبيئة التي توجد فيها ولحالها المزاجية في تلك اللحظة. ويُعد الثبات ضروريًا لتحديد الحدود ومساعدة الطفل على استيعابها، لأن القواعد غير المتسقة قد تربكه. أما الأسر التي تضع حدودًا صارمة، فتقيّد حرية أطفالها إلى حد كبير، ما يعني أن الطفل يكون خاضعًا تمامًا لسيطرة والديه. لذلك، عليكِ ضبط الحدود الخاصة بطفلكِ بما يتناسب مع عمره ومرحلة نموه. وينبغي أن يعرف طفلكِ نطاق حريته وأين ينتهي. ويُعد التعامل معه بثبات وحزم أمرًا بالغ الأهمية لنموه.') WHERE id = '2a7f4e56-4746-44ba-a23e-5b21fa398b44';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يؤدي تناول طفلكِ الطعام بسرعة شديدة أو استغراق الوجبة أكثر من نصف ساعة إلى بعض الآثار السلبية. تهضم إنزيمات الأميلاز الموجودة في اللعاب جزءًا من الكربوهيدرات على وجه الخصوص، كما تشكّل هذه العملية مرحلة تمهيدية لهضم الطعام في المعدة. وعندما يأكل طفلكِ بسرعة ومن دون مضغ كافٍ، يصل الطعام إلى المعدة غير مهضوم وفي قطع أكبر حجمًا، ما يعني أن على المعدة والأمعاء بذل جهد أكبر لهضمه. وباختصار، قد يتسبب الأكل السريع في إصابة طفلكِ بعسر الهضم وحرقة المعدة والانتفاخ وآلام الغازات. ومن ناحية أخرى، فإن إطالة وقت الوجبة أكثر من اللازم ستؤخر شعور الطفل بالجوع وموعد وجبته التالية. وخلال هذه المرحلة التي يقلدكِ فيها طفلكِ بنشاط، عليكِ الانتباه إلى طريقة تناولكِ الطعام بقدر اهتمامكِ بنوعية الأطعمة التي تتناولينها.') WHERE id = 'df961caa-4d98-4df5-a5a0-5f406bf41593';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد التسنين لدى طفلكِ مرحلة تبدأ عادةً بعد الشهر 6 وتتقدم بالتوازي مع نمو العظام. ومع نمو عظام وجه طفلكِ وجمجمته، تتحرك براعم الأسنان الموجودة منذ الولادة تدريجيًا نحو تجويف الفم. وتكتمل الأسنان التي تشق اللثة فوق عظام الفك وتبرز منها بحلول عمر 2.5 سنة تقريبًا. لكن ربما تكون الأضراس اللبنية الثانية لدى طفلكِ قد ظهرت بالفعل، ولا داعي للقلق في هذه الحالة. فقد يختلف توقيت بزوغ الأسنان اللبنية، الذي يبدأ في المتوسط في الشهر 6 ويُتوقع اكتماله في الشهر 30، بفارق يصل إلى 6 أشهر. أي إن ظهور القواطع الأمامية لدى طفلكِ في عمر 4 أشهر أمر طبيعي، وكذلك ظهور أضراسه اللبنية الثانية في الشهر 24. وقد تتمثل هذه الاختلافات أيضًا في تأخر التسنين. وباختصار، قد يكتمل ظهور أسنان طفلكِ اللبنية، البالغ عددها 20 سنًا، في عمر 3 سنوات تقريبًا.') WHERE id = '15d59f5c-8023-4040-b4f8-dbb2186a2bc6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من السهل جدًا تطبيق برنامج تغذية طفلكِ في المنزل. لكن إذا كنتِ ستحضّرين وجباته في المنزل وتأخذينها معكِ في الأيام التي تخرجين فيها، فقد تحتاجين إلى إعادة النظر في طرق حفظها. وعلى وجه الخصوص، لا تخضع رقائق الألومنيوم الشائعة الاستخدام في حفظ الأطعمة لعمليات المعالجة الخاصة نفسها التي تخضع لها المقالي وأواني الطهي. فعلى سبيل المثال، قد يكون استخدام رقائق الألومنيوم لتغليف تفاحة أو جزرة كاملة غير ضار نسبيًا. لكن عند ملامستها للحرارة، يزداد تحلل الألومنيوم من الرقائق بدرجة كبيرة. وعند تغليف طعام ساخن بها، تنتقل كمية كبيرة من الألومنيوم إلى الطعام. وكلما طالت مدة التلامس وازدادت سخونة الطعام، ارتفعت كمية الألومنيوم المنتقلة إليه. وقد يؤدي تناول طفلكِ أطعمة تحتوي على كميات كبيرة من الألومنيوم إلى إلحاق أضرار خطيرة بصحته. لذلك، من المهم جدًا لصحة طفلكِ استخدام وسائل حفظ معروفة بأنها أكثر أمانًا، مثل العبوات الزجاجية.') WHERE id = '99249fa2-1976-4010-a97c-d6cb7198f3f3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لتحديد ما إذا كان طفلكِ قصير القامة أو طويلها، ينبغي تقييم قياسات طوله الدورية وجنسه ومخطط النسب المئوية للنمو معًا. وعادةً ما يُشخَّص قصر القامة عندما يكون طول طفلكِ دون المئين 3 على مخطط النمو. ويبلغ متوسط زيادة طول طفلكِ السنوية 25 سم حتى عمر سنة، و10 سم من عمر سنة إلى سنتين، ثم ينبغي ألّا تقل عن 5 سم سنويًا في الأعمار اللاحقة. وإذا كانت الزيادة السنوية في الطول أقل من المعدل الطبيعي، فقد يشير ذلك إلى تأخر النمو. أما إذا كان الطول أعلى من المعدل الطبيعي، فيؤخذ الاستعداد الوراثي في الاعتبار أولًا. فإذا كان الوالدان طويلَي القامة وكانت تغذية الطفل وتوازن هرموناته طبيعيين، فسيستفيد طفلكِ إلى أقصى حد من هذه الإمكانات الوراثية. وفي حالات نادرة، قد يكون الطول المفرط ناجمًا أيضًا عن اضطرابات هرمونية مثل ضخامة الأطراف. وضخامة الأطراف مرض مزمن ينشأ نتيجة إنتاج هرمون النمو وإفرازه بكميات تفوق المعدل الطبيعي.') WHERE id = '03b2f142-4194-4c82-b5dd-f72012624ef1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكي ينشأ طفلكِ في المستقبل فردًا نافعًا للمجتمع وحسن التربية، عليكِ أن تقيّمي بشكل صحيح تطوّر شخصيته خلال المرحلة العمرية من 0-6 سنوات. ولتلبية حاجته إلى الانتماء والشعور بأنه مميز، حاولي أن تكوني إلى جانبه كلما احتاج إليكِ. وفّري له بيئة يشعر فيها بالأمان واحرصي على استمراريتها. فالشعور بالأمان والسعادة في هذه البيئة مهم جدًا لنمو طفلكِ. ومن الطبيعي أن تمر حياتكِ، كحياة أي إنسان، بفترات من الصعود والهبوط. لكن عليكِ أن تحاولي قدر الإمكان ألّا تجعلي طفلكِ يشعر بمشكلاتكِ العاطفية. ينبغي أن يدرك طفلكِ أن الأسرة أهم من أي شيء آخر. ولتحقيق ذلك، احرصي على أن يكون الوقت الذي تقضيانه معًا ذا جودة عالية. كما يُعد الشعور بالمسؤولية أحد الجوانب الأساسية في نمو طفلكِ. لذلك، أوكلي إليه مهام يستطيع إنجازها حتى يتذوق طعم النجاح. 😊 والأهم من كل ذلك، حافظي دائمًا على التواصل الجسدي مع طفلكِ؛ فالاهتمام واللمس والاحتضان ستلبي احتياجاته العاطفية.') WHERE id = '851123b6-5c41-4adf-9869-410006ae22db';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن أهم مؤشر على نمو طفلكِ بصحة جيدة هو زيادة طوله ووزنه بصورة متناسبة. ويزداد طول طفلكِ بفضل نمو النسيج الغضروفي الموجود عند أطراف العظام، والذي يُسمى صفائح النمو. والعامل الأول الذي يحدد عملية النمو هذه هو مجموعتا الجينات اللتان تنتقلان منكما أنتِ وشريككِ عند الإخصاب. وباختصار، سيؤثر طولكِ وراثيًا بصورة مباشرة في طول طفلكِ. أما العامل الثاني الذي يدعم النمو فهو التغذية. إذ تؤدي التغذية دورًا مهمًا في تحقيق أقصى استفادة من قابلية النمو في الطول التي تحددها الجينات. ومن الضروري أن يحصل طفلكِ على المقدار الكافي من السعرات الحرارية، مع مراعاة الطاقة التي يستهلكها الأيض الأساسي ونشاطه اليومي. وقد يؤدي عدم حصول طفلكِ خلال هذه المرحلة على سعرات حرارية كافية وعدم اتباعه نظامًا غذائيًا متوازنًا وصحيًا إلى حالة تُعرف بتأخر النمو.') WHERE id = 'e44ac09f-18ca-44ae-bc3d-9e4035e1db5d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج جسم طفلكِ إلى كمية كبيرة من البروتين والحديد لمواصلة نموه المتوازن. وخلال هذه المرحلة، ينبغي أن يحصل طفلكِ على ما يكفي من البروتين والحديد من خلال تناول أطعمة مثل السمك ولحم العجل ولحم البقر ولحم الضأن والدجاج والديك الرومي بانتظام. وبدلًا من الانشغال بمناقشات مثل: لحم العجل أم لحم الضأن؟ أو اللحوم الحمراء أم البيضاء؟ ينبغي التركيز على الخصائص المميزة لكل مجموعة من مصادر البروتين الحيواني. فعلى سبيل المثال، يحتوي لحم الضأن على دهون أكثر مقارنة بلحم العجل. ولذلك قد يكون خيارًا جيدًا لتلبية احتياجات طفلكِ اليومية من الطاقة. وبالمثل، يسهم لحم العجل بدرجة كبيرة في النمو لأنه يحتوي على بروتين أكثر من لحم الضأن. ومن الضروري لصحة طفلكِ وحصوله على الطاقة اللازمة أن يستفيد بصورة متوازنة ومنتظمة من كل مصدر من مصادر البروتين، كما هو الحال مع جميع المجموعات الغذائية.') WHERE id = '615c6205-aab5-4619-80ef-02dd20b724f7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يعاني الأطفال الذين ينمون ببطء أكبر من أقرانهم، أو الذين يقل نموهم عن المئين 3 وفقًا لمخطط المئينات المعتمد، من مشكلة تأخر النمو. ويمكن اكتشاف هذه المشكلة بسهولة من خلال مخطط النمو الذي يُعد بناءً على القياسات الدورية للطول والوزن. والخطوة الأولى في علاج تأخر النمو هي تحديد سببه. وعادةً ما تأتي الاضطرابات الهرمونية المرتبطة بهرمون النمو واضطرابات التغذية في مقدمة الأسباب. وفي حالات اضطرابات التغذية، يُعد برنامج خاص تحت إشراف اختصاصي تغذية وطبيب أطفال. أما في حال وجود مشكلات مرتبطة بهرمون النمو أو هرمونات الغدة الدرقية، فإن تعويض طفلكِ بالهرمون الناقص يساعد على علاج تأخر النمو خلال فترة قصيرة. وتأخر النمو حالة يسهل علاجها، لكنها قد تؤدي إلى مشكلات صحية خطيرة ودائمة إذا تأخر التدخل. لذلك، لا تهملي الفحوصات الطبية الدورية لطفلكِ.') WHERE id = 'b62b2d36-7ebf-4e11-9bed-226c4b783fbe';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُلاحظ اضطرابات النطق لدى طفل واحد من كل 10 أطفال بلغوا سن المدرسة. وغالبًا ما تؤدي هذه الحالة إلى عجز الأطفال عن التعبير عن أنفسهم. وقد يصبح الطفل الذي لا يستطيع التعبير عن مشاعره وأفكاره عدوانيًا عندما يشعر بأن الآخرين لا يفهمونه. وينجم ذلك عادةً عن أساليب التعامل الخاطئة التي تتبعها الأسرة. ومن أمثلة ذلك عدم منح الوالدين طفلهما فرصًا كافية للتعبير عن نفسه خلال المرحلة التي تتطور فيها مهارات اللغة والنطق بنشاط. كذلك، ينظر الأطفال الذين ينشؤون في بيئة يسودها الشجار الدائم إلى الكلام على أنه مجرد وسيلة للجدال. ولا يمكن أيضًا الحديث عن مهارات نطق سليمة في البيئات التي يسودها إهمال الوالدين ويقل فيها الحوار. ومن ناحية أخرى، عندما تُفرط الأسرة في رعاية طفلها وتلبي جميع رغباته قبل أن تمنحه فرصة للتحدث، لا تتطور مهارات النطق لديه بشكل كافٍ. لذلك، من المهم جدًا أن تحاولي تنمية مهارات اللغة والنطق لدى طفلكِ باتباع نهج سليم، والحفاظ على التوازن، وتوفير بيئة بعيدة عن المؤثرات السلبية.') WHERE id = 'a1da3103-38bb-409a-b6a8-60cff787aea4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم توجد أي موانع، فسيكتسب طفلكِ عادة استخدام المرحاض خلال بضعة أسابيع بفضل اتباع الأساليب الصحيحة. لكن قد تقع بعض الحوادث البسيطة، مثل تبليل سرواله، إلى أن تكتمل هذه العملية. وفي مثل هذه الحالات، يكون رد فعلكِ مهمًا جدًا لما له من تأثير في شعور طفلكِ تجاه نفسه. وعند وقوع حادث، عليكِ الانتباه بشدة إلى الكلمات التي تستخدمينها، بل وحتى إلى تعابير وجهكِ. فتعابير الوجه المبالغ فيها والأسلوب الذي يتضمن اللوم لن يساعدا طفلكِ على التقدم، بل سيولدان لديه شعورًا بالفشل ويؤخران التدريب. كما ينبغي ألّا تسببي له التوتر بتكرار أسئلة مثل: هل تحتاج إلى دخول المرحاض؟ كذلك فإن إخافته والبقاء إلى جانبه ومراقبته باستمرار ما لم يطلب طفلكِ ذلك بنفسه من السلوكيات الأخرى التي تزيد توتره.') WHERE id = 'e4ec1981-d0f3-401a-8422-6e105994d820';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نظرًا لأن قدرة طفلكِ على الاستيعاب تكون كبيرة جدًا ويتقدم تطوره اللغوي في هذه المرحلة، يمكنكِ البدء بتعليمه اللغة الإنجليزية. فتعلّم لغة أجنبية في سن مبكرة يمنح الطفل ميزة كبيرة في المستقبل. يتعلم الأطفال اللغة أولًا من خلال الكلمات المفردة، ثم مجموعات الكلمات، وأخيرًا الجمل. ولمساعدة طفلكِ خلال هذه العملية، عليكِ مراقبته جيدًا. ومن المفيد جدًا تهيئة فترات قصيرة في المنزل تتحدثان خلالها بالإنجليزية، أو الاستماع معًا بشكل متكرر إلى الأغاني والتهويدات الإنجليزية. وإذا كان طفلكِ يشاهد الرسوم المتحركة، فإن اختيارها باللغة الإنجليزية سيساعده أيضًا على استيعاب اللغة.') WHERE id = 'ad97f664-295a-40e4-a267-0055f05130e8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الضروري التحلي بالصبر وعدم الشعور باليأس خلال مرحلة الفطام. لذلك ينبغي التخطيط جيدًا قبل البدء بالفطام والتفكير في الأمر مليًا. وقد تستسلم بعض الأمهات من حين إلى آخر بسبب صعوبة التكيف مع هذا التغيير الجذري ومواجهته. لكن الاستسلام والفوضى الناتجة عنه قد يجعلان هذه المرحلة أكثر صعوبة على الطفل. إذا قررتِ فطام طفلكِ، فعليكِ تقبّل أنه سيكون أكثر حساسية وانزعاجًا من المعتاد. وقد يبكي كثيرًا، مما قد يحزنكِ ويزيد صعوبة الفطام. لذلك احرصي بشكل خاص على احتضانه كثيرًا والتربيت على ظهره ومعانقته وتقبيله.') WHERE id = '4edac414-47f5-4ace-b884-331a8009248b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ يتحدث إلى ألعابه أو إلى نفسه خلال هذه المرحلة. ويشيع التحدث إلى النفس في عمر السنتين، لذلك لا داعي للقلق. إن استخدام الأطفال المستمر للغة في هذه المرحلة يساعد على نمو حصيلتهم اللغوية بسرعة كبيرة. ووفقًا للأبحاث، يتطور النمو اللغوي لدى الأطفال الذين يتحدثون إلى أنفسهم أو إلى والديهم أو الأشخاص المحيطين بهم أو ألعابهم بسرعة أكبر مقارنة بغيرهم من الأطفال. ومع ذلك، إذا كان طفلكِ يؤلف جملًا قصيرة أو كان كلامه غير مفهوم تمامًا، فلا تلحّي عليه لإكمال كلامه. فالإلحاح والغضب قد يثيران غضبه وينفّرانه من التحدث. لذلك حاولي إجراء حوارات متبادلة معه باستمرار من دون الضغط عليه. وأتيحي له الفرصة للتحدث وطرح الأسئلة. وحتى إن شعرتِ من حين إلى آخر بالتعب من كثرة أسئلته، فمن المهم جدًا ألا تجعليه يشعر بذلك.') WHERE id = '76dbf32a-12ec-49d7-ab16-15fdada3d51f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أبرز سمات مرحلة السنتين هي الاستقلالية. ففي هذه المرحلة، يصبح طفلكِ مدركًا تمامًا أنه فرد مستقل لا يعتمد على الآخرين في كل شيء. ونتيجة لهذا الإدراك، قد تلاحظين أنه يحاول إنجاز كل شيء بمفرده، لأنه سيبذل قصارى جهده ليثبت لكِ أنه شخص مستقل عنكِ. في هذه المرحلة، عليكِ أن تتعلمي احترام استقلالية طفلكِ وألا تتدخلي إلا عند الضرورة. وعندما تتدخلين، يُفضَّل أن يكون ذلك من خلال تحويل انتباهه إلى شيء آخر. وقد تكون التصرفات العنيدة الناتجة عن تحديات عمر السنتين والشعور المكتسب بالاستقلالية مرهقة ومزعجة جدًا للوالدين. فالتعامل مع طفل قليل الصبر وعنيد ومصرّ على فعل ما يريده أمر متعب لكثير من الآباء والأمهات. لكن محاولة كسر عناده في هذه المرحلة بالضغط عليه تضر بتصوره لذاته، وتجعله يشعر بالرفض في أثناء محاولته إثبات نفسه.') WHERE id = '6ba61781-1ee0-4e31-8537-9186df6efc0e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تتساءلين إن كان طفلكِ سيستخدم يده اليمنى أم اليسرى؟ يبدأ في سن مبكرة ظهور الجزء الذي يستخدمه الطفل بنشاط أكبر من دماغه، وبالتالي اليد التي سيعتمد عليها أكثر في أداء مهامه اليومية. وعلى الرغم من أن اليد المهيمنة قد تبدأ بالظهور في عمر سنة تقريبًا، فإن تفضيل إحدى اليدين يستقر عادةً في سن ٣-٤ سنوات. ويمكنكِ منذ الآن معرفة اليد التي يميل طفلكِ إلى استخدامها من خلال مراقبته. فعلى سبيل المثال، قد تكون مراقبة اليد التي يمدها نحو ألعابه، أو يمسك بها الأشياء غالبًا، أو يستخدمها لتناول الطعام بداية جيدة. وإذا كنتِ تعتقدين أن طفلكِ يستخدم يده اليسرى بنشاط أكبر، فلا تقلقي. قد تؤدي المعتقدات الخاطئة المرتبطة باستخدام اليد اليسرى إلى الضغط على الطفل لتنمية استخدام يده غير المهيمنة أيضًا، لكن ذلك قد يسبب العديد من المشكلات في نموه.') WHERE id = 'c72377ae-83c6-42fd-be3d-7ba1f89c4920';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'التغذية الصحية عادة يبدأ اكتسابها في مرحلة الطفولة. وبعبارة أخرى، سيستمر طفلكِ مستقبلًا وفق النمط الغذائي الذي تضعينه له الآن. فعلى سبيل المثال، إذا عوّدتِ طفلكِ على تناول وجبات خفيفة خلال اليوم، فسيشعر بالحاجة إليها حتى عندما يكبر. وإذا تخطيتِ أي وجبة رئيسية خلال اليوم، فقد يعتاد في المستقبل أيضًا على عدم تناولها. لذلك حاولي تنظيم وجبات طفلكِ الرئيسية والخفيفة وفق روتين محدد. وسيساعدكِ الالتزام بهذا الروتين والثبات عليه على تسهيل اكتساب طفلكِ لهذه العادة. ونظرًا لأن ضعف الشهية شائع في هذه المرحلة، فإذا لم يرغب طفلكِ في تناول إحدى الوجبات، يمكنكِ اللجوء إلى بدائل مثل الوجبات الخفيفة الصحية.') WHERE id = '20150dab-66b0-4920-818c-13a3e7136048';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع بلوغ طفلكِ عمر 2 سنة، يبدأ نظامه الغذائي بالتشابه إلى حد كبير مع نظام البالغين. ومع ازدياد تفاعله الاجتماعي ورؤيته الآخرين يتناولون المشروبات الغازية والليموناضة والأطعمة الجاهزة المعبأة، سيبدأ بإبداء اهتمام بهذه المنتجات. ومن الأفضل تلبية هذا الاهتمام بتقديم بدائل أو خيارات أقل ضررًا. فعلى سبيل المثال، قد تحتوي الليموناضة الجاهزة على كميات كبيرة من السكر والمواد المضافة. وإذا أراد طفلكِ شرب الليموناضة، فيمكنكِ تحضير ليموناضة طبيعية بسهولة في المنزل. أما المشروبات الغازية، فينبغي إبعاد طفلكِ عنها قدر الإمكان، لأنها تحتوي على كميات كبيرة من الملونات والمنكهات والمواد الحافظة. وبدلًا منها، يمكنكِ إعداد مزيج من عصير الفاكهة وكمية قليلة من المياه المعدنية الطبيعية ليكون بديلًا صحيًا أكثر. وتُعد المياه المعدنية مصدرًا طبيعيًا للمعادن بفضل مكوناتها، لكن يجب الانتباه إلى كميتها، لأن الإفراط في تناولها قد يؤدي إلى تكوّن حصوات في كليتي طفلكِ.') WHERE id = 'f07f1c96-bc65-46e5-aee7-1f4704bbe735';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أوشك طفلكِ الآن على بلوغ عامه الثاني. وهذا يعني أنه بدأ تدريجيًا في تجاوز أسرع مراحل النمو. فخلال أول 12 شهرًا منذ ولادته، يزداد طول طفلكِ بمعدل 25 sm ويتضاعف وزنه ثلاث مرات. وعلى الرغم من تباطؤ النمو نسبيًا خلال الفترة الممتدة من الشهر 12 إلى الشهر 24، فإنها تظل مرحلة سريعة النمو. وبعد إكمال 24 شهرًا، ينمو الأطفال بوتيرة ثابتة حتى مرحلة المراهقة، باستثناء حالات نادرة. ولذلك، فإن المرحلة التالية التي سيرتفع فيها منحنى نمو طفلكِ مجددًا هي مرحلة المراهقة. وتبدأ أولى علامات المراهقة في المتوسط عند عمر 11 سنة لدى الفتيات و12 سنة لدى الفتيان، وفي هذه الأعمار يبدأ الطول بالازدياد بسرعة من جديد. وحتى مرحلة المراهقة، سيزداد طول طفلكِ بمعدل 6-7 sm سنويًا، وسيكتسب وزنًا يتراوح بين 2000-3000 qram. والمهم ليس مقدار نموه، بل أن يستمر نموه بصورة متوازنة ومتناسقة.') WHERE id = 'aff1da93-456e-48a8-9491-2359d0f1819f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الأفضل لصحة طفلكِ ألّا يشرب الشاي قدر الإمكان. ولكن إذا رآكِ تشربينه وأصر على تجربته، فلن تسبب له بضع رشفات من الشاي المخفف بالماء مشكلة. فقد يقلل الشاي امتصاص الحديد في الجسم، ما قد يؤدي إلى إصابة طفلكِ بنقص الحديد. ويؤدي نقص الحديد إلى إبطاء إنتاج الهيموغلوبين، فلا يحصل الجسم على كمية كافية من الأكسجين الضروري للنمو الصحي. ونتيجة لذلك، قد يصاب طفلكِ بفقر الدم. لذا ينبغي ألّا تسمحي له بشرب كميات كبيرة من الشاي. كما أن السكر المضاف إلى الشاي قد يحد من حصوله على الفيتامينات والمعادن، ويزود جسمه بسعرات حرارية خالية من القيمة الغذائية. وقد يكون للشاي أيضًا تأثير منبه في جسم طفلكِ بسبب احتوائه على الكافيين؛ إذ يمكن أن يؤدي على المدى القصير إلى الأرق وفرط النشاط، وعلى المدى الطويل إلى خفقان القلب وبعض أمراض القلب. لذلك، يُفضّل عدم تقديم الشاي لطفلكِ، أو تقديم كمية قليلة جدًا منه بعد تخفيفها بالماء.') WHERE id = '1bee19ec-571c-4174-99b3-cd8351c86d71';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشير الأكاديمية الأمريكية لطب الأطفال إلى أن الفتيات يكتسبن عادات استخدام المرحاض في وقت أبكر من الفتيان. ويرجع ذلك إلى أن الفتيان أكثر حركة وأقل ميلًا إلى الجلوس. ويجب أن تتذكري أن عادات استخدام المرحاض وقواعد النظافة تختلف بين الجنسين. بالنسبة إلى الفتيان، يُفضّل تعويد الطفل على التبول جالسًا بدلًا من الوقوف، لأن ذلك يساعد بسهولة أكبر على تجنب الحوادث البسيطة المحتملة. وإذا أراد التبول واقفًا، فيمكنكِ أن تطلبي من والده أو أخيه الأكبر، إن كان لديه أخ، أن يريه الطريقة الصحيحة. أما بالنسبة إلى الفتيات، فأهم ما ينبغي مراعاته هو التنظيف من الأمام إلى الخلف. وتمنع هذه القاعدة انتقال الكائنات الدقيقة الضارة إلى الأعضاء التناسلية، ما يقلل خطر الإصابة بالعدوى إلى أدنى حد.') WHERE id = 'ae97b92b-a7d9-475b-9849-10e43e2e1c73';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الليكوبين هو الصبغة التي تمنح اللون الأحمر لأطعمة مثل الطماطم ومعجون الطماطم والبطيخ والغريب فروت الوردي وثمار الورد البري. ويُعد الليكوبين أحد أقوى مضادات الأكسدة، والطماطم هي أغنى الأغذية به. وعلى خلاف الخضراوات الأخرى، لا يؤثر الطهي سلبًا في كمية الليكوبين الموجودة في الطماطم، بل يزيد قدرة الجسم على امتصاصه. ومن هذا المنطلق، يساعد تناول طفلكِ أطعمة غنية بمضادات الأكسدة على حمايته من الآثار الضارة للجذور الحرة في الجسم. وتُظهر الدراسات أن تناول هذه الأطعمة بانتظام يحافظ على توازن مضادات الأكسدة في الجسم. كما يدعم تكوّن خلايا جديدة ويسهم في حماية طفلكِ مستقبلًا من سرطان الأمعاء وغيره من أنواع السرطان، بالإضافة إلى أمراض القلب.') WHERE id = '41b94477-7ace-4910-a0f5-44deccc75aca';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يؤدي رفض جميع طلبات طفلكِ إلى الإضرار بعلاقتكما. وإذا وافق زوجكِ على أمر رفضتِه أنتِ، فقد يربك ذلك طفلكِ ويزيد التوتر. لذلك، من المهم جدًا أن تكوني ثابتة وحازمة عندما تقولين «لا». يعتقد بعض الوالدين أحيانًا أن تجنب كلمة «لا» يزيد ثقة الطفل بنفسه، لكن استخدامها في الوقت والمكان المناسبين يسهم في نموه وتطوره. فالطفل الذي تُلبّى جميع رغباته لن يعرف متى يجب أن يتوقف، ولن يدرك حدوده. ومن المهم أيضًا أن تحترمي كلمة «لا» التي يقولها طفلكِ. وهكذا، عندما يسمع هذه الكلمة، سيكون أكثر ميلًا إلى التفاهم بدلًا من العناد.') WHERE id = '98b637d9-7d59-44a7-bf65-65315858e258';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع اقتراب طفلكِ من عمر 2 عامين، قد تلاحظين أنه يعبّر منذ فترة عن مشاعره بوضوح من خلال صوته وقبضتيه وضرب قدميه بالأرض ودموعه. من الطبيعي أن تشعري بالقلق في البداية، لكن تذكّري أن الحزن شعور طبيعي تمامًا مثل السعادة. لذلك، لا تتعجّلي في تهدئة طفلكِ عندما يعبس أو يبكي. من الأفضل ألا تبالغي في التدخل، وأن تتيحي له فرصة إدراك أن الشعور بالانزعاج أمر طبيعي أيضًا. فالإلحاح في محاولة إزالة حزنه قد يوصّل إليه رسالة خاطئة مفادها أن "الشعور بالغضب أو الحزن أمر سيئ". كما أن حل جميع مشكلات طفلكِ بنفسكِ يحرمه من فرصة التعرّف إلى مشاعره وتعلّم كيفية التعامل مع المشكلات. وإذا كان يصرخ أو يضرب عندما يغضب، فيمكنكِ أن تعلّميه طرقًا أكثر هدوءًا وقبولًا للتعبير عن مشاعره.') WHERE id = 'd1b69dfc-0c51-40d4-ab46-57e12080ec1e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يفاجئكِ أحيانًا تفاوت شهية طفلكِ؛ فقد تلاحظين أنه ينهي طعامه بالكامل في بعض الأيام، بينما يأكل القليل جدًا أو يرفض الطعام في أيام أخرى. وتُعد الشكوى من ضعف الشهية من الأسباب الشائعة جدًا لمراجعة الطبيب خلال المرحلة العمرية بين 1.5-2 عامين. تتأثر شهية طفلكِ مباشرةً بالبيئة التي يتناول فيها الطعام، وشكل الطعام وطريقة تقديمه، وتجاربه السابقة، وثقافة الأسرة الغذائية. لذلك، إذا كنتِ قلقة بشأن ضعف شهيته، فمن المفيد أن تضعي هذه العوامل في الاعتبار قبل مراجعة الطبيب. يمكنكِ مثلًا تجربة تقديم طعام سبق أن رفضه بطريقة مختلفة، أو تغيير المكان الذي يتناول فيه وجباته.') WHERE id = '90f2176f-d469-499a-9a1d-3e82e805f900';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يعمل دماغ طفلكِ في مرحلة ما قبل المدرسة بوتيرة مختلفة، فجسمه ودماغه مفعمان بطاقة لا تنفد. وهذا ليس مشكلة، بل هو مؤشر طبيعي على نموه. والأهم هو توجيه هذه الطاقة في الاتجاه الصحيح. فبدلًا من الألعاب التقليدية، يمكنكِ اختيار ألعاب أكثر فائدة، مثل الألعاب الكبيرة التي يمكن دفعها أو ركوبها، وألعاب التركيب والآليات القابلة للبناء، والمكعبات، وألعاب الأحجية، وملابس الدمى، والعرائس، والمواد الإبداعية كالألوان. ولكي تظل الألعاب ممتعة بالنسبة إليه، يمكنكِ تقديمها بالتناوب بدلًا من إعطائه إياها جميعًا في الوقت نفسه. كما يُعد الصلصال أو الرمل المخصص للأطفال وسيلة ممتازة لتفريغ طاقته وتحفيز حواسه.') WHERE id = 'f6438f5c-5190-493d-b6e8-a062c6c8373c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد مرحلة عمر 2 عامين وقتًا ممتازًا لإعادة مراجعة قواعد السلامة المنزلية. نعلم أنكِ أجريتِ سابقًا العديد من التعديلات في المنزل، لكن قد تظهر مخاطر جديدة مع ازدياد طول طفلكِ وحبه للاستكشاف والمغامرة. أعيدي تقييم المنزل من وجهة نظره، مع مراعاة تطوره الجسدي. وبما أن قدرته على حل المشكلات قد ازدادت الآن، فقد يتمكن من الوصول إلى أماكن لم تخطر ببالكِ قط. وبدلًا من تأجيل اتخاذ الاحتياطات ظنًا منكِ أنه لن يستطيع الوصول، ضعي الأدوات الحادة والمدببة في أماكن بعيدة عن متناوله، واحرصي على حفظ الأدوية والفيتامينات في عبوات مزودة بأغطية مقاومة لعبث الأطفال.') WHERE id = '7c251dbc-3324-4894-adb1-12e3963965fc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أهم الأمور خلال مرحلة الفطام عن حليب الأم إيجاد أنشطة تشتت انتباه طفلكِ عن الرضاعة، وقد تختلف هذه الأنشطة من طفل إلى آخر. يمكنكما مثلًا الذهاب إلى المتجر معًا وشراء طبق طعام أو كوب مميز يعجبه. وإذا كان طفلكِ معتادًا على النوم أثناء الرضاعة، فاحرصي على أن تكون وجبة العشاء مشبعة. وعندما يحين موعد الرضاعة، حاولي تشتيت انتباهه بقراءة كتاب أو ممارسة ألعاب هادئة أو غناء تهويدة أو سرد قصة. وإذا كنتِ ترضعينه دائمًا على كرسي معين، فحاولي تجنب الجلوس عليه لبعض الوقت. وإذا استيقظ ليلًا طلبًا للرضاعة، فحاولي تهدئته بالتربيت على ظهره أو التحدث إليه بكلمات لطيفة. نحن، أسرة Anacan، إلى جانبكِ خلال هذه المرحلة الانتقالية.') WHERE id = '4a81e876-e127-40b0-8888-e4bf91cbafc4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تمرّين بمرحلة يكون فيها طفلكِ نشيطًا للغاية، ولهذا قد تنشأ بينكِ وبين شريك حياتكِ من وقت إلى آخر اختلافات في الرأي بشأن تربيته. في مثل هذه الحالات، من الأفضل لطفلكِ أن تقدّما له ردًا يستند إلى قرار مشترك. وعندما تحدث مشكلة، يكون من المنطقي أن يتدخل الوالد الذي شهد الموقف بالطريقة التي يراها مناسبة. وإذا لم تتمكنا من الاتفاق بشأن ذلك، فيمكنكما مناقشة الأمر لاحقًا بعيدًا عن مسامع طفلكِ. يُعد الاتساق والثبات أساس الانضباط، لذا يُستحسن أن تناقشا رؤيتكما الأساسية للقواعد والعواقب التربوية، وأن تتوصلا إلى أرضية مشتركة. وبدلًا من الجدال، يمكن لكل منكما أن يشرح للآخر أسلوبه ولماذا يعتقد أنه سيكون فعالًا. ومن الأفضل أن تركّزا نقاشكما على مسائل محددة، وأن تتجنبا التعميمات التي قد تتحول إلى هجمات شخصية، مع السعي إلى التوصل إلى حل وسط.') WHERE id = '237018c6-9f32-4ad2-bdf7-fd0aaaeb2f68';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد عمر السنتين مرحلة يتعرّف فيها الأطفال بكثافة إلى الأطعمة غير الصحية والوجبات الخفيفة قليلة القيمة الغذائية. لكن لا يزال بإمكانكِ تنظيم تغذية طفلكِ بطريقة صحية وعدم التهاون في هذا الأمر. ويمكنكِ التأكد من حصول طفلكِ على كمية كافية من كل مجموعة غذائية باتباع نموذج ورقة البرسيم رباعية الأوراق في نظامه الغذائي. تمثل كل ورقة في هذا النموذج مجموعة غذائية: فالورقة العلوية تمثل الحليب ومنتجات الألبان، واليمنى تمثل اللحوم والبيض والبقوليات، والسفلية تمثل الخضراوات والفواكه، أما اليسرى فتمثل منتجات الحبوب. احرصي على إدراج كل مجموعة من هذه المجموعات في غذاء طفلكِ بكميات كافية ومتوازنة. وكلما أخّرتِ تعريف طفلكِ إلى الوجبات الخفيفة غير الصحية، كان ذلك أفضل ليصبح شخصًا أكثر صحة في المستقبل.') WHERE id = '467c9786-4914-430a-9924-35e942ff8361';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ نشيطًا بدنيًا ولا يعاني من أي تأخر في النمو، فعمر السنتين وقت مناسب لشراء دراجة له. وتُعد الدراجات المصممة بخصائص ملائمة للأطفال في هذا العمر وسيلة رائعة لمساعدة طفلكِ على تفريغ طاقته. كما أن ركوب الدراجة ممتع جدًا للطفل، ويمكنكِ في الوقت نفسه الاستفادة من هذا النشاط لتعزيز التناسق بين اليد والعين، والمهارات الحركية الدقيقة والكبيرة، والثقة بالنفس، والشعور بالإنجاز. وقد تكون المنتجات المعروفة باسم دراجات التوازن من أنسب الخيارات لطفلكِ في هذه الفئة العمرية. ودراجة التوازن هي نوع من الدراجات يتعلم الأطفال باستخدامه الحفاظ على توازنهم بدءًا من عمر السنتين. ومن الناحية المثالية، يمكن لطفلكِ استخدام دراجة التوازن مدة تتراوح بين 2-3 سنوات تقريبًا قبل الانتقال إلى الدراجة العادية.') WHERE id = '039fea2a-271b-4d91-ab26-1321bf9ae441';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد فقدان الشهية من الأمور التي تقلق كل من لديه طفل في هذا العمر. فقد تؤثر التغييرات الكبيرة، مثل التسنين والانتقال إلى بيئة جديدة كالسكن في منزل آخر، أو بدء الأم بالعمل، أو تغيير مقدّم الرعاية، بصورة مباشرة في شهية الأطفال. ومع ذلك، من المهم أن تكون توقعاتكِ بشأن شهية طفلكِ وكمية الطعام التي يتناولها واقعية؛ فمن الطبيعي أن يتباطأ معدل نمو الأطفال بعد عمر السنة، ما يؤدي إلى انخفاض احتياجاتهم من الطاقة. وعندما تقل احتياجاتهم من الطاقة، فمن الطبيعي أن يتناولوا سعرات حرارية أقل ويشعروا بالشبع بسرعة أكبر. لكن بعض الأمراض المختلفة، مثل نقص الحديد والارتجاع والتهابات المسالك البولية والداء البطني واضطرابات الغدة الدرقية، قد تسبب أيضًا فقدان الشهية. لذلك، إذا كانت توقعاتكِ واقعية ومع ذلك استمر فقدان الشهية الشديد لأكثر من 3 أسابيع، فقد تحتاجين إلى استشارة الطبيب.') WHERE id = 'dca414d3-e320-48c8-8813-fff940ae46cb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدءًا من هذه المرحلة، يبدأ خيال طفلكِ بالتطور بصورة ملحوظة. ويمكنكِ ملاحظة ذلك بمجرد مراقبة ألعابه وطريقة لعبه لبعض الوقت، إذ تنعكس قدرته المتنامية على طرح الأسئلة والربط بين السبب والنتيجة على ألعابه في صورة إبداع. لذلك، يمكنكِ استخدام ألعاب تساعد على إثراء عالمه الخيالي المتطور. فمثلًا، يمكنكِ التفكير في شراء ألعاب تنمّي مهاراته الذهنية إلى جانب مهاراته اليدوية. وقد تكون عربة تسوق يضع فيها ألعابه الأخرى، أو هاتفًا لعبة، أو ملابس لدمى، أو ألوانًا للرسم بالأصابع، أو مكعبات ليغو وعجائن لعب يمكنه تشكيلها. وإلى جانب ذلك، يمكنكِ تنمية اهتمامه بالموسيقى وموهبته فيها باستخدام آلات موسيقية مصممة للأطفال، مثل البيانو أو الناي.') WHERE id = '57b8155c-5ee1-41d1-934a-7cebf0187e62';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ أمًا ترضعين طفلكِ رضاعة طبيعية بانتظام، فقد تشعرين بامتلاء ثدييكِ بشدة وتورمهما والتسبب لكِ بالانزعاج عند إيقاف الرضاعة فجأة. وقد تكون لهذه الحالة أسباب عديدة، لكنها غالبًا ما تشير إلى أنكِ استعجلتِ هذه العملية وأوقفتِ الرضاعة بسرعة كبيرة. ومن المهم جدًا تقليل الرضاعة تدريجيًا لتجنب الشعور بالانزعاج في ثدييكِ. فعندما تقللين الرضاعة ببطء، سينخفض إنتاج الحليب أيضًا، ما يساعد على الوقاية من هذه المشكلات. وإذا كنتِ تعتقدين أنكِ أدرتِ العملية بأكملها على نحو صحيح، لكن إنتاج الحليب لا ينخفض رغم ذلك، فيمكنكِ تجربة بعض الطرق. فمثلًا، يساعد شفط كمية من الحليب تكفي فقط لتشعري بالراحة على الوقاية من الألم في تلك المنطقة. لكن عليكِ توخي الحذر: إذا شفطتِ حليبًا أكثر من اللازم، فقد يزداد إنتاجه بدلًا من أن ينخفض.') WHERE id = '0d192335-07c1-48ae-b0c1-73b57c665f7d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أنتِ الآن في مرحلة بدأت فيها الثنيات الموجودة في ذراعي طفلكِ وساقيه بالاختفاء، وأصبح رأسه يبدو أكثر تناسبًا مع جسمه. وخلال هذا العام، ستبدأ ساقاه وجذعه أيضًا بالاستطالة، وسينتقل تمامًا من مظهر الرضيع إلى مظهر الطفل. كما أن ازدياد تسطح منطقة البطن سيجعل ظهره يبدو أكثر استقامة. وتدل هذه التغيرات في المظهر على أن طفلكِ لا يزال ينمو بنشاط. ومع ذلك، قد تلاحظين أنه يأكل أقل ويحصل على سعرات حرارية أقل مقارنة بالعامين الأولين. وفي الواقع، تكون احتياجات طفلكِ من السعرات الحرارية في هذه المرحلة، قياسًا إلى طوله وحجم جسمه، أقل مقارنة بمعدل نموه خلال الأشهر الأولى. تذكّري أن نموه سيستمر بصورة طبيعية ما دمتِ تقدمين له باستمرار أطعمة مغذية وصحية.') WHERE id = '9f4e48f3-4698-48db-86e2-c05bac7cae8f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك عدة طرق لمعرفة ما إذا كان طفلكِ مستعدًا للتدريب على استخدام المرحاض. ومن أهم العلامات بقاء الحفاض جافًا لمدة 2-3 ساعات، وقدرة طفلكِ على التحكم في إخراجه ولو لفترة قصيرة أثناء اللعب. كذلك، فإن توجهه إلى زاوية عند حاجته إلى قضاء حاجته، أو استدارته خجلًا، أو رغبته في البقاء بمفرده، كلها مؤشرات مهمة. وإذا كان طفلكِ يساعدكِ عند تبديل ملابسه، ويستطيع إنزال سرواله ورفعه، فهذا يعني أنكما مستعدان لبدء التدريب. يمكنكِ في البداية شراء نونية لطفلكِ. شجّعيه على الجلوس عليها 1-2 مرة يوميًا، ويمكنكما أيضًا، إن رغبتما، تزيينها معًا بملصقات شخصياته المفضلة. في البداية، اسمحي لطفلكِ بالجلوس عليها مرتديًا ملابسه أو حفاضه، لكن لا تضغطي عليه أبدًا في هذا الأمر.') WHERE id = 'a75526ab-d8f7-4d2d-95ac-987058ff01a0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد الخضراوات غنية جدًا بالفيتامينات والمعادن والمركبات الكيميائية النباتية المهمة لتغذية طفلكِ. في هذه المرحلة، ينبغي أن يتناول طفلكِ نحو 3 حصص من الخضراوات يوميًا. يمكنكِ تقديم خيارات مثل 3 ملاعق كبيرة من الخضراوات المطهوة، أو طبق من سلطة الخضراوات المغسولة جيدًا، أو شرائح الجزر في الوجبات الخفيفة، أو عصائر الخضراوات. وبالمثل، تحتوي الفواكه على فيتاميني A وC والبوتاسيوم والكالسيوم ومعادن أخرى مهمة لصحة بشرة طفلكِ وعينيه ولثته. يوصي المختصون بأن يتناول الأطفال في هذه المرحلة حصتين من الفاكهة يوميًا. لذلك، يمكنكِ تقديم 1-2 شريحة من الفاكهة أو الخيار لطفلكِ كوجبة خفيفة صحية بدلًا من الأطعمة غير الصحية. وتُعادل كل من تفاحة صغيرة واحدة، أو 8-10 حبات فراولة متوسطة الحجم، أو نصف كوب من التوت الأزرق، أو برتقالة متوسطة الحجم حصة واحدة من الفاكهة.') WHERE id = '181a660f-adf3-4c1d-b661-7b1e99455b57';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال فترة تدريب طفلكِ على استخدام المرحاض أو بعد إتمام التدريب، قد تواجهين بعض الحوادث البسيطة. وتُعد بقع البول أو البراز من الأمور المزعجة لكثير من الأمهات. لكن تذكّري أن تنظيف البقع وهي حديثة أسهل وأسرع. لإزالة بقع البراز والبول من ملابس طفلكِ، يمكنكِ إضافة مزيل للبقع إلى ماء بارد ونقع الملابس فيه لبعض الوقت. وإذا لم تنجح هذه الطريقة، يمكنكِ وضع مزيل بقع متعدد الاستخدامات مباشرة على المنطقة المتسخة. ومن الطرق الأخرى مزج كوب واحد من الماء مع ملعقة كبيرة واحدة من محلول الأمونيا، ثم وضع المزيج على البقعة. ولأن هذه العملية قد تُبهت ألوان الملابس، فمن الأفضل اختبارها أولًا على جزء صغير منها.') WHERE id = 'fde67b77-39bc-4fff-8eb0-e8ebcbe7b5be';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه الفترة أن طفلكِ يستيقظ من نومه كثيرًا وهو يبكي ويصرخ. وقد تؤدي التشنجات العضلية والإحساس بالسقوط إلى شعور الأطفال بخوف شديد واستيقاظهم. ويزداد هذا الخوف ليلًا، خصوصًا لدى الأطفال الذين يسقطون أثناء اللعب أو المشي نهارًا. وقد يُلاحظ أيضًا أن بعض الأطفال ينهضون واقفين على السرير ليلًا وهم شبه نائمين. وقد يستيقظ طفلكِ فجأة أثناء تحركه بمحاذاة حواف السرير، فيجد صعوبة في فهم مكانه وكيفية العودة إلى النوم، فيصرخ ويبكي. في مثل هذه الحالات، يُعد الحفاظ على هدوئكِ قدر الإمكان أفضل ما يمكنكِ فعله لطفلكِ. فإذا اقتربتِ منه بذعر وهو مرتبك أصلًا، فقد يصبح الموقف أكثر تعقيدًا.') WHERE id = 'b4c378f2-23ac-470c-8fa7-75b6a433a8f8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر الأطفال في مرحلة ما قبل المدرسة بنمو وتطور مستمرين. ولكي يسير هذا النمو بالمستوى المطلوب، من المهم أن تتوافق السعرات الحرارية والعناصر الغذائية الكبرى والصغرى التي يتناولها الطفل يوميًا مع احتياجاته. تُظهر الأبحاث أن كثيرًا من حالات السكري وأمراض القلب وبعض أنواع السرطان لدى البالغين ترتبط بالعادات الغذائية غير السليمة خلال الطفولة. لذلك، ينبغي أن تكوني مرشدة جيدة لطفلكِ فيما يتعلق بالتغذية. ويمكنكِ طلب دعم مختص عند الحاجة. في هذه المرحلة، يصبح طفلكِ أقل اعتمادًا عليكِ في احتياجات مثل تناول الطعام وارتداء الملابس واستخدام المرحاض. لكنه، كما في سائر الأمور، لا يزال يقتدي بكِ وبوالده في عاداته الغذائية. وفي هذا الصدد، سيكون ما تفعلانه أكثر تأثيرًا مما تقولانه. وإذا أردتِ إكساب طفلكِ عادات غذائية صحية، فعليكِ أولًا تطبيق هذه العادات بنفسكِ في المنزل.') WHERE id = '71a028e9-244b-4bb2-828b-adb6991c70a4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن نمط نوم الأطفال يستمر بصورة طبيعية تقريبًا حتى عمر سنتين، فإن مشكلات النوم تبدأ بالازدياد مع اقترابهم من هذا العمر. وقد يكون تدريب الطفل على النوم في عمر سنتين صعبًا على الوالدين والأطفال معًا؛ فاعلمي أنكِ لستِ وحدكِ في مواجهة ذلك. وخلال هذه الأشهر، التي لا تزال فيها أعراض مرحلة السنتين حادة، قد تظهر حالات مثل مقاومة النوم، والاستيقاظ خائفًا، وقلة النوم. تذكّري أن مشكلات النوم في هذه المرحلة تنشأ عادةً بسبب الخوف والقلق، وقد تنتج أحيانًا عن آلام جسدية أيضًا. ولمساعدة طفلكِ على النوم براحة أكبر، يمكنكِ قضاء بعض الوقت معه في بيئة مظلمة قبل موعد النوم. فالظلام مهم جدًا لإفراز هرمون الميلاتونين واستعداد الدماغ للنوم.') WHERE id = '57c7a36d-f4d1-4633-b6cf-7d31210afabf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج الطفل في عمر سنتين إلى الحصول على ما بين 1150 و1450 سعرة حرارية في المتوسط يوميًا. وهذه الكمية من السعرات الحرارية مهمة لعمل عملية الأيض بصورة طبيعية ولنموه ضمن المعدلات المناسبة. لكن ينبغي ألا تأتي هذه السعرات التي يحصل عليها طفلكِ من أطعمة منخفضة القيمة الغذائية. فعلى سبيل المثال، يُعد السكر من أبرز الأطعمة الغنية بالسعرات الحرارية رغم انعدام قيمته الغذائية. وعلى العكس من ذلك، تُعد المكسرات من الأطعمة الأعلى من حيث السعرات الحرارية والقيمة الغذائية معًا. ولكي ينمو طفلكِ بصحة جيدة، فهو يحتاج إلى أطعمة عالية القيمة الغذائية، لا إلى سعرات حرارية فارغة. لذلك من المهم جدًا عند إعداد برنامجه الغذائي اليومي أن تركزي على مدى فائدة الطعام بدلًا من الانشغال المفرط بالأرقام.') WHERE id = 'c5185021-525c-412b-89be-7978a0800fb0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه المرحلة بعض المشكلات، مثل استيقاظ طفلكِ فجأة في منتصف الليل، وصعوبة عودته إلى النوم، وعدم انتظام قيلولاته النهارية. ويمكن للأطفال في عمر سنتين النوم نحو 12-13 ساعة يوميًا. وفي هذه المرحلة، قد تقصر مدة القيلولة النهارية، بينما تطول مدة النوم ليلًا. إذا كنتِ تعانين من استيقاظ طفلكِ ليلًا، فربما حان الوقت لتقليل قيلولاته النهارية. ويساعد تقليل القيلولة تدريجيًا على توفير نوم ليلي أكثر صحة وجودة. ينام معظم الأطفال في عمر سنتين مدة 10-11 ساعة ليلًا ونحو ساعتين نهارًا. ومن المهم الانتباه إلى ضرورة إضافة الوقت الذي يُقتطع من القيلولة النهارية إلى النوم الليلي؛ فمن الضروري جدًا لصحة طفلكِ أن يستوفي إجمالي عدد ساعات النوم التي يحتاج إليها يوميًا.') WHERE id = '26503615-41cd-4d9a-ab25-64f208211b61';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون نمط التغذية اليومي غير منتظم لدى كثير من الأطفال في هذه الفئة العمرية. وقد يظهر ذلك في تناول كمية قليلة في إحدى الوجبات ثم تعويضها في وجبة أخرى. وفي بعض الأحيان، قد يعقب يومًا يأكل فيه الطفل قليلًا يومٌ تكون فيه شهيته مفرطة، أو قد يطلب الحلويات والوجبات الخفيفة غير الصحية قبل الطعام. وعندما يتناول هذه الوجبات الخفيفة المنخفضة القيمة الغذائية والمرتفعة السعرات الحرارية، يفقد شهيته ويتخطى موعد الوجبة الرئيسية. إذا كنتِ تواجهين هذه المشكلة أيضًا، فعليكِ الحد منها وتقليل استهلاكه للدهون غير الصحية والسكريات البسيطة، وعدم السماح بتحول ذلك إلى عادة. إن اكتساب طفلكِ عادات غذائية منتظمة لا يقل أهمية عن تلبية احتياجاته اليومية. ويُعد انتظام الوجبات وعدم تفويت مواعيدها من أهم العادات التي ينبغي غرسها خلال مرحلة الطفولة.') WHERE id = '999e50f0-32f5-409b-95b1-57d5bb7ccc27';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين بدءًا من هذه المرحلة أن طفلكِ يلعب مع أقرانه، خصوصًا في ساحات اللعب. فهو يستمتع بمراقبة ما يفعله الأطفال الآخرون من حوله وكيف يلعبون، وقد يقلدهم أيضًا. لكن قضاء الوقت مع أطفال آخرين لا يعني أنه سيوافق على مشاركة ألعابه معهم. وعلى الرغم من أنكِ قد تلاحظين مشاركته لهم لفترات قصيرة أحيانًا، فإنه سيفضل تجنب ذلك عمومًا. وعدم الرغبة في المشاركة سلوك طبيعي تمامًا لدى الأطفال في هذا العمر. ومع ذلك، يمكنكِ محاولة غرس عادة المشاركة لديه من دون الإفراط في إجباره. فمثلًا، يمكنكما في المنزل تبادل الألعاب بالتناوب، ثم إجراء عمليات تبادل بسيطة بينكما بعد فترة، لتتحول إلى نشاط تدريبي ممتع.') WHERE id = '228c8956-54f6-42b1-91c3-92700a15abf3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشير الدراسات إلى أن 60% من الأطفال في مرحلة ما قبل المدرسة يتناولون الطعام أكثر من ثلاث مرات يوميًا. وقد لوحظ نقص الطاقة والكالسيوم والبروتين وفيتامين C والحديد لدى الأطفال الذين يتناولون أقل من أربع وجبات يوميًا. لذلك، ينبغي أن تنظمي وجبات الإفطار والغداء والعشاء لطفلكِ بشكل كافٍ ومتوازن لدعم نموه، وأن تضيفي وجبات خفيفة خلال اليوم بحسب احتياجاته. تذكري أن سعة معدة طفلكِ ليست مماثلة لسعة معدة البالغين؛ لذلك ينبغي أن تتراوح حصته بين 1/4 و1/3 الكمية التي تتناولينها. عندما يجلس الطفل إلى المائدة، فإنه يُقيّم الطعام أولًا وفقًا لمظهره. وإذا كان طفلكِ ضعيف الشهية خصوصًا، فاحرصي في كل وجبة على تقديم طبق صحي وملون. إن تنسيق أطعمة متنوعة الألوان في الطبق وتقديمها بأشكال مختلفة ومرحة سيساعدان على تحفيز شهية صغيركِ.') WHERE id = '146da55d-f9f1-483e-8342-8aa377d3cf2c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكون معظم الأطفال مستعدين للتدريب على استخدام المرحاض بدءًا من عمر سنتين، لكن توقيت ذلك يعتمد على الخصائص الفردية لكل طفل. فعلى سبيل المثال، قد يكون رضيع في عمر 18 شهرًا مستعدًا لذلك، بينما قد لا يكون طفل في عمر 24 شهرًا مستعدًا بعد. وترتبط هذه الاختلافات تمامًا بالنمو الفردي. باختصار، إذا كنتِ تعتقدين أن طفلكِ الذي بلغ عامين لم يستعد بعد للتدريب على استخدام المرحاض، فلا تقلقي. راقبيه لبعض الوقت وشجعيه من دون الضغط عليه أو الإلحاح. فقد يؤدي الإصرار أو توبيخ الطفل إلى شعوره بالخوف والعجز؛ لأن التدريب على استخدام المرحاض يمثل تغييرًا جذريًا بالنسبة إلى طفلكِ، وقد تُخيف مثل هذه التغييرات أي طفل. كذلك، تُعد أطعمة مجموعة الحليب ضرورية للحفاظ على صحة طفلكِ واستمرار نموه.') WHERE id = '12f09593-bf34-4be0-bc69-2dfdea7442a0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ ترغبين في فطام طفلكِ ولم تنجح الأساليب التي جرّبتِها سابقًا، فقد يساعدكِ تقليل عدد مرات الرضاعة من خلال تغييرات بسيطة. يكفي أن تراقبي الأوقات التي تزداد أو تقل فيها حاجة طفلكِ إلى الرضاعة. بعبارة أخرى، يمكنكِ البدء مع مراعاة عدد مرات رضاعته خلال اليوم ومدى تعلّقه بكل جلسة. ما عليكِ فعله في هذه الطريقة هو تقليل عدد جلسات الرضاعة واحدة تلو الأخرى، بدءًا من الجلسات الأقل أهمية بالنسبة إليه. وعند تقليل عدد الجلسات، قد يكون تقصير مدة كل رضعة خيارًا آخر. فعلى سبيل المثال، إذا كنتِ ترضعينه عادةً لمدة 10 دقائق، يمكنكِ تقليلها أولًا إلى 7 دقائق، ثم إلى 5 دقائق، وبعد ذلك إلى 3 دقائق، قبل إيقافها تمامًا في النهاية. وهكذا تساعدين طفلكِ على التكيّف مع هذه العملية بسهولة أكبر وتجاوزها بأقل قدر ممكن من التأثر النفسي.') WHERE id = 'b2d2a191-cfa2-4680-b7fa-56aec3d43443';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكون حس الاستكشاف لدى الأطفال في عمر 25 شهرًا في ذروته. ففي هذه المرحلة، يثير كل شيء فضول طفلكِ، وقد يجد أدق التفاصيل مثيرة للاهتمام ويحاول استكشافها بنفسه من دون الاعتماد على أحد. ولتجنّب إرباكه، ينبغي أن تتناسب أنشطة عمر السنتين مع مستوى نمو طفلكِ. يمكنكِ بسهولة تنظيم أنشطة وألعاب له باستخدام المواد المتوفرة في المنزل. فعلى سبيل المثال، يمكنكِ شراء ألوان أطفال مصنوعة من مكونات طبيعية تمامًا. ضعي كيسًا بلاستيكيًا على يدكِ واستخدمي هذه الألوان للرسم على الورق بالشكل الذي ترغبين فيه، وبذلك يمكنكِ تعزيز ارتباط طفلكِ بالألوان ومساعدته على تكوين حس جمالي. باختصار، ستجمع هذه الطريقة بين التعلّم وتنمية الخيال والمرح في آنٍ واحد! :)') WHERE id = '3bc058c0-b2b8-4d01-8dfe-9d742de7ca23';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم أن يتناول طفلكِ يوميًا وبصورة متوازنة كميات محددة من الأطعمة التي تحتوي على اللحوم والحليب والحبوب والفواكه والخضراوات والدهون. في هذه المرحلة، يحتاج الطفل في المتوسط إلى 350 ملغ من الكالسيوم يوميًا. ويمكن أن يلبي تناول 250-300 غرام من الحليب والزبادي، إلى جانب قطعة من الجبن الأبيض بحجم علبة كبريت، احتياج طفلكِ اليومي من الكالسيوم. كذلك، يظل فيتامين D ضروريًا في هذه المرحلة لاستمرار نمو العظام. ونظرًا إلى محدودية الأطعمة المحتوية على فيتامين D وقلة فرص الاستفادة من أشعة الشمس خلال الشتاء، ينبغي الاستمرار في إعطاء الأطفال من هذه الفئة العمرية 400 وحدة من فيتامين D. كما تُعد الحاجة إلى الحديد من الأمور التي يجب الانتباه إليها في هذه المرحلة. ولتحسين امتصاص الحديد، حاولي تقديم الأطعمة الغنية به مع فيتامين C. ولأن فيتامين C لا يُخزَّن في الجسم، فمن المفيد تناوله يوميًا.') WHERE id = '32027992-7ca5-4f41-9e94-b756c09c029b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن طفلكِ البالغ من العمر 25 شهرًا يحقق تقدمًا كبيرًا في مهاراته الحركية والاجتماعية والمعرفية، فإن تطوره اللغوي يتسارع بصورة ملحوظة، خصوصًا خلال هذه الأشهر. ومع تطور مهاراته الحركية، قد تلاحظين أنه يمشي ويقفز، بل ويركض أيضًا. وقد أصبح معتادًا على صعود الدرج، وستواصل هذه المهارات التحسن مع مرور الوقت. وينبغي أن يكون طفلكِ، الذي بدأ بالفعل بتنظيف أسنانه من دون مساعدة، قادرًا أيضًا على غسل يديه بنفسه. وهذه خطوة كبيرة في حياته، إذ سيتمكن من الاعتناء بنفسه من دون حاجة كبيرة إلى مساعدتكِ. كما يمكنه خلال هذه المرحلة تنفيذ التعليمات البسيطة التي تعطينها له والمكوّنة من بضع كلمات. وقد لا يكون كلام طفلكِ واضحًا تمامًا بعد، وربما يواجه صعوبة في تكوين جمل صحيحة. وستحتاجين إلى الانتظار نحو 1.5-2 سنة أخرى حتى تصبح جمله مفهومة تمامًا.') WHERE id = 'ba59a28d-3a83-4205-ae5d-916e1a3c9cd4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطرق الشائعة بين الناس لفطام الطفل وضع مواد لاذعة، مثل الطماطم أو الفلفل، على حلمة الثدي. لكن جميع المختصين يتفقون على أن هذا الأسلوب خاطئ للغاية. فقد يتحول إيقاف الرضاعة من خلال إثارة اشمئزاز الطفل أو إخافته، أي باستخدام أساليب صادمة، إلى تجربة مؤلمة نفسيًا له. فالرضاعة الطبيعية ليست المصدر الأساسي لغذاء الرضيع في بداية حياته فحسب، بل هي أيضًا عملية عاطفية تُنشئ رابطًا خاصًا بين الأم وطفلها. لذلك، عندما يحين وقت الفطام، فإن تقليل الرضعات تدريجيًا حتى إيقافها هو الأسلوب الأكثر توصية بدلًا من استخدام الطرق القاسية. تذكّري أن هذه العملية قد تستغرق عدة أسابيع، وأحيانًا عدة أشهر، بحسب عمر الطفل ومدى تعلّقه بالرضاعة. والتحلي بالصبر هو أهم جزء في هذه الرحلة.') WHERE id = '1e6cc207-c282-439c-9382-edd1bb9f0fbf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد مرحلة العناد التي تتطور لدى الأطفال بين عمر 18-30 شهرًا من المراحل التي تشكّل تحديًا كبيرًا للوالدين. ففي هذه الفترة، يختبر الأطفال مشاعر عديدة في الوقت نفسه ويعبّرون عنها مباشرة لمن حولهم. وخلال مرحلة العناد، يختبر الأطفال استقلاليتهم وقدراتهم ويتجاوزون الحدود لإظهار مدى أهميتهم بالنسبة إليكِ. وعلى المدى البعيد، تُكسب هذه المرحلة الطفل مهارات متنوعة؛ إذ يبدأ تطوره اللغوي بالتسارع ويشرع في الربط بين المشاعر والأفكار والأحداث. وحين يبدأ الطفل تدريجيًا بالتعبير عن مشاعره وأفكاره، يدرك أن رغباته لا تتحقق كلها. وقد تدفعه هذه العوائق إلى التصرف بانفعال وتؤثر سلبًا في التواصل داخل الأسرة. ومن خلال اتباع نهج تربوي حازم ومتّسق، سيتعلم طفلكِ أنه لا يمكنه الحصول على كل ما يريده، وسيتعلم تأجيل رغباته، كما ستتطور لديه مهارات حل المشكلات.') WHERE id = 'f7c23bf2-ec35-4dd7-9dc0-07a8b4bba0ce';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعدّ مجموعة الحليب ومشتقاته مصدرًا مهمًا للبروتين والكالسيوم، وهما ضروريان لتمتّع طفلكِ بعظام وأسنان وعضلات قوية. وإلى جانب البروتين والكالسيوم، تتميز أطعمة هذه المجموعة بغناها بالمغنيسيوم وحمض الفوليك وفيتامينات B1 وB2 وB6 وB12 وA وD، التي تؤدي دورًا حيويًا في عملية الأيض. وبما أن البروتين الموجود في منتجات الألبان من أصل حيواني، فإنه يُعدّ عالي الجودة ويمتصه الجسم بكفاءة كبيرة. لذلك، من المهم جدًا أن يتناول طفلكِ 2-3 حصص من مجموعة الحليب ومشتقاته يوميًا. ويمكنكِ تلبية احتياجات طفلكِ اليومية بتقديم 1 كوب من الحليب أو 1 وعاء من الزبادي أو 1,5 كوب من العيران. وإذا كان طفلكِ لا يتناول منتجات الألبان مباشرةً، فقد تكون إضافة الحليب أو الزبادي إلى الحساء بديلًا جيدًا.') WHERE id = '9f64f831-67cc-4be0-97ce-2205dfe840a9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد أن بلغ طفلكِ الآن 25 شهرًا، سيحب خلال هذه المرحلة الألعاب القائمة على الخيال أكثر من ذي قبل. وقد تلاحظين أنه يتحدث كثيرًا إلى ألعابه، ويحاول إطعامها وتنويمها، بل وقد يغضب منها أحيانًا. عليكِ أن تعلمي أن هذا أمر طبيعي تمامًا، فلا تقلقي من تعامله مع ألعابه وكأنها كائنات حية. يمكنكِ في هذه المرحلة مشاركته ألعابًا تحاكي الحياة الواقعية، مثل اللعب بالبيت أو الطبيب أو المتجر. وإذا قام أثناء اللعب بتصرف لا يعجبكِ، فأريه التصرف الصحيح بدلًا من إخباره بأنه مخطئ. فهذه الأنواع من الألعاب تسهم مباشرةً في نمو طفلكِ العقلي، وتؤدي دورًا مهمًا في تكوين شخصيته.') WHERE id = '7e1b66ed-5e66-4aa1-b4a6-f41e10ded050';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يختلف وزن الأطفال في عمر 25 شهرًا اختلافًا ملحوظًا. ففي هذه المرحلة، يبلغ الحد الأدنى لوزن البنات 9300 غرام، بينما يبلغ الحد الأعلى 15.500 غرام. ويبلغ متوسط وزن البنات في عمر 25 شهرًا نحو 12.200 غرام. أما لدى الأولاد، فيبلغ الحد الأدنى للوزن 9600 غرام، والحد الأعلى 16.000 غرام، بينما يبلغ متوسط وزنهم نحو 12.600 غرام. ويرتبط السبب الأبرز لهذه الفروق في الوزن ارتباطًا مباشرًا بالنمط الغذائي الذي اتبعتِه منذ بدء مرحلة إدخال الأطعمة التكميلية. وإلى جانب ذلك، تؤدي عوامل عديدة، مثل جنس الطفل وخصائصه الوراثية ونمط حياته، دورًا مهمًا في تحديد وزنه.') WHERE id = 'a2bfd1ad-4106-4f9b-8d0d-cdce4a5cf06d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكن للطفل الذي أُتيحت له فرصة تناول الطعام بنفسه منذ عمر سنة تقريبًا أن يبدأ باستخدام الملعقة في شهره 18. وبحلول الشهر 25، يُتوقع أن يتمكن طفلكِ من استخدام الملعقة والشوكة بسهولة. أما إذا لم تُتَح له هذه الفرصة بما يكفي من قبل، فقد لا تكون هذه المهارة قد اكتملت لديه بعد. لا تنسي أن قدرة الطفل على الإمساك بالملعقة ترتبط ارتباطًا مباشرًا بتطور مهاراته الحركية الدقيقة. لذلك، إذا كان طفلكِ لا يزال غير قادر على استخدام الملعقة والشوكة بفاعلية، فعليكِ إعطاء الأولوية للأنشطة التي تنمّي مهاراته الحركية الدقيقة. ويمكنكِ، تحت إشرافكِ، تجهيز وعاءين يحتوي أحدهما على الماء ويكون الآخر فارغًا، ثم مساعدة طفلكِ على نقل الماء بالملعقة إلى الوعاء الفارغ. سيساعدكما ذلك على قضاء وقت ممتع ومفيد معًا، كما سيتيح له فرصة التعلم والتطور أثناء اللعب.') WHERE id = '8f4758cd-90b9-472e-8df7-d37b3ac362c8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تأتي التغيرات النمائية والشعور المتزايد بالاستقلالية في مقدمة أسباب مشكلات النوم لدى الأطفال في عمر السنتين. وتظهر مشكلات النوم عادةً خلال الفترات التي يبدأ فيها الطفل بالمشي والكلام، وتبلغ ذروتها في عمر 2 سنة. ومع تطوره، يصبح الطفل أكثر قدرة على فهم ما يحدث من حوله، فيتأثر بالأحداث مباشرةً. وقد تؤدي المواقف السلبية التي يشاهدها، خصوصًا، إلى شعوره بالخوف ليلًا ورؤيته الكوابيس. وفي بعض الأحيان، قد لا تقتصر هذه الحالة على حلم سيئ، بل قد تكون أيضًا تعبيرًا عن استيقاظ جسدي وقلق داخلي. كذلك، قد تسبب وسائل الإعلام مثل التلفزيون ومقاطع الفيديو إثارة مفرطة لدى الطفل، أو ترسّخ في ذهنه مشاهد تمنعه من النوم. ولكي ينام طفلكِ بهدوء وراحة، من المهم جدًا أن يعيش في أجواء هادئة ومطمئنة، ليس ليلًا فحسب، بل خلال النهار أيضًا.') WHERE id = 'a576e8d4-a044-40f6-9103-4fbc7ac08bc4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعدّ اللحوم والدجاج والأسماك والبيض والبقوليات بالغة الأهمية لنمو طفلكِ العقلي والجسدي. فهذه الأطعمة غنية بالبروتين والحديد والزنك وفيتامينات مجموعة B. وفي هذه المرحلة، ينبغي أن يتناول طفلكِ من اللحوم أو الدجاج أو السمك كمية تعادل تقريبًا حجم 2-3 أقراص من كفتة اللحم. أما البيض، فهو الغذاء الوحيد الذي يحتوي، بعد حليب الأم، على بروتين بأعلى جودة؛ لذلك ينبغي أن يحتل مكانة مهمة في قائمة طعام طفلكِ وأن يُقدَّم له كثيرًا في وجبة الإفطار. وإذا كنتِ مترددة بشأن حجم الحصص، فقد تساعدكِ هذه المقادير: تُعدّ كل من كمية لحم مطهو تعادل حجم 2-3 أقراص من كفتة اللحم، أو 3-4 قطع صغيرة من فخذ الدجاج، أو 3-4 ملاعق كبيرة من البقوليات المطهوة، أو 1 بيضة، حصة واحدة لطفلكِ.') WHERE id = 'a66e9b59-566b-45ea-b98a-39eeae68efc4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أكثر الأمور التي قد تغفل عنها الأسرة عند وجود طفل في المنزل عدم تهيئة مساحة المعيشة بما يناسبه. فتنظيم البيئة المنزلية وفقًا لاحتياجات الطفل يرتبط ارتباطًا وثيقًا بتربيته وتعليمه الانضباط. ذلك لأن كثيرًا من الأشياء التي يُمنع الطفل منها ويُقال له بشأنها «لا» في الحياة اليومية هي في الواقع أشياء يرغب في استكشافها، لكنها قد تكون خطرة عليه أو ذات أهمية خاصة لوالديه. ومهما كرر الوالدان كلمة «لا»، يظل الأطفال راغبين في فعل بعض الأمور؛ مثل العبث بجهاز التحكم عن بُعد، أو ضرب المزهرية بسيارة لعبة، أو إدخال شوكة في مأخذ الكهرباء. ومن الواضح أنه لا يمكن السماح بهذه التصرفات. ولكن بدلًا من فرض الحظر باستمرار والعيش في أجواء متوترة ومقلقة، يمكنكِ تسهيل حياتكِ ببعض الحيل البسيطة. يمكنكِ وضع جهاز التحكم في مكان مرتفع، وحفظ المزهرية داخل خزانة مقفلة حتى يكبر طفلكِ، وتركيب أغطية أمان على مآخذ الكهرباء. باختصار، بدلًا من تقييد طفلكِ بقول «لا» لكل شيء، من الأفضل إزالة المواقف التي تضطركِ إلى قولها.') WHERE id = '24d78195-52d6-418b-9a44-151ac076ad3c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشير الدراسات إلى أن الأطفال في عمر 26 شهرًا يصبحون قادرين على إظهار أولى علامات التعاطف الواضحة. ففي هذه المرحلة، يبدؤون على الأقل في تكوين فكرة عن مشاعر الآخرين، حتى إن لم يكونوا يشعرون بالإحساس نفسه. وإذا شعر شخص مقرّب منهم بالألم، فإنهم لا يكتفون بفهم ذلك، بل يحاولون أيضًا التخفيف من ألمه. لكن هذا لا يعني أن طفلكِ سيكون قادرًا على إظهار التعاطف في كل لحظة. لذلك قد تلاحظين أنه يهتم كثيرًا بمشاعركِ في يوم، ثم يتصرف بأنانية تامة في يوم آخر. وإذا أخذنا في الاعتبار أن قدرة البالغين أنفسهم على التعاطف قد تضعف أحيانًا، فلا ينبغي أن تتوقعي أن تكتمل هذه المهارة لدى طفلكِ في يوم واحد. وتذكّري أن التواصل السليم معه مهم للغاية لتنمية قدرته على التعاطف.') WHERE id = '66b861ee-daf9-4bb4-99ec-98a5a4c85861';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك أسباب معينة قد تثير سلوك طفلكِ المتقلب والمشاغب، لا سيما في مرحلته العمرية الحالية. فمثلًا، قد يصبح الطفل الذي قضى يومه كله خارج المنزل وتعرّض للكثير من المؤثرات الخارجية، مثل الضوضاء والألوان والناس، مفرط النشاط والمشاغبة عند عودته إلى المنزل. وفي المقابل، قد يقاوم الطفل الذي بقي في المنزل طوال اليوم النوم مساءً. في مثل هذه الحالات، بدلًا من اعتبار سبب عدم استجابته لكِ لغزًا، حاولي التعرّف إلى طبيعته واحتياجاته. فمن المعروف أن الأطفال قد يصبحون صعبي المراس عندما يشعرون بالجوع أو لا يحصلون على قسط كافٍ من النوم، أو عندما لا يحظون باهتمام كافٍ خلال اليوم. لذلك، عندما يبدأ طفلكِ بالتصرف بعدوانية، حاولي أولًا تلبية احتياجاته الأساسية. وهكذا ستتمكنين من تحديد السبب الحقيقي وراء فرط نشاطه وتقلب سلوكه بصورة أوضح.') WHERE id = 'a6f116b1-a2fd-4df4-9d02-8024e8406686';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ازدادت قدرة طفلكِ على التركيز كثيرًا في هذه المرحلة. ويمكنكِ الآن أن تلاحظي بوضوح أنه أصبح يهتم بنشاط معين بعمق ولفترة أطول من السابق. فمثلًا، كغيره من الأطفال، يكون صغيركِ في هذه الفترة شغوفًا جدًا بالرسم، وتركيزه الكامل على الورق والألوان أثناء الرسم خير دليل على ذلك. ويمكنكِ توجيه هذا التركيز نحو أنشطة مفيدة، كتشجيعه على تصفح المزيد من الكتب المصوّرة. حاولي ألا يستهلك طفلكِ قدرته على التركيز أمام التلفاز أو الجهاز اللوحي، لأن المشاهد التي يتعرض لها هناك من دون رقابة قد تؤثر سلبًا في خياله. وبدلًا من ذلك، ساعديه على تنمية عالمه الخيالي بأفضل صورة ممكنة.') WHERE id = '3dd2e755-52bb-485f-aae6-0adf656f3d85';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعرف المرحلة الممتدة بين عمر 1.5 و2.5 عام بأزمة عمر السنتين، وهي إحدى أصعب مراحل تربية الطفل بالنسبة إلى الوالدين. وقد يتطلب التعامل مع طفلكِ في هذه المرحلة الكثير من الصبر. تذكّري أنكِ لستِ وحدكِ في مواجهة هذه الصعوبة؛ فنحن، عائلة Anacan، إلى جانبكِ. يلجأ كثير من الآباء والأمهات إلى أساليب مختلفة للتعامل مع هذه الحالة، لكن بعضها قد يضر بنمو الطفل. ومن هذه الأخطاء، مثلًا، إعطاء الطفل الهاتف وتركه يستخدمه لساعات كي لا يثير المتاعب. فالتساهل في هذا الأمر ولو مرة واحدة قد يؤدي لاحقًا إلى عادات يصعب التخلص منها. وإذا أصبح طفلكِ متعلقًا بالهاتف إلى حد الإدمان ولم تتمكني من معالجة الأمر، فيمكنكِ طلب المساعدة من مختص. كذلك، ينبغي أن تتوافق أفعالكِ مع ما تقولينه في هذا الشأن. باختصار، إذا كنتِ لا تعطين طفلكِ الهاتف حين يطلبه، فعليكِ أنتِ أيضًا الابتعاد عن هاتفكِ خلال تلك الفترة.') WHERE id = 'f1c6bc8b-26e9-4fdb-a3cc-6f2e7f573fdd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يستمر نمو دماغ الطفل بسرعة منذ ولادته وحتى بلوغه 3 سنوات. ويُعد حليب الأم أهم غذاء يؤثر في نمو قدراته الذهنية. لذلك، تُسهم الرضاعة الطبيعية خلال أول عامين من حياة الطفل إسهامًا كبيرًا في تطوره العقلي. فالدهون تشكّل 60% من الدماغ، ويشكّل حمض DHA، وهو أحد أحماض أوميغا-3 الدهنية، نصف هذه الدهون. وباختصار، يُعد DHA من أهم العناصر الضرورية لدعم نمو دماغ طفلكِ في هذه المرحلة. ومن المهم أن يتناول طفلكِ في جميع مراحل نموه أطعمة تدعم تطور الدماغ، إلا أن الأشهر التي يمر بها الآن تُعد من أسرع فترات هذا التطور. لذلك قد يكون تناول الأسماك الغنية بـDHA خيارًا جيدًا لطفلكِ، وإذا كان لا يتناول السمك، فيمكن إعطاؤه زيت السمك بناءً على توصية طبيبكِ.') WHERE id = '43411138-1170-4057-8905-a104a8761813';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُظهر طفلكِ خلال هذه المرحلة سلوكيات عدوانية إلى حدّ ما. وقد تتمثل هذه السلوكيات في ضرب الآخرين أو عضّهم، أو قلب طبق الطعام، أو الدخول في نوبة غضب عندما لا تُلبّى رغبته. تنتج هذه السلوكيات عن عدم قدرة الطفل على إدارة مشاعره. في الواقع، يعرف الأطفال كيفية تنظيم مشاعرهم منذ ولادتهم، إلا أن بعض التصرفات الخاطئة قد تُضعف هذه القدرة. بعبارة أخرى، عندما تكبتين مشاعر طفلكِ، ولو من دون قصد، فإنه يتعلم إخفاءها أو التعبير عنها بطرق غير صحية. فعلى سبيل المثال، حتى لو كان أسلوبكِ صحيحًا، فإن طفلكِ إذا رأى منكِ سلوكًا عدوانيًا أو معاملة سلبية، فسيبدأ باعتبار ذلك أمرًا طبيعيًا. من المهم أن تكوني قدوة لطفلكِ، وأن تعبّري عن غضبكِ تجاه الآخرين بكلمات هادئة وتوضيحية بدلًا من الإساءة اللفظية.') WHERE id = '0102cad4-afdc-443f-9c50-810c77e5f6b0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تهانينا! لقد أتممتِ مع طفلكِ 26 شهرًا. أصبح طفلكِ الآن في عمر 26 شهرًا! في هذه المرحلة، بات يستطيع إمساك الكوب بيد واحدة بسهولة أكبر، كما يمكنه تناول بعض الأطعمة والمشروبات بمفرده. وأصبحت حركاته أكثر نشاطًا مقارنة بالأشهر السابقة ضمن مسار نموه البدني. فهو يستطيع الآن الركض واللعب بالكرة والقفز بسهولة. ولا تزال طاقته التي لا تنضب في أوجها. ومع بعض المحاولة، يمكنه ارتداء حذائه وجواربه وخلعهما بمفرده. كما يستطيع غسل يديه ووجهه وتنظيف أسنانه من دون مساعدتكِ. إذا كنتِ لا تزالين تفضّلين القيام بهذه المهام اليومية بدلًا منه، فقد حان الوقت لمنحه بعض الاستقلالية! :)') WHERE id = 'c1200e82-5b42-4c10-b000-d86a0a9bfcb9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يدخل نمو الطول والوزن لدى الأطفال في عمر 26 شهرًا مرحلة مختلفة مقارنة بالأشهر السابقة. باختصار، لقد تغيّر معدل نمو طفلكِ. لذلك، لا داعي للقلق إذا لم تلاحظي زيادة في وزنه على الميزان. بعد عمر السنتين، يميل وزن الأطفال إلى الاستقرار، بينما يستمر طولهم في الازدياد. وهذه عملية طبيعية تجعل بنية أجسامهم أقرب إلى بنية أجسام البالغين. وقد تؤدي زيادة الطول من دون زيادة الوزن إلى ظهور الطفل بمظهر أنحف. يتراوح وزن الفتيات في عمر 26 شهرًا بين 9600 غرام و15400 غرام، بينما يتراوح وزن الأولاد بين 10200 غرام و15900 غرام. إذا كان طول طفلكِ ووزنه ضمن هذه المعدلات الطبيعية، فلا داعي للقلق.') WHERE id = 'c91fefd7-5188-4567-b316-4d37d49bdc9f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يواجه صعوبة في اكتساب الوزن، فعليكِ أولًا الحد من تناوله مشروبات مثل الحليب وعصير الفاكهة والماء قبل الوجبة مباشرة أو في أثنائها. كذلك، إذا كان طفلكِ يتناول مشروبات لا تناسب عمره، مثل المشروبات الغازية والشاي، فيجب إيقاف ذلك فورًا. من المهم أن تحددي حجم الحصص التي تقدمينها لطفلكِ وفقًا لاحتياجاته، لا بحسب رغبتكِ أنتِ. إذا رفض طفلكِ الطعام الذي أعددتِه، يمكنكِ تقديم طبق آخر له. لكن إذا لم يرغب في تناول أي شيء في تلك الوجبة، فلا تجبريه. فالأطفال، مثل البالغين، قد يفقدون شهيتهم من وقت إلى آخر. إذا كان هذا الأمر يقلقكِ، فأعدّي له أطباقًا ملوّنة ومزيّنة تجذب انتباهه. ويمكنكِ شرح فوائد الأطعمة له من خلال الألعاب؛ وتذكّري أن منحه فرصة الاختيار أمر مهم للغاية.') WHERE id = '15c24f02-d146-4c26-955a-b36ec124d9fb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أتيناكِ بنشاط ممتع وتعليمي في آنٍ واحد لطفلكِ البالغ من العمر 26 شهرًا! :) يبدأ جميع الأطفال تقريبًا بالتعرّف إلى أجزاء الوجه منذ عمر سنة، ويصبحون بارعين في ذلك عند بلوغهم عمر السنتين. لممارسة هذه اللعبة، ستحتاجين إلى 5-6 أوراق A4 ملوّنة. قصّي من إحدى الأوراق شكل وجه وأعدّيه للنشاط (ويمكنكِ تلوين الورقة بلون البشرة إذا رغبتِ). بعد ذلك، قصّي من الأوراق الأخرى 3-4 أشكال مختلفة للأنف والفم والعينين والأذنين والحاجبين. لوّني هذه الأجزاء بالألوان التي تريدينها. قدّمي لطفلكِ أجزاءً مثل العينين والأنف والشعر والفم والشارب أو النظارات، واطلبي منه وضعها على قالب الوجه الفارغ بالطريقة التي يرغب بها. تتمنى لكِ عائلة Anacan وقتًا ممتعًا! :)') WHERE id = '030305b5-b63d-4484-a47e-c90776cee51b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يختلف كل طفل عن الآخر، ومن الطبيعي أن تتباين خصائص النمو بينهم. ومع ذلك، فإن متوسط المهارات التي يُظهرها الأطفال في العمر نفسه يضع بعض المعايير العامة في هذا الشأن. في المرحلة العمرية التي يمر بها طفلكِ، أي بين عمر سنتين و3 سنوات، يُفترض أن يصل متوسط حصيلته اللغوية إلى نحو 450 كلمة. ويبلغ الحد الأدنى لهذا العدد نحو 50 كلمة. باختصار، إذا كان طفلكِ ينطق أقل من 50 كلمة، فقد يكون ذلك علامة على تأخر النطق. وتأخر النطق حالة تستدعي استشارة اختصاصي من دون تأخير. فالأطفال الذين يُكتشف لديهم التأخر في سن مبكرة ويبدؤون العلاج مبكرًا يمكنهم تحقيق تقدم كبير خلال فترة قصيرة واللحاق بأقرانهم. إذا لم تكوني متأكدة من عدد الكلمات التي يستخدمها طفلكِ، فيمكنكِ تدوين الكلمات الواضحة والمختلفة التي ينطقها على مدار أسبوع، ثم إحصاؤها.') WHERE id = '6d292b09-fdd7-410b-a261-f55fbb6b64f8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج جسم طفلكِ إلى قدر من الملح، لكن هذه الحاجة ليست كبيرة خلال السنوات الأولى. لذلك، ينبغي عدم تعريف الأطفال بالملح خلال السنة الأولى من العمر، كما ينبغي ألا تكون ملّاحة الطعام موجودة على المائدة حتى بعد بلوغهم عامهم الأول. إن عدم تعويد طفلكِ على المذاق المالح والحلو هو أهم استثمار يمكنكِ القيام به لحمايته مستقبلًا من الأمراض المرتبطة بالملح والسكر. وبالنسبة إلى طفلكِ الذي تجاوز عمره عامين، يمكنكِ إضافة كمية قليلة من الملح المُدعّم باليود إلى طعامه، نظرًا إلى شيوع نقص اليود في بلدنا. يحتاج طفلكِ في هذه المرحلة إلى نحو 1-2 غرام من الملح يوميًا. وعلى الرغم من ازدياد الحاجة إلى الملح مع التقدم في العمر، فإنها لا تتجاوز عادةً 3-4 غرامات. ومن الأفضل أيضًا إضافة الملح إلى الطعام بعد طهوه حتى لا يتبخر اليود ويُفقد. وفي الوقت نفسه، احرصي على أن يتناول طفلكِ السمك والحليب ومنتجات الألبان واللحوم بصورة متوازنة لتلبية حاجته إلى اليود.') WHERE id = 'e16dcc56-eb7e-4fc3-973b-a0196af2cc6b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ، وقد بلغ الآن 25 شهرًا، يمتلك مهارات حركية دقيقة تمكّنه من تقليب صفحات الكتاب بسهولة عندما تعطينه إياه. كما تطورت قوته ومهارته بما يكفي لفتح أغطية الزجاجات أو البرطمانات عبر تدويرها. ويستمتع الأطفال في هذا العمر كثيرًا أيضًا بتشغيل وإطفاء الأزرار الموجودة على الأجهزة التي تحتوي على أزرار كثيرة، مثل التلفاز. تسعد هذه التطورات كل أم وأب، لكنها تجلب معها مخاطر جديدة ينبغي الانتباه إليها. فقد تعرّض مهارات طفلكِ الحركية المتقدمة وقوته المتزايدة سلامته للخطر في بعض الحالات. لذلك، لا تنسي وضع الأدوية ومواد التنظيف في أماكن لا يستطيع طفلكِ الوصول إليها. وإذا لم تتوفر لديكِ أماكن مرتفعة لحفظ هذه المواد الخطرة، فيمكنكِ استخدام أقفال أكثر متانة لضمان سلامته.') WHERE id = '68ecf8cd-54e7-4312-816c-db417c732ac3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الفطام أو التوقف عن الرضاعة الطبيعية من أكثر الموضوعات التي تشغل بال الأمهات خلال هذه المرحلة. إذا كنتِ لا تزالين ترضعين طفلكِ، فربما تبحثين بجدية عن طرق الفطام. تستمر هذه العملية بسعادة ما دمتِ ترغبين في إرضاع طفلكِ وهو يرغب في الرضاعة. لكن عندما تريد الأم التوقف عن الرضاعة لسبب ما بينما لا يكون الطفل مستعدًا بعد، فقد تصبح العملية صعبة للغاية. وعلى العكس، قد تظهر صعوبات أيضًا عندما يكون الطفل مستعدًا للفطام، بينما ترغب الأم في استمرار هذه الرابطة المميزة. ولتجاوز هذه العملية المرهقة بأقل قدر ممكن من الصعوبات، يمكنكِ تأجيل الفطام لبعض الوقت إذا دعت الحاجة. ويوصي بعض المتخصصين بأن تتخذ الأم وطفلها معًا قرار موعد التوقف عن الرضاعة الطبيعية، وأن يشعرا كلاهما بالاستعداد التام لذلك.') WHERE id = '5e6fd373-9ca1-43c3-bef0-2470cbfda2a2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع إتمام عامهم الثاني، يدخل الأطفال في عمر 25 شهرًا مرحلة قوية من إثبات الشخصية. وقد تتكرر خلال هذه الفترة سلوكيات غير مرغوب فيها، مثل فعل عكس ما يُطلب منهم تمامًا. وتُعرف "مرحلة العناد"، التي تسمى أيضًا "مراهقة الطفولة"، بأنها فترة تمتد بين عمر 2-4 سنوات، يتخذ فيها الأطفال مواقف عنيدة، ويفعلون ما يحلو لهم، ويواجهون صعوبة في التواصل، وكثيرًا ما تنتابهم نوبات بكاء للحصول على ما يريدون. حتى لو لم يُظهر طفلكِ سلوكًا عنيدًا من قبل، فقد تواجهين منه عنادًا شديدًا خلال هذه المرحلة. وهي محطة نمائية يبدأ فيها الأطفال بإدراك استقلالهم ومحاولة تأكيد شخصياتهم. وبوجه عام، تُعد هذه عملية مهمة وصحية لنمو شخصية الطفل. لكن أساليب الوالدين الخاطئة هي ما قد يدفع هذه العملية في اتجاه سلبي. لذلك، بدلًا من الضغط على طفلكِ دون داعٍ، من المهم جدًا أن تدركي أن هذه السلوكيات جزء من نموه وأن تتعاملي معه بتعاطف.') WHERE id = '263f0565-7a52-428a-8087-e11f47811c14';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد فقدان الشهية لدى الأطفال من أكثر المشكلات شيوعًا بعد عمر عام واحد، ويبلغ ذروته في نحو عمر عامين. ويعود ذلك إلى دخول طفلكِ مرحلة فقدان الشهية الفسيولوجي، نتيجة تباطؤ معدل نموه بعد إتمام عامه الأول. وباختصار، من الطبيعي تمامًا أن يمر طفلكِ بهذه المرحلة التي يمر بها جميع الأطفال. فمن الطبيعي أن ينخفض معدل زيادة وزن طفلكِ من 400 غرام شهريًا خلال عمر 6-9 أشهر إلى 200 غرام شهريًا بعد بلوغه عامًا واحدًا، بل قد لا يزداد وزنه إطلاقًا في بعض الأشهر. وهذه المرحلة، التي غالبًا ما يفسرها الوالدان على أنها “فقدان للشهية”، طبيعية في الواقع لدى معظم الأطفال. إذا لم يبقَ وزن طفلكِ ثابتًا لمدة طويلة، ولم يكن يفقد الوزن باستمرار، وكان فحصه السريري طبيعيًا، فلا حاجة إلى إجباره على تناول المزيد من الطعام. ويمكنكِ الحصول على معلومات أكثر تفصيلًا عبر مناقشة الحصص الغذائية الكافية لطفلكِ وجودة طعامه مع طبيبه.') WHERE id = '2530ccd6-7ee5-40e4-96e7-b2eaadf767b1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون طفلكِ في هذه المرحلة شديد الحماس والرغبة في مساعدتكِ في الأعمال المنزلية. لكن هل تعلمين أنكِ تستطيعين الإسهام في نموه أيضًا عندما توكلين إليه بعض المهام؟ على سبيل المثال، يُعد طي الملابس وكيّها بعد غسلها من الأعمال التي تُنجز في كل منزل. ويمكن أن يكون نشاط مطابقة الجوارب وتكوين أزواج منها ممتعًا لطفلكِ، كما يمنحه شعورًا بأنه يساعدكِ. ويتيح هذا النشاط لطفلكِ أيضًا استخدام حواسه بفاعلية، ويُعد وسيلة رائعة لتنمية مهاراته الحركية الدقيقة. لتنفيذ النشاط، ضعي جميع الجوارب مختلطة على الأرض واطلبي من طفلكِ العثور على كل زوج متطابق. ودعيه يناولكِ الأزواج كلما عثر عليها لتطويها أنتِ. وهكذا يتعلم طفلكِ وتخفّ أعباؤكِ المنزلية في الوقت نفسه! :)') WHERE id = '16247942-6521-4d3c-b412-05d1285066ab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تتسخ يدا طفلكِ باستمرار خلال هذه المرحلة بسبب رغبته في استكشاف كل شيء. وهذا جزء من نموه، لذا لا ينبغي لكِ منعه. ورغم سهولة الحفاظ على النظافة في المنزل، فقد تحتاجين كثيرًا إلى استخدام الجل المضاد للبكتيريا خارج المنزل. ويُعد هذا الجل بديلًا جيدًا في الأماكن التي لا يتوفر فيها الماء والصابون. لكن تذكّري أن هذه المنتجات تحتوي على نسبة عالية من الكحول ومواد سامة. لذلك، لا تضعي عبوة الجل في يد طفلكِ أبدًا. وعند الحاجة، يمكنكِ وضع 1 قطرة منه في راحة يده ومساعدته على فرك يديه. لا تسمحي لطفلكِ بشم يديه بعد استخدام الجل، لأن ذلك قد يهيّج جهازه التنفسي. كما أن الجل المضاد للبكتيريا قد يهيّج العينين أيضًا، لذا امنعي طفلكِ من فرك عينيه. وإذا لامس الجل عينه عن طريق الخطأ، فاغسليها فورًا بكمية وفيرة من الماء.') WHERE id = '611311a5-f1da-4044-901d-5e129a858e3b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي تمامًا أن يفقد طفلكِ بعض الوزن خلال هذه المرحلة، شأنه في ذلك شأن أقرانه. ولكن لضمان عدم تباطؤ نموه وحصول جسمه على أفضل قدر من العناصر الغذائية التي يحتاج إليها، ينبغي لكِ إعادة النظر في نظامه الغذائي. ومن المهم أن تتضمن الوجبات التي تحضّرينها أطعمة غنية بالألياف والبروتين. يمكنكِ تجنّب الأطعمة شديدة الدسم لفترة، لكن هذا لا يعني أن يكون نظامه الغذائي "خاليًا من الدهون" تمامًا؛ فالدهون من المغذيات الكبرى الضرورية جدًا لنمو طفلكِ الجسدي والعقلي. والمهم أن تأتي هذه الدهون من مصادر صحية. فعلى سبيل المثال، يُعد الأفوكادو والسمك مصدرين ممتازين للدهون الصحية. ويسهم السمك بدرجة كبيرة في نمو طفلكِ بصورة صحية بفضل غناه بالمعادن وأوميغا-3.') WHERE id = '5c08add0-1273-45c1-b0fd-3449a7f6de9c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما تلاحظين الآن أن طفلكِ أصبح قادرًا على اللعب بألعابه بمفرده والتحكم في جسمه بصورة أفضل. ونتيجة لذلك، بات يستطيع استخدام أدوات مختلفة ويُظهر اهتمامًا بألعاب أكثر تعقيدًا. ولن تقل متعتكِ بالمشاركة في هذه العملية عن متعتكِ بمتابعة هذا التطور الرائع. يمكنكِ باستخدام أغراض بسيطة متوفرة لديكِ إعداد العديد من الأنشطة المفيدة لنمو طفلكِ الجسدي والعقلي. فعلى سبيل المثال، عندما تخرجان معًا، يمكنكما ممارسة لعبة "البحث عن الألوان". وستستمتعان كثيرًا بالتنافس في العثور على نباتات أو أغراض بالألوان التي تحددانها. ويمكنكما أيضًا تصفح صور العائلة القديمة والطلب منه تخمين شكل أقاربه عندما كانوا أطفالًا. ومن الأفكار الرائعة أيضًا بناء حصون للعب باستخدام كراسي المنزل والشراشف، أو إقامة خيمة سرية تحت الطاولة.') WHERE id = '08464b0f-495b-4181-afc5-ae0e47bd6f76';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكون أحكام طفلكِ خلال هذه المرحلة حادة وقاطعة إلى حد كبير. فقد يرى الشخص، مثلًا، إما جيدًا تمامًا أو سيئًا تمامًا. وكما لا يتصور أن الأشخاص الجيدين قد تكون لديهم جوانب سلبية، فإنه لا يتقبل أيضًا وجود جوانب إيجابية لدى من يراهم سيئين. لذلك، قد يتعامل مع بعض الأشخاص ببرود وتحفّظ شديدين. وعلى العكس من ذلك، يكون ودودًا ودافئًا للغاية مع الأشخاص الذين يحبهم. تذكّري أن هذا السلوك شائع لدى جميع الأطفال في عمره، ولا ينبغي لكِ إجباره على شيء. إذا كان طفلكِ لا يحب شخصًا ما لسبب ما، فإن الضغط عليه للتقرب منه قد يزيد الوضع صعوبة. ولكن إذا لاحظتِ أن طفلكِ يتعامل عمومًا مع الجميع ببرود مفرط، فمن المفيد استشارة مختص.') WHERE id = '4eec5008-4918-434b-9083-b409f329d305';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون طفلكِ في هذه المرحلة شديد العناد ومُصرًّا على تنفيذ ما يريده. ورغم أن هذا السلوك قد يضعكِ أحيانًا في موقف صعب، فإن القاعدة الذهبية للتعامل مع مشاكسة الأطفال هي تحويل انتباههم إلى شيء آخر. فغالبًا ما يصنع قولكِ: "تعال لنلعب معًا!" بدلًا من "لا تفعل ذلك!" المعجزات. بالطبع، قد لا يتوفر لديكِ في كل مرة الوقت أو الصبر لتوجيهه نحو نشاط آخر. لكن لا تظني أنكِ مضطرة إلى قضاء ساعات معه في النشاط الجديد؛ إذ يكفي أن تنشغلي معه لمدة 5-10 دقائق فقط حتى يخف عناده ويندمج في اللعب. باختصار، حاولي كلما أمكن أن يكون تشتيت انتباهه هو أسلوبكِ الأول.') WHERE id = '406f94ca-8e7c-4eb0-ba29-320528d7f38a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين لدى طفلكِ خلال هذه المرحلة فقدانًا واضحًا للشهية. ووفقًا لكثير من الأطباء، غالبًا ما يكون فقدان الشهية لدى الأطفال ناتجًا عن عادات غذائية غير صحيحة، ولا يُعد مرضًا في حد ذاته. لذلك، لا تقلقي. ولكن إذا أصبح فقدان الشهية مزمنًا واستمر لأكثر من 3 أسابيع، فيُنصح بمراجعة الطبيب؛ فقد تكون وراء فقدان الشهية طويل الأمد بعض العدوى أو مشكلات صحية أخرى. وإذا كانت المشكلة مرتبطة بعادات غير صحيحة، فانتبهي إلى بعض التفاصيل. فقد لا يحب طفلكِ بعض الأطعمة مثلًا؛ وفي هذه الحالة، قدّمي له بدائل بدلًا من إجباره على تناولها. فإذا كان لا يحب السبانخ، يمكنكِ تقديم اللحوم أو الحليب أو البيض أو السمك له، حتى يحصل من مصادر أخرى على الحديد والفيتامينات التي لا يحصل عليها من السبانخ.') WHERE id = 'c34bd107-e494-44f0-ad8f-0d26c2cab8c1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ طفلكِ منذ هذه الأشهر بفهم الفروق بين الجنسين. ويمكن القول إنه بلغ من النضج ما يسمح له بإدراك وجود بعض الاختلافات بين النساء والرجال. لذلك، قد تظهر لدى بعض الأطفال سلوكيات مختلفة ناتجة عن إدراك هذه الفروق. فمثلًا، قد يغضب من أحد الجنسين أسرع من الآخر، أو يتصرف بعصبية دون سبب واضح. وقد يشعر أيضًا بالخجل أو التحفظ تجاه أحد الجنسين، أو على العكس، يتعامل معه بألفة أكبر. لكن هذا أمر طبيعي تمامًا خلال مراحل النمو. وبدلًا من القلق، راقبي سلوكيات طفلكِ وناقشي مع زوجكِ كيفية الحد من هذه التصرفات قدر الإمكان، وكيفية حل أي مشكلة قد تنشأ بأبسط طريقة. فأنتِ أكثر من يعرف طفلكِ، وأنتِ الأقدر على إيجاد الحل الأنسب.') WHERE id = 'a2a1f8bf-e46d-4735-b6ff-cfa1846c3118';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'جميع مواعيد وجبات طفلكِ وما يتناوله مهمان للغاية، لكن لوجبة الإفطار مكانة خاصة بينها. فالإفطار ضروري للجميع من أجل حياة صحية، لأن الجسم يستهلك قدرًا كبيرًا من الطاقة بعد وجبة العشاء. وعدم تناول أي طعام أثناء النوم حتى الصباح قد يبطئ إنتاج الجسم للطاقة. لذلك، تُعد وجبة الإفطار أفضل فرصة لتعويض الطاقة المستهلكة خلال الليل. وهكذا، سيبدأ صغيركِ يومه بمزيد من النشاط والحيوية، ويحصل على "الوقود" اللازم لحركته طوال اليوم. كما أن نوعية الأطعمة المتناولة في الإفطار لها أهمية خاصة. فتناول طفلكِ البيض ومنتجات الألبان يلبّي جزءًا كبيرًا من احتياجاته اليومية. ويُعد البيض على وجه الخصوص غذاءً مميزًا يجمع عددًا كبيرًا من العناصر الغذائية القيّمة بعد حليب الأم.') WHERE id = 'f7cb97a9-2f7f-4a20-87e3-acdb8e3339f0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يظل طفلكِ يعاني بشدة من مظاهر مرحلة العامين. ويتأثر بعض الأطفال بهذه المرحلة أكثر من غيرهم، وقد تظهر بينهم سلوكيات غير مرغوب فيها مثل العض. إذا كان صغيركِ يعض أو يضرب أو تنتابه نوبات غضب مفاجئة، فمن المهم أولًا أن تتحلي بالصبر والهدوء. تذكّري أن هذا السلوك هو في الواقع وسيلة يستخدمها طفلكِ للحصول على شيء يريده. ومن المهم جدًا لنموه العاطفي السليم أن تتعاملي بوضوح وحزم مع سلوكيات العض أو الضرب. وإذا لم يتمكن طفلكِ من التعبير عن مشاعره بالكلمات، فيمكنكِ أنتِ أو والده التعبير عنها نيابةً عنه. في مثل هذه المواقف، يمكنكِ استخدام عبارات مثل: أنت غاضب جدًا، أليس كذلك؟ حتى يشعر بأنكِ تفهمينه.') WHERE id = '067c1fbe-4e1e-4749-96ff-19097dcc209e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد قطع النمو الذهني لطفلكِ شوطًا كبيرًا مقارنة بمرحلة ولادته، لكنه لا يزال غير قادر على التمييز تمامًا بين الكائنات الحية والأشياء الجامدة. فمثلًا، قد يتصور الشمس والقمر بالطريقة نفسها التي يتصور بها الإنسان. وباختصار، يُعد النظر إلى الأشياء الجامدة كما لو كانت حية من السمات المميزة لهذه المرحلة. وإذا كسر لعبة أو مزهرية، فقد يظن أن المزهرية نفسها أرادت أن تنكسر. ويرجع ذلك أيضًا إلى أن إدراكه للواقع لم يكتمل بعد. ومع استمرار نموه الذهني، سيفهم العالم من حوله بصورة أدق. ويمكنكِ تقديم أكبر دعم لهذا التطور من خلال الإجابة عن أسئلته التي لا تنتهي، مثل ماذا وكيف ولماذا، باهتمام وصبر وعناية كبيرين.') WHERE id = '77742548-5dac-44f3-becd-3cd309b83f2b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أبرز سمات المرحلة الحالية من نمو طفلكِ كثرة طرحه للأسئلة. وقد يدهشكِ أنه يفكر في تفاصيل حول كل موضوع ربما لم تخطر ببالكِ، ثم يطرح أسئلة عنها. وأحيانًا قد يفعل طفلكِ ذلك لمجرد جذب الانتباه، وغالبًا ما تكون الأسئلة التي يطرحها لهذا الغرض أقل منطقية. لكن مهما بلغ عدد أسئلته أو بدت غير منطقية أو متكررة، فلا توبّخي طفلكِ أبدًا بسبب كثرة سؤاله. حاولي الإجابة عنه بأبسط طريقة وأكثرها منطقية لدعم نموه الذهني. ومع تزايد الأسئلة، قد ترغبين في التهرب من الإجابة، لكن تذكّري أن ذلك خطأ كبير من ناحية نموه. تحلّي بالصبر قدر الإمكان؛ فما زلتِ في بداية الطريق. :)') WHERE id = '272f9de9-ae5a-4eb4-b4f0-09f249a69a3c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج الأطفال إلى طاقة أكبر من البالغين لأنهم كثيرو الحركة. وبما أنهم يمرون بمرحلة نمو سريع، فينبغي أن يحصلوا على كميات كافية من الفيتامينات والمعادن الضرورية لأجسامهم. تُعد الفترة حتى بلوغ طفلكِ سن الخامسة من أكثر المراحل نشاطًا في تطوره المعرفي والحركي والبصري. ويساعد حصوله على كميات كافية من جميع المجموعات الغذائية على دعم سلامة وظائف خلايا الدماغ والأعصاب، وقد يساهم في الحد من بعض المشكلات المرتبطة بنقص الانتباه وفرط الحركة. كما يدعم النظام الغذائي المتوازن النمو الذهني والقدرة على التعلم. ويساعد تناول الدهون الصحية بانتظام، على وجه الخصوص، في الحفاظ على سلامة خلايا الدماغ وتسهيل التواصل بين الخلايا العصبية. وقد ينعكس ذلك إيجابًا على الحالة النفسية لطفلكِ ويساعد على تقليل نوبات العناد والعدوانية.') WHERE id = '957a986d-ee56-489a-b467-9bed2d7b4892';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكتسب جميع الوجبات والحصص التي يتناولها طفلكِ خلال اليوم أهمية كبيرة لنموه الصحي. وفي هذا السياق، يمكنكِ أن تقدّمي له في وجبة الإفطار 2/3 كوب من الحليب، وبيضة واحدة أو قطعة جبن بحجم علبة كبريت، وملعقة صغيرة من الزبدة، و1-2 ملعقة صغيرة من المربى / العسل / الدبس / معجون البندق، و2-3 حبات من الزيتون. بالإضافة إلى ذلك، يمكنكِ تقديم شريحة رقيقة من خبز الحبوب الكاملة وبضع شرائح من الطماطم أو اليوسفي كخيارات بديلة. وفي وجبة الغداء، تكفي 4-5 ملاعق كبيرة من طبق خضراوات باللحم المفروم، و1-2 ملعقة كبيرة من الأرز، وملعقتان كبيرتان من الزبادي. أما في وجبة العشاء، فتُعد قطعة كفتة واحدة مع وعاء من شوربة العدس أو نصف شريحة من الخبز خيارًا جيدًا. وإلى جانب الوجبات الرئيسية، يمكنكِ تقديم وعاء من الزبادي، وثمرة فاكهة صغيرة، و2-3 قطع من البسكويت المنزلي، والمكسرات، وحليب المتابعة كوجبات خفيفة. ومن النقاط التي ينبغي الانتباه إليها في هذه القائمة: إزالة نوى الزيتون وسحق المكسرات قليلًا حتى لا تشكّل خطر الاختناق.') WHERE id = 'f17d2eda-9f54-40f8-8442-4a42173f4c40';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمتلك طفلكِ حاليًا طاقة مذهلة وعالمًا مليئًا بالفضول. فتفاصيل الحياة اليومية التي تبدو عادية بالنسبة إليكِ تمثّل له مغامرة كبيرة تنتظر أن يكتشفها. لذلك، لا ينبغي أن تقيّدي طفلكِ باستمرار بقول «لا!». فالأطفال يحتاجون إلى المرح والحرية ما لم توجد ضرورة حقيقية لتقييدهم. وعندما يكتشف طفلكِ العالم، سواء أثناء اللعب أو المشاغبة، ينبغي أن تستندي إلى 3 معايير قبل أن تقولي له «لا»: هل يسبّب ما يفعله ضررًا لشخص آخر؟ هل ما يفعله خطير حتى تحت الإشراف؟ هل ما يفعله مزعج فعلًا أو غير أخلاقي؟ فكّري في هذه الأسئلة، وحلّلي عدد المرات التي تقولين فيها «لا» لطفلكِ خلال اليوم، وما إذا كانت هذه القيود ضرورية حقًا.') WHERE id = '67f098da-7fda-41a8-92dc-91e2b7af2b79';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تشعرين بالقلق كثيرًا لأنكِ تظنين أن طفلكِ فقد بعض الوزن أو لم يعد يبدو مفعمًا بالنشاط كما كان. لكن تذكّري أن وتيرة نمو كل طفل تختلف عن غيره وترتبط بإمكاناته الوراثية. إذا لاحظتِ تعثرًا في نمو طفلكِ أو فقدانًا شديدًا جدًا للشهية، فإن استشارة الطبيب هي الخطوة الأنسب. ابدئي بعرضه على طبيب الأطفال الذي تراجعينه بانتظام. وإذا كانت نتائج الفحص طبيعية وكان نمو طول الطفل ووزنه وفق مخططات النمو المئينية مناسبًا لعمره، فتحدثي مع الطبيب عن مكونات الطعام وحجم الحصص. ينبغي تحديد كمية الطعام التي يتناولها الطفل بحسب احتياجاته، لا بحسب الكمية التي ترضيكِ. وإذا ترافق فقدان الشهية مع تباطؤ في معدل النمو وهبوط على منحنى النمو، فيمكن البحث عن الأسباب بإجراء تعداد دم كامل، وتحليل للبول، وغيرها من الفحوص التي يراها الطبيب ضرورية.') WHERE id = 'eecab972-e990-4a43-b73c-ca756216bc2e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك العديد من الطرق والمؤشرات المختلفة التي تساعدكِ على معرفة مدى استعداد طفلكِ لاكتساب عادة استخدام المرحاض. ومن أهمها أن يفهم طفلكِ التعليمات البسيطة التي توجّهينها إليه وأن يتمكن من تنفيذها. فالتواصل يؤدي دورًا بالغ الأهمية في التدريب على استخدام المرحاض، ولذلك من الضروري أن يكون طفلكِ قادرًا على فهم كلامكِ تمامًا. كذلك، إذا كان طفلكِ ينزعج من اتساخ حفاضه ويبلغكِ بذلك فورًا عن طريق الإشارة أو الكلام، فهذا يدل أيضًا على استعداده للتدريب على استخدام المرحاض. ويبدأ الأطفال في عمر 2 تقريبًا عادةً بإبداء الاهتمام بما يفعله الكبار في المرحاض. فهذا موضوع يثير فضول طفلكِ، ولذلك لا ينبغي أن تلوميه أو توبّخيه. إذ يُعد هذا الفضول علامة أخرى على استعداد طفلكِ للتدريب على استخدام المرحاض.') WHERE id = '7e8892e7-dddb-4acc-8056-5a75077c9cb9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد أنشطة مونتيسوري مهمة جدًا لنمو طفلكِ. وفي هذه المرحلة، نقدّم لكِ نشاطًا من أنشطة مونتيسوري يمكنكِ تنفيذه انطلاقًا من الأعمال المنزلية اليومية! :) ابدئي بدعوة طفلكِ للوقوف بجانبكِ أثناء تفريغ غسالة الصحون، واسأليه إن كان يرغب في مساعدتكِ. فجميع الأطفال تقريبًا في عمر 2 متحمسون للمساعدة. ولكن إذا لم يرغب طفلكِ في ذلك، فلا تجبريه. بعد إبعاد الأدوات الحادة والقاطعة، يمكنكِ إعطاء طفلكِ السلة التي تحتوي على الشوك والملاعق. واطلبي منه وضع الشوك والملاعق في أماكنها الصحيحة داخل درج المطبخ. وبعد بضع محاولات، ستندهشين من مدى نجاح طفلكِ في أداء هذه المهمة. كما سيساعده ذلك على تنمية مهارات التجميع والتصنيف لديه.') WHERE id = 'a21412bd-7f9d-4cd0-8052-99c4370e5744';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد مرحلة عمر 2 التي يمر بها طفلكِ حاليًا فترة يشيع فيها كل من فقدان الشهية وزيادة الوزن والسمنة. والتغذية عادة مكتسبة، لذلك من المهم جدًا أن تساعدي طفلكِ على اكتساب عادات غذائية سليمة. وقد تسهم العادات الغذائية الصحية التي ترسّخينها في هذا العمر في وقاية طفلكِ من كثير من الأمراض التي قد تظهر في السنوات المقبلة. ولكي تكسبيه عادات صحيحة، من الضروري أن تكوني قدوة له. وتتطلب الزيادة الأخيرة في حالات السمنة إيلاء مزيد من الاهتمام للعادات الغذائية. وغالبًا ما تبدأ السمنة في هذا العمر بسبب الأطعمة غير الصحية وقلة الحركة. ينبغي أن يكون هدفكِ الأساسي الوقاية من السمنة قبل حدوثها. وعليكِ معرفة الوزن المناسب لطول طفلكِ، وتنظيم روتينه اليومي ونظامه الغذائي وفقًا لذلك.') WHERE id = '0c5e42c2-ff51-4921-be51-98211c1fde6d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، أصبح طفلكِ قادرًا على تلبية بعض احتياجاته الشخصية بصورة مستقلة. ومن أوضح المؤشرات على ذلك قدرته على خلع حذائه وجواربه دون مساعدة. وقيامه بهذه الأمور بمفرده يعزز ثقته بنفسه. كذلك ستتطور لديه عادات النظافة الشخصية، مثل تنظيف أسنانه وغسل يديه. وسيساعده تشجيعكِ في هذا الاتجاه على الاعتياد على النظافة بسرعة أكبر. فالعادات التي يكتسبها في سن مبكرة تمكّنه مستقبلًا من تبنّي السلوكيات المقبولة اجتماعيًا بسهولة أكبر. وفي الواقع، تُرسى أسس شخصيته المستقبلية في هذه المرحلة تحديدًا. لذلك، عليكِ توخي الكثير من الانتباه خلال هذه الفترة لتعليمه السلوكيات الصحيحة والخاطئة بطريقة سليمة.') WHERE id = '1cf45b6a-65d5-41da-a06e-3f002349179b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتناول طفلكِ في بعض الأيام طعامًا أكثر مما تتوقعين. فلا تحرميه من الطعام ظنًا منكِ أنه قد شبع بالفعل. فالأطفال النشطون الذين يمرون بمرحلة نمو قد يتناولون في بعض الأيام كمية من الطعام تساوي ما يتناوله البالغون، ومع ذلك لا يكتسبون عادةً وزنًا زائدًا. لكن الأطعمة غير الصحية قد تؤدي إلى زيادة الوزن والخمول. وتُعد الوجبات الخفيفة مهمة لنمو طفلكِ بقدر أهمية الوجبات الرئيسية. تتجنب بعض الأمهات تقديم الفاكهة بين الوجبات خشية أن تقل شهية الطفل. لكن المدة بين الوجبات الرئيسية طويلة، وقد يشعر الأطفال خلالها بالجوع ويحتاجون إلى الطاقة. وتلبّي الوجبات الخفيفة هذه الحاجة، كما تمنع الطفل من الوصول إلى الوجبة التالية وهو شديد الجوع والإفراط في الأكل بما يرهق معدته. وهذا مفيد جدًا لجهاز طفلكِ الهضمي.') WHERE id = '576b4ad4-9092-4186-be86-eba5187c22f3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تحسنت قدرة طفلكِ على التعبير عن نفسه بدرجة كبيرة مقارنة بالسابق. لكن هذا لا يعني أن قدراته اللغوية قد اكتملت تمامًا. ففي هذه المرحلة، يرى الأطفال أنفسهم محور كل شيء. وخلال هذه المرحلة التي تُسمى «التمركز حول الذات»، لا يراعون بعد احتياجات الآخرين. وقد يلجأ طفلكِ إلى طرق مختلفة للتعبير عن رغباته ومشاعره. وأحيانًا قد تكون هذه الطرق سلوكيات غير مرغوب فيها، مثل ضرب شخص ما أو عضّه. وفي مثل هذه الحالات، عليكِ الحفاظ على هدوئكِ وشرح سبب خطأ هذا السلوك بلغة يفهمها طفلكِ، من دون إصدار أحكام عليه.') WHERE id = '1916c84e-aa52-46dc-a413-ae73bae1219c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه الفترة أن طفلكِ يهتم وقت تناول الطعام وبقائه إلى المائدة بكل شيء عدا الطعام نفسه. لذلك، لا ينبغي أن تلوميه، بل عليكِ الانتباه إلى بعض التفاصيل الدقيقة حتى لا يتحول وقت الطعام إلى معاناة. أولًا، احرصي على ألا يستغرق تناول الطعام وقتًا طويلًا أكثر من اللازم، لأن الأطفال يشعرون بالملل بسرعة ولا يحبون الوجبات الطويلة إطلاقًا. كذلك، قد لا يحب طفلكِ جميع الأطعمة. فعلى سبيل المثال، لا ينبغي أن تضغطي عليه ليأكل الكرفس. لكن يجب ألا يدفعه ذلك أيضًا إلى تناول الأطعمة غير الصحية. ولتجنب ذلك، حضّري وجبات خفيفة صحية في المنزل، وإلا فقد يطلب الأطعمة التي يراها خارج المنزل. ويمكنكِ الحد من تشتت انتباه طفلكِ من خلال مشاركة جميع أفراد الأسرة في تناول الطعام. فرؤيته الجميع يتناولون طعامهم ستجعل هذه العملية أسهل بالنسبة إليه أيضًا.') WHERE id = '4f28c186-22d8-43cc-bc2e-3b3c3bfa0f2b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، يكون معظم الأطفال نشطين إلى حد كبير من ناحية الكلام، ويُتوقع منهم تكوين جمل مكونة من 3-4 كلمات. وإذا كنتِ تشكين في أن كلام طفلكِ غير كافٍ، فمن المفيد أن تتعرفي بمزيد من التفصيل على مفهوم تأخر النطق. ويُقصد بالأطفال المتأخرين في الكلام أولئك الذين تتراوح أعمارهم بين 18-36 شهرًا، ولا يواجهون مشكلة في الفهم، لكنهم لا يتكلمون أو يتحدثون بدرجة أقل من المتوقع لأعمارهم. ويُظهر هؤلاء الأطفال نموًا مماثلًا لأقرانهم في مجالات أخرى، مثل اللعب والمهارات الحركية والتفكير. ولكل طفل سرعة وأسلوب خاصان به في التعلم، كما أن الفروق الفردية في تطور اللغة طبيعية. ومع ذلك، يُتوقع من الأطفال اكتساب مهارات معينة ضمن مراحل عمرية محددة. وعندما يتعلق الأمر بمهارات النطق واللغة، فمن المهم ألا تتجاوز الفروق الفردية بين الأطفال 3-4 أشهر.') WHERE id = 'acc902b1-927f-42d0-8f73-ca7698f89eab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يبدأ بالبكاء عند سماع بكاء رضيع آخر، حتى عندما كان لا يزال حديث الولادة، فهذا يضع أساس قدرته على التعاطف. وينبع هذا التصرف من إحساسه بانزعاج رضيع آخر. لكن لا يزال من المبكر في هذا العمر الحديث عن تعاطف واعٍ تمامًا. وإذا كان عمر طفلكِ بين 12-18 شهرًا، فقد يستطيع فهم أن تعبيرات الوجه المختلفة تعكس مشاعر مختلفة؛ أي إنه يدرك غضبكِ أو حبكِ أو حزنكِ. وفي هذه الأشهر تقريبًا، يبدأ أيضًا في إدراك أن مشاعره وأفكاره قد تختلف عن مشاعر الآخرين وأفكارهم. ويشير ذلك إلى بدء تطور قدرته على وضع نفسه مكان الآخرين، أي التعاطف. وبالطبع، لا يمكن بعد توقع أن يتصرف واضعًا مشاعر الشخص المقابل له قبل مشاعره الخاصة.') WHERE id = '213fc964-930a-472e-84f6-21113ae224d3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بسبب مشاغل الحياة اليومية وضغوطها، يفوّت كثير من الآباء والأمهات مراحل مهمة في حياة أطفالهم الذين يتصرفون بعدوانية. وغالبًا ما يسمح الوالدان، رغبةً منهما في تهدئة غضب الطفل بسرعة، بأن يستغلهما من خلال تلبية كل ما يريده. إذا كان طفلكِ يُظهر مثل هذه السلوكيات، فلا تلبّي طلبه في اللحظة نفسها، لأن ذلك خطأ كبير. فعندما يرى طفلكِ أنه حصل على ما يريد، سيحوّل السلوك العدواني إلى عادة. لا ينبغي لكِ الاستسلام لعدوانيته. ومن المهم جدًا أن تخصّصي له وقتًا وتُشعريه باهتمامكِ به وبأنكِ تحاولين على الأقل فهمه ومساعدته. حاولي تحويل انتباهه إلى شيء آخر وإيجاد طرق تساعده على التعبير عن نفسه بصورة أفضل. وهذه هي الطريقة الأنسب لتربية الأطفال الذين يتصرفون بعنف أو يضربون الآخرين.') WHERE id = 'f625e959-60b5-495d-a840-b56855c25995';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد اجتزتِ مع طفلكِ 27 شهرًا. تهانينا! خلال هذه المرحلة، يمكنكِ ملاحظة ازدياد قدراته الإدراكية بشكل ملحوظ إلى جانب نموه الجسدي. ويُعد التقليد إحدى أهم طرق التعلّم لديه، لذلك سيقلّد كل حركة تقومين بها. ولهذا ينبغي لكِ الانتباه أكثر إلى تصرفاتكِ أمامه. يمكنكِ الآن تكليفه ببعض المهام، مثل جمع الألعاب التي بعثرها، أو خلع حذائه، أو إحضار نعليكِ المنزليين. اشرحي له هذه المهام عمليًا من خلال توضيح كيفية تنفيذها، وأشعريه بتقديركِ وشكركِ عندما ينجزها. شجّعيه أيضًا على العناية بنفسه؛ إذ يمكنه الآن القيام ببعض الأمور بمفرده، مثل تنظيف أسنانه وغسل يديه. لكن لا تتوقعي منه أداء مهام تفوق قدراته، لأن شعوره بالفشل قد يُفقده الحماس.') WHERE id = 'b44114a4-c08d-4b3e-a2d0-1cd68b02620c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا لمخطط النسب المئوية للنمو، يبلغ متوسط وزن الأولاد بعمر 27 شهرًا 13.100 غرام، بينما يبلغ متوسط وزن البنات في العمر نفسه 12.500 غرام. ويتراوح الوزن الآمن للأولاد بعمر 27 شهرًا بين 10.700 غرام و16.200 غرام، وللبنات بين 10.400 غرام و15.700 غرام. وفي هذه المرحلة، يبلغ متوسط طول الأولاد 90 سم، ومتوسط طول البنات 88,5 سم. ويُعد نطاق الطول الآمن للأولاد 83 سم–97 سم، وللبنات 81,5 سم–95 سم. ويبلغ متوسط محيط الرأس لدى الأولاد بعمر 27 شهرًا 49 سم، ولدى البنات 47,8 سم. إذا كان وزن طفلكِ أو طوله أو محيط رأسه خارج هذه النطاقات، فيمكنكِ استشارة طبيبكِ بشأن ذلك.') WHERE id = '70fc133b-03bd-43e1-aada-df82f087d242';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكون الجهاز الهضمي خلال مرحلتي الرضاعة والطفولة شديد الحساسية تجاه مسببات الحساسية. وتختفي في السنوات اللاحقة أنواع كثيرة من الحساسية التي تظهر، خصوصًا قبل عمر سنة. وفي هذه المرحلة، يكون طفلكِ أكثر تحمّلًا لمسببات الحساسية مقارنةً برضيع يبلغ من العمر 6 أشهر. إلا أن حساسية الغلوتين ازدادت بشكل ملحوظ في السنوات الأخيرة. وهي حساسية وراثية المنشأ تصيب الأمعاء الدقيقة، وتنشأ استجابةً لمادة الغلوتين الموجودة في القمح والشعير والشوفان وغيرها من الحبوب. وبما أن الغلوتين يتلف الزُغابات الموجودة في الأمعاء الدقيقة، فلا يستطيع جسم الطفل امتصاص العناصر الغذائية الضرورية، ما يؤدي إلى حدوث مشكلات في الجهاز المناعي. إذا ظهرت على طفلكِ بعد تناول أطعمة تحتوي على الغلوتين أعراض مثل القيء أو الإسهال أو انتفاخ البطن أو فقدان الشهية أو تأخر النمو، فقد يُشتبه في إصابته بحساسية الغلوتين.') WHERE id = 'eb1b2068-46a0-49bb-b797-caac49ade7df';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون العودة إلى العمل وتحديد ما إذا كان الطفل مستعدًا للالتحاق بالحضانة مرحلة مرهقة للأمهات العاملات. وفي السنوات الأخيرة، ازدادت الحاجة إلى مؤسسات التعليم قبل المدرسي لأسباب تربوية واقتصادية. لكن إذا لم تكن هناك ظروف استثنائية، يوصي الخبراء بألّا ينفصل الأطفال عن البيئة الأسرية قبل عمر 2.5 - 3 سنوات، لأن ما يحتاج إليه الطفل في هذا العمر أولًا ليس الحضانة، بل دفء الأسرة. وقد يتعرض الطفل الذي يُرسل إلى الحضانة قبل بلوغ مستوى كافٍ من النضج الجسدي والعقلي والعاطفي لأذى نفسي، وقد تستمر الآثار السلبية لهذا القرار سنوات طويلة. لذلك، تأكدي من استعداد طفلكِ للالتحاق بالحضانة ولا تتسرعي في اتخاذ هذا القرار.') WHERE id = 'a4e9b2f0-988c-4121-83d2-5b078dc54a4e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ إكساب طفلكِ عادة تناول الطعام بانتظام وثقافة التغذية الصحية، لكن لا يصح فعل ذلك بالضغط والإجبار. فالنظام المفروض بالقوة لا ينجح على المدى الطويل. ولترسيخ عادات غذائية صحية، ينبغي لكما أولًا، بصفتكما الوالدين، الاهتمام بنظامكما الغذائي، لأن الطفل ينمو وهو يقلّد أمه وأباه. وإذا لم تكن هناك ثقافة للتغذية الصحية في المنزل، فمن الصعب أن يتصرف الطفل بطريقة مختلفة. ويبدأ النظام الغذائي المتوازن بتناول وجبات منتظمة. قد يرفض طفلكِ تناول الطعام أحيانًا لأنه يعتبره مضيعة للوقت. وسيساعد تحديد مواعيد ثابتة للوجبات في المنزل طفلكِ على فهم النظام والانضباط وأهمية تناول الطعام.') WHERE id = '6d888f31-72fe-4046-b79d-3d045211080a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'طفلكِ الآن في ذروة سعيه إلى الاستقلال، وقد يدفعه ذلك إلى رفض بعض الخضراوات. يقول بعض الآباء إن أطفالهم يظنون أن كل ما هو أخضر خضراوات وأن مذاقه سيكون سيئًا. إذا كنتِ تواجهين هذا الموقف أيضًا، فحاولي لبعض الوقت إبعاده عن هذه الفكرة. ويمكنكِ فعل ذلك باستخدام خضراوات أكثر تنوعًا في ألوانها! فمثلًا، قد تجذب الأطباق المحضّرة بخضراوات ملوّنة مثل الفلفل الأحمر والأصفر والجزر والطماطم والشمندر واليقطين اهتمام طفلكِ أكثر. كما أن هذه الخضراوات غنية بفيتاميني A وC. ويمكنكِ أيضًا الجمع بين الأطعمة التي يحبها وتلك التي لا يحبها. فمثلًا، إذا كان طفلكِ يحب كرات اللحم، يمكنكِ وضع بضع قطع من القرنبيط أو البروكلي بجانبها. وامزجي قطع الدجاج مع البازلاء الخضراء وقدّميها كجزء من تنسيق الطبق.') WHERE id = 'e19f528f-be1a-4590-a1ad-08cb799868f7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذه الأشهر التي يكون فيها طفلكِ في قمة نشاطه، قد تتساءلين عن الأنشطة الأكثر فائدة التي يمكنكِ ممارستها معه. في الواقع، لديكِ خيارات كثيرة داخل المنزل وخارجه. تُعد المراكز الرياضية المخصصة للأطفال فكرة جيدة لتنمية العضلات واكتساب عادة ممارسة الرياضة. كما قد تكون مجموعات اللعب وورش العمل التي تطوّر المهارات الحسية والحركية مفيدة أيضًا. أما القيام بالأعمال المنزلية معًا، فهو مثالي لقضاء الوقت وتعليمه النظام والانضباط. فمثلًا، بينما تمسحين الأرض، يمكن لطفلكِ الانضمام إليكِ باستخدام مجموعة التنظيف الخاصة بألعابه. ويمكنكِ طلب مساعدته عند وضع الملابس المتسخة في الغسالة. باختصار، يمكنكِ إشراك طفلكِ في كل عمل تقومين به في حياتكِ اليومية.') WHERE id = 'c3a4f4bb-ac8b-4cd2-b729-634f2ef8e015';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الإسهال من أكثر الشكاوى شيوعًا لدى الأطفال. وإذا كان طفلكِ يُصاب بالإسهال من حين إلى آخر، فستحتاجين إلى بعض المعلومات المتعلقة بتغذيته. ينبغي أن تعلمي أنه، على عكس الإمساك، يجب تقديم أطعمة قليلة الألياف أثناء الإسهال. ويُعد الزبادي من أفضل الأطعمة المفيدة في حالات الإسهال، لأنه مصدر قوي للبروبيوتيك. ومن أهم المعادن التي يفقدها الجسم أثناء الإسهال الزنك. لذلك تُعد جنين القمح الغنية بالزنك من أفضل الأطعمة التي يمكن تقديمها خلال هذه الفترة. كما أن إضافة كميات قليلة من السماق إلى الطعام قد يكون لها تأثير إيجابي في الإسهال. وإذا كان طفلكِ لا يرغب في تناول الطعام بسبب الوهن، فيمكنكِ تقديم الموز والخوخ له. فعلى الرغم من أن الخوخ قد يكون له تأثير مليّن للأمعاء لدى البالغين، فإنه يمتلك خصائص تساعد على الحد من الإسهال لدى الأطفال.') WHERE id = 'a3da791d-47b3-44f0-b6db-2186758922d6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون لرضيعكِ خلال هذه الأشهر صديق خيالي يلعب ويتناول الطعام معه. يشعر كثير من الآباء بالقلق عندما يلاحظون مثل هذه السلوكيات لدى أطفالهم ويحاولون التدخل. لكن لا داعي للقلق في الواقع، إذ لا يكون الحد الفاصل بين الخيال والواقع واضحًا تمامًا خلال مرحلة ما قبل المدرسة. وقد يتعامل الأطفال في هذا العمر مع الأشياء الجامدة كما لو كانت كائنات حية. وأحيانًا قد يرافق رضيعكِ دبّه المحشو أو دميته المفضلة. وفي بعض الحالات، قد تشاهدين رضيعكِ يتحدث إلى شخص ما رغم عدم وجود أي شيء أمامه... تُعد كل هذه الصداقات جزءًا طبيعيًا من نمو رضيعكِ. ولكن إذا استمر هذا الوضع مدة طويلة جدًا وبدأ يثير قلقكِ الشديد، فيمكنكِ استشارة طبيبكِ.') WHERE id = '43ebcc3b-a67c-42aa-91cf-6698742da655';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الآيس كريم من الأطعمة التي سيطلبها رضيعكِ دائمًا، صيفًا وشتاءً. وقد يكون من غير المنصف قليلًا تصنيفه مباشرة ضمن الوجبات السريعة أو الأطعمة غير المفيدة، إذ يحتوي الآيس كريم على فيتامينات B12 وB6 وD وC وE. كما أنه غني بالدهون والبروتين والكربوهيدرات. ويمكن اعتباره مصدرًا ممتازًا للطاقة، ولا يسبب زيادة الوزن عند تناوله باعتدال. لكن بعض أنواع الآيس كريم قد تحتوي على منكّهات صناعية. لذلك، إذا كان لديكِ وقت، يمكنكِ تحضير آيس كريم صحي لطفلكِ في المنزل. المكونات اللازمة: 100 غرام من الشوكولاتة، و100 ml من الحليب، و1 عبوة من الكريمة الثقيلة. طريقة التحضير بسيطة جدًا: أذيبي الشوكولاتة بطريقة الحمّام المائي، ثم أضيفي إليها الحليب وامزجيهما جيدًا. اخفقي الكريمة في وعاء منفصل باستخدام الخلاط حتى تصبح هشة ورغوية. ثم امزجي جميع المكونات وضعيها في المجمّد مدة 2 ساعة. أصبح الآيس كريم جاهزًا! :)') WHERE id = 'd4f84a64-6da8-4928-8a62-9c2d85080c7a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدأ رضيعكِ الآن باستخدام أصابعه للإشارة إلى عمره، كما يستمر تطوّر لغته بسرعة. فمثلًا، قد يتمكن من تسمية أعضاء الجسم، والتعرّف إلى 1-2 من الألوان، والإجابة بسهولة عن جنسه عند سؤاله. وبعد أن كان صغيركِ يستخدم الكلمات بصيغة المفرد حتى الآن، قد يبدأ أيضًا باستخدام صيغة الجمع. أي إنه بدلًا من قول «كتاب» فقط، قد يقول «كتب» عندما يرى عدة كتب. وإلى جانب ذلك، يبدأ باستخدام أفعال الماضي في مواضعها الصحيحة، مثل «ذهب» و«جاء». وسيواصل طرح سؤالَي «ما هذا؟» و«ما ذاك؟» بكثرة. ومن المهم جدًا أن تجيبي عن أسئلته في كل مرة بصبر وبأسلوب يمكنه فهمه. لا يصح تجنّب أسئلته، لأن رضيعكِ يفهم العالم والحياة من خلال طرح الأسئلة.') WHERE id = '623efdbe-b7f0-42be-97e8-fdfbef54b271';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن الإصابة بالقمل مشكلة قد تظهر في أي عمر، فإنها أكثر شيوعًا لدى الأطفال. وقد يرجع ذلك إلى أن جهازهم المناعي لا يزال في طور النمو، وإلى عدم قدرتهم على الالتزام بقواعد النظافة التزامًا كاملًا. ويكون خطر انتقال القمل مرتفعًا جدًا، خصوصًا في الأماكن المزدحمة مثل مجموعات اللعب ورياض الأطفال. ويُعد قمل الرأس النوع الأكثر شيوعًا بين الأطفال. وتستمر دورة حياته عبر مرحلتي البيوض واليرقات، لذلك ينبغي ألا تهملي العناية بشعر طفلكِ. إذا أُصيب طفلكِ بالقمل، فيمكنكِ استخدام أنواع الشامبو المخصصة لعلاجه. كما يُعد تمشيط الشعر بمشط دقيق الأسنان أثناء الاستحمام وسيلة فعالة لإزالة القمل.') WHERE id = 'f0808361-bf65-40fb-aa73-6be6cd94a7ac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُسهم الدهون الموجودة في الأسماك بفاعلية كبيرة في الحفاظ على صحة طفلكِ. ويُعرف زيت السمك بخصائصه المضادة للالتهاب والأكسدة والأورام، كما يساعد على الوقاية من تصلب الأوعية الدموية وانسدادها. ويرى معظم المختصين أن حصول الأطفال على هذا الزيت عن طريق تناول السمك مباشرةً أكثر فائدة للصحة من تناوله كمكمّل غذائي. لكن كثيرًا من الأطفال لا يحبون تناول الأسماك الدهنية. وتشير بعض الآراء إلى أن الأطفال الذين يتناولون السمك مرتين أسبوعيًا لا يحتاجون إلى مكملات زيت السمك. بينما يؤكد بعض المختصين أن أسماك منطقتنا تنتمي في الغالب إلى أسماك البحار الدافئة، ولذلك تحتوي على كميات قليلة جدًا من أحماض أوميغا-3 الدهنية (DHA وEPA)، ما يجعل دعمها بمكملات زيت السمك مهمًا. لذا قد يكون إعطاء طفلكِ زيت السمك يوميًا فكرة جيدة بعد استشارة طبيبكِ.') WHERE id = 'fbb69386-c7e5-4fbb-97e9-982d14f4b94e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكبر طفلكِ أكثر قليلًا يومًا بعد يوم، وقد قطع شوطًا كبيرًا في نموه خلال مدة قصيرة. ومهمتكِ الآن هي أن تُشعريه بأنه أصبح أكبر سنًا. ولتُظهري لطفلكِ أنه فرد من أفراد الأسرة، يمكنكِ إلى جانب تخصيص أغراض شخصية له، شراء طبق وشوكة خاصين به لاستخدامهما وقت الطعام. وستكون هذه اللمسات الصغيرة، خصوصًا إذا كانت مزينة بشخصياته المفضلة، وسيلة لطيفة لتشجيعه على تناول الطعام. ويمكنكِ أيضًا أن تطلبي من طفلكِ وضع ملابسه التي خلعها في سلة الغسيل المتسخ. قد لا يبدو اكتساب مثل هذه العادات بالغ الأهمية للوهلة الأولى، لكن الشعور بالمسؤولية يتشكل في هذه السن تحديدًا. وستساعده هذه المهام الصغيرة على أن يصبح شخصًا بالغًا أكثر تنظيمًا وتحملًا للمسؤولية مستقبلًا.') WHERE id = '3101c4cb-3b48-4335-a262-39fa7a1322ad';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد بدأ طفلكِ الآن يهتم بالأعمال التي تقومين بها. وفي هذه المرحلة، سيتبعكِ ويحاول تقليدكِ في حركات مثل مسح الأشياء. لا يرغب كثير من الوالدين في مشاركة الطفل في الأعمال، فيمنعونه من ذلك. لكن بدلًا من منعه اعتقادًا منكِ أنه سيجعل عملكِ أكثر صعوبة، دعيه يشارك وامنحيه بعض الحرية. ويمكنكِ أيضًا تحويل هذه اللحظات إلى فرصة لتعليمه معلومات بسيطة من خلال التواصل اليومي. فعلى سبيل المثال، يكون تعلّم الألوان والأرقام أسهل عندما يأتي في صورة لعبة. وستسهم أنشطة مثل تصنيف الأدوات المنزلية التي يحب اللعب بها بحسب ألوانها، أو عد بلاط الأرضية أثناء مسحها، إسهامًا كبيرًا في نمو طفلكِ. وهكذا يمكنكما الاستمتاع معًا، وقضاء وقت ممتع ومفيد، ودعم تعلّمه في الوقت نفسه.') WHERE id = '62a7c96c-d9da-4a1b-918e-e957e6e835d1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في الشهر السابع والعشرين، سيستمر طفلكِ في إغراقكِ بالأسئلة بوتيرة مكثفة. وقد تواجهين باستمرار أسئلة كثيرة، بعضها مرتبط بالموضوع وبعضها غير مرتبط به، وسينتظر منكِ حتمًا تفسيرًا. ومن المهم جدًا أن تجيبيه بأبسط طريقة وأكثرها وضوحًا، وأن تُشعريه بأنكِ تقدّرين أفكاره. وقد يغضب الطفل أحيانًا أو يُظهر انزعاجه خلال هذه المرحلة، لكن محاولتكِ الشرح له بصبر ستؤثر حتمًا بصورة إيجابية في نموه. ومن المهم أيضًا أن تقدّري طفلكِ على ما يستطيع فعله، وألا تحكمي عليه بسبب ما لا يستطيع فعله؛ لأن هذا النهج قد يسبب له توترًا نفسيًا. كوني صبورة معه، فهو يتعرف إلى العالم عن قرب أكثر مع كل سؤال يطرحه وكل تصرف مشاغب يقوم به.') WHERE id = '8617b177-02ab-46b0-bf53-616ceb20767c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكتسب العادات الغذائية في مرحلة الطفولة أهمية كبيرة، لأن حماية الأطفال من الأمراض ونمو قدراتهم الذهنية والجسدية يرتبطان ارتباطًا مباشرًا بالتغذية الصحية. وفي الواقع، التغذية السليمة مهمة في جميع الأعمار، لكنها بالغة الأهمية للأطفال الذين لا يزالون في مرحلة النمو. ويُعد سوء التغذية وعدم توازنها من الأسباب الأساسية للعديد من الأمراض. كما قد يؤدي اختيار الأطعمة الضارة إلى اضطرابات في النمو وبعض المشكلات الصحية. وغالبًا ما تكون المرحلة التالية لسن الثانية بداية تكوّن العادات الغذائية الخاطئة؛ إذ يتعرف الأطفال خلالها إلى الأطعمة الجاهزة المعبأة والحلويات الخالية من القيمة الغذائية. ويُعد ذلك أحد أكبر العوائق أمام النمو الصحي. ويوصي المختصون بإبعاد الأطفال عن هذه الأطعمة الضارة على الأقل حتى بلوغ سن المدرسة.') WHERE id = 'b67098ba-523c-4deb-8d75-c6e4c04c833c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا بد أنكِ لاحظتِ أن طفلكِ بدأ منذ بضعة أشهر بإعلان استقلاليته. وقد يستمر صغيركِ في الاعتراض على طلباتكِ وطرح أسئلة مثل: "لماذا؟" و"لأي سبب؟"، وقد يطرح عليكِ أحيانًا أسئلة تضعكِ في موقف صعب. فعلى سبيل المثال، يهتم الأطفال في هذا العمر عادةً بمعرفة كيف تكوّنوا. باختصار، قد يأتي إليكِ طفلكِ ويسألكِ: "كيف تكوّنتُ، وكيف جئتُ إلى الدنيا؟". يعتقد كثير من الآباء أن هذا السؤال مرتبط مباشرةً بالجنس، فيتجنبون الإجابة عنه ويحاولون تغيير الموضوع. لكن هذا الأسلوب يزيد فضول الطفل، فتتوالى أسئلته بلا انقطاع. في مثل هذه الحالات، لا حاجة إلى شرح جميع التفاصيل للطفل. وبدلًا من ذلك، من الأنسب أن تجيبيه بلغة يفهمها، كأن تقولي له: "لقد كبرتَ في بطني".') WHERE id = '63361e0d-5fd3-4108-803f-7f7fd698945d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد فيتامين D من أهم العناصر لصحة طفلكِ. وعند نقصه، قد يصاب الأطفال بمرض يُسمى الكساح، وهو مرض يسبب تشوهات في العظام، إذ يؤدي فيتامين D دورًا بالغ الأهمية، خصوصًا في نمو العظام وصحة الأسنان. وقد يكون نقص فيتامين D تحديدًا سببًا لمشكلات مثل الخمول والقلق وكثرة الإصابة بالأمراض وفقدان الشهية لدى طفلكِ. لذلك، من المفيد أن يحصل الطفل على فيتامين D بانتظام. وعلى خلاف الفيتامينات الأخرى، يحصل الجسم على فيتامين D من الأطعمة ومن خلال أشعة الشمس أيضًا. والأطعمة التي تحتوي عليه طبيعيًا قليلة، ويأتي السمك في مقدمتها. فالأسماك الدهنية، مثل السردين والسلمون والماكريل، غنية بفيتامين D بشكل خاص. كما توجد منه كميات قليلة في أطعمة مثل البيض والفطر والحليب والجبن. تذكّري أن التعرض للشمس وحده أو التغذية وحدها قد لا يكفيان لتصنيع فيتامين D، وأن الجمع بينهما أكثر فاعلية.') WHERE id = '54b7999d-3552-4ccb-ad57-5e50a6a6a619';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تعتقدين أن طول طفلكِ لا يزداد بالسرعة الكافية أو أنه متأخر وفقًا لمخطط النمو (المئينات)، فمن الطبيعي جدًا أن تشعري بالقلق. ويؤكد المختصون أن زيادة الطول والوزن هما من أهم مؤشرات النمو لدى الأطفال. ويحدث ازدياد الطول من خلال نمو النسيج الغضروفي الموجود في نهايات العظام، والذي يُعرف بصفائح النمو. وفي نهاية مرحلة المراهقة، يتوقف ازدياد الطول مع انغلاق هذه الصفائح. وهناك عاملان أساسيان يؤثران في النمو: أولهما العوامل الوراثية، إذ يتأثر طول كل طفل بالجينات التي يرثها من والديه. أما العامل الثاني فهو التغذية. ومن المهم جدًا أن يحصل الطفل على السعرات الحرارية المناسبة لعمره وأن يتبع نظامًا غذائيًا متوازنًا، ليستفيد إلى أقصى حد من إمكاناته الوراثية للطول. وتُعد اضطرابات التغذية، والقيء المزمن، والإسهال المزمن، أو التغذية غير السليمة، ولا سيما خلال العامين الأولين اللذين يتسمان بسرعة النمو، من أبرز العوامل التي تؤدي إلى تأخر النمو.') WHERE id = 'e4cccfa5-92e6-4cfb-b6af-32b8c84e3a41';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تُلبسين طفلكِ حفاضًا عند الخروج، ثم تتركينه بملابسه الداخلية فقط عند العودة إلى المنزل، فسيتسبب ذلك في إرباكه. لذلك، عليكِ تطبيق القاعدة نفسها في المنزل وخارجه وفي الحضانة إن كان يرتادها، والتأكد من أن الطفل يفهم ما هو متوقع منه. ومن الطبيعي تمامًا أن تقع بعض الحوادث من وقت إلى آخر خلال مرحلة اكتساب عادة استخدام المرحاض. وفي مثل هذه الحالات، تكون ردة فعلكِ أو ردة فعل الشخص الذي يعتني بالطفل مهمة جدًا. تجنّبي تمامًا العبارات القاسية والناقدة، ولا تستخدمي كلمات قد تثير قلق الطفل، مثل: قلتُ لك، أو لقد كبرتَ الآن، أو ما زلتَ تقضي حاجتك في ملابسك مثل الأطفال الرضع. وبدلًا من ذلك، اختاري عبارات مشجعة، مثل: لا بأس، قد تحدث مثل هذه الأمور، أو حدث هذا اليوم، لكننا سنكون أكثر انتباهًا غدًا، أليس كذلك؟ من المهم جدًا تشجيع طفلكِ أثناء تدريبه على استخدام المرحاض. فالخطأ أمر طبيعي، وقد يخطئ الجميع. وتذكّري أن عملية التعلم لا يمكن أن تتم من دون أخطاء.') WHERE id = '74cbe601-3405-4913-b913-ad225051c0de';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تغذية طفلكِ مهمة جدًا لنموه الصحي ولتزويده بالطاقة التي يحتاج إليها خلال اليوم. ويشكو كثير من الآباء في هذه المرحلة من عناد أطفالهم ورفضهم تناول الأطعمة المفيدة. وقد يكون البيض مجرد مثال على ذلك. وأحيانًا قد تساعد طريقة تقديم مختلفة أو إضافة نوع جديد من التوابل على تشجيع طفلكِ على تناول البيض. لذلك، لدينا وصفة رائعة لكِ! :) اسم وصفتنا: البطاطس بالبيض. المكونات اللازمة: 1 حبة بطاطس، كمية مناسبة من الجبن الأبيض، 1 بيضة، 2-3 ملاعق صغيرة من دقيق القمح الكامل، قليل من البقدونس، رشة ملح، نعناع، زعتر، و2 ملعقة كبيرة من زيت الزيتون للقلي. أما طريقة التحضير فهي بسيطة جدًا: ابشري البطاطس، ثم أضيفي إليها البيضة والدقيق والبقدونس والجبن والتوابل. بعد خلط المكونات جيدًا، خذي من الخليط مقدار ملعقة في كل مرة واقليه في زيت الزيتون حتى يتحمر من الجانبين. بالهناء والشفاء! 😊') WHERE id = 'a528e9be-0130-4c5b-8b4a-8c91b4559506';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد الهرمونات أهم عامل يؤثر في نمو طفلكِ بعد العوامل الوراثية والتغذية. وتُفرز الغدد الموجودة في جسم الإنسان هرمونات تنظّم النمو والتطور وغيرها من الوظائف الحيوية. ويأتي في مقدمتها هرمون النمو (Growth hormone) الذي تفرزه الغدة النخامية في الدماغ. ويساعد هرمون النمو وبعض العوامل التي ينتجها الجسم على انقسام الخلايا الغضروفية في نهايات العظام، ما يؤدي إلى زيادة الطول. كما تدعم هرمونات الغدة الدرقية النمو من خلال تنظيم عمليات الأيض. ويؤدي هرمون الإستروجين لدى الفتيات وهرمون التستوستيرون لدى الفتيان دورًا مهمًا في زيادة الطول والتطور. وقد يؤدي نقص هذه الهرمونات إلى تأخر النمو أو قصر القامة. إذا كانت لديكِ أي شكوك في هذا الشأن، فاستشيري طبيبكِ بالتأكيد.') WHERE id = '9f60c03d-388c-4852-aae7-a31ffa00fa8f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكن القول إن طفلكِ البالغ من العمر 27 شهرًا يمرّ خلال هذه المرحلة برحلة مكثفة لاكتشاف هويته. ومن المهم جدًا في هذه الفترة أن تنتبهي إلى تصرفاتكِ وكلماتكِ أمامه. وعلى الرغم من أن ذلك قد يكون غير مرغوب فيه لدى كثير من الآباء والأمهات، فقد يبدأ الأطفال في هذا العمر باستخدام كل كلمة يسمعونها. لذلك، قد يكون من الجيد تنبيه الأشخاص الذين يستخدمون عبارات غير لائقة أو بذيئة في وجود طفلكِ. وبالمثل، احرصي على عدم الجدال أو استخدام كلمات سيئة أمامه، وعلى ضبط نبرة صوتكِ؛ لأن طفلكِ سيبدأ بتقليد كل ما يراه منكِ تقريبًا. لذا حاولي أن تكوني قدوة حسنة له. وخلال هذه المرحلة، ينبغي أن تساعدي طفلكِ على تطوير مهاراته الحركية، وأن تدرّبيه أيضًا على اكتساب مهارات العناية بنفسه. فعلى سبيل المثال، يُفترض أن يتمكن طفلكِ الآن من تنظيف أسنانه وغسل يديه من دون مساعدتكِ.') WHERE id = '5abe92b5-f52e-400b-a5f6-cabd63afd859';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الفلورايد أحد المعادن المهمة جدًا لصحة طفلكِ، ومع ذلك يجب الانتباه إلى الكمية المستخدمة منه. يساعد الفلورايد بوجه خاص على الوقاية من تسوس الأسنان، ويمكن أن يحصل عليه الجسم من مياه الشرب. إذا كانت كمية الفلورايد في المياه التي تشربونها كافية، فلا حاجة إلى تناول أي مكملات. أما إذا كانت كميته منخفضة وكان طفلكِ معرضًا لخطر تسوس الأسنان، فيمكنكِ إعطاؤه مكملات الفلورايد بعد موافقة طبيبه. وفي بعض مناطق بلدنا، تكون المياه غنية جدًا بالفلورايد. وقد تؤدي زيادته إلى مشكلات مثل ظهور بقع على الأسنان، وهي حالة تُعرف بتفلور الأسنان. يوجد الفلورايد أيضًا في معاجين الأسنان، ولكن نظرًا إلى إضافة الفلورايد المصنّع إلى هذه المنتجات، يجب توخي الحذر الشديد عند استخدامها. لذلك، لا يحتاج طفلكِ إلى مكملات إضافية من الفلورايد خلال الفترة الأولى من بدء استخدامه معجون الأسنان.') WHERE id = '6748d69e-868b-4bd5-8a5b-784f97c40a36';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتمكن طفلكِ في هذه المرحلة من نطق أكثر من 50 كلمة بوعي. كما يستطيع استخدام هذه الكلمات لتكوين جمل، لكن لا ينبغي أن تتوقعي منه بعدُ جملًا شديدة التعقيد أو غنية بالمعاني. ويمكنه التعبير عن رغباته بجمل مثل: «ارمِ الكرة»، و«تعالي يا أمي»، و«انظر يا أبي»، و«أعطني الدمية»، و«لنذهب إلى المطبخ». وإلى جانب ذلك، قد يتحدث بعض الأطفال في هذه المرحلة عن أنفسهم بصيغة الغائب. ولأن الآخرين ينادونه باسمه، فقد يذكر اسمه بدلًا من قول «أنا» عند الحديث عن نفسه. وعندما يسمع أصوات حيوانات مثل القطط والكلاب والطيور، قد يتمكن من معرفة الحيوان الذي يصدر ذلك الصوت إذا كنتِ قد عرّفتِه إليه من قبل. لا ينبغي أن تتوقعي من طفلكِ مطابقة جميع الأصوات بالحيوانات الصحيحة، بل واصلي مساعدته على التطور. وستكون التطبيقات التي تتضمن أصوات الحيوانات، أو الألعاب باستخدام بطاقات تحمل صورها، مفيدة جدًا لهذا الغرض.') WHERE id = '0b2efb81-ea8f-4a69-a8e4-bfa0406f23c0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ تخوضين معركة كبيرة مع طفلكِ بشأن الطعام. لا تقلقي، فهناك أمهات لا يُحصين يشاركنكِ الشعور نفسه! :) تذكّري خلال هذه المرحلة أن لطفلكِ أطعمة يحبها وأخرى لا يحبها، وأنه لا ينبغي إجباره على تناولها. وستشعرين براحة كبيرة إذا كانت توقعاتكِ واقعية ولم تضغطي على نفسكِ أو على طفلكِ. وعندما يشعر الآباء والأمهات بالعجز، غالبًا ما يلجؤون إلى الهاتف والتلفاز. لكن تشتيت انتباه الطفل بهذه الأجهزة لإطعامه قد يؤثر سلبًا في تطور قدرته على التعلم والإدراك. والأفضل أن تبدئي في هذا العمر بتعويد طفلكِ على الجلوس إلى مائدة الطعام وتناول وجباته عليها. فهذه العادة التي يكتسبها الآن ستساعده مستقبلًا على التأقلم بسرعة أكبر وتكوين عادات غذائية منتظمة.') WHERE id = '28fd7c5d-9fca-4359-bc66-b636a21a6247';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشير الدراسات إلى أن الفتيات يبدأن عمومًا بإبداء الاهتمام بالتدرب على استخدام المرحاض في عمر 23 شهرًا، بينما يبدأ الأولاد بذلك في عمر 25 شهرًا تقريبًا. ولا تقل جاهزية الطفل الجسدية أهمية عن اهتمامه بهذا الأمر. وعادةً ما تتمكن الفتيات من إتقان استخدام المرحاض تمامًا في عمر 33 شهرًا، بينما قد يتمكن الأولاد من ذلك في عمر 37 شهرًا. ومن المتوقع أن يكتسب الأطفال هذه المهارة بحلول هذه الأعمار، لكن عليكِ أن تتذكري أن وتيرة نمو كل طفل تختلف عن غيره. وفي الشهر 27 الذي يمر به طفلكِ الآن، قد يكون قد أتقن استخدام المرحاض تمامًا، أو ربما لا يزال في مرحلة التدريب. وحتى إذا كنتِ قد أتممتِ هذه العملية، فقد تواجهين بعض «الحوادث» البسيطة لبعض الوقت. وهذا أمر طبيعي تمامًا، والأفضل ألا تتعاملي معه بقسوة، بل أن تتفهمي الموقف.') WHERE id = 'a2e641a4-c0c5-4079-b4c0-664fe147cd24';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تساعد الحبوب على تسهيل عملية الهضم لدى طفلكِ بفضل غناها بالألياف، كما تقي من شكاوى مثل آلام البطن. وهي أيضًا مجموعة غذائية غنية بفيتامينات B، التي تؤدي دورًا مهمًا في نمو الجهاز العصبي وتساهم في إنتاج الطاقة في الجسم. إضافة إلى ذلك، تتميز منتجات الحبوب بغناها بمعادن مفيدة للعظام والعضلات، مثل الحديد والسيلينيوم والمغنيسيوم. إذا أردتِ أن يحصل طفلكِ على كامل فوائد الحبوب، فلا تصفّي ماء سلق المعكرونة مثلًا، لأن العناصر الغذائية الموجودة فيها تنتقل إلى الماء أثناء الطهي. لذلك، من الأفضل عند إعداد المعكرونة لطفلكِ أن تطهيها في كمية قليلة من الماء حتى تمتصه. أما الأرز، فإن نقعه في الماء مدة طويلة قبل الطهي أو تحميره في الزيت مدة طويلة يقلل من قيمته الغذائية. وعند إعداد المخبوزات مثل لفائف الخبز، إذا كان طفلكِ سيتناولها أيضًا، فاختاري الخميرة بدلًا من مسحوق الخَبز.') WHERE id = 'e7b4691f-ceeb-4bdc-b7b7-f707d0e7fa17';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد إتقان استخدام المرحاض خطوة كبيرة ومهمة صعبة نسبيًا لطفلكِ. إذا كنتما لا تزالان في هذه المرحلة، فهناك بعض النقاط التي ينبغي لكِ الانتباه إليها. فعلى سبيل المثال، ليس من المناسب بدء التدريب على استخدام المرحاض قبيل تغييرات كبيرة، مثل بدء الحضانة أو الفطام أو الانتقال إلى منزل جديد. إذ يجب أن يكون طفلكِ مستعدًا، وأن يكون التوقيت مناسبًا أيضًا. وفي الوقت نفسه، ينبغي أن تكوني أنتِ مستعدة لهذه المرحلة بقدر استعداد طفلكِ، لأن اكتساب هذه العادة قد يكون أكثر صعوبة لدى بعض الأطفال. من المهم أن تكوني ثابتة وصبورة خلال هذه الفترة. وسيصبح الأمر أسهل كثيرًا إذا تجنبتِ لوم طفلكِ، وتعاملتِ مع العملية بصورة طبيعية، ومنحتِه الكثير من الحب.') WHERE id = '2add9cbb-bed9-4a33-8609-e9090d87a0b2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أكملتِ شهرًا آخر برفقة طفلكِ. أهلًا بكِ في الشهر الثامن والعشرين! :) بدأت شخصية صغيركِ تتبلور بوضوح. لكن تذكري أن شخصيته قد تختلف عن شخصيتكِ. وكلما أظهر سماته الفطرية، ينبغي ألا تلوميه، بل أن تتقبليه كما هو. باختصار، لا تجبريه على أن يصبح تمامًا كما تريدين. إن دعم طريقته الخاصة في فهم العالم سيساعده على النمو بشخصية سليمة. خلال هذه المرحلة، قد يبدأ طفلكِ في التعرف إلى جسده، ولا سيما أعضائه التناسلية، وإبداء الاهتمام بها. وهذا ليس أمرًا يستدعي غضبكِ منه إطلاقًا. وإذا دعت الحاجة، يمكنكِ استشارة مختص لمعرفة الطريقة المناسبة للتعامل مع طفلكِ بشأن هذا الموضوع.') WHERE id = '6e1b9324-94a1-40b9-be8a-0189cd97ec29';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذه الأشهر، تظل نزعة التمركز حول الذات مرتفعة لدى طفلكِ. لذلك، قد يتصرف أحيانًا بأنانية. لكن تذكري أن هذه مرحلة مؤقتة وستزول مع مرور الوقت. ويرجع هذا النوع من السلوك إلى أن قدراته المنطقية لم تتطور بما يكفي بعد، وأنه لا يفهم تمامًا مفهوم الآخر، ولم يتكون لديه بعد مفهوم المشاركة، كما أنه لا يستطيع استيعاب المعاني المجردة. وفي الوقت نفسه، لم يكتسب بعد القدرة الكاملة على تصنيف الأحداث أو ترتيبها أو تجميعها. ونتيجة لذلك كله، لا يراعي طفلكِ في كثير من الأحيان آراء الآخرين وأفكارهم، بما في ذلك آراؤكِ وأفكاركِ، لأنه لم يصل بعد إلى هذا المستوى من النضج المعرفي. لذا، لا داعي للقلق. ولكن إذا كان هذا الأمر يثير قلقكِ بشدة، فقد يكون من المفيد استشارة مختص.') WHERE id = 'e03558fa-2b62-46f8-8b8d-62974309090d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن الحليب مصدر ممتاز للبروتين، فقد يرفض بعض الأطفال تناوله. وإذا كان طفلكِ لا يحب الحليب أيضًا، فاعلمي أنكِ لستِ وحدكِ. :) ولكن كي لا تحرمي طفلكِ من هذا الغذاء المهم، يمكنكِ اللجوء إلى بعض الحيل البسيطة وخلط الحليب بأطعمة أخرى. فعلى سبيل المثال، إذا كان طفلكِ يحب خبز البيض، فاخفقي البيض مع الحليب لتحضير فطور مغذٍ. اغمسي خبز الحبوب الكاملة في هذا الخليط وحمّريه بقليل من الزبدة. وإذا كان طفلكِ يحب المشروبات، فيمكنكِ إعداد سموذي (smoothie) لذيذ. ولتحضيره، امزجي الحليب والموز في الخلاط، وأضيفي فواكه أخرى متوفرة في المنزل حسب الرغبة. كما أن البودينغ المنزلي مذاق شهي لا يستطيع معظم الأطفال مقاومته! فضلًا عن أنه من أفضل الطرق التي تساعد طفلكِ على حب الحليب. :) يمكنكِ طهي الحليب مع مسحوق الكاكاو غير المحلى وإضافة النكهات إليه لابتكار مذاقات مختلفة.') WHERE id = 'd764e4e1-1fd6-421c-bf7e-324e9264d8bd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمثل هذا الشهر مرحلة يبدأ فيها طفلكِ بالتعلم المكثف عن طريق التجربة والخطأ. فقد بدأ الآن يطرح سؤالي «لماذا؟» و«لأي غرض؟» بوعي وهدف أوضح. فعلى سبيل المثال، قد يحاول فتح عبوات الأشياء الصغيرة ثم يسألكِ عن استخداماتها. ويكتسب طفلكِ أيضًا مهارات جديدة خلال هذه المرحلة، وبناء أبراج أعلى ليس سوى واحدة منها. ومن خلال تقليدكِ، قد يتمكن من طي الورقة إلى نصفين بسهولة، أو إغلاق سحّاب ملابسه، أو محاولة ارتداء ملابسه بنفسه. وخلال هذه الأشهر التي يستمر فيها نموه السريع، يمكنكما قضاء وقت ممتع من خلال ممارسة أنشطة متنوعة في المنزل أو خارجه. فعلى سبيل المثال، ستكون لعبة الوقوف على قدم واحدة معًا ممتعة، وستساعد أيضًا على نموه البدني! :)') WHERE id = '1c1e64d8-d06f-466f-9b34-33f9ed75a828';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون الأسماك أهم مصدر للبروتين في غذاء طفلكِ. ولأن العثور على السمك الطازج وطهيه وتنظيفه من العظام قد يكون صعبًا، يفضل كثير من الآباء الأسماك المعلبة. لكن ينبغي لكِ توخي الحذر بشأنها. إذ يُصنع التونة المعلبة من أنواع مختلفة من الأسماك، وقد تحتوي بعض الأنواع على الزئبق الذي يمكن أن يكون سامًا حتى بجرعات صغيرة. وتحتوي التونة البيضاء على كمية من الزئبق أعلى من تلك الموجودة في التونة الخفيفة. وعلى الرغم من أن الحد الأقصى الموصى به للبالغين من التونة البيضاء هو 170 غرامًا أسبوعيًا، فقد تكون هذه الكمية خطرة على طفلكِ. ففي هذا العمر، يكفي الطفل تناول 85 غرامًا فقط من السمك شهريًا. لذلك، ورغم أن الأمر يتطلب جهدًا أكبر، فإن تفضيل المأكولات البحرية الطازجة على المعلبة سيكون أكثر فائدة لصحة طفلكِ.') WHERE id = '42d066ad-b938-4b87-8fff-39d96cc2a17e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطورت المهارات الحركية الدقيقة والكبيرة لدى طفلكِ بشكل ملحوظ في هذه المرحلة. فهو الآن يركض بسهولة، ويتوقف متى شاء، ويتجاوز العوائق دون صعوبة. كما يستطيع القرفصاء بسهولة لالتقاط غرض من الأرض، ثم الوقوف من دون الاستناد إلى يديه. ويمكنه الصعود على الأثاث والنزول عنه غالبًا من دون مساعدة. وقد ترينه أيضًا واقفًا على أطراف أصابعه. يستطيع صعود الدرج ونزوله بمفرده ممسكًا بالدرابزين، لكنه سيظل يضع كلتا قدميه على كل درجة للحفاظ على توازنه. في هذه الأشهر، يحاول الأطفال ركل الكرة الموجودة أمامهم، لكنهم غالبًا ما يخطئونها. ومن الطبيعي تمامًا أن يمسك طفلكِ القلم بيده كلها ويخطّ خطوطًا عشوائية. كما يحب كثيرًا تقليب صفحات الكتب. وهذا يعني أن الوقت قد حان ليبدأ طفلكِ بالرسم! ومع ذلك، يُستحسن أن تراقبيه كي لا يرسم على الجدران! :)') WHERE id = 'b039724d-e5f7-45e9-8fc4-95a761a5df3b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أحرز طفلكِ تقدمًا كبيرًا من الناحيتين الجسدية والذهنية. لكنه لا يزال في هذه المرحلة بحاجة إلى 11-12 ساعة من النوم ليلًا. لذلك، ينبغي أن تحددي موعد نومه مساءً وفقًا لوقت استيقاظه صباحًا. فعلى سبيل المثال، إذا كان طفلكِ يستيقظ الساعة 07:00 صباحًا، فعليكِ وضعه في الفراش قرابة الساعة 20:00 ليحصل على حاجته من النوم البالغة 11 ساعة. ولتكوين نمط نوم صحي، احرصي على ألا يتجاوز موعد نومه الساعة 21:00 تقريبًا. وإذا كان طفلكِ قد توقف عن أخذ القيلولة نهارًا، فيمكنكِ تقديم موعد نومه قليلًا، ما يساعد على منعه من الخلود إلى النوم وهو مرهق جدًا، ويقلل أيضًا من استيقاظه ليلًا. ويمكنكِ من خلال طقوس ما قبل النوم إشعار طفلكِ بأن وقت النوم قد حان. ويُعد تنظيف الأسنان، وقراءة كتاب، والتحدث عن أكثر حدث أعجبه خلال اليوم، وإطفاء الأنوار، ومنحه قبلة قبل النوم أنشطة مناسبة لهذه المرحلة العمرية.') WHERE id = 'aa2b7696-4c81-4ab5-b66f-36eb3f265c8f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا لمخطط النسب المئوية للنمو، يبلغ متوسط وزن الأولاد في عمر 28 شهرًا 13.200 غرام، بينما يبلغ متوسط وزن البنات 12.700 غرام. وقد يكون وزن طفلكِ أقل أو أعلى قليلًا من هذه القيم، لأن قياسات الجسم الصحية تختلف من طفل إلى آخر تبعًا للعديد من العوامل. ومن أبرز هذه العوامل الخصائص الوراثية لطفلكِ وتوازنه الهرموني الخاص. وإلى جانب ذلك، يؤثر نظامه الغذائي، ومدى نشاطه خلال اليوم، والظروف البيئية التي يعيش فيها تأثيرًا مباشرًا في وزنه. ومن المهم تذكّر أن مؤشرات نمو طفلكِ مترابطة. فعلى سبيل المثال، سيكون الوزن الصحي للطفل الأطول من المتوسط أعلى من المتوسط أيضًا. لذلك، فإن الطبيب الذي يتابع طفلكِ بانتظام هو الأقدر على إجراء التقييم الأدق.') WHERE id = '5a3ba4d7-afcf-4bb0-aad2-6d8e229cd0e1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد مشكلات النطق من أكثر المسائل التي تقلق الوالدين في هذه المرحلة. وغالبًا ما يُنظر إلى اضطراب تطور اللغة وتأخر النطق لدى الأطفال على أنهما مفهوم واحد، لكنهما أمران مختلفان. فإذا كان طفلكِ يجد صعوبة في فهم ما يُقال له والتعبير عن نفسه، فقد يشير ذلك إلى اضطراب لغوي. وفي هذه الحالة، يستخدم الطفل جملًا أقصر مقارنة بأقرانه، ويستعمل اللواحق اللغوية بطريقة خاطئة أو ناقصة، وتكون حصيلته من المفردات محدودة. أما إذا كان طفلكِ غير قادر على نطق الأصوات بصورة صحيحة وطليقة، فهذا يُعد اضطرابًا في النطق. وقد يظهر اضطراب النطق على شكل عدم القدرة على نطق بعض الحروف (اضطراب النطق أو التلفظ)، أو التأتأة، أو تأخر تطور اللغة. لكن الطبيب وحده يستطيع تشخيص هذه الحالة. ومن المهم أن تتبني نهجًا واقعيًا، لا سيما أن طفلكِ لا يزال يتعلم كلمات جديدة وقواعد بنائها.') WHERE id = 'adac34a3-0b40-4281-8ff2-1c451c990897';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد التغذية الصحية والمتوازنة مهمة جدًا لاستمرار نمو طفلكِ وتطوره بصورة سليمة. وتؤدي البروتينات دورًا كبيرًا في هذه العملية. فالبروتينات، التي تُعد مادة البناء الأساسية للجسم، ضرورية لترميم العضلات والخلايا. ويلبي حليب الأم هذه الحاجة حتى عمر 1 سنة. وبعد عمر 1 سنة، ينبغي أن يكون 20% من البروتين اليومي من مصادر حيوانية و80% من مصادر نباتية. وفي هذه المرحلة، يكفي أن يحصل طفلكِ يوميًا على 2 غرام من البروتين لكل كيلوغرام من وزنه. وهذا يعادل في المتوسط 16 غرامًا من البروتين يوميًا. فعلى سبيل المثال، يمكن لوعاءين من الزبادي أو طبق من المعكرونة بالجبن أن يلبّي كامل احتياجات طفلكِ اليومية من البروتين. وتُعد أطعمة مثل الحليب والبيض واللحوم والدجاج والأسماك مصادر للبروتين الكامل، إذ تحتوي على جميع الأحماض الأمينية التي يحتاج إليها الجسم. وإلى جانب ذلك، من المفيد أن تقدمي الحبوب والبقوليات والخضروات معًا لتلبية احتياجاته من البروتين بالكامل.') WHERE id = '5d36b2bf-f065-4e27-b7dc-33f78f228aae';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تعتقدين أن طفلكِ لم يحرز بعد تقدمًا كافيًا في اكتساب عادة استخدام المرحاض، فمن المفيد معرفة بعض النقاط المهمة. فعلى الرغم من أنكِ لا ترينه شخصًا ناضجًا تمامًا بعد، فإن إدراكه متطور ومنفتح إلى حد كبير مثل البالغين. لذلك، يستطيع خلال فترة التدريب على استخدام المرحاض ملاحظة مشاعر اللوم أو الضجر على وجهكِ بسهولة، ويكيّف ردود أفعاله وفقًا لها. عليكِ تذكير طفلكِ بانتظام بإخباركِ عندما يشعر بالحاجة إلى استخدام المرحاض. لكن حاولي أثناء ذلك أن تكوني أكثر صبرًا وحنانًا من المعتاد. وفي الوقت نفسه، يمكنكِ إجلاسه على المرحاض وتشجيعه على فترات منتظمة، حتى إن لم يطلب ذلك بنفسه. ويمكنكِ اصطحابه إلى المرحاض كل ساعة لمدة تتراوح بين 1-2 يوم، ثم زيادة هذه المدة تدريجيًا. وهكذا، سيبدأ طفلكِ خلال وقت قصير بإخباركِ بنفسه عندما يشعر بالحاجة إلى استخدام المرحاض.') WHERE id = '115cbd6b-06db-4566-8c7c-e6c251edd677';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبحت مهارات طفلكِ في تناول الطعام أكثر تطورًا الآن. فهو يستطيع إمساك الملعقة بفاعلية، وشرب الماء من الكوب بيد واحدة، وتناول العديد من الأطعمة بيده. ورغم أنه بدأ يأكل بانتظام، فإنه لا يزال يتعلم كيفية المضغ والبلع؛ وقد يبتلع الطعام أحيانًا قبل مضغه جيدًا لأنه متعجل للعودة إلى اللعب. لذلك، لا يزال خطر الاختناق قائمًا. عليكِ تجنب الأطعمة التي قد تسد مجرى التنفس، مثل ملعقة من زبدة الفول السوداني، والمكسرات، والحلقوم، والعنب، والجزر النيئ، والكرفس النيئ، والكرز غير منزوع النوى. من المهم جدًا أن تتوخي الحذر عند تناول طفلكِ هذه الأطعمة. وإذا كان يتناولها، فحاولي ألا تتركيه بمفرده. إذا واجه أي صعوبة، فلا تفزعي وراقبيه، وفي حال حدوث انسداد كامل ولاحظتِ أنه غير قادر على التنفس، فاتصلي بخدمات الطوارئ المحلية فورًا وطبّقي قواعد الإسعافات الأولية.') WHERE id = '43766e9c-9331-414f-9fe4-c87c7161371c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي لطفلكِ في هذه المرحلة تناول ثلاث وجبات رئيسية، بالإضافة إلى وجبة أو وجبتين خفيفتين. ويمكنه الآن تناول الطعام نفسه الذي يتناوله بقية أفراد الأسرة؛ أي إنكِ لستِ بحاجة إلى إعداد طعام خاص له. ومع تطور مهاراته اللغوية والاجتماعية، سيمنحه الجلوس إلى المائدة مع الجميع فرصة للمشاركة بفاعلية في وقت الطعام. المهم هنا هو قضاء وقت ممتع من دون التركيز المفرط على كمية الطعام التي يتناولها أو تحويل وقت الطعام إلى معركة. فكلما جادلتِه أكثر بشأن خياراته الغذائية، ازداد إصرارًا على فعل ما يريده. ومع ذلك، ينبغي لكم كأسرة الالتزام بعادات غذائية صحية واتخاذ خيارات صحية معًا. ويُعد جلوس الأسرة كلها إلى المائدة في وقت الطعام بداية لعادات جميلة.') WHERE id = '690fc0a4-31a8-41bb-8387-afbb9a513803';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كلما كبر طفلكِ، سيتعلم القيام بالعديد من المهام بنفسه، بدءًا من ارتداء قميصه وخلعه وصولًا إلى وضع الطعام في طبقه. إن متابعة تطور استقلالية طفلكِ تجربة مؤثرة تدعو إلى الفخر في آن واحد، وهي جزء مهم من نموه الشخصي والاجتماعي. ورغم أنه يستطيع منذ فترة ارتداء الملابس الفضفاضة بنفسه، فقد يحتاج إلى بضعة أشهر أخرى حتى يتمكن من ارتداء الملابس الضيقة، مثل القميص قصير الأكمام، بصورة مستقلة. أما ارتداء ملابسه بالكامل من دون أي مساعدة فقد يستغرق عامًا أو عامين. لذلك، اجعلي توقعاتكِ واقعية ولا تقلقي، وتجنبي أيضًا التدخل المفرط. فعلى سبيل المثال، ينبغي أن يكون طفلكِ قادرًا الآن على خلع حذائه من دون مساعدة، وأن يختار بنفسه لونًا معينًا عند ارتداء ملابسه.') WHERE id = 'd7f6ffc6-8357-4c5b-94b8-550d90fdcbed';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون أوقات الطعام صعبة بعض الشيء مع طفلكِ الذي بدأ يتخذ قراراته بنفسه حتى فيما يتعلق بالطعام، وأصبح أكثر استقلالية. ولكِ بصفتكِ أمًا دور كبير في مساعدة طفلكِ على اكتساب عادات غذائية صحية والانضباط. فالإصرار عليه ليأكل، أو استخدام الطعام وسيلةً للمكافأة أو العقاب، يؤثر سلبًا في عاداته الغذائية. وما عليكِ فعله هو احترام شهيته. ومن أهم أسس التغذية الصحية عدم تفويت الوجبات الرئيسية والخفيفة، وعدم تعويده على الأطعمة غير الصحية. وتُعد الحليب ومنتجات الألبان، والبيض، والجبن، والخضراوات والفواكه الموسمية الطازجة، والحبوب، واللحوم الحمراء، والدواجن، والأسماك، والبقوليات من الأطعمة المهمة، خصوصًا في هذه المرحلة. عليكِ إدراجها بصورة متوازنة في نظام طفلكِ الغذائي. وتذكري أن كل طعام صحي يتناوله طفلكِ اليوم هو من أهم الاستثمارات في مستقبله.') WHERE id = '7ace9092-3ee2-47b6-b891-840cce162d3e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر طفلكِ حاليًا بالمرحلة الثانية من مراحل النمو المعرفي، وهي "مرحلة ما قبل العمليات". وتُعد هذه المرحلة أيضًا بداية التفكير؛ أي إن طفلكِ بدأ الآن استخدام قدراته العقلية لتحقيق أهدافه. وتُعد قدرته على استخلاص النتائج من تجاربه الأولى القائمة على المحاولة والخطأ من أهم العوامل المساعدة في عملية تعلمه. ويبدأ طفلكِ في هذه المرحلة استخدام ذاكرته بفاعلية، ويكتسب مفهوم بقاء الأشياء وهويتها. كما ينتقل الآن من ردود الفعل الداخلية إلى ردود الفعل الخارجية. وتتطور قدرته على التقليد بدرجة أكبر، ولذلك من المهم جدًا أن يكون الأشخاص المحيطون به قدوة حسنة له.') WHERE id = '694eaa85-119e-4aa0-b132-331a3944017a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ اعتبار كل طعام صحي يتناوله طفلكِ في هذه المرحلة استثمارًا في مستقبله. فعلى سبيل المثال، من المفيد إضافة مرق العظام الداعم لجهاز المناعة إلى قائمة أغذيته، إلى جانب الخضراوات والفواكه الموسمية. يحتوي مرق العظام على العديد من الفيتامينات والمعادن وكمية كبيرة من البروتين، ولذلك يحتل مكانة مهمة في النظام الغذائي لطفلكِ. ويساعد الكولاجين والكوندرويتين والغلوكوزامين الموجودة في مرق العظام على تقوية النسيج الغضروفي ودعم النمو الصحي لعظام طفلكِ. بالإضافة إلى ذلك، يُعد مرق العظام غنيًا بالحمض الأميني غلايسين، الذي يساعد الجسم على الاسترخاء، ما قد يساعد طفلكِ على النوم براحة أكبر. ولا يزال جهاز طفلكِ الهضمي في طور النمو، لذا فمن الطبيعي أن يواجه صعوبة في هضم بعض الأطعمة الدسمة التي تتناولينها. أما مرق العظام، فهو طعام يسهل على طفلكِ هضمه بفضل قابليته العالية للامتصاص.') WHERE id = 'a406b692-65b5-470a-8764-73b3f8d9ec30';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعدّ الحدود مهمة جدًا في المرحلة العمرية الحالية لطفلكِ. يحب الوالدان وضع الحدود، بينما يحب الأطفال اختبارها وتجاوزها. والمفتاح الأساسي هنا هو الثبات؛ لأن تطبيق الحدود أحيانًا وعدم تطبيقها أحيانًا أخرى سيزيد ارتباك طفلكِ. عليكِ وضع حد لطلبات ما قبل النوم، مثل «كوب آخر من الماء» أو «قبلة أخرى لأبي» أو «الذهاب إلى الحمام للمرة الأخيرة». على سبيل المثال، إذا كان طفلكِ يختلق أعذارًا مختلفة لتجنب النوم، فعليكِ تحديد حدودكِ والالتزام بها دائمًا. وعندما يعاند طفلكِ، تذكّري أنكِ الطرف الأكثر نضجًا. ومن ناحية أخرى، لا جدوى من الدخول في صراع عناد معه، لأنكِ لن تتمكني من الفوز في هذه المعركة. :) فهذا لن يؤدي إلا إلى استمرار السلوك الذي لا ترغبين فيه. بدلًا من ذلك، استرخي واجلسي وحاولي أن تكوني قدوة لطفلكِ بهدوئكِ.') WHERE id = 'bc1477cb-0848-495f-b85f-1500cde5812a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذه الفترة التي أتممتِ فيها تدريب طفلكِ على استخدام الحمام أو ما زلتِ تواصلينه، قد تلاحظين أنه يواجه في بعض الأيام صعوبة في التبول. وقد تظهر لديه أعراض مثل البكاء أثناء التبول أو نوبات بكاء من دون سبب واضح. قد يكون ذلك من مظاهر مرحلة «العامين الصعبة»، لكنه قد يكون أيضًا علامة على وجود عدوى. تحدث عدوى المسالك البولية، وهي أكثر شيوعًا لدى الفتيات خصوصًا، نتيجة التهاب المسالك البولية. ويرجع شيوعها لدى الفتيات إلى سهولة انتقال البكتيريا بسبب طبيعة أجسامهن. إذا ظهرت لدى طفلكِ أعراض مثل ألم البطن، أو رائحة غير طبيعية للبول، أو القيء، أو الغثيان، أو فقدان الشهية، أو سلس البول، أو التبول المتكرر بكميات قليلة، فعليكِ استشارة الطبيب. وإذا أظهرت التحاليل وجود التهاب، فسيصف الطبيب العلاج المناسب بالمضادات الحيوية.') WHERE id = 'da48700f-d847-4b96-8c98-118ee88f992c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبحت السمنة لدى الأطفال في السنوات الأخيرة مشكلة شائعة في بلدنا، كما هي الحال في مختلف أنحاء العالم. ويُعد تناول الأطفال للسكر والحلويات المتنوعة والأطعمة منخفضة القيمة الغذائية وعالية السعرات الحرارية من أبرز أسباب السمنة. يتسبب السكر الأبيض في ارتفاع مستوى سكر الدم بسرعة ثم انخفاضه فجأة، ما يُدخل الأطفال في حلقة مستمرة من اشتهاء السكر. ومن المهم أيضًا الحد من تقديم الكعك والمعجنات المشابهة بدلًا من وجبة الإفطار؛ فهذه الأطعمة ذات المؤشر الغلايسيمي المرتفع تُسبب، مثل السكر تمامًا، شعورًا دائمًا بالجوع. كما تجذب الحلوى الهلامية الطرية المباعة في عبوات ملونة انتباه كل طفل. وعادةً ما تُصنع هذه المنتجات من الجيلاتين المستخرج بغلي الأجزاء العظمية من الماشية. باختصار، عليكِ إبعاد طفلكِ تمامًا عن هذه المنتجات التي لا يُعرف على وجه الدقة ما تحتوي عليه.') WHERE id = 'd02c7a47-3078-410b-a75a-b2f0b0e780c9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يثير اضطراب طيف التوحد، الذي ازداد انتشاره كثيرًا في الآونة الأخيرة، قلقكِ مثل كثير من الأمهات والآباء. يُعد التشخيص المبكر أهم نقطة في التعامل مع التوحد، لذلك من الضروري أن تعرفي علاماته. التوحد اضطراب عصبي بيولوجي يظهر منذ مرحلة الطفولة المبكرة، ويُعتقد أنه ناجم عن اختلاف في بنية الدماغ والجهاز العصبي أو طريقة عملهما. وعادةً ما يظهر قبل سن 3 سنوات، وقد يعيق التواصل مع الآخرين ويجعل الطفل ينغلق على عالمه الداخلي. وتؤثر هذه الحالة سلبًا في تواصل الطفل الاجتماعي وتفاعله وسلوكياته. قد يكون تشخيص التوحد وغيره من اضطرابات طيف التوحد صعبًا، لأن شدة الأعراض تختلف من طفل إلى آخر. ومن أشهر العلامات ضعف مهارات التواصل، وتجنب التواصل البصري، والسلوكيات المتكررة مثل رفرفة الذراعين أو ضرب الرأس أو تدوير جسم ما مرارًا، بالإضافة إلى صعوبة التكيف مع التغييرات. وقد يكون ضيق نطاق الاهتمامات وعدم الرغبة في العناق أو اللمس من علامات التوحد أيضًا.') WHERE id = '47c104cd-1ceb-4881-829f-8f78f639b9f1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدأ طفلكِ بمص إصبعه وهو لا يزال في رحمكِ. وفي عمر 18-24 شهرًا تقريبًا، قد يصبح مص الإصبع سلوكًا مستمرًا لأن منطقة الفم تكون المصدر الأساسي للشعور بالمتعة والرضا. كما يساعده مص إصبعه ضمن روتينه اليومي على تهدئة نفسه والشعور بالراحة. عادةً ما يكتسب الطفل بعد سن 2 سنوات مهارات جديدة للتعبير عن نفسه بالتزامن مع تطور النطق، فيقل مص الإصبع. لكن بعض الأطفال يواصلون هذه العادة مع تقدمهم في العمر، وقد يمصون أصابعهم عندما يشعرون بالخوف أو التعب أو الملل أو لمساعدتهم على النوم. إذا كان طفلكِ يواصل هذا السلوك أيضًا، فمن المهم مساعدته على تركه في الوقت المناسب وبالأساليب الصحيحة. فقد تؤدي الأساليب الخاطئة إلى شعور الطفل بأنه مُعاقب أو مذنب. على سبيل المثال، يمكنكِ التركيز على الأوقات التي لا يمص فيها طفلكِ إصبعه. ومدحه في هذه اللحظات سيمنحه دافعًا إيجابيًا ويشجعه على الابتعاد عن هذه العادة.') WHERE id = '0ce7f0c6-55c7-478c-bbc2-e2aef384f568';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما اكتمل بزوغ الأضراس اللبنية الثانية لدى طفلكِ. وإذا لم تظهر بعد، فنود تذكيركِ بأنها قد تكتمل خلال الشهرين المقبلين! :) قد يستمر اكتمال بزوغ الأسنان اللبنية حتى عمر سنتين ونصف أو حتى 3 سنوات، ويُعد وجود فارق يبلغ 6 أشهر أمرًا طبيعيًا. تُعد الأضراس أصعب الأسنان بزوغًا، لذلك قد تمرين بمرحلة أكثر توترًا مقارنةً بظهور الأسنان الأولى. وقد يظهر خلال هذه الفترة تورم أرجواني اللون في موضع بزوغ السن، ويُسمى طبيًا كيسة البزوغ. لا يتطلب الأمر عادةً تدخلًا طبيًا؛ فقد يساعد تدليك المنطقة أو تبريد عضّاضات التسنين في الثلاجة ثم إعطاؤها لطفلكِ. وفي حالات نادرة، قد تعجز السن عن البزوغ عبر الكيسة؛ وعندها يمكن للطبيب مساعدتها على الظهور بإجراء شق صغير.') WHERE id = '5201e9e6-1a37-48d8-b089-cbbfefcfd807';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدأ طفلكِ بالتبول أو التبرز في ملابسه مجددًا بعد فترة، رغم تعلّمه استخدام المرحاض على نحو صحيح. تُلاحظ هذه الحالة لدى بعض الأطفال، ومن المهم جدًا أن تعرفي كيفية التعامل معها بدلًا من الشعور بالهلع. إذا بدأ طفلكِ فجأة بقضاء حاجته في ملابسه بعد تعلّمه استخدام المرحاض، فعليكِ محاولة معرفة السبب ومراجعة ما يحدث في المنزل. يُعد تعلّم استخدام المرحاض آخر المهارات النمائية التي يكتسبها الأطفال في عمر ٢–٣ سنوات، ولذلك غالبًا ما يظهر التراجع عند هذه النقطة أولًا عند حدوث أي مشكلة. ويُقصد بالتراجع أن يطلب الطفل الذي فُطم منذ فترة طويلة الرضاعة الطبيعية مجددًا، أو أن يرغب الطفل الذي ترك اللهاية في النوم بها من جديد، أو أن يبدأ الطفل الذي أنهى التدريب على استخدام المرحاض بقضاء حاجته في ملابسه. عليكِ الانتباه إلى الأسباب التي قد تعكّر حياة طفلكِ اليومية وتدفعه إلى العودة إلى الشعور بالأمان المرتبط بمرحلة سابقة. فعلى سبيل المثال، قد تؤدي الضغوط التي يتعرض لها من أقرانه في الحضانة، أو المعاملة السلبية من أفراد الأسرة، أو ولادة أخ أو أخت جديدين إلى مثل هذه الاستجابات.') WHERE id = '618a4bda-826f-4f95-b833-9fc6f643980b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُظهر طفلكِ في حياته اليومية، ولا سيما في لحظات التوتر، بعض السلوكيات الشبيهة بالعُرّات. ومن أمثلتها شدّ شعره، أو هزّ ساقه، أو ضرب رأسه بشيء ما، أو مصّ إصبعه. عليكِ أولًا تحديد الأسباب التي تدفع طفلكِ إلى القيام بهذه الحركات. فإذا لاحظتِ، مثلًا، أنه يمصّ إصبعه عندما يشعر بالقلق والتوتر، فعليكِ حمايته من مصادر هذا التوتر. حاولي أيضًا تهيئة طفلكِ نفسيًا قبل أي تغييرات قد تسبب له الضغط النفسي. ولا تسمحي له بمشاهدة صور أو محتوى غير مناسب لعمره. إذا شعرتِ أنكِ غير قادرة على التعامل مع هذه الحالة بمفردكِ، فسيكون طلب المساعدة من مختص، بدلًا من الضغط على الطفل، هو الخيار الأنسب.') WHERE id = '45fb1590-a84e-4747-9499-1dc671d7ac73';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتخيّل طفلكِ خلال هذه المرحلة شخصًا لا يعرفه إطلاقًا ويتخذه صديقًا خياليًا. تظهر هذه الحالة في عمر عامين ونصف تقريبًا، وهي جزء طبيعي تمامًا من تطور التفكير المجرّد لدى طفلكِ. وقد تلاحظين أحيانًا أنه يستعين بهذا الصديق الخيالي لتأكيد أفكاره أو ينسب إليه خطأً ارتكبه. فإذا كسر شيئًا، مثلًا، فقد يقول إنه لم يفعل ذلك. وفي الواقع، لا يُعد هذا كذبًا بالمعنى الكامل، لأنه لم يكن يقصد كسر ذلك الشيء. لذلك، بدلًا من الغضب منه، عليكِ تشجيعه على التحدث عما حدث. عادةً ما يختفي الأصدقاء الخياليون بحلول سن السادسة. ويرجع ذلك إلى أن الطفل لا يزال غير قادر على إدراك الفرق بين الواقع والخيال إدراكًا كاملًا. وقد يؤثر تدخلكِ في هذه العملية سلبًا في نمو شخصية طفلكِ.') WHERE id = 'f133f827-1aea-4a05-8919-15682019fac0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الصعب جدًا في المستقبل التخلص من الاعتماد، المكتسب منذ الطفولة، على الأطعمة المعدلة وراثيًا والمنكّهات ومحسّنات الطعم المضافة إلى الوجبات السريعة. وقد يصبح أحيانًا فقدان الوزن الزائد الناتج عن التغذية غير السليمة واستعادة التوازن الهرموني المختل أمرًا بالغ الصعوبة أو حتى مستحيلًا. لهذا السبب تحديدًا، ينبغي ألا تعوّدي طفلكِ على الأطعمة المعبأة والوجبات السريعة. ولكي يكتسب طفلكِ عادات غذائية صحية، من المهم جدًا الالتزام بمواعيد منتظمة لتناول وجبات محضّرة في المنزل مع جميع أفراد الأسرة. قد يبدو الفشار، مثلًا، صحيًا جدًا، لكن الذرة من أكثر المحاصيل التي يشيع فيها التعديل الوراثي. وعند إضافة عوامل مثل تحضيره في الميكروويف، يصبح أكثر ضررًا لطفلكِ. كما تُعد قطع الدجاج المقلية، والبطاطس المقلية، والهمبرغر، ورقائق البطاطس، ومنتجات اللحوم المصنّعة الغنية بالنترات مثل السجق والنقانق من الأطعمة التي ينبغي إبعادها عن طفلكِ.') WHERE id = 'f814e388-56b0-4495-929d-571e82ff8364';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يصبح نظام نوم طفلكِ خلال هذه المرحلة مضطربًا أكثر من أي وقت مضى. وقد تشعر الأسر التي عانت سابقًا من مشكلات النوم ببعض الإحباط عندما تلاحظ استمرارها بعد سن الثانية. ورغم شيوع الاعتقاد بأن مشكلات نوم الأطفال ستتحسن تلقائيًا مع تقدمهم في العمر، فإن الواقع لا يكون كذلك دائمًا. إذا كنتِ تعانين أنتِ أيضًا من مشكلات نوم طفلكِ، فعليكِ الانتباه إلى بعض الأمور. فوفقًا للدراسات، يؤدي وجود التلفاز والإنترنت في المكان الذي يوجد فيه الطفل إلى مقاومته النوم بشكل مباشر. ويرجع ذلك أساسًا إلى فرط التحفيز. وباختصار، مثلما يسبب السكر والشوكولاتة تأثيرًا محفزًا في الجسم، تُحدث أجهزة مثل التلفاز التأثير نفسه. لذا فإن إيقاف تشغيل أجهزة مثل التلفاز والجهاز اللوحي والهاتف قبل موعد نوم طفلكِ بساعتين على الأقل سيخفف هذا التوتر إلى حد كبير.') WHERE id = '27bc15ff-de70-4213-99e8-421c8ec7be89';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد غذاء ملكات النحل منتجًا قيّمًا يفرزه النحل من أجسامه لتغذية يرقاته، وله دور مهم في صحة طفلكِ وتغذيته. وغذاء ملكات النحل، الذي يتمتع بقيمة غذائية عالية جدًا، مادة هلامية يفرزها النحل البالغ من العمر أسبوعًا واحدًا. ومن المعروف أنه يعزز جهاز المناعة، كما أن تناوله كل صباح مع ملعقة صغيرة واحدة من العسل يزيد من تأثيره. يحتوي كل ١٠٠ غرام من غذاء ملكات النحل على نحو ١٥ غرامًا من البروتين، كما أنه غني بفيتامينات المجموعة B وحمض الفوليك ومعادن المغنيسيوم والزنك والحديد. ويحتوي غذاء ملكات النحل على بروتين خاص يُسمى رويالاكتين لا يوجد في أي غذاء آخر، وعلى حمض دهني قيّم يُسمى 10-HDA. وبفضل كل هذه الخصائص، يُعد غذاء ملكات النحل منتجًا طبيعيًا يمكن استخدامه لدعم نمو طفلكِ وتطوره. وعند استخدامه بانتظام، ستلاحظين آثاره المتمثلة في تعزيز مناعة طفلكِ ودعم نموه الجسدي والعقلي وتنظيم شهيته.') WHERE id = 'a10c3d04-e569-47ea-bad2-70a751db07a2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعدّ الفترة الممتدة من عمر سنة، حين يبدأ الأطفال بالمشي، وحتى عمر 3 سنوات مرحلة الاستقلال. تذكّري أن طفلكِ لا يزال في هذه المرحلة. فهو يتعلّم الآن أن يكون فردًا مستقلًا وأن يقوم بالكثير من الأمور بنفسه. وعلى الرغم من أن كل جديد وتجربة يواجهها يمنحانه السعادة، فقد يثير المجهول قلقه أحيانًا. ليس من السهل التعامل مع المواقف غير المألوفة، لذلك لا يزال بحاجة إلى الدعم والتشجيع من شخص يثق به. وبتشجيعكِ وحده، يستطيع مواصلة استكشاف ما حوله. وخلال رحلة الاستكشاف هذه، لا مفر من أن يقوم أحيانًا بتصرفات ممنوعة. لذلك قد يعترض كثيرًا عندما يواجه حدودًا وقواعد. وقد يولّد لديه هذا الشعور بالمنع غضبًا أحيانًا. لكن هذه المواجهات تنمّي قدرة الطفل على قول "لا"، وهي خطوة مهمة نحو إدراك خياراته ومشاعره.') WHERE id = 'd9130ed0-2f5f-4d02-851c-ceed9e0bc359';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بينما يشكو بعض الآباء من أن أطفالهم يأكلون قليلًا، يقلق آخرون من إفراط أطفالهم في الأكل. إذا كنتِ تواجهين هذه المشكلة أيضًا، فعليكِ أولًا التفكير في الأساس الذي تعتمدين عليه لتحديد مفهوم "الكثير". تذكّري أن كل طفل مختلف، ولكل واحد منهم درجة شبع خاصة به. النهج الأنسب هو البحث عن سبب إفراط طفلكِ في الأكل. فإذا كان السبب فسيولوجيًا، فمن المهم جدًا استشارة طبيب أطفال، وإذا كان نفسيًا، فاستشيري اختصاصي تربية أو اختصاصي علم نفس. وقد يفرط الأطفال أحيانًا في الأكل لمجرد جذب الانتباه. وفي جميع الحالات، يجب ألا تتدخلي في طعام طفلكِ أو تُخضعيه لحمية غذائية من دون رأي الطبيب، لأن ذلك قد يؤدي إلى عواقب خطيرة على الطفل الذي لا يزال في مرحلة النمو والتطور.') WHERE id = 'b0d1338b-df42-42bb-9eec-8ea39482f47d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تواصل خلايا دماغ طفلكِ في هذه المرحلة جمع المعلومات الجديدة بسرعة مذهلة! فهو يخزّن في ذاكرته جميع تجاربه الحياتية ليستفيد منها مستقبلًا. وأصبح الآن يتعرّف إلى نفسه في المرآة، بل يرغب في تأمل صورته مرارًا بدافع الفضول. وهو يتدرّب على أن يكون مثل الأشخاص من حوله، ولا سيما من خلال تقليد الأعمال المنزلية البسيطة التي تقومين بها. وعندما يُصلح والده شيئًا في المنزل، قد يتفاعل وكأنه يشاهد أكثر حدث ممتع في العالم. ثم سيحاول تطبيق الحركات نفسها على ألعابه. وتسهم ملاحظات طفلكِ وتقليده والتجارب التي يخزّنها في ذاكرته أيضًا في إرساء أسس شعوره بالتعاطف مع الآخرين.') WHERE id = 'af02d5b9-9b5a-44a3-8a27-d35bbbd65550';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من النقاط المهمة التي ينبغي أن تنتبهي إليها في تغذية طفلكِ طريقة طهي الطعام. فأساليب مثل الطهي على البخار والطهي الخفيف لا تضر ببنية الأطعمة، وبذلك تحافظ على قيمتها الغذائية. ومن هذا المنطلق، فإن أفضل طريقة لجعل الخضراوات مفيدة لطفلكِ هي طهيها على البخار. أما السمك، فيمكنكِ تحضيره في الفرن أو على الشواية أو بطريقة الطهي على البخار. ويُعدّ القلي ضارًا جدًا لكل من الخضراوات والأسماك. وإذا أمكن، فإن تجنّب القلي تمامًا سيكون من أهم الاستثمارات في صحة طفلكِ مستقبلًا.') WHERE id = 'b026868b-14a9-4e91-9d7c-64f2335b71be';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حتى يبلغ طفلكِ نحو 36 شهرًا، يحتاج إلى 11 ساعة من النوم ليلًا وإلى 1,5-2 ساعة نهارًا. ينام معظم الأطفال في هذا العمر بين الساعة 19.00-21.00 مساءً، ويستيقظون بين الساعة 06.30-08.00 صباحًا. وتشير هذه المواعيد إلى أن نمط نومهم أصبح أقرب إلى نمط نوم البالغين. وقد يستمر نوم طفلكِ الأخف من نومكِ حتى يبلغ نحو 4 سنوات. وإذا استيقظ صباحًا قبلكِ، فمن المفيد أن تعلّميه كيفية العودة إلى النوم. ومن الشائع جدًا في هذه المرحلة أن يقاوم الطفل الذهاب إلى النوم. وقد يكون رفضه الذهاب إلى السرير ناتجًا عن الخوف من الظلام أو مخاوف متخيّلة. الخوف جزء من النمو الطبيعي للطفل، لذا عليكِ التعامل معه بتفهّم وحنان.') WHERE id = 'd4569b71-1c50-4817-b555-f4e1a27ff451';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعدّ الفترة بين عمر 2-6 سنوات المرحلة التي يتشكّل فيها وعي الطفل بالتغذية الكافية والمتوازنة. لكن الأنشطة الاجتماعية خلال اليوم وكثرة حركة الطفل قد تجعل هذه العملية أكثر صعوبة. ومن التحديات الأخرى أيضًا ميل الأطفال في هذا العمر إلى العناد. ينبغي أن يكون هدفكِ الأساسي ترسيخ عادات غذائية سليمة لدى طفلكِ قبل بلوغه سن المدرسة، لأن تفضيلات المذاق والعادات التي تتكوّن في هذا العمر تؤثر في حياته المستقبلية بأكملها. وأكبر خطأ يرتكبه الآباء هو الضغط على الطفل خوفًا من أن يبقى جائعًا. بل ينبغي للطفل أن ينظر إلى تناول الطعام بوصفه نشاطًا ممتعًا، لا نوعًا من العذاب.') WHERE id = 'cca7e654-d2f4-435d-ac1b-7bc12c892a08';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ما لم يكن الأمر متعلقًا بالسلامة أو بالقواعد الأخلاقية المهمة، ينبغي ألا تكثري من استخدام عبارات المنع مثل «لا» و«لا تفعل» مع طفلكِ. فقد تتحول هذه العبارات إلى حواجز يصعب تجاوزها في ذهنه المنفتح على التعلّم. وقد يؤدي منعه من فعل ما يرغب فيه إلى تحطيم خياله وتقليل ثقته بنفسه. لذلك، حاولي تفضيل أسلوب تواصل قائم على العبارات الإيجابية بدلًا من السلبية. وبدلًا من قول «لا»، يمكنكِ اقتراح بدائل أكثر متعة وفائدة لكليكما. عندما يرتكب الطفل خطأً، قد يشعر بالفعل بالذنب وبأنه سيئ. وبصفتكما أكثر شخصين يثق بهما، ينبغي لكِ ولشريككِ الوقوف إلى جانبه من دون إصدار أحكام عليه. وبينما توجّهينه نحو السلوكيات الصحيحة، احرصي أيضًا على حمايته من الشعور العميق بالذنب بسبب أخطائه.') WHERE id = 'adaca540-c013-4a03-bbd7-74d6af6f0d5a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تبدأ مرحلة جديدة ستقضين فيها أوقاتًا حافلة وممتعة مع طفلكِ. في هذه المرحلة، تتحسن تناسق حركات الطفل وقدرته على التوازن مع ازدياد قوة عضلاته. يكون طفلكِ مفعمًا بالطاقة ودائم الحركة، وقد يجد كثير من الآباء والأمهات صعوبة في مجاراة هذه الطاقة. وبالتوازي مع نموه الجسدي، يستمر نموه الذهني بسرعة أيضًا. لذلك، من المهم في هذه الفترة توجيه طفلكِ إلى أنشطة تعزز قوة عضلاته وإبداعه وقدرته على التحمل البدني. ويُعد ركل الكرة والجري وركوب الدراجة والتسلق أمثلة رائعة على الأنشطة المناسبة لطفل يبلغ من العمر 29 شهرًا. كما ستسهم كل هذه الحركات البدنية التي يؤديها إسهامًا كبيرًا في نموه الذهني أيضًا.') WHERE id = '1aab8015-59a1-447d-9108-ce75d06b5eba';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من عمر سنة واحدة، يزداد طول الأطفال بمعدل 5-7 سنتيمترات سنويًا، ويكتسبون نحو 2-3 كيلوغرامات من الوزن. لكن هذا النمو الجسدي قد يختلف تبعًا للعديد من العوامل. وفي هذه المرحلة، يبدأ العامل الوراثي في إظهار تأثيره بدرجة أكبر. لذلك، حتى إذا لم تتغير عادات طفلكِ الغذائية، فقد تلاحظين اختلافًا في تطور طوله ووزنه مقارنةً بأقرانه، سواء بالزيادة أو النقصان. فعلى سبيل المثال، قد يبدو أطفال الوالدين ذوي البنية النحيفة والصغيرة أصغر من أقرانهم مهما كان نظامهم الغذائي متوازنًا. لذا، ينبغي أن يكون رأي طبيبكِ هو المعيار الوحيد لتقييم النمو الجسدي. ويمكن أن يساعدكِ أيضًا مخطط المئينات (النمو) في هذا الشأن. وفقًا للمخطط، يبلغ الحد الأدنى لوزن الفتيات بعمر 29 شهرًا 10.000 غرام، والحد الأعلى 16.000 غرام. أما لدى الأولاد بعمر 29 شهرًا، فيبلغ الحد الأدنى للوزن 10.500 غرام، والحد الأعلى 16.400 غرام. وبالنسبة إلى الطول، يبلغ الحد الأدنى لدى الفتيات بعمر 29 شهرًا 83,4 سم والحد الأعلى 96,4 سم؛ أما لدى الأولاد، فيبلغ الحد الأدنى 84,9 سم والحد الأعلى 97,5 سم.') WHERE id = 'db8346fb-9273-49d5-bf2c-a86e6c17b290';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يستمد طفلكِ جزءًا كبيرًا من الطاقة التي يحتاج إليها خلال اليوم من الكربوهيدرات، تمامًا مثل البالغين. ويُعد الخبز في مقدمة مصادر الكربوهيدرات التي تلبي هذه الحاجة، إلى جانب مصادر أخرى. لكن تقع على عاتقكِ مسؤولية اختيار الأنواع الصحية منها. وينبغي لكِ ولطفلكِ تفضيل خبز القمح الكامل (الحبوب الكاملة) بدلًا من الخبز الأبيض. فدقيق القمح الكامل أقل معالجة، ولذلك فهو أغنى من حيث القيمة الغذائية. كما يُعد استخدام البرغل بدلًا من الأرز بديلًا جيدًا. وإذا كان طفلكِ يميل إلى اكتساب الوزن، فيمكنكِ تقليل حجم الحصص بدلًا من منع هذه الأطعمة تمامًا. وإلى جانب ذلك، يمكنكِ إدراج البقوليات التي تنتمي إلى مجموعة الكربوهيدرات الصحية، مثل الفاصولياء والحمص والعدس، في قائمة طعام طفلكِ 2-3 مرات أسبوعيًا.') WHERE id = '1c27be1f-dfab-44ba-8a0e-90b8852c1426';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يستمتع طفلكِ كثيرًا في هذا العمر بألعاب مثل المطاردة والغميضة. واللعب معكِ ذو قيمة كبيرة بالنسبة إليه، لأنه يشعر من خلاله بأنه شخص مرغوب فيه وأنكِ تبحثين عنه. كما تعزز لحظة العثور عليه أثناء لعب الغميضة فهمه لمفهوم بقاء الأشياء. وفي هذه المرحلة، قد يشارك بعض أغراضه لأن مفهوم الملكية لديه لم يكتمل بعد، لكنكِ قد تلاحظين أنه لا يشارك الأطفال الآخرين في لعبة جماعية مباشرة. فعادةً ما يراقب طفلًا آخر عندما يلعب بجانبه، لكنه قد يتصرف كما لو أنه غير موجود. ومع ذلك، قد يبادل طفلكِ طفلًا آخر الضحك عندما يراه يضحك، أو قد يشعر بالخوف عند بكائه. بل قد تلاحظين أيضًا شعوره بالتوتر إذا كان هو من تسبب في بكاء طفل آخر.') WHERE id = '48eeead7-4aaf-4261-980b-2417b364eaf1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه الأيام التي يقترب فيها طفلكِ من عمر 2.5 سنة، من الطبيعي تمامًا أن يرغب في تناول حصص أصغر وأن يقول كثيرًا «شبعت». ولا يعني ذلك بالضرورة أن طفلكِ فقد شهيته، لذا لا تقلقي. والسبب الرئيسي هو أن سرعة نموه أصبحت أبطأ بكثير. عندما يبدأ طفلكِ بتناول كميات أقل، يكون الخيار الأفضل هو تقديم وجباته في حصص صغيرة، مع الحرص على أن تكون أغنى بالعناصر الغذائية. في هذه المرحلة، قد يتناول الطفل نصف كمية الطعام التي يتناولها شخص بالغ كحد أقصى. لذلك، من المهم جدًا ألا تجبريه على تناول المزيد. واحرصي على أن تكون الكميات القليلة التي يتناولها صحية. وينبغي أن يتمكن طفلكِ من الوصول بسهولة إلى وجبات خفيفة صحية متى أراد، بينما يجب إبقاء الأطعمة غير الصحية بعيدًا عن متناول يده.') WHERE id = '3870e199-6a66-48e6-9897-cabfbe66081e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وصل طفلكِ الآن إلى مرحلة يمكن أن يتحول فيها كل غرض في المنزل إلى لعبة بالنسبة إليه، بما في ذلك أغراضكِ الشخصية. فقد ينقل الأشياء التي يراها ألعابًا إلى أماكن مختلفة في المنزل، أو يبعثرها في كل مكان، أو يغيّر مواضعها. ورغم أن ذلك قد يسبب فوضى كبيرة في المنزل، فإن محاولة منعه ليست رد فعل صحيًا؛ لأن طفلكِ يكتشف العالم ويتعرّف إليه ويتعلم من خلال اللعب. وقد يؤدي تقييده باستمرار إلى إخماد شغفه بالتعلم. الأفضل هو وضع حدود واضحة؛ فمثلًا، يمكنكِ منعه من اللعب بالأدوات الحادة والمدببة في المطبخ، مع السماح له باللعب بالقدور. وبعد انتهاء اللعب، يمكنكما جمع الأغراض معًا لتعليمه الشعور بالمسؤولية.') WHERE id = '368b3b11-1e1f-4a83-bc4e-453fba29a7a6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن طفلكِ قد أتمّ التدريب على استخدام المرحاض، فقد يظل يبلل فراشه ليلًا. ويُسمّى ذلك طبيًا «سلس البول الليلي». عادةً ما يتعلم معظم الأطفال التحكم في البول ليلًا ونهارًا في نحو سن 2، بفضل التدريب على استخدام المرحاض ونمو المثانة. وغالبًا ما تنتج مشكلة التبول اللاإرادي ليلًا عن تأخر نمو المثانة، وتزول مع التقدم في العمر. إذا لاحظتِ هذه الحالة، فاستشيري الطبيب أولًا للتأكد من عدم وجود مشكلة مثل التهاب المسالك البولية. وإذا لم يكن السبب مرضيًا، فيمكنكِ الانتباه إلى بعض الأمور: قللي تناول السوائل خلال الساعتين السابقتين للنوم، وتجنبي المشروبات المحتوية على الكافيين. والأهم من ذلك، لا تجعلي طفلكِ يرتدي حفاضًا ليلًا لمجرد الحفاظ على النظافة؛ لأن ذلك قد يضعف دافعه إلى الاستيقاظ ليلًا.') WHERE id = '8d79c984-59c4-461b-b19e-f63da9c3b917';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه المرحلة أن طفلكِ يقول أشياء لا تتوافق مع الواقع، لكن هذا لا يُعد «كذبًا» بالمعنى الحقيقي للكلمة. فحتى سن 5-7 سنوات، لا يستطيع الأطفال التمييز تمامًا بين عالم الخيال والواقع. وقد يختلق الأطفال، وخصوصًا في سن 2.5-3 سنوات، بعض القصص لجذب الانتباه. فمثلًا، إذا قال طفلكِ إن دمية الدب الخاصة به هربت واختبأت، فهذا ليس كذبًا، بل من نسج خياله. عالم طفلكِ الخيالي واسع جدًا، لذا لا ينبغي لكِ اعتبار هذه التصرفات «كذبًا» أو لومه عليها. ستتراجع هذه السلوكيات تدريجيًا، وعادةً ما تختفي تمامًا بحلول سن 7 سنوات.') WHERE id = '312018ab-f646-4975-9148-a5d080d99b50';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ما زلتِ القدوة الأهم لطفلكِ، وهذا يعني أنه سيرغب في تذوق كل ما تأكلينه وتشربينه. يثير الشاي والقهوة والمشروبات الغازية فضول الأطفال كثيرًا. وأحيانًا لا يصمد الوالدان أمام إصرار الطفل، فيسمحان له بتذوق القليل من هذه المشروبات الضارة. لكن مواد مثل الثيين الموجود في الشاي والكافيين الموجود في القهوة لها تأثير منبّه وقد تسبب الاعتماد عليها. كما أن الشاي والمشروبات المشابهة تقلل امتصاص الحديد، ما قد يؤثر في مستواه في الدم. أما المشروبات الغازية والملونة، فقد تسبب العصبية لدى الأطفال، فضلًا عن أضرارها الصحية. والأفضل ألا يتعرّف طفلكِ إلى مذاق هذه الأنواع من المشروبات أصلًا.') WHERE id = 'd3f39e2d-95d5-4448-a3ee-5735bd480f16';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مهما حاولتِ حمايته، فقد يمرض طفلكِ من وقت إلى آخر. ولتقليل شدة هذه الأمراض، من المهم تقوية جهازه المناعي. ومن أكثر الطرق الطبيعية لتحقيق ذلك أن يتعرض الطفل للبكتيريا «النافعة». فعندما يقضي الأطفال وقتًا في الطبيعة ويلعبون بالتراب، تتطور مناعتهم بصورة أقوى. ونظرًا إلى تراجع اللعب خارج المنزل في عصرنا، حاولي قضاء وقت أطول مع طفلكِ في الطبيعة. كذلك لا تبعديه عن الأطفال الآخرين خوفًا من أن يمرض. تشير الأبحاث إلى أن الأطفال الذين يتواصلون كثيرًا مع أقرانهم ويشاركون في مجموعات اللعب يتمتعون بجهاز مناعي أكثر قدرة على المقاومة.') WHERE id = 'f9d7a8b1-31bd-4aa3-ada9-e3738e8a0231';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ في هذه المرحلة يدرك أن للطعام أدوارًا تتجاوز مجرد التغذية. فمثلًا، يتعرّف خلال هذه الفترة إلى استخدام الطعام كرشوة أو مكافأة أو هدية، كما يكتشف قوة رفضه له. وقد تسمعين طفلكِ الآن يقول إنه شبع بعد تناول حصة أصغر من الطعام. ويرجع ذلك جزئيًا إلى أن معدل نموه أصبح أبطأ بكثير مقارنة بمرحلة الرضاعة، وبالتالي انخفض احتياجه إلى السعرات الحرارية. والأهم هو ضمان حصوله على هذه السعرات من أطعمة صحية. فلا تتوقعي أن يتناول الطفل طبق الخضراوات بشهية على العشاء إذا كان قد ملأ معدته بعصير الفاكهة والبسكويت المملح قبله. يمكنكِ البدء بتقليل كمية الوجبات الخفيفة واختيار أطعمة أقل حلاوة. أما في الوجبة الرئيسية، فإذا قدّمتِ الأطعمة بالتتابع، بدءًا بالخضراوات ثم البروتينات وبعدها الكربوهيدرات، فستلاحظين أن طفلكِ يكون أكثر استعدادًا لتناول الخضراوات عندما يكون في أشد حالات الجوع.') WHERE id = '644f27a1-772e-4290-a4c7-b64545b7ca56';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من بين سمات نمو طفلكِ في عمر ٢٫٥ سنة قدرته على تمييز الألوان، واستخدام الكلمات استخدامًا صحيحًا، والبدء في العدّ. وقد تختلف هذه المهارات تبعًا للطريقة التي توجهينه بها بصفتكِ أمًّا. في هذه المرحلة، يبدأ طفلكِ أيضًا في تكوين شعور بالاستقلالية، إلى جانب رغبته في التحكم في البيئة المحيطة به. ويُعد عمر ٢٫٥ سنة إحدى أصعب مراحل النمو لدى الطفل. ففي هذه الفترة، التي تُسمى أيضًا مرحلة العناد، قد يُظهر طفلكِ سلوكيات سلبية ومتمردة ومترددة للغاية. وتبدأ رغبته في فرض سيطرته على محيطه في التصادم مع القيود التي تفرضها البيئة المحيطة والوالدان. ومن الطبيعي تمامًا أن يكون الطفل سريع الانفعال وأن يتصرف باندفاع في هذه المرحلة، فهذا جزء طبيعي من نموه. لذلك، قد يكون من المفيد إشراك طفلكِ بصورة أكبر في البيئات الاجتماعية خلال هذه الفترة، دعمًا لنموه العاطفي والاجتماعي.') WHERE id = 'fd9715f6-ed39-43d1-a0a5-6696d68a16b2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين في هذه المرحلة أن طفلكِ يستمتع كثيرًا بالرسم، وأنه يطلق أسماء على الرسومات التي يرسمها. وبما أنه أصبح مدركًا تمامًا لاسمه، فقد يبدأ في إخبار الآخرين به. ومع تسارع نموه العقلي، يواصل تطوير المفاهيم الأساسية التي تعلمها. فعلى سبيل المثال، قد تلاحظين زيادة عدد الألوان التي يعرفها، وتعلّمه بعض الأغاني وغناءها، وبدءه في عدّ الأرقام حتى وإن لم يكن ترتيبها صحيحًا. يستطيع طفلكِ في هذه المرحلة استخدام ما لا يقل عن ٢٠٠ كلمة مختلفة. كما يمكنه نطق ضمائر المتكلم مثل "أنا، إياي، لي" بوضوح. ومع ذلك، لا داعي للقلق إذا لم تنعكس هذه التغيرات الكبيرة في قدراته اللغوية بعد على استخدام صيغ الأزمنة؛ إذ لا يزال طفلكِ بحاجة إلى بعض الوقت كي يفهم مفاهيم الزمن ويستخدمها، مثل "جاء، يأتي، سيأتي".') WHERE id = '0ce06f10-94aa-437c-be3f-bceab8e03d9c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يطوّر طفلكِ في هذه المرحلة بعض العادات أو الاهتمامات المتكررة تجاه أشياء وأحداث مختلفة. فمشاهدة مسلسل الرسوم المتحركة نفسه مرارًا، والاستماع إلى الحكاية نفسها، واصطحاب لعبته أو بطانيته المفضلة إلى كل مكان، كلها سلوكيات شائعة لدى الأطفال بين عمر سنتين و٥ سنوات. ويُعد ظهور السلوكيات والعادات المتكررة لدى الأطفال في هذه المرحلة العمرية جزءًا من عملية النمو الطبيعية. وقد ترتبط رغبته الدائمة في الشرب من الكوب نفسه بصورة شخصيته الكرتونية المفضلة عليه أو بلونه المحبب. وقد يشعر الوالدان أحيانًا بالقلق عند تكرار هذه السلوكيات، لكنها عادةً ما تبدأ بالتراجع بعد سن الخامسة.') WHERE id = '2a252a94-6183-4f26-b967-1e55f04f7793';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة التي يبلغ فيها ضعف الشهية والانتقائية في تناول الطعام ذروتهما، قد يشعر بعض الآباء بالقلق بشأن زيادة وزن أطفالهم. ولا ينصح المختصون باتباع الأطفال حميات أو برامج قاسية لإنقاص الوزن خلال هذه الفترة، ما لم يكن الوزن قد بلغ بالفعل مستوى حرجًا. فالحميات شديدة التقييد قد تعيق نمو الأطفال وتؤدي إلى مشكلات صحية أخرى إذا لم تُتابَع بعناية. ويوصي المختصون عادةً بتصحيح العادات الغذائية وزيادة النشاط البدني لدى الأطفال الذين يعانون من زيادة الوزن. والهدف هنا هو تقليل الأنسجة الدهنية مع استمرار نمو الطول وتطور العظام والعضلات. ويجب إجراء هذه العملية تحت إشراف مختص. وينبغي ألا يقع الوالدان في خطأ تطبيق حميتهما الغذائية على الطفل، بل يجب أن يحدد الطبيب الأهداف بما يتناسب مع عمره ومرحلة نموه.') WHERE id = '12d89f35-8555-4479-a974-3feb5d64d6dc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اللعب وسيلة نمو أساسية لكل طفل. وتكتسب الألعاب واللُّعب أهمية كبيرة في دعم النمو الجسدي والعقلي لطفلكِ الذي يحتاج إلى تفريغ طاقته. ويُعد لعب الأدوار العائلية، الذي يحبه الأطفال جميعًا سواء كانوا أولادًا أم بنات، من أكثر الأنشطة المنزلية فائدة لطفلكِ في عمره الحالي. ففي هذا النوع من اللعب، يتقمص طفلكِ شخصيات مختلفة ويتصرف بما يتناسب مع كل شخصية، مما يدعم نمو ذكائه ويساعده أيضًا على الشعور بالراحة النفسية. كما يساعده هذا اللعب على التعرف إلى ذاته ويهيئه للأدوار الكبيرة التي سيتولاها مستقبلًا. ويستفيد طفلكِ أثناء اللعب من التجارب التي يمر بها في حياته اليومية، وينقل كذلك خياله ومشاعره إلى اللعبة. وهكذا يتعلم وضع نفسه مكان الآخرين، وتحمل المسؤولية، والتعبير عن مشاعره، والتخفيف عن نفسه من خلال مشاركة ما يزعجه داخل الأسرة. وأثناء تمثيل الأدوار، تتطور قدرته على التعبير عن نفسه والتحدث بطلاقة، وتتسع حصيلته اللغوية. لذلك، يُعد لعب الأدوار العائلية من أفضل الأنشطة التي يمكنكِ ممارستها مع طفلكِ.') WHERE id = '7052912b-8ae5-42fd-9ebb-4b3f1ca4c1a8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لاحظتِ أن طفلكِ يضرب الأطفال الآخرين من حوله أو يعضّهم أو يكسر الألعاب، فعليكِ اتخاذ موقف حازم. وباختصار، من المهم جدًا أن تقولي له: "يُمنع إيذاء الآخرين أو إيذاء نفسك!" وألّا تتراجعي عن هذه القاعدة. وحتى إذا منحتِ طفلكِ بعض الحرية في القواعد العامة، فلا تترددي في وضع حدود صارمة للسلوك العنيف. فبهذه الطريقة فقط سيفهم طفلكِ ضرورة احترام الآخرين، ووجود قواعد اجتماعية يجب الالتزام بها. أما أهم ما ينبغي أن تنتبهي إليه فهو ألّا تعاقبي طفلكِ على خطئه أبدًا، مهما كان سلوكه غير مقبول. فعلى سبيل المثال، ليس من الصواب أن تعضّيه لتُظهري له مقدار الألم الذي شعرتِ به عندما عضّكِ. بل إن هذا الأسلوب الخاطئ قد يزيد سلوكه سوءًا. والأفضل أن توضحي له بالكلام أن الضرب أو العض يسبب ألمًا شديدًا، وأن تتيحي له فرصة إدراك خطئه بنفسه.') WHERE id = '1d14becf-2063-41bf-9be0-72a1734a9d5c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه الفترة أن طفلكِ يرى كوابيس متكررة، وقد يستيقظ صارخًا أحيانًا. في هذه الحالة، توجّهي إليه فورًا وهدّئيه وتحدّثي معه عن مخاوفه. إذا لم تتكرر هذه الحالات كثيرًا، فلا يوجد سبب جدي للقلق. أما إذا استمرت بانتظام، فعليكِ البحث عن العوامل التي قد تسببها خلال النهار (مثل مشاهدته حادثة عنيفة، أو تعرّضه لصدمة نتيجة السقوط، أو رؤيته شخصيات مخيفة على التلفاز)، واستشارة مختص عند الحاجة. ستساعدكِ متابعة الأشخاص الذين يتواصل معهم طفلكِ وما يشاهده خلال اليوم عن كثب على حل المشكلة. وبعد تحديد السبب، ستلاحظين أن الكوابيس تختفي تدريجيًا.') WHERE id = 'b61f296a-4531-4652-8575-c61cd39dfd62';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أكملتِ عامين ونصف العام برفقة طفلكِ، تهانينا! لكن عمر 2.5 سنة قد يكون أيضًا بداية مرحلة جديدة تُعرف باسم «متلازمة سن الثالثة». فقد أصبح لديه الآن رأي في كل موضوع، ويرغب في إثبات ذاته والحصول على التقدير. هذه مرحلة طبيعية من النمو، لذا لا تدخلي معه في صراع عناد؛ فلا معنى للتعامل معها كمعركة يجب أن يفوز فيها أحدكما. حاولي في اللحظات الصعبة تحويل انتباه طفلكِ إلى شيء آخر، وانتظري بصبر حتى تهدأ نوبة غضبه. تجنّبي العقوبات القاسية، لأن المشاعر في هذا العمر شديدة التقلب؛ فقد يبكي الطفل في لحظة ثم يهدأ في اللحظة التالية. وأصبح الآن من الأسهل مقارنة بالسابق تهدئته عبر جذب انتباهه إلى نشاط آخر ممتع.') WHERE id = '639bc96b-c7fc-4373-a80d-f5910cdd0c67';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن خصائص النمو والتغيرات التي يمر بها طفلكِ في هذه الفترة قد تختلف عن غيره من الأطفال، فإنها تتبع عمومًا مسارًا متوقعًا. إن معرفتكِ بهذه التغيرات ستخفف من مخاوفكِ، كما أنها مهمة للغاية لتتمكني من دعم طفلكِ. في عمر 2.5 سنة، قد يظهر لديه بوضوح الخوف من الغرباء والخوف من الانفصال. فقد لا يرغب في الابتعاد عنكِ خشية أن تتركيه، وفي الوقت نفسه قد يتوق إلى قضاء الوقت مع أقرانه؛ لأنه أصبح الآن يدرك مَن يحبهم من أقرانه ويرغب في التقرب منهم. لكن عندما يقع في هذا التردد، قد يُظهر سلوكًا عنيدًا أكثر من أي وقت مضى. في مثل هذه الحالات، من المهم جدًا أن تحافظي على هدوئكِ قدر الإمكان، وأن تدركي أن هذه المرحلة مؤقتة، وأن تشعريه بأنكِ بجانبه دائمًا.') WHERE id = '68cb6aa4-e74d-46fc-9a61-c95e7e0181e6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أهم ما يميز جسم الطفل عن جسم البالغ أنه يمر باستمرار بعملية نمو وتطور. إلا أن هذا النمو يختلف من طفل إلى آخر. فمثلًا، تتباطأ وتيرة النمو قليلًا بين عمر 1-2 سنة، ثم تستمر بوتيرة ثابتة بين عمر 2-10 سنوات. وخلال مرحلة المراهقة تحدث طفرة نمو سريعة من جديد. باختصار، يمر طفلكِ حاليًا بمرحلة يستقر فيها نمو الطول وزيادة الوزن نسبيًا. وبفعل جميع العوامل البيئية والوراثية، قد تختلف مؤشرات الوزن والطول كثيرًا بين الأطفال في هذا العمر. فمثلًا، قد يبلغ وزن طفل في عمر 2.5 سنة 9.900 غرام، بينما قد يبلغ وزن طفل آخر 16.500 غرام. والأهم بالنسبة إلى طفلكِ أن يبقى وزنه ضمن هذه القيم الطبيعية التي تُعرف بالنطاق الآمن.') WHERE id = '02cec2db-f46a-42b8-bf27-568e1890c0f7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يحتاج طفلكِ خلال هذا الشهر إلى تلقّي الجرعة المعززة من لقاح التهاب الكبد A. والتهاب الكبد A هو عدوى تصيب الكبد نتيجة انتقال الفيروس الذي يحمل الاسم نفسه. ورغم تفاوت انتشار هذا المرض بحسب الظروف الاجتماعية والاقتصادية ومنطقة السكن، فإنه واسع الانتشار في جميع أنحاء العالم. وتزداد الإصابة به خلال الخريف والأشهر الأولى من الشتاء. ويُعد لقاح التهاب الكبد A الوسيلة الأكثر فعالية للوقاية من هذا المرض. وتشير الدراسات الطبية إلى أن عدد الإصابات السنوية انخفض انخفاضًا حادًا بفضل حملات التطعيم واسعة النطاق. لذلك يؤدي اللقاح دورًا وقائيًا بالغ الأهمية في حماية طفلكِ من الإصابة بالتهاب الكبد A.') WHERE id = 'df299f90-e498-4bad-8aac-c9ce133896e2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن يكون هدفكِ الأساسي في تغذية طفلكِ تلبية احتياجات جسمه من الفيتامينات والمعادن والبروتينات والكربوهيدرات والدهون. وتمثل الفترة بين عمر 2-6 سنوات مرحلة يتكوّن فيها وعي الطفل بالتغذية الكافية والمتوازنة. ومع ذلك، قد تجعل الأنشطة الاجتماعية وفرط حركة الطفل عملية التغذية أكثر صعوبة قليلًا. كما أن عناد طفلكِ في هذا العمر قد يكون أحد التحديات التي تواجهينها. والنقطة المهمة هنا هي ترسيخ عادات غذائية سليمة لدى الطفل قبل بلوغه سن المدرسة؛ لأن تفضيلاته في المذاق والعادات التي تتشكل في هذا العمر ستؤثر في حياته المستقبلية بأكملها، ومن الصعب جدًا تغييرها لاحقًا. تذكّري أن العادات الغذائية الخاطئة في الطفولة تقف وراء مشكلات الوزن والصحة لدى كثير من البالغين.') WHERE id = 'fe0a2002-9184-44fe-a34f-37af62aa35fd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يحب السمك، فالسبب الأرجح، كما هي الحال لدى الأطفال الآخرين، هو انزعاجه من رائحته. فالأطفال يقيّمون الطعام من خلال المذاق والرائحة والشكل معًا. وإلى جانب ذلك، قد تدفع بعض الأعراض المزعجة التي تظهر بعد تناول السمك طفلكِ إلى رفضه. وعلى الرغم من أن حساسية السمك تصيب شخصًا واحدًا من كل 200 شخص في المتوسط، فإن معدلها مرتفع نسبيًا بين الأطفال. ومن أعراض حساسية السمك: الغثيان، والقيء، والإسهال، وتقلصات المعدة، وأزيز التنفس، وسيلان الأنف، واحمرار الجلد وتورمه. وتشمل المأكولات البحرية التي قد تسبب الحساسية: الماكريل، والتونة، والكركند، والسردين، والروبيان، وسرطان البحر، والحلزون، وبلح البحر. كذلك، تتطاير جزيئات بروتينية صغيرة أثناء طهي السمك، لذا قد يؤدي حتى استنشاق هذا البخار إلى إثارة رد فعل تحسسي لدى الأطفال المصابين بالحساسية.') WHERE id = 'ac158c46-bbd5-4329-8d4c-0e71f3f20b42';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الرقص نشاطًا مثاليًا لطفلكِ في مرحلة نموه الحالية. فالرقص ليس مجرد رياضة، بل هو فن أيضًا. وهو ينمّي لدى الطفل الإحساس بالتناغم والإيقاع والتوازن. وإلى جانب ذلك، يعلّم الرقص طفلكِ كيفية التعبير عن مشاعره، ويساعده على التخلص من التوتر، ويعزز قدرته على التعامل مع الضغوط. ومن أهم فوائد الرقص أيضًا تأثيره الإيجابي في النمو البدني. إذ يصبح جسم طفلكِ الذي يرقص أكثر مرونة وقوة ورشاقة. ولأن حركات الرقص تُؤدى مع إطالة العضلات، فإنها تساعد على نمو بنية العظام والعضلات وتناسق شكل الجسم بصورة أفضل وأكثر رشاقة. وللرقص دور مهم في الوقاية من اضطرابات القوام التي قد تظهر مستقبلًا. كما أنه مفيد جدًا للوقاية من تسطح القدمين، وانحراف القدمين إلى الداخل أثناء المشي، وانحناءات العمود الفقري. وبالنظر إلى كل هذه الفوائد، يمكنكِ تشجيع طفلكِ خلال اليوم على الرقص على أنغام موسيقى مناسبة.') WHERE id = '068ebdad-194f-4a1d-9270-77ef045bd6c5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر طفلكِ حاليًا بمرحلة قد تقل فيها شهيته للأطعمة الصحية، بينما يزداد إقباله بشدة على المنتجات السكرية والمعلبة الجاهزة. ويحب جميع الأطفال تقريبًا هذا النوع من الأطعمة، وقد يتناولون منه كميات مفرطة إذا لم تضعي حدودًا لذلك. تذكّري أن الانتقائية في الطعام شائعة جدًا وطبيعية لدى الأطفال في مرحلة ما قبل المدرسة. أي أنكِ لستِ وحدكِ في هذا الأمر، فهناك الكثير من الآباء والأمهات الذين يشاركونكِ المشاعر نفسها. لذلك، سيتطلب منكِ إطعام طفلكِ طعامًا صحيًا ومتوازنًا خلال هذه المرحلة بعض الصبر والجهد. وإذا استسلمتِ لانتقائيته في الطعام في هذا العمر، فقد لا يتمكن من التغلب على هذه المشكلة، وقد تُرسى بذلك أسس مشكلات غذائية تستمر معه في مرحلة البلوغ. وفي هذه الفترة، ينبغي أن تقدمي له أكبر تنوع ممكن من الأطعمة وتشجعيه على تجربة نكهات جديدة.') WHERE id = '57a840ed-dc9e-4918-86ea-a8434bde9387';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تقتصر أهمية الحركة المنتظمة على البالغين، بل إنها مهمة جدًا للأطفال أيضًا. وتُظهر الدراسات أن خطر الإصابة بالأمراض ينخفض بنسبة 57% لدى الأطفال النشطين الذين يمارسون الرياضة خلال اليوم. وفي الوقت نفسه، يكون الأطفال الذين يتحركون بانتظام أقل عرضة للإصابة بعدوى الجهاز التنفسي العلوي، كما يتعافون بسرعة أكبر عند الإصابة بنزلات البرد. لذلك، تكتسب الأنشطة التي يمكنكِ ممارستها مع طفلكِ أهمية كبيرة. كما يعزز النشاط البدني جودة نوم طفلكِ. فعلى سبيل المثال، يُعد اللعب في الحديقة بملابس مناسبة للطقس، بصرف النظر عن الفصل، نشاطًا رياضيًا ممتعًا ومفيدًا في آنٍ واحد. وتُعد النزهات العائلية، ولعبة المطاردة، والكرة الطائرة، وكرة القدم، والسباحة أنشطة مفيدة جدًا لطفلكِ.') WHERE id = 'b3c41e3b-28a4-4d9f-a7f2-3d2269ca1f16';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يستعين المختصون بالهرم الغذائي للجمعية الأمريكية لاختصاصيي التغذية عند تخطيط النظام الغذائي للأطفال بعمر 2-3 سنوات. ووفقًا لهذا الهرم، توجد 5 مجموعات غذائية أساسية ينبغي للأطفال تناولها. المجموعة 1: الحبوب والخبز؛ المجموعة 2: الخضراوات والفواكه؛ المجموعة 3: الحليب والزبادي؛ المجموعة 4: اللحوم والبيض والبقوليات؛ أما المجموعة 5 فهي السكريات والدهون. وينبغي أن تكون الحصة اليومية لطفلكِ كما يلي: 6 حصص من المجموعة 1 (نصف شريحة خبز، أو وعاء صغير من الأرز أو المعكرونة)؛ 5 حصص من المجموعة 2 (عصير الخضراوات، أو الفاكهة الطازجة)؛ 3 حصص من المجموعة 3 (نصف وعاء من الزبادي أو الحليب، أو قطعة جبن بحجم علبة ثقاب)؛ حصتان من المجموعة 4 (1 ملعقة طعام من الدجاج أو السمك أو اللحم، و1 بيضة)؛ و3-4 حصص من المجموعة 5 (1 ملعقة شاي من الزيت النباتي أو الزبدة خلال اليوم).') WHERE id = '962b4a12-0b09-4183-b941-3cfed8499be2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يسعد كل والد ووالدة سماع عبارة: “ما أروع أدب طفلكِ!”. فتربية طفل يتعامل باحترام هي عملية تتطلب الصبر، وتقديم القدوة، والتقدير. وإذا أردتِ أن يكون طفلكِ محترمًا، فعليكِ أولًا أن تكوني قدوة له. إذ يتعلم طفلكِ الأدب منذ طفولته المبكرة ممن حوله. فعلى سبيل المثال، عندما ينتزع شيئًا من يدكِ، يمكنكِ أن تقولي له “من فضلك”، أو عندما يشد شعركِ، يمكنكِ أن تقولي “هذا يؤلمني” وتفتحي يده برفق؛ فمثل هذه التصرفات تعلّمه اللطف. ومن الضروري أن يشعر طفلكِ بأنه يحظى بالاحترام. ومن أفضل الأمثلة على ذلك أن تستمعي إليه من دون مقاطعته مع النظر في عينيه، وأن تطرقي باب غرفته قبل الدخول، وأن تسأليه عن رأيه عند اتخاذ قراراتكِ. كوني ثابتة في تصرفاتكِ؛ لأن رد فعلكِ الصارم أحيانًا والمتساهل أحيانًا أخرى تجاه الموقف نفسه قد يزعزع ثقة طفلكِ بكِ واحترامه لكِ.') WHERE id = 'faf2efdc-0dd3-4966-8ab3-9c85e83a2de6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر طفلكِ عمومًا بمرحلة يتباطأ فيها نموه وتطوره نسبيًا. لذلك قد يأكل قليلًا في بعض الأيام، وأكثر في أيام أخرى. ومن المهم جدًا ألّا تجبريه على تناول كمية محددة من الطعام كل يوم. وكما هو الحال دائمًا، عليكِ احترام شهية طفلكِ في هذا العمر أيضًا. إن تقديم الطعام في أوقات محددة وعدم تشجيعه على تناول الأطعمة غير الصحية (كالوجبات الخفيفة والحلوى) أمران مهمان لاكتسابه عادات جيدة. وأهم شرط لتكوين عادات غذائية صحية هو أن تكوني ثابتة في تصرفاتكِ وأن تقدّمي له قدوة حسنة بصفتكِ أمًا. باختصار، لن يفيد أن تأكلي الشوكولاتة ثم تضغطي على طفلكِ ليأكل البيض على الفطور. كذلك فإن الإلحاح المستمر عليه ليأكل، أو وضع قواعد تتعلق بالمكافأة أو العقاب، سيؤثر سلبًا في سلوكه الغذائي مستقبلًا.') WHERE id = '0ff6de72-1685-4d41-9fb9-6bad83bfb59a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الإبداع هو أكثر أشكال التعبير عن الذات حرية. ولا شيء يمنح طفلكِ شعورًا بالرضا أكثر من التعبير عن نفسه بحرية وانفتاح. وقد لاحظتِ منذ لحظة ولادته أنه يراقب محيطه باستمرار ويستمع ويخوض تجارب مختلفة. أما في هذه المرحلة، فستزيد كل تجربة واكتشاف جديدين من حماسه. إن دعم هذه القدرة الفطرية بالنهج الصحيح سيكون عاملًا حاسمًا في تنمية التفكير الإبداعي لدى طفلكِ طوال حياته. لذا عليكِ دعم جميع محاولاته. قد يستغرق وصول طفلكِ إلى نتيجة مثالية بعض الوقت، لكن الأهم هو أن تقدّري جهده وتثني عليه. فهذا سيعزز ثقته بنفسه ويساعده على إظهار مواهبه.') WHERE id = '4508e3d7-7e76-4f2d-8b22-fd23d4a47309';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُظهر الدراسات أن لكل طفل أسلوبه الخاص في التعلم وإمكاناته المميزة. ومع نمو طفلكِ، يمكنه استيعاب المعلومات الجديدة بسرعة أكبر بدعمكِ. لكن أهم ما في الأمر هو غرس الحماس للتعلم والفضول لديه. فعلى سبيل المثال، يمكنكِ إتاحة الفرصة له لاتخاذ قراره بنفسه من بين الخيارات التي تقدمينها له. وعليكِ تقدير الجهد الذي يبذله بدلًا من الثناء على نجاحاته فقط. ومن أهم الأمور التي ينبغي أن تنتبهي إليها الإجابة عن أسئلته بصبر ومن دون أن تقولي له إنه لا يزال صغيرًا. وخلال هذه العملية، عليكِ السماح لطفلكِ بأن يسقط أو تتسخ ملابسه أو يفكك ألعابه ثم يعيد تركيبها. وينبغي لكِ مناقشة سلوكياته في وقت تكونان فيه كلاكما هادئين. والأهم من ذلك كله، لا تقارني طفلكِ أبدًا بأقرانه.') WHERE id = 'cb11e36c-39a0-4aef-be34-9d54b22af192';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ، مثل كثير من الأمهات، تشتكين من ضعف شهية طفلكِ، فلا تقلقي، فلستِ وحدكِ! :) رغم أن كثيرًا من الأهل يعتقدون أن طفلهم ضعيف الشهية، فإن توقعاتهم تكون في الواقع بعيدة عن الواقع، ويطلبون من الطفل تناول كمية أكبر مما يستطيع. لكن إذا كنتِ تعتقدين حقًا أن شهية طفلكِ ضعيفة، فعليكِ الانتباه إلى بعض التفاصيل الدقيقة. تذكّري أن مظهر الطعام أهم لدى الأطفال من مذاقه. كما أن الرائحة من العوامل التي تؤثر في شهية الطفل. وقد يرفض النكهات المختلطة والأطعمة ذات المظهر غير المتناسق. لذلك حاولي أن تكوني مبتكرة عند تقديم الطعام. فعلى سبيل المثال، بدلًا من ترتيب شرائح الجزر التي سيتناولها على الفطور في الطبق بشكل عادي، اصنعي منها أشكالًا ممتعة، ونحن واثقون من أنها ستجذب انتباه صغيركِ! 😊') WHERE id = 'fac64036-a219-4703-b872-665eb449d5b6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم يكن طفلكِ قد أتقن استخدام المرحاض بالكامل بعد، فمن المهم جدًا أن تتحلي بالصبر وألّا تقارنيه بالآخرين أو تعاقبيه. ويشير المختصون إلى أن أنسب وقت للتدريب على استخدام المرحاض هو خلال أشهر الصيف وبين عمر 1.5 - 3 سنوات. وبعبارة أخرى، إذا لم تنجحي بعد في إكسابه هذه العادة، فلا يعني ذلك أنكِ تأخرتِ. وإذا لم تتمكني من تحقيق النجاح، فقد يعود السبب إليكِ أو إلى الطفل. فبينما يعتاد بعض الأطفال على ذلك خلال بضعة أيام، قد يُظهر آخرون مقاومة شديدة. وقد يؤدي اتباعكِ نهجًا خاطئًا بصفتكِ أمًا إلى مشكلات خطيرة لدى الطفل في المستقبل. تذكّري أن صغيركِ، مثل كل طفل سليم، سيتعلم عاجلًا أم آجلًا استخدام المرحاض. لكن أساليب التدريب الخاطئة قد تسبب له مشكلات تتعلق بالثقة بالنفس والشخصية والتعلق.') WHERE id = 'feaefa5c-467b-473d-8593-ed69b32fa642';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح الشاي المثلج البارد مؤخرًا من أكثر المشروبات المحببة لدى الأطفال. وإذا كان طفلكِ يحب الشاي البارد أيضًا ويرغب في شربه باستمرار، فاعلمي أنكِ لستِ وحدكِ. 😊 لكن من المهم الحرص قدر الإمكان على تلبية احتياجات طفلكِ من السوائل عن طريق الماء. وعند تقديم الشاي البارد له، عليكِ الانتباه إلى كمية الكافيين والسكر الموجودة فيه. فهذه الأنواع من المشروبات قد تسبب فرط الاستثارة لدى الطفل وتؤدي إلى زيادة وزنه بسهولة. حتى لدى البالغين، يسبب الكافيين يقظة مفرطة عند تجاوز كمية معينة. أما لدى الأطفال، فقد يؤدي إلى نوبات عصبية وفرط الحركة ومقاومة النوم.') WHERE id = '0d16f898-6bee-46b7-810a-0ae08cd779d7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعدّ النوم ضروريًا للنمو الصحي لطفلكِ في كل مرحلة عمرية، لأن هرمون النمو يُفرَز أثناء نومه. وعلى الرغم من انخفاض حاجته إلى القيلولة بعد سن 2، فإن حاجته إلى النوم ليلًا تزداد. في هذه المرحلة، يكفي أن ينام 11 ساعة متواصلة ليلًا، ومن 1 إلى 1,5 ساعة نهارًا. وبينما تظنين أن تحديات سن الثانية قد انتهت، قد يصبح طفلكِ عنيدًا بعض الشيء بسبب تحديات سن الثالثة، وقد يقاوم النوم. عندما يحاول تأخير موعد نومه، أشعريه بأنكِ حازمة، مع إمكانية إبداء بعض المرونة البسيطة من دون أن تكوني شديدة الصرامة.') WHERE id = '4051aaec-c1ae-4638-bc35-ce5ea1cf068b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الضروري أن تستمعي إلى طفلكِ الذي تتطور مهاراته اللغوية، وأن تدعميه في التعبير عن أفكاره. فالطفل الذي لا يفهم ماذا يفعل ولماذا يفعله لا يمكنه المشاركة في اتخاذ القرارات. ومن المهم جدًا أن توضحي له الأمور، وتشرحي أسبابها، وتسأليه بصدق عن مشاعره، حتى في أبسط القرارات. إن الإصغاء إلى طفلكِ يجعله يشعر بالتقدير ويعزز ثقته بنفسه. وحتى إن لم يكن من الممكن تحقيق كل ما يريده، فاشرحي له السبب. وتذكّري أن طفلكِ سينشأ شخصًا مستقلًا قادرًا على الاعتماد على نفسه كلما استمعتِ إليه ودعمتِ مشاركته في اتخاذ القرارات.') WHERE id = '0ce591a9-3ab7-4fd5-aaf6-d14c88201ae3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من عمر 24 شهرًا، يبدأ الأطفال باكتساب قدر متزايد من الاستقلالية. وفي عمر 2,5 سنة، يرغب طفلكِ في إظهار نفسه داخل الأسرة بوصفه فردًا أكثر استقلالية. ويؤثر هذا الشعور بالاستقلالية أيضًا في عاداته الغذائية. خلال هذه المرحلة، قد يصرّ طفلكِ على عدم تناول الأطعمة التي لا يحب مذاقها، أو قد يتعلق بنوع معين من الطعام. إذا كان الطعام الذي يصرّ عليه غير صحي، فقدّمي له خيارات. على سبيل المثال، يمكنكِ أن تقولي له: يمكنك تناول البطاطس المقلية بعد الانتهاء من طبق الخضراوات. وبهذه الطريقة تراعين رغبته وتضمنين في الوقت نفسه حصوله على غذاء صحي.') WHERE id = '158b48bc-de87-4a18-8590-049c1345f651';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن تعلّمي طفلكِ في هذه المرحلة تسمية المشاعر الأساسية، مثل السعادة والحزن والغضب والخوف. وبعد ذلك، يمكنكِ طرح أسئلة عليه مثل: ماذا تشعر عندما تكون سعيدًا؟ أو ماذا تشعر عندما تغضب؟ ويمكنكِ أن تطلبي منه الرسم أو التحدث لتفهمي ما الذي تعنيه له هذه المشاعر. ويمكنكِ أن تسألي طفلكِ كل يوم: كيف تشعر اليوم؟ أو كيف كان شعورك اليوم؟ ومن المهم جدًا أيضًا أن تتحدثي معه عن الشعور الذي عبّر عنه. على سبيل المثال، يمكن أن تساعد أسئلة مثل: ما الذي أسعدك؟ ما الذي أحزنك؟ أو ما الذي لو كان مختلفًا لجعلك تشعر بشكل أفضل؟ في تحقيق هذا الهدف. وفي هذه المرحلة، يمكنكِ مساعدته من خلال تقديم مثال من تجربتكِ الشخصية لكل شعور. لكن تذكّري أن استراتيجياتكِ وعاداتكِ في التعامل مع المواقف السلبية ستكون نموذجًا يحتذي به طفلكِ. فإذا كنتِ تصرخين بصوت مرتفع عندما تغضبين، أو لا تعبّرين عن مشاعركِ، أو تلقين شيئًا على الأرض تعبيرًا عن انفعالكِ، فلن يكون من المنطقي أن تتوقعي من طفلكِ التعبير عن مشاعره بالكلمات والتعامل مع المشاعر السلبية بطريقة سليمة.') WHERE id = '0daa42c4-6bd6-49b7-8345-003a12087e4e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في عصر التكنولوجيا، من غير الواقعي إبعاد طفلكِ عنها تمامًا. لكن عليكِ تعلّم أخذ استراحة من الأجهزة التكنولوجية في أوقات محددة، وبمشاركة جميع أفراد الأسرة عند الحاجة. فالتلفاز والهواتف المحمولة وأجهزة الكمبيوتر كلها مسلية للغاية، لكنها لا تترك مجالًا كبيرًا لإبداع طفلكِ. لذلك، عليكِ إيقاف هذه الأجهزة مدةً معينة لتمنحيه وقتًا للإبداع وإطلاق خياله. على سبيل المثال، يمكنكِ أن تطرحي عليه أسئلة تتطلب استخدام الخيال، مثل: "بماذا تشبه السحابة في السماء أو الظل على الحائط؟" ويمكنكِ أثناء لعبه تشجيعه على استخدام الألعاب أو الأشياء بطريقة مختلفة عن الغرض المخصص لها. فبقليل من الإبداع، يمكن أن تتحول اللعبة إلى شيء مختلف تمامًا. كما يُعدّ سرد القصص مفيدًا جدًا لدعم إبداع طفلكِ. يمكنكِ إعادة سرد قصة يعرفها بعد تغيير بعض أحداثها، ثم تشجيعه على سرد القصص بعد تعديلها بطريقته الخاصة.') WHERE id = '8115dfc9-eb92-4e72-a543-4ea919c775ac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يتعلق الأمر بطفلكِ، فمن الطبيعي أن تراودكِ دائمًا تساؤلات بشأن الأطعمة التي يتناولها. ومن بين هذه التساؤلات موضوع الخبز ومنتجات الدقيق، الذي لم يتوصل حتى الأطباء إلى اتفاق تام بشأنه. وينتمي إلى هذه المجموعة الغذائية الخبز وغيره من مصادر الكربوهيدرات. وبالنسبة إلى مجموعة الخبز، ينبغي للأطفال، وليس البالغين فقط، تناول خبز القمح الكامل (الحبوب الكاملة) بدلًا من الخبز الأبيض. فدقيق الحبوب الكاملة أقل معالجةً، ولذلك فهو أغنى بالعناصر الغذائية. كما قد يكون استخدام البرغل بدلًا من الأرز بديلًا أفضل وأكثر صحة. وإذا كان طفلكِ عرضة لاكتساب الوزن، فمن الأنسب تقديم هذه الأطعمة له بحصص أصغر بدلًا من استبعادها تمامًا من نظامه الغذائي.') WHERE id = 'bb018208-0884-4d7b-917a-81edc759ffd2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا أن تساعدي طفلكِ على اكتساب مهارة التعرّف على المشاعر، فهي جزء أساسي من نموه الاجتماعي والعاطفي. فالأطفال الذين يستطيعون التعبير عن مشاعرهم بطريقة ملائمة للمواقف الاجتماعية يعانون مشكلات سلوكية أقل. وإذا تمكّن طفلكِ عند غضبه من شيء ما من قول «لقد غضبت كثيرًا»، فسيقل احتمال تعرضه لنوبات الغضب والبكاء. وعندما تساعدينه على التعرّف على مشاعره والتعبير عنها، فإنكِ تعلّمينه أيضًا كيفية التعامل مع المشاعر السلبية بطريقة أكثر صحة. وإضافة إلى نموه العاطفي، يكتسب الطفل القدرة على التعاطف. وهكذا يبدأ منذ سن مبكرة في إدراك أن الأشخاص المحيطين به قد يشعرون بمشاعر مختلفة في المواقف المختلفة. فعلى سبيل المثال، إذا أدرك طفلكِ أن صديقه سيحزن عندما يأخذ اللعبة من يده، فسيقل احتمال قيامه بذلك.') WHERE id = '6f6fea86-044b-4ad1-8721-a20a4d184e96';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكل طفل الحق في التعبير عن آرائه بحرية عند اتخاذ قرار يتعلق به. أي إن مشاركة طفلكِ في القرارات حق من حقوقه وجزء مهم من نموه في الوقت نفسه. فمشاركة الطفل في اتخاذ القرارات تدعم نموه العقلي والاجتماعي، وتعزز قدرته على تحمّل المسؤولية وحل المشكلات. والطفل الذي يُنظر إليه بوصفه فردًا، ويُسأل عن رأيه، ويشعر بقيمته، يكون أقدر على حماية نفسه، كما يقل احتمال تعرضه للإهمال أو الاستغلال. إذا لم تكوني قد بدأتِ بذلك بعد، فمن المهم أن تغرسي في طفلكِ مسؤولية المشاركة في اتخاذ القرارات. ويمكنكِ في البداية تشجيعه على اتخاذ القرارات المتعلقة بجسده. فعلى سبيل المثال، يمكنكِ البدء بترك قرار السماح للأقارب أو المعارف بتقبيله واحتضانه له.') WHERE id = '20007018-c312-42f8-9d7c-bba3d4a8dc28';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تناول طفلكِ كمية أقل من الطعام مقارنة بالسابق هو جزء طبيعي من نموه. أما مهمتكِ فهي الحرص على أن تكون الأطعمة التي يتناولها من الخيارات الأعلى جودة. فعلى سبيل المثال، ينبغي أن تكون مصادر البروتين والكربوهيدرات التي تقدمينها لطفلكِ عالية الجودة. وتشمل مصادر البروتين عالية الجودة البيض والحليب والزبادي وكرات اللحم والبقوليات. وينبغي لطفلكِ تناول 2–3 حصص يوميًا من هذه الأطعمة. ومن النقاط التي يجب أن تنتبهي إليها كمية الحليب. فقد يؤدي إعطاؤه كمية مفرطة منه بسبب حبه الشديد له إلى ضرر يفوق فائدته. يجب ألا تتجاوز كمية الحليب أو الزبادي 500 ml يوميًا؛ إذ قد تؤدي زيادة هذه الأطعمة إلى الإمساك وفقر الدم (الأنيميا) من خلال إعاقة امتصاص الحديد.') WHERE id = 'a35dfbb5-f5f6-479e-a555-e5d0082e7b04';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يختلف كل طفل عن الآخر. فحتى الإخوة أو التوائم الذين ينشؤون في المنزل نفسه قد لا يتشابهون تمامًا. ومن أهم أسباب ذلك مفهوم المزاج أو الطبع. والمزاج هو مجموعة السمات الفطرية التي يولد بها طفلكِ، والتي تشكل أساس شخصيته التي ستتطور مستقبلًا. فعلى سبيل المثال، يكون بعض الأطفال أكثر هدوءًا، بينما يكون آخرون أكثر نشاطًا وسرعة في الاستجابة. وفي الواقع، فإن كلمتي «سهل» و«صعب» اللتين تُستخدمان خصوصًا عند الحديث عن الرضّع تصفان مزاج الطفل. وقد حُددت عمومًا تسع سمات أساسية للمزاج، من أبرزها مستويات النشاط والتفاعل الاجتماعي والقدرة على التكيف. فعلى سبيل المثال، يوضح مستوى التكيف مدى قدرة الطفل على التأقلم مع المواقف الجديدة والتغييرات. وترتبط سرعة اعتياد طفلكِ على تغيير غرفته أو منزله أو مدرسته بهذه السمة تحديدًا.') WHERE id = 'd7b7b77e-5570-44db-89ff-93dc046edc75';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما يكون طفلكِ قد تعلّم استخدام المرحاض في هذه المرحلة، أو ربما لا تزالان في مرحلة تعلّم هذه العادة. لكن لهذه العملية مشكلة شائعة تؤثر في جميع الأطفال تقريبًا، وهي الإمساك! فكثيرًا ما يعاني الأطفال الإمساك خلال مرحلة التدريب على استخدام المرحاض. وقد يتعمّد طفلكِ، بعد الاستغناء حديثًا عن الحفاض، تأخير التبرز، مما يؤدي إلى تصلّب البراز والشعور بالألم أثناء إخراجه. وبمجرد بدء دائرة الألم والخوف، ينبغي ألا تضغطي كثيرًا على طفلكِ لإعادة الوضع إلى طبيعته. كذلك، ليس من الصواب إبداء تعليقات سلبية عن براز الطفل خلال هذه الفترة؛ فالبراز يكون ذا قيمة كبيرة بالنسبة إلى الطفل في هذا العمر، إذ يعدّه جزءًا من جسده. وقد يشعر عند التبرز كما لو أن جزءًا من جسده ينفصل عنه ويذهب بعيدًا.') WHERE id = '8cd65094-234a-43ba-9216-79ad31e952d9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد انتظام مواعيد الطعام من أهم العادات التي يمكنكِ إكسابها لطفلكِ. لكن إلى جانب النظام، تُعد أحجام الحصص مهمة أيضًا. خلال هذه المرحلة، ينبغي أن تقدمي لطفلكِ حصصًا صغيرة يستطيع تناولها، وألا تضعي أمامه كمية من الطعام لا يمكنه إنهاؤها. وإذا كان طفلكِ ضعيف الشهية جدًا، فاتركي له حرية تحديد الكمية التي يتناولها ما دام نموه وتطوره يسيران بصورة طبيعية. ومن المهم جدًا تحضير الوجبات بطرق طهي صحية. وينبغي أن تتجنبي الأطعمة الحارة وكثيرة التوابل، وألا تقدمي الطعام شديد السخونة أو البرودة. ومع اتساع تفاعل طفلكِ الاجتماعي، قد يتعرف أحيانًا على أطعمة غير صحية. وهنا ينبغي أن يكون هدفكِ الأساسي إبعاده عن هذه الأطعمة قدر الإمكان ومحاولة الحفاظ على نظام غذائي صحي.') WHERE id = '16c8ff33-deb6-4f40-89a3-c531e7b4cb9c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن عادات النظافة والروتين والتغذية التي يكتسبها الطفل في مرحلة الطفولة تدوم طويلًا. لذلك، فإن إرساء أسس التغذية السليمة، والقدرة على العناية بالنظافة الشخصية، وتحويل بعض الممارسات الأساسية إلى عادات يومية قد يحمي طفلكِ من الأمراض على المدى الطويل. وإلى جانب الوقاية من الأمراض، تُعدّ هذه العادات مهمة جدًا لنمو طفلكِ أيضًا. تذكّري أن الجهد الذي تبذلينه من أجل طفلكِ هو أعظم استثمار في مستقبله. لذا من المهم أن تحرصي على أن يغسل طفلكِ يديه قبل تناول الطعام وبعده، وأن يعتاد تنظيف أسنانه بالفرشاة مساءً قبل النوم، وأن يغيّر ملابسه عند عودته من الخارج. وفي هذه المرحلة التي يكون فيها طفلكِ مستعدًا لاكتساب شتى العادات، ينبغي لكِ أيضًا الانتباه إلى العادات السلبية. فعلى سبيل المثال، إذا رأى أشخاصًا من محيطه يتواصلون بالصراخ، أو يخرّبون ما حولهم عند الغضب، أو سمع كلمات بذيئة، فقد يكتسب هذه العادات بسهولة أيضًا.') WHERE id = 'fa462e53-99cc-4df3-9374-bf4b0433f122';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع دخول طفلكِ شهره الـ31، تكون مهاراته الحركية الدقيقة قد تطورت بدرجة كبيرة. ويمكنه بسهولة تعلّم إمساك القلم والرسم من خلال تقليدكِ. ورغم أنه قد لا يتمكن بعد من رسم صور واضحة بالمعنى الكامل، فإنه يستطيع استخدام الألوان بصورة عشوائية. يمكنكِ شراء ألوان الرسم بالأصابع لطفلكِ وتشجيعه على الرسم، بل ويمكنكما الرسم معًا وقضاء وقت ممتع. وأثناء الرسم، ينبغي أن تسمحي له باستخدام جميع الألوان لتنمية إبداعه. وبوجه عام، قد يفضّل اللون الأسود أكثر من غيره لأنه لون طاغٍ، لكن لا ينبغي لكِ التدخل في اختياره للألوان. وقد تكون ألوان الرسم بالأصابع أكثر فائدة من الفرشاة، لأنه يستطيع رسم الخطوط بأصابعه بسهولة أكبر. ومهما حاولتِ منعه، فقد يجرّب طفلكِ الرسم ليس على الورق فقط، بل على جدران المنزل أيضًا. استعدّي للتنظيف من الآن! وإذا طليتِ جدران منزلكِ بطلاء سهل المسح، فسيكون تنظيفها أسهل. ‐ عائلة Anacan.') WHERE id = 'f361492b-3d92-4ce0-97da-c8386dbad563';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن ينام طفلكِ في هذه المرحلة ما بين 11-13 ساعة في المتوسط. ويُفضّل توزيع إجمالي وقت النوم بين الليل والنهار على النحو الآتي: 10-11 ساعات من النوم ليلًا، و1-2 ساعة في قيلولة نهارية واحدة. لا يجعل بعض الوالدين أطفالهم ينامون نهارًا في هذه المرحلة. لكن القيلولة النهارية تظل مهمة لنمو الأطفال حتى سن 4 سنوات تقريبًا. لذا ينبغي لكِ الاستمرار في الاهتمام بقيلولة طفلكِ النهارية، كي يتمكن من تعلّم أشياء جديدة واستعادة الطاقة اللازمة لبقية اليوم، وحتى لا يُصاب بإرهاق شديد يجعله يرفض النوم ليلًا. أصبح طفلكِ الآن في سن تسمح له بفهم كل شيء، ولذلك قد يتأثر نومه بأي تجربة سلبية يمر بها خلال اليوم. ومع نمو صغيركِ وزيادة حركته، قد يصعب إبقاؤه في سرير الأطفال ذي القضبان. وعادةً ما تكون هذه الفترة الأنسب للانتقال من سرير الرضيع إلى سرير الأطفال. ومن المفيد أن تجعلي عملية الانتقال ممتعة، حتى تساعديه على حب سريره الجديد. وإلا فقد يصعب تجنّب مواجهة مشكلات في النوم.') WHERE id = 'a72583c0-5214-45e6-a7f3-7cad2b42e3ee';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يبدأ طفلكِ بتناول كل الأطعمة التي تعدينها لنفسكِ، فمن الطبيعي تمامًا أن تراودكِ أسئلة حول كمية الملح التي تضيفينها إلى الطعام. ورغم أن كثيرًا من الوالدين يحاولون عدم إضافة الكثير من الملح إلى الطعام، فإن وجود الملّاحة على المائدة غالبًا ما يثير اهتمام الأطفال بها أيضًا. لا يحتاج جسم طفلكِ في فئته العمرية الحالية إلى كمية كبيرة من الملح. وبما أن الأطعمة تحتوي بطبيعتها على الملح، فيكفي إضافة كمية قليلة منه إلى الوجبات. وأهم ما ينبغي الانتباه إليه هو استخدام الملح المعالج باليود. وإذا اعتاد طفلكِ تناول أطعمة شديدة الملوحة، فقد يواجه خطر الإصابة بارتفاع ضغط الدم مستقبلًا. لذلك، إذا كان صغيركِ يحب الأطعمة المالحة، فقد تحتاجون كأسرة إلى التوقف لبعض الوقت عن إضافة الملح الزائد إلى طعامكم.') WHERE id = '190574b9-2d94-41ec-8775-1a8e11808369';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تختلف درجة التفاعل الاجتماعي من طفل إلى آخر. وسواء كانت درجة تفاعل طفلكِ الاجتماعي منخفضة أم مرتفعة، فإن لكِ بصفتكِ أمًا دورًا مهمًا. وتشير درجة التفاعل الاجتماعي إلى استجابة الطفل للمواقف الاجتماعية وللأشخاص الذين يراهم للمرة الأولى، أي إلى ميله إلى الاقتراب منهم أو الابتعاد عنهم. يشعر بعض الأطفال براحة كبيرة في البيئات الجديدة ويندمجون سريعًا، بينما يخجل آخرون ولا يرغبون في الاقتراب من أحد. إذا كانت درجة تفاعل طفلكِ الاجتماعي منخفضة، فلا ينبغي لكِ إجباره على التواصل مع الأشخاص فورًا عند وجوده في بيئة جديدة. وفي هذه الحالة، يكون الخيار الأفضل هو الانتظار حتى يعتاد طفلكِ أولًا على ما حوله. أما إذا كانت درجة تفاعله الاجتماعي مرتفعة، فعليكِ مراقبته والإشراف عليه باهتمام أكبر. وإذا كان مستوى تفاعله الاجتماعي يثير قلقكِ بشدة، فيمكنكِ استشارة طبيب مختص.') WHERE id = '3818caec-41c6-4171-b3ce-2ce4abd11b1e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اعتبارًا من هذا الشهر، يبلغ متوسط وزن طفلكِ 13.250 غرامًا. ويبلغ هذا الرقم في المتوسط نحو 12.900 غرامًا للفتيات و13.600 غرامًا للفتيان. أما متوسط طول الأطفال في عمر 31 شهرًا فيبلغ 92 سم. ويبلغ متوسط الطول 91,4 سم للفتيات و92,7 سم للفتيان. لكن تذكّري أن هذه الأرقام ليست سوى قيم متوسطة. وحتى إذا لم يكن طول طفلكِ ووزنه ضمن القيم المتوسطة، فلا توجد مشكلة ما داما ضمن النطاق الآمن. ووفقًا لمخطط النسب المئوية، يكون نطاق الطول والوزن للأطفال بعمر 31 شهرًا كما يأتي: بالنسبة إلى الفتيات بعمر 31 شهرًا، يبلغ الحد الأدنى للوزن 10.300 غرام والحد الأعلى 16.500 غرام؛ أما الفتيان بعمر 31 شهرًا، فيبلغ الحد الأدنى للوزن 10.800 غرام والحد الأعلى 16.900 غرامًا. وبالنسبة إلى الطول، يبلغ الحد الأدنى لدى الفتيات بعمر 31 شهرًا 84,7 سم والحد الأعلى 98,2 سم؛ بينما يبلغ الحد الأدنى لدى الفتيان 86,2 سم والحد الأعلى 99,2 سم.') WHERE id = '3842dedf-9bba-4a59-b233-533a1cd51008';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أكثر الأمور التي تثير قلق الوالدين في هذه المرحلة أن يبدأ طفلهم في تكوين أصدقاء خياليين. إذا لاحظتِ مثل هذا الأمر أيضًا، فعليكِ أولًا أن تتحلي بالهدوء وأن تعرفي أنه جزء طبيعي من النمو. قد يتواصل طفلكِ، الذي لديه صديق خيالي، أيضًا مع حيوان أو لعبة يتقمص شخصيتها ويوجه إليها الأوامر. وقد يحاول تأديبها، بل قد يغضب منها ويصرخ في وجهها. فلا تتفاجئي إذا واجهتِ موقفًا كهذا؛ إذ يرجع ذلك إلى تقليده لكِ ورؤيته لنفسه كشخص بالغ. في هذه المرحلة، يمكنكِ شراء ألعاب محشوة مناسبة لعمره تدعم نموه الجسدي والعقلي وتتيح له ممارسة لعب الأدوار. واحرصي على اختيار ألعاب تشجعه على النشاط الذهني والجسدي وتحفّز خياله المتنامي. ينبغي أن يكون اختيار الألعاب التي تساعد طفلكِ النامي على توجيه طاقته بطريقة صحية من بين أولوياتكِ.') WHERE id = 'f8ae4ada-7f41-4498-b68a-fecd1f544ae2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا للإحصاءات المتاحة، يعاني طفل واحد من كل 5 أطفال في وقتنا الحالي من السمنة، مع الأسف. وعند النظر إلى الأطفال الذين يعانون من زيادة الوزن، نلاحظ أنهم قليلو الحركة ويمضون وقتًا طويلًا أمام التلفاز أو الحاسوب، بل وينشغلون بهذه الأنشطة حتى أثناء تناول الطعام. كذلك، يُعد عدم ممارسة الرياضة، والأهم من ذلك إطعام الطفل باستمرار من قِبل الآخرين، من العوامل المهمة التي تحفّز الإصابة بالسمنة؛ لأن الأطفال الذين لم يعتادوا تناول الطعام بأنفسهم يكتسبون عادات غذائية غير صحية. ومن الأسباب الأخرى اعتياد الأطفال على الأطعمة التي تحتوي على مواد مضافة. ويوصي المختصون بإبعاد الأطفال عن الوجبات السريعة والأطعمة الجاهزة ورقائق البطاطس والكولا والمشروبات الغازية، وكذلك المنتجات التي تحتوي على إضافات صناعية. وبالنظر إلى أن طفلكِ البالغ من العمر 2.5 عامًا سيبدأ المدرسة في المستقبل القريب وقد يصبح أكثر عرضة للإصابة بالأمراض، فعليكِ ألا تنسي مدى أهمية التغذية الصحية في تقوية مناعته.') WHERE id = '58502d60-f8e0-4b8e-a1fb-c17d973d4ff1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، يصبح طفلكِ اجتماعيًا بدرجة ملحوظة، ويتواصل باستمرار مع المحيطين به، ويشعر بمشاعر مختلفة تجاه الناس. وقد تلاحظين أن طفلكِ في مرحلة ما قبل المدرسة يعبّر كثيرًا عن مشاعر مفاجئة من الحب أو الكراهية؛ ففي مرحلة الطفولة قد تتغير المشاعر بسرعة تبعًا لتحقق ما يريده في تلك اللحظة من عدمه. لذلك لا جدوى من مطالبة طفلكِ بأن يحب شخصًا ما أو ألا يحبه؛ فهو يشعر بمشاعر معينة بناءً على العلاقة التي تجمعه بالشخص المقابل. أي إن مشاعره تتشكل وفقًا لمدى اهتمامه بهذه العلاقة وطبيعة التفاعل والمشاركة بينهما. ولهذا، فإن عبارات مثل «انظر، إنه صديق رائع، هيا أحبّه» أو «يجب أن تحب جدتك» لا تحمل معنى كبيرًا لطفلكِ. باختصار، تتشكل مشاعر الطفل وفقًا لكيفية تطور العلاقة. وقد يؤدي إجباره على ذلك إلى شعوره بمزيد من المشاعر السلبية تجاه ذلك الشخص.') WHERE id = '24346579-f274-43ec-b861-363147af3e6c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن وعي طفلكِ البالغ من العمر 31 شهرًا قد ازداد مؤخرًا. ويتجلى أوضح مثال على هذا الوعي في مفهوم الزمن، إذ يبدأ هذا المفهوم بالتشكل تدريجيًا لديه خلال هذه المرحلة. فعلى سبيل المثال، عندما تقولين «بعد 3 ساعات»، يكون قد بدأ يفهم معنى كلمة «بعد» في الجملة، لكنه لا يزال غير قادر تمامًا على إدراك مدى قِصر المدة أو طولها. ولمساعدته على استيعاب ذلك، يمكنكِ مثلًا أن تشرحي له موعد الذهاب إلى مكان ما بعد يومين بقولكِ: «سننام، ثم نستيقظ، ثم ننام مجددًا، ثم نستيقظ». ستساعد هذه الأمثلة طفلكِ على فهم الزمن بصورة أفضل وتمنع حدوث أي التباس محتمل.') WHERE id = '12b0c10e-3144-4c46-a3b6-1700a0248288';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يزال يقاوم النوم، فاعلمي أنكِ لستِ وحدكِ وأن أمهات كثيرات يواجهن المشكلة نفسها! من الطبيعي تمامًا في هذا العمر أن يفضّل اللعب وطرح الأسئلة وقضاء مزيد من الوقت معكِ بدلًا من النوم. كما يمكن اعتبار استيقاظه بعد فترة من نومه ورغبته في اللعب أمرًا طبيعيًا. في هذه المرحلة، سيكون من المفيد جدًا وضع نظام ثابت للنوم واتباع روتين للاستعداد له. فإذا كان طفلكِ لا يزال يرغب في النوم معكِ، مثلًا، فعليكِ عدم التهاون في هذا الأمر. وسيكون من الأسهل عليكِ أن تكون له غرفته الخاصة إن أمكن، أو سريره الخاص على الأقل إن تعذر ذلك. وعندما يحين موعد النوم، أغلقي ستائر الغرفة وأطفئي الضوء لتوفري بيئة مظلمة وهادئة. وعندما تلبسينه ملابس النوم وتهيئينه للنوم، سيفهم أن موعد النوم قد حان.') WHERE id = 'fcf11140-2354-4af3-8445-6e3473639648';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'احرصي على وجود فاصل زمني لا يقل عن 4 ساعات بين الوجبات الرئيسية الثلاث التي تحضّرينها لطفلكِ، وهي الإفطار والغداء والعشاء؛ إذ يؤثر تواتر تناول الطعام بدرجة كبيرة في شهية طفلكِ وعاداته الغذائية. ويمكنكِ تقديم وجبات خفيفة صغيرة بين الإفطار والغداء، وكذلك بين الغداء والعشاء. لكن بخلاف ذلك، ينبغي عدم إعطاء الطفل أي طعام أو شراب باستثناء الماء. فقد تكفي قطعة بسكويت أو مقرمشات صغيرة لا تُؤخذ في الحسبان لإفساد شهية طفلكِ للوجبة التالية. كما تحل هذه الوجبات الخفيفة محل الأطعمة الأساسية التي يحتاج الطفل إلى تناولها. لذلك، حتى إذا تناول طفلكِ كمية قليلة في الوجبات الرئيسية، يُنصح بأن تنتظري موعد الوجبة الخفيفة أو الوجبة الرئيسية التالية بدلًا من إعطائه شيئًا ليأكله.') WHERE id = '03e2d49c-fc1b-4405-8b1e-dc104530e959';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يتعلم طفلكِ معلومات جديدة من خلال اللعب بطريقة طبيعية وتلقائية وممتعة. في عمر 2.5 سنة، يبدأ طفلكِ بإظهار سلوكيات هادفة، وتصبح مدة تركيزه أطول مقارنة بالسنوات السابقة. وسيجعل التواصل النشط الذي تقيمينه معه الوقت الذي تقضيانه معًا أكثر جودة. فعلى سبيل المثال، يمكن لطفلكِ في هذه المرحلة التركيز على نشاط واحد لمدة 10 دقائق تقريبًا. يحب الأطفال في عمر 2.5 سنة ممارسة الأنشطة مع الأشخاص المحيطين بهم. لكن عليكِ ألا تنسي أن هذه المرحلة تُعرف بمرحلة اللعب المتوازي. وهي مرحلة يستمتع فيها الطفل بقضاء الوقت مع أقرانه أو البالغين في المكان نفسه وباستخدام الألعاب نفسها، لكنه لا يشاركهم بعد في لعب تفاعلي مشترك. لذلك قد يواجه بعض الصعوبات، خصوصًا في مشاركة ألعابه مع أقرانه.') WHERE id = 'ba0dbae3-755a-40e2-a8cd-2a1d2c900c58';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تراودكِ في هذه المرحلة أسئلة حول الأطعمة التي يمكنكِ تقديمها لطفلكِ، سواء من حيث الكمية أو التنوع الغذائي. فعلى سبيل المثال، يمكنكِ أن تقدمي له في وجبة الإفطار خبزًا مدهونًا بالجبن الأبيض مع بيضة مسلوقة، أو 1 شريحة من خبز القمح الكامل مع دبس السكر والطحينة والجبن الأبيض. وبعد الإفطار بنحو 1-1.5 ساعة، يمكنكِ إعطاؤه عصير فاكهة طازجًا من دون سكر أو 1 كوب من الحليب. ومن المهم جدًا لنموه أن تقدمي له الفاكهة أو الزبادي قبل الغداء بنحو 1 ساعة أو بعده بنحو 1 ساعة. أما في وجبة الغداء، فقد يكون طبق من الخضراوات مع نصف طبق من الأرز أو المعكرونة المصنوعة من دقيق القمح الكامل خيارًا جيدًا. وفي وجبة العشاء، يمكنكِ أن تقدمي لطفلكِ تقريبًا جميع أطباق الخضراوات المطهوة باللحم التي تعدينها للأسرة. وإذا لم يتناول في الغداء أو العشاء مصادر البروتين مثل اللحوم أو الدجاج أو السمك، فمن المهم جدًا أن يكون طبق الخضراوات في العشاء غنيًا بالبروتين النباتي.') WHERE id = 'a05e1296-3724-4f4f-b2bb-e078e101f1c5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذه المرحلة من عمر 2.5 سنة، تبدأ قدرة طفلكِ على التواصل بالتطور بوتيرة أسرع من جديد. وفي هذه المرحلة من تطوره اللغوي، يحتاج طفلكِ إلى التواصل وجذب انتباه الآخرين والتعبير عن رغباته ومشاعره وأفكاره. يُتوقع حاليًا أن يتمكن من نطق نحو 200-250 كلمة وأن يبدأ بربط الكلمات معًا. ويُفترض أن تتسع حصيلته اللغوية بوضوح، خصوصًا خلال الأشهر 1-2 المقبلة مع اقترابه من عمر 3 سنوات، وأن يبدأ بتكوين جمل من 3-4 كلمات. وسيكون عدد الكلمات التي يفهمها أكبر بكثير من عدد الكلمات التي يستطيع نطقها. وقد يستخدم الأطفال في هذا العمر أسلوبًا يُعرف بالكلام البرقي، أي جملًا قصيرة لا تتضمن سوى الكلمات الأساسية، مثل «أبي، العب بالكرة». لذلك، يُنصح أثناء مواصلة الأنشطة التي تدعم تطور لغة طفلكِ بألا تتوقعي منه حاليًا ما يتجاوز قدراته المعرفية.') WHERE id = 'e211eecc-39db-4566-ab98-8e17bb940902';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'غالبًا ما يتعرف الأطفال في هذه المرحلة على الأطعمة غير الصحية والوجبات السريعة. وقد يؤدي ذلك إلى تأخر النمو لدى الأطفال ضعيفي الشهية، وإلى السمنة لدى الأطفال ذوي الشهية الجيدة. إذا كان طفلكِ مهتمًا بالأطعمة الجاهزة المعبأة ويطلبها باستمرار، فمن المهم جدًا أن تجدي له بدائل صحية ولذيذة. فعلى سبيل المثال، إذا كان يحب رقائق البطاطس، يمكنكِ تقطيع البطاطس إلى شرائح رقيقة وتتبيلها بالتوابل ثم خبزها في الفرن. وإلى جانب ذلك، إذا تناول طفلكِ كمية كافية من الحبوب والفاكهة، فستقل رغبته في تناول هذه الأطعمة غير الصحية. ويمكن مثلًا إضافة منتجات الحبوب إلى الحساء أو تقديمها مع الحليب أو الزبادي. كما يمكن تقديم كمية صغيرة من الأرز أو المعكرونة المصنوعة من دقيق القمح الكامل إلى جانبها. ولا تساعد هذه الأطعمة على تقليل اهتمام طفلكِ بالأطعمة غير الصحية فحسب، بل تُعد مهمة أيضًا لنموه الصحي وحمايته من الأمراض.') WHERE id = 'dea526e3-269a-402d-8089-37a01ca0586f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أبرز الاختلافات بين عالم البالغين وعالم الأطفال طريقة إدراك المشاعر وتقييمها. يتمتع طفلكِ في مرحلة ما قبل المدرسة بقدرة كبيرة على فهم المشاعر من خلال تعابير وجهكِ وتعابير وجوه الأشخاص المحيطين به، وكذلك من خلال الرسائل غير اللفظية. وهناك نشاط رائع مستوحى من منهج مونتيسوري يمكنكما القيام به في المنزل لمساعدة طفلكِ على فهم المشاعر المختلفة بصورة أفضل. ستحتاجين إلى: ورق مقوى ومقص وأقلام تلوين لبادية. :) قصّي الورق المقوى على شكل بيضة أو مربع أو مثلث بحجم 10 sm تقريبًا، ثم ارسمي عليه بأقلام التلوين فمًا وحاجبين يتناسبان مع تعبيره. فعلى سبيل المثال، أكملي الفم الذي يُظهر أسنانًا مطبقة وتعبيرًا غاضبًا بحاجبين معقودين، والفم الذي يُظهر الدهشة بحاجبين مرفوعين. بعد ذلك، اقطعي الورق المقوى بالمقص من المنتصف تمامًا، بحيث ينفصل الفم عن الحاجبين. ثم اخلطي جميع القطع، واستمتعي بمشاهدة طفلكِ وهو يجمع كل فم مع الحاجبين المناسبين له! :)') WHERE id = 'a9c58f85-ffb9-43bd-bd02-2e1899f70507';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك بعض النصائح التي تساعدكِ على اكتشاف مجالات الذكاء التي يتميز بها طفلكِ وتنميتها. ومن أكثر الوسائل شيوعًا الألعاب واللُّعب المخصصة لتنمية مجالات الذكاء المختلفة. خلال مرحلة عمر 2.5 سنة، يمكنكِ ممارسة أنشطة متنوعة مع طفلكِ لتحديد المجالات التي تثير اهتمامه أكثر وتلك التي يُظهر فيها أداءً أفضل. فعلى سبيل المثال، ستكون ألعاب الأحجيات ذات القطع الكبيرة، والصناديق المتداخلة، والجري في الخارج، والقفز فوق العوائق الصغيرة التي تصادفه أنشطة ممتعة للغاية. كما تُعد ألعاب الرمل، مثل رمي الكرة والتقاطها وصنع الأشكال بالرمل أو العثور على الأشياء المخبأة فيه، من الأنشطة التي تنمي ذكاء طفلكِ. ولا شك في أن اللعب بالرمل نشاط يحبه كل طفل تقريبًا. إضافة إلى ذلك، لا داعي لانتظار أشهر الصيف حتى يلعب طفلكِ بالرمل. يمكنكِ وضع وعاء ذي حواف مرتفعة ومملوء بالرمل النظيف على طاولة تناسب طول طفلكِ، ليتمكن من اللعب في المنزل وتقوية عضلات أصابعه.') WHERE id = '27c1de50-2c42-464a-b6bf-b96b6763bf44';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه الأيام أن الشعور بالذنب بدأ يتطور لدى طفلكِ. فقد أصبح قادرًا على التعاون مع أقرانه أثناء اللعب، وإظهار المودة لأحبائه، والبدء في مشاركة ألعابه. ومع تطور الشعور بالذنب لديه، قد يشعر بالقلق إذا تسبب عن طريق الخطأ في إيذاء أحد أصدقائه. ومع تحسن مهارات التواصل، يصبح سلوك طفلكِ أكثر انتظامًا، وتبدأ تصرفاته العدوانية في التراجع تدريجيًا. لكن ينبغي ألا تنسي أيضًا تأثيرات متلازمة سن 3 سنوات. ففي هذه المرحلة، قد يكون طفلكِ متعاونًا ومطيعًا جدًا في لحظة، ثم يعود بعد فترة قصيرة إلى العناد والعدوانية. وسيساعدكِ كثيرًا خلال هذه المرحلة المتقلبة أن تحافظي على تواصل قوي معه قدر الإمكان.') WHERE id = 'a43e3be1-81c8-45fd-98c2-ea9d64a44b8b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن قادرًا على تناول كل شيء تقريبًا، كما أن خطر إصابته بحساسية الطعام أقل مقارنة بالسنوات السابقة. ومع ذلك، يُفضّل استشارة الطبيب قبل إدخال أطعمة مثل الكبد والباذنجان وأسماك قاع البحر والفول إلى نظامه الغذائي. يمكن تصنيف الأطعمة التي تستطيعين تقديمها لطفلكِ حتى عمر 3 سنوات ضمن 4 مجموعات رئيسية: المجموعة 1: البيض واللحوم الحمراء والأسماك والدجاج والفاصولياء والعدس والحمص والأطباق المحضّرة منها، وهي مصادر لفيتامينات B والبروتين والمعادن الضرورية لتكوين الدم والطاقة. المجموعة 2: منتجات مثل الحليب والجبن واللبن الزبادي، وهي غنية بالكالسيوم وفيتاميني A وB. المجموعة 3: الحبوب التي تمد الجسم بالطاقة وجميع الأطعمة المحضّرة منها. المجموعة 4: الفواكه والخضراوات التي تُعد مصدرًا لفيتامين C. وتكتسب الخضراوات الورقية الخضراء الغنية بفيتامينات A وB وC أهمية خاصة. احرصي على أن يحصل طفلكِ في وجباته الرئيسية الـ3 يوميًا على كميات كافية ومتوازنة من كل مجموعة من هذه المجموعات.') WHERE id = 'f972da56-9345-45fd-af4a-8733021b3193';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تشتد مخاوف طفلكِ بدرجة كبيرة خلال هذه المرحلة، وقد يستمر خصوصًا خوفه من الظلام. وعلى الرغم من ثقته بكِ وحبه لكِ، فإن المخاوف التي قد تكون جديدة بالنسبة إليه يمكن أن تثير قلقه. وحتى إذا كنتِ قد فصلتِ سريره عن سريركِ، فقد يستيقظ طفلكِ كثيرًا ليلًا ويرغب في النوم معكِ. إن استجابتكِ لاحتياجاته بمحبة وتوفير بيئة آمنة له يساعدانكِ على تنشئة طفل واثق بنفسه ومتفائل. وقد يكون من المفيد تشغيل موسيقى هادئة عند النوم أو شراء «رفيق للنوم» له، مثل لعبة محشوة ناعمة. بالإضافة إلى ذلك، ينبغي إيقاف تشغيل أجهزة مثل التلفاز والهاتف قبل موعد النوم بساعتين على الأقل، لأن المشاهد العابرة التي يراها على الشاشة قد تثير الخوف في عقله الباطن وتقلل من جودة نومه.') WHERE id = 'd586b6dd-dba7-499f-a5f6-07d3a6c2087c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكون احتياجات طفلكِ اليومية من الطاقة والعناصر الغذائية مرتفعة خلال هذه المرحلة. ولا يرتبط ذلك بالنمو فحسب، بل أيضًا بكثرة حركته طوال اليوم. لكن الأطفال لا يستطيعون تناول حصص كبيرة دفعة واحدة. ومن الشائع في هذا العمر أن يرفض الطفل أطعمة معينة، أو يكون شديد الانتقائية، أو يرغب في تناول أنواع قليلة فقط من الطعام، وهي مشكلة مؤقتة. وعلى الرغم من ضعف شهية طفلكِ، فإنه عادة ما يتناول الطعام جيدًا في إحدى الوجبات، ويستكمل احتياجاته من الطاقة بتناول الوجبات الخفيفة بينها. ومع ذلك، ينبغي ألا تقدمي له بين الوجبات الرئيسية أطعمة مرتفعة السعرات الحرارية مثل البسكويت والمقرمشات والحلوى والمشروبات الغازية والشوكولاتة. فقد يؤدي ذلك إلى فقدان شهيته تجاه الأطعمة المفيدة، وزيادة وزنه، وحصوله على سعرات حرارية فارغة.') WHERE id = 'df828bef-6a35-4e81-bf54-f27cccf0eaf6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد عمر السنتين، غالبًا ما يصبح الأطفال غير راغبين في أخذ قيلولة نهارية. وإذا كنتِ تواجهين هذه المشكلة أيضًا، فعليكِ أولًا التعامل معها بتفهّم. فهذه حالة تُسمى «انتكاسة النوم»، وهي شائعة لدى الأطفال في الفئة العمرية من 2 إلى 3 سنوات وتُعد جزءًا من نموهم. ولن يجدي الدخول في صراع عناد مع الطفل في هذه الحالة، بل سيزيده عنادًا. حاولي ألا يصل طفلكِ إلى مرحلة الإرهاق الشديد قبل النوم. ومن الشائع الاعتقاد أن الطفل ينام بسرعة أكبر عندما يشعر بالتعب، لكن الإرهاق المفرط يسبب في الواقع التوتر والبكاء لدى الأطفال، ما يزيد صعوبة الاستغراق في النوم. تذكّري أن الإرهاق الشديد لا يجلب النوم، بل يؤدي إلى الأرق والانزعاج.') WHERE id = '8f507486-74e1-4930-a39d-bd0f1f3a9dd1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ طفلكِ خلال هذه الأشهر في تكوين تصورات ذهنية مجردة للمفاهيم والأشياء. ومع تطور مفهوم الزمن لديه، يصبح أكثر قدرة على تذكّر بعض الأمور، كما يزداد تركيزه. وقد تلاحظين أنه يخبركِ بعد أيام أو حتى أسابيع عن حدث أو شيء أثار اهتمامه، أو يتذكره عند وقوع حدث مشابه. خلال هذه المرحلة، يمكنكِ شراء دراجة ثلاثية العجلات لطفلكِ، وألوان مناسبة للأطفال، وآلات موسيقية مثل الطبل والدف والناي، إضافة إلى الكرات. كما تُعد أطقم المطابخ وأدوات الإصلاح المخصصة للعب مناسبة جدًا لتمكينه من تقليد الأعمال المنزلية، إلى جانب ألعاب التركيب (البازل) وقطع الليغو التي يكون حجمها كبيرًا بما يكفي لمنع ابتلاعها، والسيارات، والكتب المتحركة والملونة، والأشكال الهندسية. فهذه الألعاب تسرّع نموه الذهني إلى جانب تطوره الجسدي. واحرصي دائمًا على التحقق من أن الألعاب ومواد الهوايات التي تشترينها آمنة لطفلكِ.') WHERE id = '64a38c2b-47fb-49f6-b66e-e941b4f59ce1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعدّ أطعمة مثل اللحوم والدجاج والأسماك والبيض والبقوليات غنية بالبروتين. وهي ضرورية لتقوية العضلات وتكوين الدم ونمو الجسم بصورة صحية والحفاظ على صحة جيدة. وللبروتينات أهمية كبيرة جدًا في التغذية. لكن بعض الآباء والأمهات يشكون من أن أطفالهم لا يأكلون اللحوم. إذا كان طفلكِ لا يرغب في تناول قطع اللحم، فيمكنكِ أن تقدّمي له كرات اللحم أو الدجاج أو السمك أو أطباق البقوليات المحضّرة باللحم المفروم. عدم إعجابه بطعام ما لا يعني أنه لن يتناوله إذا قُدّم بطريقة مختلفة أو طُهي بأسلوب آخر. فعلى سبيل المثال، إذا كان طفلكِ لا يأكل الطماطم النيئة، فيمكنكِ تلبية احتياجاته الغذائية بتقديمها مطبوخة ضمن الوجبات. كذلك تُعدّ أطعمة مثل الحليب واللبن والجبن مصادر للكالسيوم وفيتامين A والبروتين عالي الجودة، وهي عناصر ضرورية لنمو العظام والأسنان وعمل الأعصاب والعضلات بانتظام.') WHERE id = '00d733e5-f424-4abb-bd54-db1b13f18fb2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يشيع الإمساك الوظيفي لدى الأطفال. وهي حالة لا يكون وراءها سبب طبي خطير، بل تنشأ عن عوامل نفسية واجتماعية متنوعة. هناك 5 عوامل رئيسية تسبب الإمساك: الأسباب النفسية والاجتماعية، والأخطاء الغذائية، والمشكلات البنيوية في الجهاز الهضمي، وتأثيرات الأدوية، واضطرابات الغدد الصماء. تشمل الأسباب النفسية والاجتماعية تعمّد الأطفال حبس البراز بسبب شعورهم بالألم أثناء التبرز، ثم تحوّل ذلك إلى عادة. أما الأخطاء الغذائية فتشمل قلة تناول الطعام، وشرب أكثر من نصف لتر من حليب البقر يوميًا، واتباع نظام غذائي فقير بالألياف مثل الخضراوات والفواكه، والأخطاء التي تحدث عند بدء تقديم الأغذية التكميلية. ويُقصد بالمشكلات البنيوية في الجهاز الهضمي الشق الشرجي أو الخُراج أو وجود فتحة الشرج في موضع خِلقي غير طبيعي. وقد ينجم تأثير الأدوية عن بعض مضادات الاكتئاب أو الأدوية المضادة للكولين. ويُعدّ قصور الغدة الدرقية أكثر اضطرابات الغدد الصماء شيوعًا في هذا السياق. لذلك، إذا لاحظتِ إصابة طفلكِ بالإمساك بصورة متكررة، فمن المهم استشارة الطبيب.') WHERE id = 'a1fca9a1-a5b5-4cd3-9585-094e87558f67';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبحت الذاكرة البصرية لدى طفلكِ قوية إلى درجة أنه يراقبكِ عندما تضعين أي غرض في مكان ما. بل قد يساعدكِ بالإشارة إلى مكانه إذا لم تتمكني من العثور عليه. وهذا مؤشر رائع جدًا على تطوره. وقد يحاول رسم صورة رآها أو مشهد شاهده في الخارج على الورق. حتى إن لم ينجح في ذلك تمامًا أحيانًا، يساعده هذا النشاط على الإمساك بالقلم والتمييز بين الألوان. كما سيرغب فورًا في أن يشارككِ أي شيء يلفت انتباهه. فعندما يرى فراشة مثلًا، يريدكِ أن تريها أيضًا وأن تشاركيه حماسه، فيصرّ على الإشارة إليها. وتثير التفاصيل والأغراض الصغيرة، وخصوصًا الأشياء التي لا تسمحين له بلمسها، فضوله بشدة. فهو يحفظها فورًا في ذاكرته ويحاول الوصول إلى هدفه عند أول فرصة.') WHERE id = 'f14124df-63d7-46de-a1b0-fb1bc90ef99c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تدخل مهارات طفلكِ اللغوية والكلامية مرحلة جديدة خلال هذه الفترة. وربما لاحظتِ منذ مدة أنه بدأ يتحدث مستخدمًا صيغ الضمائر المختلفة. كما يستخدم كلمات القرابة مثل "الخالة" و"الخال" و"العم"، مدركًا أن هؤلاء الأشخاص جزء من عائلته. إضافة إلى ذلك، قد ينطق كلمتي "ماما" و"بابا" بطريقة أكثر طرافة، محاولًا لفت الانتباه وزيادة تواصله معكِ. وهو يفهم صيغة النفي في الكلمات، ويستخدم تعبيرات مثل "لي" أو "لأبي" ليوضح أن شيئًا ما يخصه. لكنه قد يظل خلال هذه الأشهر يخلط بين تعبيرات مثل "برأيك" و"برأيي". وتشير كل هذه المهارات الجديدة إلى أنه قطع شوطًا كبيرًا في تطور الكلام.') WHERE id = 'c55bb7ad-082f-45d6-afd3-b0c6f31390a4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعدّ التغذية الصحية لطفلكِ مهمة جدًا للوقاية من مشكلات الجهاز الهضمي مثل الإمساك والإسهال، ومن فقر الدم الناتج عن نقص الحديد. وللوقاية من الإمساك خلال هذه الفترة، ينبغي تقديم أطعمة غنية بالألياف تعتمد بصورة أساسية على الخضراوات والفواكه. وفي الوقت نفسه، عليكِ الحرص على تلبية احتياجاته من البروتين والفيتامينات والمعادن. إذا كان طفلكِ لا يحب تناول اللحوم، فيمكنكِ اختيار الأنواع المناسبة وتحضيرها على شكل كرات لحم أو سلقها أو إضافتها إلى أطباق الخضراوات والحساء. وينبغي أن تتضمن قائمتكم الأسبوعية السمك مرة واحدة على الأقل. ويجب أن يتناول طفلكِ يوميًا 2-3 حصص من هذه المجموعة الغذائية. وبوجه عام، يكفي لتلبية احتياجاته خلال اليوم كوبان من الحليب (400-500 غرام) وقطعة جبن بحجم علبة كبريت. وقد يؤثر تناول كمية أكبر من الكالسيوم سلبًا في امتصاص الجسم للمعادن الأخرى.') WHERE id = 'e18a2773-f5ca-428b-953b-bdd7310cbd6f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشبه المرحلة التي تعيشونها حاليًا ثورة في حياة طفلكِ؛ فقد تبدأ علامات أزمة سن الثالثة قبل أن تنتهي تمامًا علامات أزمة سن الثانية. في هذه المرحلة الجديدة، يمكنكِ أن تظهري له أنكِ تتفهمينه من خلال بعض التغييرات البسيطة، أو أن تعدّلي روتينه اليومي قليلًا. فإذا لم تكوني قد أحضرتِ له حتى الآن رفيقًا للنوم (لعبة)، فهذا هو الوقت المثالي! يمكنكِ اختيار لعبة ناعمة لا يتساقط وبرها في الفم أو الأنف، ولا تحتوي على أزرار أو سلاسل. واحرصي على أن تكون اللعبة قابلة للغسل، وأن تحتوي على أجزاء يمكن الإمساك بها مثل اليدين أو الأذنين أو الذيل. ومن المهم جدًا ألّا تضعي هذه اللعبة بجانب ألعابه الأخرى؛ إذ ينبغي أن يشعر طفلكِ بأنها ليست لعبة عادية، بل صديق مميز يرافقه وقت النوم فقط.') WHERE id = 'dad27d76-9b3f-4d94-805e-e4b144d944ca';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يشعر بأنه مستعد في هذه المرحلة، ولم يمر مؤخرًا بتغييرات جذرية مثل الانتقال إلى منزل جديد أو الطلاق أو الفطام، فيمكنكما البدء بالتدريب على استخدام المرحاض. أكثر جوانب هذا التدريب حساسية هو تزامنه مع مرحلة «التمركز حول الذات»، التي يرى فيها الطفل نفسه محور كل شيء. لذلك قد يصعب تعليمه شيئًا جديدًا. وبما أن علامات أزمة سن 3 سنوات تظهر أيضًا في هذه الفترة، فقد تتعرض حدود السلطة بينكما للاختبار. فقد تجدين نفسكِ بين وضع القواعد من جهة وعدم القدرة على تحمل بكائه من جهة أخرى، ما يجعل الموقف حساسًا. وقد يؤدي الضغط المفرط خلال هذه المرحلة إلى مشكلات مثل ضعف الثقة بالنفس وكبت المشاعر لدى الطفل. ولتفادي ذلك، يمكنكِ إتاحة الفرصة لطفلكِ للعب بالرمل وملامسة الماء والجري حافي القدمين في الطبيعة. ستساعده هذه الأنشطة على تخفيف توتره والاسترخاء.') WHERE id = '56eba127-0922-4581-82f1-54a03ed676ef';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع تحسن قدرة طفلكِ على الإمساك بالأشياء، أصبح الآن يمسك القلم بصورة أفضل ويستطيع ممارسة ألعاب باستخدام كرات صغيرة مثل كرة التنس. وسيختار طفلكِ اليد التي يستخدمها لأداء هذه الحركات وفقًا لما يشعر معه بالراحة. في هذه المرحلة، قد يجبر بعض الآباء طفلهم الأعسر على استخدام يده اليمنى، لكن هذا نهج خاطئ تمامًا. فتفضيل إحدى اليدين يتشكل وفقًا لطريقة عمل الدماغ، ولذلك فهو أمر طبيعي وصحي للطفل. وإلى جانب ذلك، يُتوقع أن يحرز طفلكِ تقدمًا في مهارات بدنية مختلفة خلال هذه الفترة. فمثلًا، قد يحاول الوقوف على قدم واحدة، وقد ترينه ينجح في ذلك. كما سيرغب في غسل يديه وارتداء ملابسه بنفسه، لأنه يشعر بتطور قدراته البدنية. وسيساعده تقديم ملابس فضفاضة ومريحة على الشعور بالنجاح أثناء محاولته تحقيق هذه الرغبة.') WHERE id = 'b96b8dee-7314-45ef-8935-c7aceece6b06';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أكثر الأمور التي تشتكي منها الأمهات خلال الفترة الممتدة من عمر 2 سنوات حتى سن المدرسة طلب الأطفال المستمر للأطعمة السكرية. فالسكر من أبرز المواد التي لا تحتوي على أي قيمة غذائية، مع ارتفاع سعراتها الحرارية. وقد يؤدي تناول طفلكِ مثل هذه الأطعمة في هذه المرحلة إلى زيادة استعداده للإصابة بالأمراض مستقبلًا. لذلك عليكِ الاحتفاظ بأقل قدر ممكن من الأطعمة السكرية في المنزل، حتى لا يتمكن من العثور عليها وتناولها بسهولة. ولتلبية رغبته في المذاق الحلو، يمكنكِ وضع الفواكه في مكان يسهل عليه الوصول إليه. ولا تستخدمي الشوكولاتة والحلوى كمكافأة، كما يفعل بعض الآباء كثيرًا. ومن أجل صحة طفلكِ، يمكنكِ جعل الكعك والبسكويت اللذين تحضرينهما في المنزل أكثر فائدة بإضافة الفواكه بدلًا من السكر.') WHERE id = 'da4edbe5-0e9f-475e-b94c-678be057a584';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن أكثر اجتماعية، وقل خجله وخوفه من الغرباء. ويمكنه مشاركة ألعابه مع أصدقائه واللعب معهم. وقد يخرج وسائد الأريكة ويبني لنفسه منزلًا صغيرًا ليصنع مساحته الخاصة، ثم يرغب في دعوة أصدقائه وحدهم إليها. ومن الطبيعي ألا يرغب في إشراككِ في ذلك، لأنه صاحب القرار في هذه المساحة. كما يزداد اهتمام الطفل في هذه المرحلة بالأقلام الملونة والرسم. قدّمي له أوراقًا فارغة وألوانًا، وأتيحي له فرصة نقل خياله إلى الورق. سيساعد ذلك على توسيع مداركه. لكن كوني حذرة، لأن تزيين الأطفال للجدران والأثاث في هذا العمر يُعد من أكبر مخاوف الآباء. 😊') WHERE id = 'b23ce050-0379-4aa6-b489-85355e97ec2f';